Ceviri.ekle("sw","olay",{
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Levnî achora Surnâme-i Vehbî", "8c127866"], "d": ["Mchoraji wa ikulu Levnî alichora Surnâme-i Vehbî, inayosimulia harusi ya tohara ya şehzade wa III. Ahmed ya 1720, kwa picha ndogo 137. Tofauti na mifano ya awali, kwa kuonyesha sherehe si katika Atmeydanı peke yake bali katika pembe mbalimbali za mji, alianzisha mtazamo mpya katika sanaa ya picha ndogo ya Ottoman.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Mfumo wa gedik kuwekwa rasmi kama utaratibu wa wafanyabiashara unaotegemea ukiritimba", "cd0f79a7"], "d": ["Kwa mujibu wa TDV, mabadiliko ya kimfumo ambamo haki ya gedik ilipata maana ya \"ukiritimba, upendeleo na aina ya hataza\" yanafuatiliwa kuanzia 1727; utaratibu huu unaowapa idadi fulani ya watu haki ya kufanya kazi katika biashara ulijikita katika maduka mengi ya mali ya waqf kwa jina la \"haki ya gedik\".", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Sâdâbâd yaharibiwa katika uasi wa Patrona Halil", "8a30f9a0"], "d": ["Wakati wa uasi wa Patrona Halil uliolipuka tarehe 25 Septemba 1730 mamia ya majumba madogo na majengo katika Sâdâbâd yaliharibiwa; mkusanyiko huu, ishara ya Enzi ya Tulip, haukupata tena fahari yake ya awali.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Kifo cha Nedîm wakati wa uasi wa Patrona Halil", "06bf909e"], "d": ["Nedîm, aliyekuwa müderris katika Madrasa ya Sekban Ali Paşa Uasi wa Patrona Halil ulipolipuka, alifariki katika siku zilizofuata uasi. Siku ya kifo haijulikani; hata hivyo kwa kuwa hati ya kassam ya mali zake iliandaliwa tarehe 15 Rebîülâhir 1143 (28 Oktoba 1730), alikufa kabla ya tarehe hii. Kuna riwaya mbalimbali kuhusu sababu ya kifo: sehemu ya vyanzo inaandika kwamba alikufa kwa ugonjwa wa hofu (illet-i vehîme) au ugonjwa wa kutetemeka aliopata kwa pombe na afyuni, huku Müstakimzâde akiandika kwamba wakati wa mapinduzi alipanda juu ya paa la nyumba yake kwa hofu na akafa kwa kuanguka kutoka hapo. Kwa kifo chake mng'aro wa kitamaduni wa Enzi ya Tulip pia ulimalizika kwa vitendo.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Kifo cha Levnî", "dd48b56e"], "d": ["Levnî, anayehesabiwa mwakilishi mkuu wa mwisho wa sanaa ya picha ndogo ya Ottoman, alifariki mwaka 1732. Sehemu kubwa ya kazi zake ipo leo katika Makumbusho ya Ikulu ya Topkapı.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Kuwekwa kwa msingi wa Msikiti na Külliye ya Nuruosmaniye", "397ec798"], "d": ["Msingi wa Külliye ya Nuruosmaniye uliwekwa na I. Mahmud tarehe 19 Januari 1749. Jengo hili huhesabiwa utekelezaji mkubwa wa kwanza wa mtindo wa baroque wa Ulaya katika usanifu wa Ottoman na linatofautiana wazi na mpango wa kawaida wa külliye.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Kufunguliwa kwa Msikiti na Külliye ya Nuruosmaniye", "15d83731"], "d": ["Kufunguliwa kwa külliye iliyoanzishwa na I. Mahmud lakini hakuona kukamilika kwake kulifanyika wakati wa ndugu yake III. Osman tarehe 5 Desemba 1755. Msikiti ulipata jina lake, lenye maana ya \"Nuru ya Osman\", kwa kumhusisha III. Osman aliyefanya ufunguzi.", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Kufunguliwa kwa Mühendishâne-i Bahrî-i Hümâyun", "a2fab1cd"], "d": ["Mühendishâne-i Bahrî-i Hümâyun, shule ya kwanza ya kisasa ya uhandisi wa majini ya Ottoman, kulingana na hati za kumbukumbu za Kifaransa ilifunguliwa tarehe 29 Aprili 1775 wakati wa I. Abdülhamid, chini ya usadrazam wa Sadrazam Derviş Mehmed Paşa.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Kuanzishwa kwa mfumo wa esham", "eabd8ece"], "d": ["Mbele ya mzigo wa fidia wa kuruş milioni 7,5 uliotokana na Mkataba wa Küçük Kaynarca, mfumo wa esham ulianzishwa mwaka 1775. Katika njia hii iliyobuniwa kuvuka mipaka ya malikâne, mapato ya mukātaa yaligawanywa katika hisa, na tofauti na malikâne, wanawake, wasio Waislamu na watu wa kawaida pia wangeweza kuwa wamiliki wa hisa.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Kuzaliwa kwa Hammâmîzâde İsmail Dede Efendi", "c033f039"], "d": ["Hammâmîzâde İsmail Dede Efendi, mmoja wa watunzi wenye uzalishaji mkubwa zaidi wa muziki wa Kituruki, alizaliwa tarehe 9 Januari 1778 katika mtaa wa Şehzadebaşı wa Istanbul. Katika maisha yake alitunga kazi zaidi ya 500; kati ya hizo takriban 294 zimefika siku zetu.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Kuanza kwa ujenzi wa Mühendishâne-i Berrî-i Hümâyun", "4f5d521a"], "d": ["Ujenzi wa Mühendishâne-i Berrî-i Hümâyun, mojawapo ya taasisi muhimu zaidi za marekebisho ya Nizâm-ı Cedîd ya III. Selim, ulianza tarehe 14 Julai 1793. Jengo lilikamilika Septemba 1795 na kufunguliwa kwa elimu; taasisi ilikuwa shule ya pili ya uhandisi wa kijeshi ya Ottoman iliyochukua mfano wa akademia za kijeshi za Ulaya.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["III. Selim kuanza kuondoa ukiritimba wa baadhi ya vyama vya wafanyabiashara", "008f4a7d"], "d": ["Kwa mujibu wa makala ya TDV ya Esnaf, katika utaratibu wa vyama vya Kiottoman uliounganishwa na shirika la ahî tangu kuanzishwa kwake, maafisa kama \"ahî baba\" na \"şeyh\" waliongoza vyama hadi mwanzoni mwa karne ya 19; katika karne ya 18, vyama vilipopandisha bei juu ya narh kwa ukiritimba na kuleta shinikizo la kiuchumi, III. Selim alianza kuanzia 1794 kuondoa ukiritimba wa vyama vya vyakula vya msingi.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Dede Efendi achukuliwa ikulu kama musâhib-i şehriyârî", "0cb99ac3"], "d": ["Dede Efendi, aliyevuta fikira za sultani kwa utungo wa bûselik wakati wa III. Selim, mwaka 1812 alichukuliwa na II. Mahmud kati ya \"musâhib-i şehriyârî\" (marafiki wa karibu wa baraza la sultani) na hivi karibuni alipandishwa hadi müezzinbaşılık.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Kufanywa kwa sensa ya kwanza ya kawaida ya idadi ya watu katika Ottoman", "4f004c6c"], "d": ["II. Mahmud, kwa lengo la kubaini idadi ya watu watakaoandikishwa jeshini, alifanya kwa mara ya kwanza sensa ya kawaida mwishoni mwa 1830; wanaume pekee ndio waliorekodiwa na takriban watu milioni 7,5 walibainishwa Anatolia-Rumeli. Katika baadhi ya maeneo kama Erzurum na Van sensa iliweza kukamilika mwaka 1836 tu.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Kuanzishwa kwa Feshâne-i Âmire", "971ab85a"], "d": ["Ili kukidhi mahitaji ya fes ya jeshi la Asâkir-i Mansûre-i Muhammediyye lililoundwa baada ya kukomeshwa kwa Ocak ya Yeniçeri mwaka 1826, uzalishaji wa fes ulianza mwaka 1833 kwa mtaji wa kuruş milioni 1,5 katika Cündî Meydanı huko Kadırga. Vifaa vilihamishiwa mwaka 1839 kwenye Ikulu ya Hatice Sultan huko Eyüp; Feshâne iliunda msingi wa tasnia ya nguo ya Ottoman.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["Shule ya tiba yachukua jina Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne", "187d60f3"], "d": ["Shule ya tiba iliyohamia jengo la Enderun Ağaları Mektebi huko Galatasaray ilipewa jina \"Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne\" tarehe 14 Mei 1839 kwa ziara ya II. Mahmud; taasisi hivyo ilisajiliwa rasmi kwa utambulisho wa shule ya kijeshi-kiutawala.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Kifo cha Dede Efendi Mina wakati wa hija", "c3e613a2"], "d": ["Hammâmîzâde İsmail Dede Efendi, aliyeshikwa na kipindupindu Mina alikokwenda kutimiza faradhi ya hija, alifariki tarehe 29 Novemba 1846. Kwa kifo cha msanii aliyetunga ayini saba tofauti za Mevlevî kati ya 1824-1839, kipindi cha muziki wa kawaida wa Ottoman kilifungwa.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Kukubaliwa kwa Kanunnâme ya Biashara ya 1850", "8ac085fd"], "d": ["Katika mfumo wa mageuzi ya sheria ya enzi ya Tanzimat, sheria mpya zilichukuliwa kutoka kwa dola za Magharibi kwa tafsiri na kunukuu: sheria ya jinai ilianza kutumika mwaka 1840, sheria ya biashara mwaka 1850, sheria ya ardhi mwaka 1857. Kanunnâme ya Biashara ilikuwa uandishi wa kwanza wa kisasa wa sheria ya biashara ya Ottoman.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Kuanza kwa wimbi kubwa la uhamiaji wa Watatari wa Krimea na watu wa Caucasus kwenda ardhi za Ottoman", "8832c06d"], "d": ["Baada ya Şeyh Şâmil kutekwa na Warusi mwaka 1859, wahamiaji wengi wa Kicherkesi na Kinogay kutoka Caucasus pamoja na Watatari wa Krimea walianza kuhamia ardhi za Ottoman. Wimbi hili la uhamiaji liliendelea kwa viwango tofauti hadi baada ya Vita vya Ottoman-Urusi vya 1877-78.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Kuanzishwa kwa Muhâcirîn Komisyonu", "9717e77e"], "d": ["Ili kusimamia wimbi la uhamiaji linaloongezeka kutoka Caucasus, serikali ya Ottoman ilianzisha Muhâcirîn Komisyonu tarehe 16 Januari 1860. Tume iliratibu kazi za makazi Anatolia, Balkan na Syria na ilifanya kazi hadi 1875.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Bank-ı Osmanî kupangwa upya kama Bank-ı Osmanî-i Şâhâne (Benki ya Ottoman)", "c3530456"], "d": ["Mwaka 1856 baada ya Vita vya Krimea, Bank-ı Osmanî, iliyokuwa na makao makuu London na mtaji wa Kiingereza, ilianzishwa ili kusimamia malipo ya madeni ya nje. Mwaka 1863 kundi la pamoja la Kifaransa-Kiingereza lilipewa ruhusa ya kuanzisha benki mpya kwa jina Bank-ı Osmanî-i Şâhâne (Benki ya Ottoman); taasisi baadaye ilipata pia mamlaka ya kutoa noti.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Kuanzishwa kwa Cem'iyyet-i Tedrîsiyye-i İslâmiyye", "77ad553a"], "d": ["Cem'iyyet-i Tedrîsiyye-i İslâmiyye ilianzishwa tarehe 30 Machi 1864 kwa lengo la kuchukua jukumu la elimu ya wanafunzi wa ufundi Waislamu maskini; mpango huu wa chama cha kiraia ni mfano wa upainia ambapo mapokeo ya taasisi za hisani yaligeuka kuwa mradi wa kisasa wa shule. Chama kingefungua Darüşşafaka miaka tisa baadaye.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Kupangwa kwa mfumo wa muhtar na baraza la ihtiyar kwa Vilâyet Nizamnâmesi ya 1864", "1a2e8cf2"], "d": ["Utawala wa vijiji ulipangwa upya kwa Vilâyet Nizamnâmesi ya 1864; katika vijiji ambamo Waislamu na wasio Waislamu wanaishi pamoja, ilikubaliwa kwamba kila jamii ichague muhtar wake na baraza lake la ihtiyar. Baraza la ihtiyar hivyo lilipata nafasi rasmi kwa mara ya kwanza katika utawala wa kijiji/mtaa.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Kilele cha Uhamisho Mkuu wa Wacherkesi", "b2ab1874"], "d": ["Kwa uvamizi wa Urusi wa Caucasus kati ya 1858-1878, kwa nguvu zaidi katika 1861-1864, Wacherkesi milioni 1,2-1,5 walilazimishwa kuhamia ardhi za Ottoman. Kwa mujibu wa TDV, watafiti wengi wanaelezea tukio hili kama \"harakati ya kwanza ya utakaso wa kikabila katika historia ya kisasa\".", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Kuchapishwa kwa Maârif-i Umûmiyye Nizamnâmesi ya 1869", "787f6022"], "d": ["Maârif-i Umûmiyye Nizamnâmesi iliyochapishwa tarehe 1 Septemba 1869 ilikuwa maandishi ya kwanza kamili yanayopanga elimu ya jumla mikoani na katikati. Kwa nizamnâme, Meclis-i Kebîr-i Maârif iliundwa; kupangwa upya kwa shule za sıbyan ili zisiwe tu hatua ya elimu ya kidini bali zielekeze kwenye ufundishaji wa kusoma na kuandika kulianza kwa mpangilio huu.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Shule ya Darüşşafaka kuanza elimu", "525c457c"], "d": ["Darüşşafaka iliyoanzishwa na Cem'iyyet-i Tedrîsiyye-i İslâmiyye ilianza kufundisha kwa vitendo tarehe 28 Juni 1873 ili kuwaelimisha watoto yatima na maskini Waislamu bila malipo kwa mfumo wa bweni; umri wa juu wa kukubaliwa uliwekwa kuwa kumi.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Tetemeko la İstanbul la 1894", "7ae7f648"], "d": ["Tetemeko lililotokea tarehe 10 Julai 1894 pwani ya Ghuba ya İzmit lilipiga İstanbul vibaya; misikiti na majengo mengi ya kihistoria, ikiwemo kuta za İstanbul, yaliharibiwa. Makala ya TDV ya zelzele inahesabu tetemeko hili, pamoja na matetemeko ya 1509, 1719 na 1766, miongoni mwa matetemeko yaliyosababisha hasara kubwa ya maisha na mali katika eneo la Marmara.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Kufunguliwa kwa Dârülaceze", "a30baf31"], "d": ["Dârülaceze, iliyoandaliwa kufuatia amri za II. Abdülhamid kuanzia 1890, ilifunguliwa tarehe 2 Februari 1896 na Sadrazam Halil Rifat Paşa. Taasisi hiyo, iliyowahifadhi watoto wasio na walezi, wazee na wahitaji, ilikuwa jengo kubwa zaidi la msaada wa kijamii la wakati wake likiwa na hospitali ya vitanda 200, karakana na nyumba za ibada tofauti kama msikiti-kanisa-sinagogi.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Dârülfünûn-ı Şâhâne yaanzishwa upya kama taasisi ya kudumu", "7d6d8fc4"], "d": ["Darülfünun, baada ya majaribio mawili yaliyoshindwa ya awali (1863 na 1870), ilianzishwa upya tarehe 31 Agosti 1900 kwa jina la Dârülfünûn-ı Şâhâne kama taasisi ya kudumu; TDV inaielezea tarehe hii kuwa msingi wa moja kwa moja wa mfumo wa vyuo vikuu vya Kituruki wa leo.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["Serbedârî walichukua Sebzevâr — dola ya kwanza ya baada ya Ilhanlı Horasan", "af997fec"], "d": ["Utawala wa kati wa Ilhanlı ulipoanguka kwa kifo cha Ebû Saîd (30 Novemba 1335), mwitikio uliokusanyika Horasan dhidi ya maafisa wa kodi ulilipuka Bâştîn: Abdürrezzâk aliasi tarehe 13 Machi 1337 na tarehe 9 Septemba 1337 (12 Safer 738) alichukua Sebzevâr. Jina \\\"Serbedâr\\\" — \\\"kichwa kwenye mti wa kunyongea\\\" — ni maneno yao wenyewe yanayoeleza kwamba walikuwa tayari kunyongwa wakishindwa.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["Maseyyid wa Mar'aşî walichukua Âmül — utawala wa maseyyid Mazenderan", "c0e03266"], "d": ["Seyyid Kıvâmüddin Mar'aşî, akifuata njia iliyofunguliwa na Serbedârî Horasan, alichukua Âmül mwaka 760 (1359) na akaanzisha dola ya maseyyid kwenye ufuo wa kusini wa Hazar. Nasaba ilienea Sârî, Bârfurûş na viunga vyake; ilitikiswa katika kampeni za Timur na ilivunjwa katika enzi ya Safavî I. Şah Abbas.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["Nasaba ya Kârkiyâ ilianzishwa Gîlân — watawala huru wa mwisho wa pwani ya Hazar", "6e5f9db7"], "d": ["Ali Kiyâ alirudi Gîlân na familia yake na mwaka 773 (1371-72) akaanzisha utawala wa Kârkiyâ wenye kitovu cha Lâhîcan; nasaba ilishikilia pwani ya kusini-magharibi ya Hazar kwa zaidi ya karne mbili na ilidumu hadi Safavî I. Şah Abbas alipoliunganisha eneo mwaka 1592.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Utawala wa Dâcû Dârfûr kupita kwa Tuncûr", "6eb22a2a"], "d": ["Kwa mujibu wa makala ya Dârfûr katika TDV İslâm Ansiklopedisi, waliokaa kwanza eneo hilo na kuanzisha dola ya kwanza ni kabila la Dâcû; Wadâcû, waliotawala eneo hilo katika karne ya XIII na XIV, walipoteza utawala wa kibiashara kwa Watuncûr, na katika karne ya XV, hasa katika eneo la kati, hali iligeuka kabisa kwa manufaa ya Watuncûr.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["Uhispania kurudisha mwamba wa Bâdis (Peñón de Vélez)", "0dc52728"], "d": ["Makala ya TDV ya Sa'dîler inaandika kwamba kuchukuliwa kwa Bâdis na Wahispania kulikuwa pigo zito kwa uanamaji wa Mağrib (1564). Nafasi hii ya mwamba kwenye pwani ya Moroko Kaskazini ilikuwa msingi wa uharamia Mediterania ya Magharibi na wa mvutano wa Ottoman-Uhispania.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["Kuachiwa kwa el-Arâiş (Larache) kwa Uhispania", "7b8f6e27"], "d": ["Katika miaka ya vita vya ndani ambapo nasaba ya Sa'dî ilivunjika, bandari ya el-Arâiş kwenye pwani ya Atlantiki iliachiwa Uhispania. Makala ya TDV ya Sa'dîler inaandika kwamba katika kipindi hiki nchi iligawanywa mara mbili kuwa emirlik za Merakeş (kusini) na Fas (kaskazini), na pande zilizokuwa kwenye mapambano ya kiti zilitafuta msaada kutoka nje. Bandari ingebaki mikononi mwa Wahispania karibu miaka themanini, na Mevlây İsmâil angeirudisha mwaka 1689.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["Mamûra (Mehdiye) kupita mikononi mwa Wahispania", "c8fd494e"], "d": ["Bandari ya Mamûra (Ma'mûre / Mehdiye) kwenye mdomo wa mto Sebû ilichukuliwa na Wahispania mwaka 1614 na ikaimarishwa kwa jina San Miguel de Ultramar. Makala ya TDV ya Mevlây İsmâil inaandika kwamba bandari ilirudishwa kutoka kwa Wahispania mwaka 1092 (1681) kwa shambulio la ghafla — yaani utawala wa Kihispania ulidumu miaka sitini na saba.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Mwisho wa nasaba ya Sa’dî — kuanza kwa enzi ya Alevî (Filâlî) Moroko", "b1afa579"], "d": ["TDV İslâm Ansiklopedisi inafafanua makala ya Sa’dîler kama \\\"nasaba ya Kiislamu iliyotawala Moroko (1511-1659)\\\". Nasaba, iliyomaliza utawala wa Vattâsî mwaka 1549 na kuiunganisha Moroko yote, iliyoangamiza jeshi la Ureno huko Vâdisseyl mwaka 1578 na iliyowahi kutowekwa tegemezi kwa Ottoman katika kipindi chochote, ilimalizika mwaka 1659 baada ya mapambano marefu ya kiti. Nafasi yake ilichukuliwa na şerif wa Alevî (Filâlî) waliotoka Tâfilâlt; Mevlây Reşîd aliingia mji wa Fas mwaka 1666 na kuimarisha nasaba mpya, na kaka yake Mevlây İsmâil alisafisha nafasi za Ulaya kwenye pwani ya Atlas.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["Uhispania kuvamia visiwa vya el-Hüseyme (Alhucemas)", "954ca998"], "d": ["Visiwa vya el-Hüseyme kwenye pwani ya Mediterania vilivamiwa na meli za Kihispania mwaka 1673. Pamoja na Bâdis na Sebte, ni miongoni mwa nafasi ambazo Uhispania ilizishikilia kwenye pwani ya Moroko Kaskazini na zinabaki mikononi mwake hadi leo. Mwaka huo huo kaka wa Mevlây İsmâil, Mevlây Reşîd, aliingia Merakeş na kupokea bîat kutoka kwa wananchi, na utawala wa Filâlî uliimarika kusini — kupotea huku pwani kunaonyesha kwamba kuunganishwa kwa ndani bado hakukuwa na kinachofanana nacho kwenye mstari wa nje.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Mevlây İsmâil kurudisha el-Arâiş kutoka kwa Wahispania", "a54bc6ee"], "d": ["Makala ya TDV ya Mevlây İsmâil iko wazi: \"Mwaka 1100 (1689) walirudisha Arâîş kutoka kwa Wahispania na kuchukua mizinga 200, na miaka miwili baadaye wakarudisha Asîle.\" Hiki ni mojawapo ya viungo vya mnyororo wa utakaso wa pwani wa sultani wa Filâlî — Tanca ilirudishwa kutoka kwa Waingereza mwaka 1678, Mamûra mwaka 1681, el-Arâiş mwaka 1689, Asîle mwaka 1691. Bandari iliyoachwa katika vita vya ndani vya Sa'dî miaka themanini iliyopita hivyo ilirudi Moroko.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Kuanzishwa kwa Usultani wa Dârfûr — nasaba ya Keyra na Süleyman Solonc", "0fc1c112"], "d": ["Kwa mujibu wa TDV, kuanzishwa kwa Usultani wa Dârfûr kunaangukia baada ya machafuko yaliyofuatia uvamizi wa Bumû el-Kasîr wa eneo mwishoni mwa karne ya XVII. Wafûr, chini ya uongozi wa nasaba ya Kîrâ (Keyra) iliyoongozwa na Süleyman Solonc, walichukua mamlaka kutoka kwa Wadâcû na Watuncûr na wakaanzisha utawala imara. Süleyman Solonc alitawala kati ya 1695-1715. Masultani wa Dârfûr waliandikiana na Bâbıâli katika karne zilizofuata; Abdülmecid na Abdülaziz walithibitisha utawala wao.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Kutangazwa kwa Jamhuri ya Kwanza nchini Ufaransa — mwisho wa ufalme", "d53d49b0"], "d": ["Katika kikao cha kwanza cha Konvansiyon ya Kitaifa ufalme ulifutwa na siku iliyofuata Jamhuri ya Kwanza ilitangazwa; mwaka wa kwanza wa kalenda mpya ulianza kuanzia siku hii. Kwa mtazamo wa Ottoman mhusika hakubadilika lakini aina ya mhusika ilibadilika: katika miaka ya Nizâm-ı Cedîd ya III. Selim, Ufaransa haikuwa tena nasaba bali utawala, na aliyetua Misri mwaka 1798 pia alikuwa jeshi la utawala huo.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["Kuanguka kwa Kabiliye Kuu — kutekwa kwa Lalla Fatma N'Sûmer", "0f61ff08"], "d": ["Makala ya TDV ya Cezayir inaandika kwamba kwa kuvamiwa kwa eneo la milima la Kabiliye (Bilâdü'l-kabâil) mwishoni mwa kampeni za 1853, 1854 na 1857, harakati ya Ufaransa ya kuivamia Cezayir ilikamilika kwa kiasi kikubwa. Kampeni ya 1857 ilivunja mstari wa Tîzî Vezzû na Akbû; Lalla Fatma N'Sûmer, ishara ya upinzani, alitekwa. Kitovu cha mwisho kikubwa cha upinzani kilichobaki baada ya Emîr Abdülkādir kusalimu amri mwaka 1847 hivyo kilizimwa.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Uvamizi wa Kifaransa wa Aynı Sâlih (Tîdîkelt)", "1e28d1d0"], "d": ["Aynı Sâlih, kitovu cha kundi la oasisi za Tîdîkelt katikati ya Sahara, ilichukuliwa na vikosi vya Ufaransa tarehe 29 Desemba 1899. Hii ni hatua kubwa ya kwanza ya kuenea kwa Ufaransa kusini kutoka pwani ya Cezayir iliyovuka hadi jangwani; ndani ya miaka miwili Tuvât na Gûrâre pia zingefuata njia hiyo hiyo.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Kuunganishwa kwa oasisi za Tuvât · Gûrâre · Tîdîkelt na Ufaransa", "d412838b"], "d": ["Ukanda wa oasisi wa Tuvât, Gûrâre na Tîdîkelt kusini-magharibi mwa Cezayir uliunganishwa rasmi na Ufaransa tarehe 21 Februari 1901. Mfumo huu wa njia za misafara unaodaiwa kwa jina tu na sultani wa Moroko — ikiwemo Advâr, Tîmîmûn, Reggân na Benî Abbâs — hivyo uliunganishwa na Cezayir; huu ndio mwanzo wa mgogoro wa mpaka kati ya Moroko na Cezayir ya Kifaransa.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Kuanzishwa kwa kituo cha Kifaransa Beşşâr (Colomb-Béchar)", "4d44d252"], "d": ["Oasisi ya Beşşâr kwenye mpaka wa Moroko ilichukuliwa na vikosi vya Ufaransa tarehe 11 Novemba 1903 na ikafanywa kituo cha mbele kwa jina Colomb-Béchar. Hatua hii, iliyokuja miaka miwili baada ya kuunganishwa kwa ukanda wa Tuvât, ni mojawapo ya viungo vya mwisho vya kusonga mbele kwa Ufaransa kutoka Cezayir kuelekea Moroko; inafungua njia ya Moroko kuwekwa chini ya ulinzi mwaka 1912.", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["Kuanzishwa kwa Ukuu wa Moscow — I. Daniil", "49549309"], "d": ["Daniil, mwana mdogo kabisa wa Aleksandr Nevski, alianza kutawala Moscow kama ukuu huru. Wakati huo Moscow ilikuwa kitovu kidogo na kisicho na umuhimu cha ardhi za Vladimir-Suzdal; uandishi wa historia wa Kirusi huhesabu tarehe hii kuwa mahali pa kuanzia pa kupanda baadaye.", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Kuanzishwa kwa beylik za Karesi na Hamîdoğulları", "3905da93"], "d": ["Kwa mujibu wa makala ya TDV ya Karesioğulları, Karesi Bey, katika shirika la mpakani la Waseljuk lililovunjika kwa kifo cha baba yake Kalem Bey, alitangaza uhuru wake na tangu 696 (1296-97) alifanya Balıkesir kuwa kitovu na kwa muda mfupi alichukua Mysia yote, ikijumuisha Erdek, Biga, Edremit na Bergama, kutoka kwa Bizanti. Mwaka huo huo (1297) Hamîd Bey alianzisha Beylik ya Hamîdoğulları kwa kufanya Uluborlu kuwa kitovu cha serikali; Isparta, Burdur, Eğirdir na Yalvaç ziliunganishwa kwenye mipaka ya kwanza ya beylik kutoka eneo la mpakani la Waseljuk lililovunjika. Beylik zote mbili ni zao la anguko moja Anatolia Magharibi — kuvunjika kwa mamlaka ya kati ya Waseljuk.", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["Mkuu wa Moscow Daniil aunganisha Kolomna na Serpuhov na Moscow", "6d82dccd"], "d": ["Daniil alichukua Kolomna kutoka Ukuu wa Ryazan (mkuu wa Ryazan aliyetekwa alikabidhi ngome ili aachiliwe) na Serpuhov; Moscow ilifika mto Oka na ilikuwa upanuzi wa kwanza wa ardhi wa Ukuu wa Moscow.", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["Mozhaysk yachukuliwa kutoka Ukuu wa Smolensk na kuunganishwa na Moscow", "462055a0"], "d": ["Ukuu wa Moscow, kwa kuchukua Mozhaysk katika bonde la juu la mto Moscow kutoka Smolensk, ulikaribisha mpaka wake wa magharibi karibu na Lithuania.", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["Ukuu wa Polotsk wapita kwa Ukuu Mkuu wa Lithuania", "04a26a6f"], "d": ["Polotsk, Vitebsk na mazingira yake yalibaki ndani ya nasaba ya wakuu wa Kirusi hadi 1307; kuenea kwa Lithuania kuelekea mashariki kabla ya Gediminas kulijitokeza wazi kwa kupita huku (tarehe ya künye ya atlasi ni 1307; kupita kwa kweli kwa Vitebsk ≈1320 kunabishaniwa).", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Kuanzishwa kwa Beylik ya Aydınoğulları — kuchukuliwa kwa İzmir, Ayasuluk, Tire", "69a021ae"], "d": ["Kwa mujibu wa makala ya TDV ya Aydınoğulları, Mübârizüddin Gazi Mehmed Bey, baada ya kuchukua eneo hili kutoka kwa Sâsâ Bey, bey wa mpakani wa Germiyanoğulları, alitawala Aydın-ili mwaka 1308; alichukua sehemu ya Kiislamu ya İzmir pamoja na Ayasuluk (Selçuk), Tire na Bodemya. Alifanya Ayasuluk kuwa kituo cha majini na aligawanya ardhi alizozichukua kati ya wanawe watano — beylik katika miongo iliyofuata, hasa katika enzi ya mwanawe Umur Bey, ingekuwa nguvu ya maamuzi katika uanamaji wa Aegean.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Mwisho wa kivitendo wa Dola ya Waseljuk ya Anatolia — utawala wa moja kwa moja wa Ilhanlı", "00f85ecb"], "d": ["Kwa mujibu wa makala ya TDV ya Mesud II, II. Gıyâseddin Mesud, aliyefariki Kayseri mwaka 708 (1308) baada ya ugonjwa mrefu, kwa maoni yanayokubaliwa kwa jumla, ndiye mtawala wa mwisho wa Dola ya Waseljuk ya Anatolia — wagombea waliopandishwa kiti baada ya kifo chake hawakupata kutambuliwa na mamlaka za ndani wala na Ilhanlı. Eneo lilikuwa tayari likitawaliwa kwa vitendo na maafisa wa Ilhanlı katika utawala wote wa Mesud; kwa kifo chake utawala huu wa moja kwa moja ulipoteza pia kifuniko chake cha kimaumbo katika vituo kama Konya, Niğde na Aksaray.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Kuenea kwa Beylik ya Candaroğulları hadi Kastamonu-Çankırı-Bartın-Safranbolu", "64e39ad0"], "d": ["Kwa mujibu wa makala ya TDV ya Candaroğulları, beylik ilianzishwa mwanzoni mwa karne ya XIV katika eneo la Kastamonu-Sinop na Şemseddin Yaman Candar, aliyepewa Eflani na viunga vyake kama iktâ na mtawala wa Ilhanlı Geyhatu; kwa sababu ya ukosefu wa vyanzo tarehe kamili ya kuanzishwa haijulikani. Mrithi wa Candar, Süleyman Bey, anatajwa kuwa mtawala aliyechukua nafasi ya Beylik ya Çobanoğulları — yaani eneo la Kastamonu na Çankırı lilipita kutoka kwa Çobanoğulları, na mstari wa Bartın-Safranbolu-Eflani kutoka utawala wa moja kwa moja wa Ilhanlı hadi Candaroğulları.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Kutekwa kwa Rodos na Visiwa Kumi na Viwili na Wapiganaji wa St. Jean (Hospitalier)", "67885b4b"], "d": ["Makala ya TDV ya Rodos inaandika kwamba kisiwa kilipita mikononi mwa Wapiganaji wa St. Jean (Hospitalier/İsbitâriyye) mwaka 1309; historia ya kawaida ya Hospitalier (taz. J. Riley-Smith, The Knights Hospitaller) inafafanua kwamba mzingiro ulianza majira ya joto ya 1306, na kwamba mji wa Rodos, uliopinga kwa muda mrefu kwa nyongeza za Bizanti, ulianguka kwa vikosi vya Grand Master Foulques de Villaret tarehe 15 Agosti 1310 tu. Kisiwa tangu tarehe hii hadi ushindi wa Ottoman wa 1522 kingekuwa kitovu cha wapiganaji, na Visiwa Kumi na Viwili vinavyokizunguka pia vilipita kutoka Bizanti hadi utawala wa Hospitalier katika mchakato huo huo.", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["Mashujaa wa Livonia warudisha ngome ya Dünaburg kutoka Lithuania", "92119516"], "d": ["Walithuania, karibu mwaka 1281, walikuwa wamechukua Jersika na kuibadilisha na ngome ya Dünaburg ya Agizo. Ngome ilipita tena mikononi mwa mashujaa wa Livonia mwaka 1313 na ikabaki kitovu cha komturlük cha Agizo.", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Kuchukuliwa kwa İstanköy (Kos) na Wapiganaji wa Saint Jean", "445666f7"], "d": ["Kwa mujibu wa makala ya TDV ya İstanköy, Wapiganaji wa Saint Jean, baada ya kukaa Rodos, walichukua pia İstanköy (1315) na kujenga ngome mpya. Kisiwa hivyo kiliingia chini ya utawala wa wapiganaji uliodumu hadi 1523; baada ya kuanguka kwa mji wa Rodos mwaka 1310, ni chini ya utawala gani Kos ilikuwa haijaelezewa kwa kina katika TDV.", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["Wadhifa wa metropolitan wahamia Moscow", "d20099f8"], "d": ["Metropolitan Petr, kichwa cha Kanisa la Kiorthodoksi la Urusi, alihamisha kitovu chake cha kidini hadi Moscow. Hii ilikuwa mwanzo wa kupanda kwa Moscow si kama kitovu cha kisiasa tu bali pia cha kidini na iliimarisha uhalali wa ukuu.", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["Agizo la Livonia lawa bwana mkuu wa mji wa Riga", "21453047"], "d": ["Askofu mkuu wa Riga na mji, vilivyopigana dhidi ya Agizo kwa msaada wa wakuu wakuu wa Lithuania Vytenis na Gediminas, vilishindwa mwaka 1330; Agizo la Livonia likawa bwana mkuu wa mji. Kwa mkataba wa Salaspils wa 1452 Riga iliingia chini ya ubwana mkuu wa pamoja wa Agizo na askofu mkuu.", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Kuanzishwa kwa Beylik ya Eretna — Anatolia ya Kati baada ya Ilhanlı", "a67bacd9"], "d": ["Kwa mujibu wa makala ya TDV ya Eretnaoğulları, Alâeddin Eretna, afisa wa Ilhanlı wa asili ya Kiuygur, baada ya kifo cha mtawala wa Ilhanlı Ebû Said Bahadır Han mwaka 1335, aligeuza unaibu wa Ilhanlı Anatolia kuwa utawala huru kwa vitendo; kwanza alionekana kama naib wa sultani wa Kimamluki, mwaka 1340 aliondoa jina la Mamluki kwenye khutba na karibu 1341 alitangaza uhuru kamili. Beylik, iliyokuwa na kitovu Sivas kwanza, kisha Kayseri, hadi kifo chake (1352) iliunda utawala mpana wa Anatolia ya Kati uliojumuisha Amasya, Tokat, Çorum, Niğde, Aksaray na Erzincan na ilimalizwa na Kadı Burhâneddin mwaka 1381.", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["Wahabsburg wachukua Carniola na Carinthia (Ljubljana)", "039918d3"], "d": ["Kwa kifo cha Duke wa Carinthia na Count wa Tyrol VI. Heinrich bila mrithi tarehe 2 Aprili 1335 katika Ngome ya Tyrol, kulingana na makubaliano ya siri yaliyofanywa na Ludwig wa Bavaria tarehe 23 Novemba 1330, ndugu wa Habsburg II. Albrecht na IV. Otto walipokea Dukedom ya Carinthia na Carniola iliyoitegemea (eneo ambalo Ljubljana ya leo pia imo) kwa hati ya kifalme; Tyrol, hata hivyo, ilibaki tofauti kupitia binti ya Heinrich. Hii ilikuwa mojawapo ya hatua kubwa za kwanza za upanuzi wa Wahabsburg katika eneo la Alps na Carniola ingebaki mikononi mwa Habsburg/Austria (kwa kukatika) hadi 1918.", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Kuanzishwa kwa Dola ya Celayirî — Azerbaijan baada ya Ilhanlı", "a13ada90"], "d": ["Kwa mujibu wa makala ya TDV ya Celâyirliler, Hasan-ı Büzürg, mjukuu wa emîr wa Ilhanlı Noyan, akitumia mapambano ya kiti yaliyolipuka kwa kifo cha mtawala wa Ilhanlı Ebû Said Bahadır Han, mwaka 1340 alianzisha dola huru yenye kitovu cha Tebriz. Wacelâyirî hivyo wakawa nasaba kubwa ya kwanza iliyojaza pengo la baada ya Ilhanlı Azerbaijan na viunga vyake; katika enzi ya mrithi wake Üveys (1356-1374) ardhi zao zingepanuka hadi Musul na Diyarbekir.", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["Ukuu Mkuu wa Nizhny Novgorod-Suzdal waanzishwa — Khan ampa Konstantin Vasilyeviç yarlık", "c69f5198"], "d": ["Khan wa Golden Horde Özbek (katika künye Özbek/Canibek) alimpa mkuu wa Suzdal Konstantin Vasilyeviç utawala wa Nizhny Novgorod-Gorodets; ukuu ukawa mpinzani wa Moscow na mwaka 1392 uliunganishwa na Moscow na I. Vasili.", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["Denmark yauza Estonia ya Kaskazini (Reval na Narva) kwa Agizo la Livonia", "6861ba55"], "d": ["Ufalme wa Denmark uliuza ardhi zake huko Estonia ya Kaskazini pamoja na Reval na Narva kwa Agizo la Livonia. Eneo lilibaki mikononi mwa Agizo hadi Vita vya Livonia.", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["Mkataba wa Bolotovo — Novgorod yatambua uhuru wa Pskov", "08eca44d"], "d": ["Novgorod ilitambua Pskov kama 'ndugu mdogo'; Pskov iliishi kama jamhuri huru ya mji yenye veçe yake na posadnik hadi ilipounganishwa na Moscow mwaka 1510.", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["I. Vasili aunganisha Ukuu wa Nizhny Novgorod-Suzdal na Moscow", "5ecf441b"], "d": ["Kwa yarlık aliyopokea kutoka kwa Khan Toktamış, I. Vasili aliunganisha Nizhny Novgorod, Gorodets na Suzdal na Moscow; kufunguka kwa Moscow kuelekea mabonde ya Volga na Oka kulianza.", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["Vytautas achukua Smolensk — Ukuu wa Smolensk waunganishwa na Lithuania", "1a68300c"], "d": ["Vytautas aliteka Smolensk; mji ulibaki katika Ukuu Mkuu wa Lithuania hadi ulipopita kwa Moscow mwaka 1514.", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["Bağdat kupita mikononi mwa Karakoyunlu — kushindwa kwa Sultani wa Celayirî Ahmed", "a42ebe92"], "d": ["Kwa mujibu wa makala ya TDV ya Karakoyunlular, Kara Yûsuf, tarehe 28 Rebîülâhir 813 (30 Agosti 1410), alimshinda vibaya Sultani wa Celayirî Ahmed karibu na Tebriz; baada ya kifo cha Sultani Ahmed, mwaka 814 (1411) alimtangaza mwanawe Pîr Budak sultani Tebriz na mwaka huo huo mwana wake mkubwa Şah Mehmed aliiteka Bağdat. Hivyo Bağdat, iliyokuwa mji mkuu wa Celayirî kwa karibu karne moja, pamoja na mstari wa Basra-Musul-Kerkük unaoizunguka, iliingia chini ya utawala wa Karakoyunlu.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["Erzincan na Kemah zilipita kwa Akkoyunlu — Karayülük Osman Bey", "122460d4"], "d": ["Baada ya kifo cha Kara Yûsuf, kwa ombi la wakazi wa Erzincan, Yâr Ali, mjukuu wa Mutahharten, alikuwa gavana wa mji. Katika wakati wake bey wa Akkoyunlu Karayülük Osman alichukua Erzincan na kuiunganisha na ardhi za Akkoyunlu. Tangu tarehe hii Erzincan ikawa mahali palipobadilisha mikono mara kwa mara, wakati mwingine kati ya Akkoyunlu na Karakoyunlu, wakati mwingine kati ya şehzade wa Akkoyunlu.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["Kuanzishwa kwa Hanlık ya Kazan — Uluğ Muhammed Han kutengana na Altınorda", "335a7408"], "d": ["Kwa mujibu wa makala ya TDV ya Kazan Hanlığı, Uluğ Muhammed Han, aliyepoteza kiti chake katika mji mkuu wa Altınorda Saray, kwanza alirudi Belev na familia yake na askari wapatao 3000, mwaka 1437-1438 alipambana na Knez wa Kirusi II. Vasili na kisha akakaa mji wa Kazan; kwa msaada wa wenyeji aliweka hapa misingi ya hanlık mpya. TDV inabainisha kwamba mchakato wa kuanzishwa ulikamilika kati ya 1437-1445 na kwamba hanlık ilipata hadhi kamili ya uhuru kuanzia 1445 — ramani inachukua mwanzo wa mchakato huu, mwaka 1438 ambapo Uluğ Muhammed alikaa Kazan.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["Kuanzishwa kwa Hanlık ya Kırım — Hacı Giray kuwa huru kutoka Altınorda", "5728223e"], "d": ["Kwa mujibu wa makala ya TDV ya Kırım, Hanlık ya Kırım ilijitokeza kama zao la kugawanyika kwa Altın Orda kwa mapambano ya kiti katika nusu ya pili ya karne ya XIV; sarafu ya zamani zaidi iliyochapishwa na mwanzilishi halisi wa hanlık Hacı Giray inabeba tarehe 845 (1441-42), na hii inahesabiwa kuwa tarehe rasmi ya kuanzishwa kwa hanlık. Mwaka huo huo Hacı Giray aliimarisha nafasi yake Kırım kwa kuanzisha urafiki na Moscow na familia za mabey wa eneo hilo, kuanzia na kabila la Şirin, zilijiunga na upande wake.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["Cihan Şah alichukua Erzincan — utawala wa Karakoyunlu", "0c928cc4"], "d": ["Mtawala wa Karakoyunlu Cihan Şah mwaka 854 (1450) alituma jeshi Erzincan na kuchukua mji kutoka kwa Akkoyunlu. Kupotea huku kulisababisha mahusiano kati ya bey wa Akkoyunlu Cihangir Mirza na kaka yake Hasan Bey (Uzun Hasan) kuvunjika.", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["Cihan Şah wa Karakoyunlu kuchukua Iran ya Timurî (Rey, İsfahan, Fars, Kirman)", "c6fbb3f5"], "d": ["Kwa mujibu wa makala ya TDV ya Karakoyunlular, mtawala wa Karakoyunlu Cihan Şah, akitumia mapambano ya kiti kati ya şehzade wa Timurî, katika miaka 856-857 (1452-1453) alichukua chini ya utawala wake vilâyet za Rey, İsfahan, Fars na Kirman; hii ni kilele cha mchakato wa upanuzi ulioanza baada ya kifo cha Şâhruh Mirza mwaka 1447 na ukafunguliwa kwa kuunganishwa kwa Sultâniye-Kazvin. Ardhi za Timurî Iran ya kusini-kati hivyo zilipita kwa Karakoyunlu; utawala wa Cihan Şah ungefikia upana wa kujumuisha Azerbaijan, Arrân, Irâk-ı Acem, Irâk-ı Arab, Fars, Kirman na Anatolia Mashariki mwaka 1466.", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["Kurudishwa kwa Bordeaux na Uingereza — kampeni ya mwisho ya Gascony ya John Talbot", "01b2b7be"], "d": ["Bordeaux, iliyopotezwa kwa Wafaransa mwaka 1451, kwa wakazi wake kuasi dhidi ya kikosi cha Kifaransa na kufungua milango, ilisalimu amri kwa jeshi la Kiingereza lililoongozwa na kamanda mzee John Talbot usiku wa 22-23 Oktoba 1452; huu ulikuwa ushindi wa mwisho na wa muda mfupi wa Uingereza Gascony katika Vita vya Miaka Mia. Bordeaux ingerudi kwa Ufaransa kwa kudumu mwaka mmoja baadaye baada ya Vita vya Castillon.", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["Kurudi kwa kudumu kwa Bordeaux kwa Ufaransa — mwisho wa kweli wa Vita vya Miaka Mia", "b0a86f6c"], "d": ["Kwa kifo cha John Talbot na kuangamizwa kwa jeshi lake katika Vita vya Castillon tarehe 17 Julai 1453, upinzani wa Waingereza huko Gascony ulipoporomoka; Bordeaux iliyozingirwa ilijisalimisha kwa vikosi vya Ufaransa tarehe 19 Oktoba 1453. Kujisalimisha huku huhesabiwa wakati ambapo Vita vya Miaka Mia vilivyodumu miaka 116 vilimalizika kwa vitendo (mkataba rasmi wa amani haukutiwa saini kamwe) na kulipunguza utawala wa Uingereza katika bara la Ulaya hadi Calais.", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["Uzun Hasan alirudisha Erzincan — Akkoyunlu tena", "550d010a"], "d": ["Uzun Hasan, baada ya kuwashinda Karakoyunlu, alirudisha Erzincan chini ya utawala wa Akkoyunlu. Mji ulibaki ndani ya mipaka ya Akkoyunlu hata baada ya Vita vya Otlukbeli vya 1473.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["Mkataba wa Pili wa Thorn — Danzig (Gdańsk) na Prussia Magharibi zilifungwa na Poland", "e2152dae"], "d": ["Mkataba wa Pili wa Thorn (Toruń) uliomaliza Vita vya Miaka Kumi na Mitatu vilivyoanza kwa Shirikisho la Prussia kuasi mwaka 1454 dhidi ya utawala wa Wapiganaji wa Kijerumani (Teutonic Order) ulitiwa saini tarehe 19 Oktoba 1466; Wapiganaji waliiachia Ufalme wa Poland Pomerania Mashariki ikijumuisha Danzig (Gdansk), mdomo wa Vistula ikijumuisha Elbing (Elbląg) na eneo la Kulm — ardhi hizi zilipata jina 'Prussia ya Kifalme'. Prussia Mashariki ingebaki kwa Wapiganaji hadi 1525.", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["III. İvan anunua nusu iliyobaki ya Ukuu wa Rostov", "5203244f"], "d": ["Nusu iliyokuwa mikononi mwa wakuu wa Rostov ilikabidhiwa kwa Moscow; pamoja na nusu nyingine iliyopita Moscow mwaka 1332, ardhi ya Rostov iliunganishwa kabisa na Moscow.", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["Ukuu Mkuu wa Tver waunganishwa na Moscow — III. İvan achukua mji", "fa3f924e"], "d": ["Kwa kuzingirwa na jeshi la Moscow, mkuu mkuu wa mwisho wa Tver Mihail Borisoviç alikimbilia Lithuania, Tver ilijisalimisha kwa III. İvan; mpinzani mwenye nguvu zaidi wa Moscow hivyo aliondolewa.", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["Malkia Katerina Cornaro alikabidhi Kupro kwa Venice — mwisho wa dola ya Wapiganaji wa Msalaba", "e24d3f3a"], "d": ["Katerina Cornaro wa Venice, aliyetawala Kupro kama malkia mlezi baada ya kifo cha mumewe Mfalme II. Jacques mwaka 1473, kwa kuwa hakuwa na mrithi, kwa shinikizo la serikali ya Venice tarehe 26 Februari 1489 alijiuzulu na kukabidhi haki za utawala kisiwani kwa doge na Jamhuri ya Venice; kwa malipo alihifadhi cheo cha malkia na akapewa kontlik ya Asolo huko Terraferma. Kwa kukabidhi huku, utawala wa nasaba ya Lusignan uliodumu tangu 1192 na dola ya mwisho ya Wapiganaji wa Msalaba ulimalizika, na kisiwa kilibaki chini ya utawala wa Venice hadi ushindi wa Ottoman wa 1570-71.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["Kuanguka kwa Granada — mwisho wa dola ya mwisho ya Kiislamu katika Peninsula ya Iberia", "46e5201b"], "d": ["Mtawala wa mwisho wa Emirliği ya Nasrî ya Granada, iliyodhoofishwa na mzingiro wa hatua kwa hatua wa miaka kumi na mgawanyiko wa ndani, Ebû Abdullah (Boabdil), kwa mujibu wa masharti ya ukarimu ya kusalimu amri (Kapitulasyon za Granada) yaliyotiwa saini Novemba 1491, alikabidhi funguo za mji kwa Wafalme wa Kikatoliki Fernando na Isabel tarehe 2 Januari 1492; Boabdil alipoondoka Elhamra, dola ya mwisho ya Kiislamu katika Peninsula ya Iberia ilimalizika na Reconquista ilikamilika. Mwaka huo huo kulifuata kufukuzwa kwa Wayahudi (Machi) na safari ya Kristof Kolomb (Agosti).", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["Vita vya Vedroşa — Moscow yashinda jeshi la Lithuania; ardhi za Bryansk na Seversk zabaki Moscow", "d3f61400"], "d": ["Katika vita vya Moscow-Lithuania vya 1500-1503, jeshi la Moscow chini ya amri ya Daniil Şçenya lilishinda jeshi la Hatman Konstanty Ostrogski kwenye mto Vedroşa karibu na Dorogobuj na likamkamata hatman. Miji ya Bryansk na Seversk iliyochukuliwa katika majira ya kuchipua ya mwaka huo huo ilibaki mikononi mwa Moscow; mwishoni mwa vita takriban theluthi moja ya ardhi za Lithuania ilikuwa imepita kwa Moscow.", "e5879803"]},
"OLAYLAR_EK16:1503-04-02:0":{"b": ["Mapatano ya Moscow-Lithuania — eneo la Çernigov-Seversk lilipita kwa Moscow", "8e4c56f9"], "d": ["Vita vya Moscow-Lithuania vya 1500-1503 vilimalizika kwa mapatano ya miaka sita kwa upatanishi wa mfalme wa Hungaria-Bohemia II. Ulászló; Grand Principality ya Lithuania ililazimika kuiachia Grand Principality ya Moscow eneo pana linaloundwa na takriban theluthi moja ya Grand Principality, ikijumuisha eneo la Çernigov-Seversk (Çernigov, Novgorod-Seversk, Starodub, karibu na Bryansk) na baadhi ya ardhi karibu na Smolensk na Polotsk. Hii ilikuwa mojawapo ya ongezeko kubwa zaidi la Moscow katika mchakato wa 'kukusanya' ardhi za Kirusi.", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Şeybânî Han kuchukua Herat na Horasan kutoka kwa Timurî", "a81d8575"], "d": ["Kwa mujibu wa makala ya TDV ya Şeybânî Han, mtawala wa Kiuzbeki Şeybânî Han, baada ya kuchukua Endîcan, Fergana, Hisâr, Kunduz na Belh kati ya 1503-1505, mwaka 913 (1507) pia alichukua Herat, mji mkuu wa Timurî; makala ya Horasan ya Encyclopaedia Iranica inatoa tarehe kamili ya ushindi huu — mji ulianguka tarehe 8 Muharrem 913 (20 Mei 1507), na wiki moja baadaye tarehe 15 Muharrem (27 Mei) khutba ilisomwa kwa jina la Şeybânî Han na ushindi ukarasimishwa. Horasan yote, ikijumuisha Meşhed, ilipita kutoka kwa Timurî hadi kwa Şeybânî ndani ya mwaka huo huo; hii ilimaanisha nasaba ya Timurî kupoteza pia, baada ya Mâverâünnehir, ngome kubwa ya mwisho Iran.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["Kuanguka kwa Oran kwa Uhispania — kampeni ya Afrika Kaskazini ya Kardinali Cisneros", "86ed8ac1"], "d": ["Vehrân (Oran), iliyodhibiti njia ya baharini ya Mediterania ya Magharibi na bandari ya Tilimsân, ilikuwa imekua kwa wakimbizi Waislamu na Wayahudi wa Andalusia waliokimbia Gırnata mwaka 1492. Ufalme wa Castilla, uliochukua miji ya bandari ya pwani ya Mağrib moja moja mwanzoni mwa karne ya XVI, ulivamia Vehrân tarehe 17 Mei 1509; sehemu kubwa ya wakazi iliuawa, wengine walitekwa na mjini hakubaki idadi ya Waislamu na Wayahudi. Wahispania walipanua kuta na ngome; Vehrân ilibaki mikononi mwa Uhispania hadi 1708.", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["Smolensk yajisalimisha kwa Moscow — III. Vasili aingia mjini", "46c61446"], "d": ["Katika kuzingirwa kwa tatu kwa vita vya Moscow-Lithuania vya 1512-1522, kikosi cha Lithuania kilijisalimisha tarehe 31 Julai; jeshi la Moscow liliingia mjini kwa sherehe tarehe 1 Agosti na watu waliapa utii kwa III. Vasili. Smolensk ni faida kubwa zaidi ya Vasili magharibi; kushindwa kulikopatikana Orsha wiki chache baadaye hakukusababisha kurudisha mji.", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["Kuunganishwa kwa Nchi za Chini na taji ya Uhispania — kifo cha Ferdinand, kutawazwa kwa Şarlken", "fbe0dbd2"], "d": ["Kwa kifo cha Mfalme wa Aragon II. Ferdinand tarehe 23 Januari 1516, mjukuu wake Şarlken, aliyekuwa tayari akitawala Nchi za Chini (Ubelgiji-Uholanzi-Luxembourg ya leo na sehemu ya Ufaransa Kaskazini) kama Duke wa Burgundy tangu 1506, alikuwa mrithi pia wa viti vya Castilla na Aragon na tarehe 14 Machi 1516 alitangazwa mfalme wa Uhispania huko Brüksel. Hivyo ardhi hizi zilianza kuhesabiwa, kwa njia ya muungano wa kibinafsi, kuwa zimefungwa moja kwa moja na taji ya Uhispania, si na tawi la Kijerumani/Kiaustria la nasaba ya Habsburg — mwaka 1519 Şarlken alipochaguliwa kuwa Maliki wa Kirumi Takatifu, vitambulisho hivi viwili (mfalme wa Uhispania na maliki wa Kijerumani-Kirumi) vingeungana katika mtu mmoja, na utegemezi wa eneo kwa Uhispania ungedumu hadi 1556 Şarlken alipojiuzulu na kumwachia mwanawe II. Filip urithi.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["Usultani wa Demak kuiangamiza Majapahit na kutawala pwani ya Java", "7da602b5"], "d": ["Kwa mujibu wa makala ya TDV ya Demak, Usultani wa Demak, dola ya kwanza huru ya Kiislamu ya Java, ulianzishwa na Raden Patah katika robo ya mwisho ya karne ya XV; kulingana na vyanzo vya Kijava, Ufalme wa Majapahit wa Kihindu-Kibudha uliokuwa ukianguka ulitoweka kwa mashambulizi ya Demak. Mwaka 1527 Demak ilichukua Tuban, iliyotajwa katika vyanzo vya Kichina tangu karne ya XI kama bandari muhimu kwa watawala wa Majapahit — huu ni mwaka ambapo mabaki ya mwisho ya Majapahit nayo yalifungwa na Demak, na ni mwamba wa mabadiliko katika mchakato wa Uislamu wa sehemu kubwa ya Java.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["Norwe kupunguzwa hadi mkoa unaofungwa na taji ya Denmark", "8e2f274e"], "d": ["Mfalme wa Denmark III. Christian, katika hati ya kutawazwa (håndfæstning) ya 1536, alitangaza kwamba Norwe haitahesabiwa tena kuwa ufalme tofauti, kwamba itatawaliwa kama mkoa wa Denmark na kwamba Baraza la Dola la Norwe (riksråd) limefutwa; uamuzi huu ulikuwa halisi mwaka 1537 kwa Kanuni za Kanisa za Denmark kutekelezwa pia Norwe na upinzani wa askofu wa Kiskoti-Kinorwe Olav Engelbriktsson ukavunjwa. Ingawa Norwe kwa vitendo iliendelea kwa muda zaidi kuhifadhi sheria na taasisi zake, hadhi yake ya kisiasa haikuwa tena ufalme huru bali mkoa unaofungwa na taji ya Denmark — hali hii ingedumu hadi 1814.", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["Narva yachukuliwa na Warusi — mji mkubwa wa kwanza wa Vita vya Livonia", "c21130d7"], "d": ["Majeshi ya IV. İvan yaliteka Narva; Urusi ilifika pwani ya Baltic. Narva ilibaki mikononi mwa Urusi hadi ilipopita kwa Uswidi mwaka 1581.", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["Dorpat (Tartu) yachukuliwa na Warusi", "f941a504"], "d": ["Majeshi ya Urusi katika msafara wa kiangazi wa 1558 yalichukua Dorpat (Tartu) na ngome zinazoizunguka; mji ulibaki chini ya utawala wa Urusi hadi Usitishaji wa Mapigano wa Jam Zapolski wa 1582.", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["Reval (Tallinn) yaingia chini ya ulinzi wa Uswidi — Estonia ya Kaskazini yapita kwa Uswidi", "3c183267"], "d": ["Wakati Shirikisho la Livonia lilipokuwa likivunjika, baraza la mji wa Reval mwaka 1561 lilitoa utii kwa Mfalme wa Uswidi XIV. Erik; Estonia ya kaskazini ilibaki Uswidi hadi Vita Kuu ya Kaskazini (1721).", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Mkataba wa Vilnius — Shirikisho la Livonia lilivunjika, Kurland na Livonia zilifungwa na Poland-Lithuania (isipokuwa mji wa Riga)", "d1ceaad5"], "d": ["Gotthard Kettler, mkuu wa mwisho mkubwa wa Shirikisho la Livonia lililovunjika chini ya shinikizo la Urusi wakati wa Vita vya Livonia, kwa mkataba uliotiwa saini Vilnius tarehe 28 Novemba 1561 (Pacta Subiectionis) aliingia chini ya ulinzi wa Grand Duke wa Lithuania na Mfalme wa Poland II. Zygmunt August; sehemu kubwa ya Livonia, isipokuwa mji wa Riga, ilifungwa na Poland-Lithuania, na Kettler akawa duke wa kwanza wa Dukedom ya Kurland. Hili lilikuwa pazia la mwisho la Agizo la Wapiganaji wa Livonia katika mpito kutoka Zama za Kati hadi Zama Mpya.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["Uswidi yachukua Narva kutoka Urusi", "5a7f7a6a"], "d": ["Katika miaka ya mwisho ya Vita vya Livonia, vikosi vya Uswidi vilichukua Narva iliyokuwa mikononi mwa Urusi tangu 1558; mji ulibaki Uswidi hadi 1704.", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["Mji huru wa Riga waunganishwa na Poland-Lithuania", "77dba329"], "d": ["Riga, iliyobaki mji huru katika Vita vya Livonia, iliunganishwa na Umoja wa Poland-Lithuania mwaka 1581; mji ulibaki katika Umoja hadi ulipopita kwa Uswidi mwaka 1621.", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Tangazo la Kukataa (Plakkaat van Verlatinghe) — Uholanzi ilitangaza uhuru wake kutoka kwa Uhispania", "a632aaee"], "d": ["Vita vya Miaka Themanini vilipokuwa vikiendelea, Baraza Kuu (Staten-Generaal) la majimbo ya Uholanzi yaliyofungwa na Muungano wa Utrecht, kwa Tangazo la Kukataa lililokubaliwa tarehe 26 Julai 1581, lilimtangaza Mfalme wa Uhispania II. Felipe kuwa 'dhalimu' na kukataa utii kwake; waraka huu unahesabiwa kuwa tamko la kuanzishwa kwa Majimbo ya Muungano (Jamhuri ya Uholanzi) yaliyo huru kwa vitendo. Kutambuliwa kwa mwisho na Uhispania kungesubiri Vestfalya ya 1648, lakini kutengana kwa kivitendo ni siku hii.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["Kuanguka kwa Smolensk kwa Poland-Lithuania — mwisho wa mzingiro wa miezi 20", "4e9678e3"], "d": ["Katika Enzi ya Machafuko (Smuta), jeshi la Mfalme wa Poland III. Zygmunt lilifungua pengo katika kuta za Smolensk, iliyozingirwa tangu Septemba 1609, kwa kulipua mtaro tarehe 13 Juni 1611 na likaichukua; upinzani wa miezi 20 ulimalizika. Smolensk ilibaki kwa Poland-Lithuania hadi 1654 na kuanguka huku kuliandaa msingi wa Mapatano ya Deulino (1618) yatakayotiwa saini miaka saba baadaye.", "25d6488d"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["Novgorod yachukuliwa na jeshi la Uswidi — Urusi ya kaskazini-magharibi yaingia chini ya udhibiti wa Uswidi katika Enzi ya Matatizo", "a8ab28bb"], "d": ["Jeshi la Uswidi la Jacob De la Gardie liliteka Novgorod; mji ukawa mji mkuu wa 'Dola ya Novgorod' chini ya ulinzi wa Uswidi hadi 1617, Karl Filip akaonyeshwa kama mgombea wa tsar.", "281592c2"]},
"OLAYLAR_EK16:1617-03-09:0":{"b": ["Mkataba wa Stolbova — Urusi ilipoteza pwani ya Baltic (İngria) kwa Uswidi", "175dc175"], "d": ["Mkataba wa Stolbova uliomaliza Vita vya İngria ulitiwa saini tarehe 27 Februari 1617 katika kijiji cha Stolbova kusini mwa Ziwa Ladoga; Urusi ilirudisha Novgorod na ardhi nyingine za kaskazini, wakati Uswidi ilishikilia Karelia na İngria (kati ya Estonia na Finland, ikijumuisha ngome za İvangorod-Yam-Koporye-Oreşek) na pwani ya moja kwa moja ya Urusi hadi Baltic ilikatwa. Kukatwa huku kungedumu hadi Petro Mkuu alipoanzisha St. Petersburg katika eneo hilo hilo mwaka 1703.", "7e70e3e6"]},
"OLAYLAR_EK16:1617-03-09:1":{"b": ["Mkataba wa Stolbovo — Urusi yaiachia Uswidi Ingermanland, Novgorod yarudishwa", "e0bcbc7a"], "d": ["Urusi iliiachia Uswidi ukanda wa Neva na sehemu ya Karelia (Yam, Koporye, Ivangorod, Oreşek) na ikakatwa kutoka pwani ya Baltic; Uswidi ilirudisha Novgorod. Hali hii ilidumu hadi Vita Kuu ya Kaskazini ya I. Petro.", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Mapatano ya Deulino — Smolensk, Çernigov na Novgorod-Seversk ziliachiwa Poland", "6880d2c1"], "d": ["Mapatano ya Deulino yaliyomaliza Vita vya Poland-Urusi vya 1609-1618 yalitiwa saini tarehe 11 Desemba 1618 na yalitoa kusitisha mapigano kwa miaka 14,5; Urusi ililazimika kuiachia Shirikisho la Poland-Lithuania Smolensk (isipokuwa Vyazma) na miji 29 ya maeneo ya Çernigov na Novgorod-Seversk — hii ilikuwa hasara nzito zaidi ya ardhi ya Enzi ya Machafuko (Smuta). Eneo lingebaki Poland hadi Mapatano ya Andrusovo ya 1667.", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["Uswidi yachukua Tartu (Dorpat) kutoka Poland — awamu ya pili ya Msafara wa Livonia", "46b7c86a"], "d": ["II. Gustav Adolf katika msafara wa 1625 aliteka Estonia ya Kusini na Livonia ya Kaskazini; Tartu ikawa mji wa Uswidi ambapo Akademia ya Gustav Adolf ingeanzishwa mwaka 1632.", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Baraza la Pereyaslav — Wakazak wa Zaporojye waliapa utii kwa tsar wa Urusi", "bcd8f8ef"], "d": ["Hetman wa Wakazak wa Zaporojye Bohdan Hmelnitski, aliyeasi dhidi ya Poland-Lithuania tangu 1648, katika Baraza la Pereyaslav la tarehe 18 Januari 1654 (Julian 8 Januari), lililohudhuriwa na ujumbe uliotoka Moscow chini ya uenyekiti wa Vasili Buturlin, aliapa utii kwa Tsar I. Aleksey Mihayloviç; hii inahesabiwa kuwa mwanzo wa Hetmanlık ya Kazak ya Ukraine kuingia chini ya ulinzi wa Urusi na ilihamisha udhibiti wa kivitendo wa eneo la Çernigov-Seversk kutoka Poland hadi Urusi — mpaka rasmi kwa upande mwingine ungechorwa na Mapatano ya Andrusovo ya 1667.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Kurudishwa kwa Smolensk na Urusi", "bf0eca92"], "d": ["Wakati wa Vita vya Poland-Urusi vilivyoanza 1654, jeshi la Urusi lilirudisha Smolensk, iliyozingirwa tangu Julai, tarehe 3 Oktoba 1654 kikosi cha Poland kiliposalimu amri; mji uliopotezwa kwa Poland mwaka 1611 ulirudi Urusi baada ya miaka 43. Hii ilikuwa mojawapo ya hatua muhimu zaidi za mchakato wa Urusi wa kugeuza hasara za Enzi ya Machafuko na ikawa ya kudumu kwa Mapatano ya Andrusovo ya 1667.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Mapatano ya Andrusovo — Kiev na Ukraine ya Ufuo wa Kushoto zilipita kwa Urusi", "799be067"], "d": ["Mapatano ya Andrusovo yaliyomaliza Vita vya Poland-Urusi vya 1654-1667 yalitoa kusitisha mapigano kwa miaka 13,5; Urusi ilipata Smolensk, eneo la Çernigov-Seversk na Ukraine ya ufuo wa kushoto wa Dinyeper na — mwanzoni kwa miaka miwili, kwa vitendo kwa kudumu — mji wa Kiev. Mkataba huu uliweka msingi wa kisheria wa kugawanywa kwa ardhi za Ukraine kando ya Dinyeper kati ya Poland na Urusi (na Kiev kubaki Urusi).", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["Urusi yachukua Nöteborg (Oreşek) kutoka Uswidi — ngome ya kwanza ya Neva ya Vita Kuu ya Kaskazini", "28d180eb"], "d": ["Majeshi ya I. Petro yaliizingira na kuchukua Nöteborg (kwa Kirusi Oreşek) kwenye mdomo wa Ladoga na kuipa jina Şlisselburg ('Ngome ya Ufunguo'); hii ilifungua njia ya kufika Neva na kuanzishwa kwa St. Petersburg mwaka 1703.", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Kuanzishwa kwa St. Petersburg — dirisha la Urusi linalofunguka kwa Magharibi", "ba196be0"], "d": ["Katika Kisiwa cha Sungura kwenye delta ya Neva iliyorudishwa hivi karibuni kutoka kwa Uswidi wakati wa Vita Kuu vya Kaskazini, Petro Mkuu aliweka msingi wa Ngome ya Petropavlovsk (Ngome ya Peter-Pavel) tarehe 16/27 Mei 1703; siku hii inakubaliwa kuwa tarehe ya kuanzishwa kwa mji wa St. Petersburg. Petro alibuni delta ya kinamasi kama 'dirisha' linalofunguka kwa Magharibi na mji ukawa mji mkuu mpya wa Urusi mwaka 1712 — eneo lingeunganishwa rasmi na Urusi kwa Mkataba wa Nystad wa 1721.", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["Kutekwa kwa Menorca na vikosi vya Uingereza-Uholanzi", "3ca66a83"], "d": ["Wakati wa Vita vya Urithi wa Uhispania, vikosi vya Uingereza-Uholanzi, vilivyotenda kama washirika wa archduke wa Austria VI. Karl, chini ya amri ya Jenerali James Stanhope vilitua kisiwani tarehe 14 Septemba 1708 na tarehe 28-29 Septemba viliporomosha ulinzi wa Kihispania na kuchukua udhibiti wa Menorca (kukabidhiwa rasmi kwa ngome kuu Fort St. Philip kulifika tarehe 24 Novemba). Bandari ya kimkakati ya Menorca Mahon ingekuwa kitovu cha mapambano ya Uingereza-Ufaransa-Uhispania kwa karne iliyofuata.", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Mkataba wa Rastatt — Vita vya Urithi wa Uhispania vilimalizika, Uholanzi ya Kihispania na Milano zilipita kwa Austria", "3c0e086f"], "d": ["Mkataba wa Rastatt uliomaliza Vita vya Urithi wa Uhispania kati ya Ufaransa na Austria ulitiwa saini tarehe 7 Machi 1714 (Utrecht mwaka 1713 ilikuwa imepanga mahusiano kati ya Uingereza na Ufaransa); kwa mkataba, Wahabsburg wa Austria walichukua Uholanzi ya Kihispania (Ubelgiji ya leo) na Napoli, Milano na Sardinia nchini Italia. Hili lilikuwa ongezeko kubwa zaidi la ardhi katika historia ya Austria na liliongeza kwenye uzito wa nasaba ya Habsburg Ulaya ya Kati mstari mpya Ulaya ya Magharibi na Kusini.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Mkataba wa Nystad — Vita Kuu vya Kaskazini vilimalizika, pwani za Baltic zilipita kwa Urusi", "068ffd06"], "d": ["Mkataba wa Nystad uliomaliza Vita Kuu vya Kaskazini vya miaka 21 ulitiwa saini Finland tarehe 10 Septemba 1721 (Julian 30 Agosti); Uswidi iliiachia Urusi Estonia, Livonia (ikijumuisha Riga), İngermanland na sehemu ya Finland ya kusini-mashariki (Karelia), na kwa malipo ilirudishiwa sehemu iliyobaki ya Finland na fidia ililipwa. Mkataba unahesabiwa kuwa mwisho wa hadhi ya Uswidi kama dola kubwa na uthibitisho rasmi wa kupanda kwa Urusi kama himaya ya Ulaya — I. Petro alipokea cheo cha 'Maliki' baada ya ushindi huu.", "f0c4fc4a"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["Ugawanyaji wa Kwanza wa Poland — kupotea kwa ardhi kwa Urusi na Austria", "2c56a0d8"], "d": ["Kwa mkataba uliotiwa saini tarehe 5 Agosti 1772 kati ya Urusi, Prussia na Austria, takriban theluthi moja ya ardhi za Shirikisho la Poland-Lithuania iligawanywa: Urusi ilichukua sehemu ya Belarus na Latvia ya leo (ikijumuisha Dünaburg, Polotsk, Vitebsk), Austria iliunganisha Galicia (Lvov na Podolia ya magharibi, ikijumuisha Yazlovets); Prussia ilichukua eneo la pwani Prussia ya Kifalme. Seym ya Poland iliidhinisha mkataba chini ya shinikizo tarehe 30 Septemba 1773 tu. Huu ulikuwa wa kwanza wa mgawanyo matatu uliodumu hadi 1795.", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Ugawanyaji wa Pili wa Poland — kupotea kwa ardhi kwa Urusi na Prussia", "31750484"], "d": ["Mageuzi ya katiba ya 1791 yalipozitia wasiwasi Urusi na Prussia, dola hizo mbili zilitia saini mkataba St. Petersburg tarehe 23 Januari 1793 na kuigawanya tena Poland: Urusi ilichukua sehemu kubwa ya Lithuania-Belarus na Ukraine ya magharibi (ikijumuisha Kamaniçe, Bar, Minsk), Prussia iliunganisha Poland Kuu ikijumuisha Gdansk na Poznan — jumla ya kilomita za mraba 307.000. Seym ya Poland chini ya shinikizo ililazimika kuidhinisha mkataba mwaka huo huo; huu ulikuwa mgawanyo wa muda mfupi ulioahirisha kuunganishwa kamili kwa Poland kwa miaka miwili. Siku hii (23 Januari 1793) katika Ugawanyaji wa Pili wa Poland Ukraine ya Ufuo wa Kulia, ikijumuisha Berdiçev, Fastov, Jitomir, Kaniv, Kostantinov, Uman na Çerkasi, ilipita kwa Urusi.", "656e71c2"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["Dukedom ya Kurland na Semigallia yaunganishwa na Urusi — duke wa mwisho Peter von Biron aachia", "8d0e410f"], "d": ["Katika mchakato wa Mgawanyo wa III wa Poland, wakuu wa Kurland walitoa utii kwa Katerina, Duke Peter von Biron alijiondoa kwenye kiti cha enzi; Kurland ikawa guberniya ya Urusi (katika vyanzo pia inatajwa tarehe 24 Oktoba 1795).", "4682774b"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["Ugawanyaji wa Tatu wa Poland — kutoweka kabisa kwa dola", "e3c02d6b"], "d": ["Urusi, Prussia na Austria, kwa makubaliano ya pande tatu yaliyotiwa saini St. Petersburg tarehe 24 Oktoba 1795, ziligawanya kabisa ardhi zilizobaki za Shirikisho la Poland-Lithuania: Urusi ilichukua Lithuania (ikijumuisha Vilnius, Kaunas) na sehemu iliyobaki ya Belarus, Prussia ilichukua Poland ya kati ikijumuisha Varşova, na Austria iliunganisha eneo la kusini ikijumuisha Krakov. Dola hizo tatu pia zilihakikishiana kijeshi ardhi mpya za kila mmoja na zilichukua tahadhari dhidi ya uwezekano wa Poland kuanzishwa upya. Huu ni kutoweka kabisa kwa dola ya Poland-Lithuania kama nchi huru; haingeanzishwa upya hadi karne ya XX.", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["Mwisho wa Jamhuri ya Venice — Baraza Kuu lilijivunja lenyewe", "5efed589"], "d": ["Jeshi la kampeni ya Italia ya Napoleon lilipovamia ardhi ya Venice na kuipa jamhuri uamuzi wa mwisho, Baraza Kuu (Maggior Consiglio) tarehe 12 Mei 1797 lilikubali kujivunja kwa kura 512 dhidi ya 20; doge wa mwisho Ludovico Manin aliacha wadhifa na utawala wa kiaristokrasia wa Jamhuri ya Venice, iliyoendelea kuwepo bila kukatika kwa zaidi ya miaka 1.100, ulimalizika. Ardhi zake kwanza ziliachiwa utawala wa muda wa kidemokrasia, kisha rasmi kwa Austria kwa Mkataba wa Campo Formio wa Oktoba 1797.", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["Mwisho wa Jamhuri ya Genoa — Napoleon alianzisha Jamhuri ya Liguria", "3d3e59ee"], "d": ["Mahali pa Jamhuri ya Genoa, iliyokabidhiwa kwa utawala wa muda mwanzoni mwa Juni 1797 kwa shinikizo la Napoleon katika kampeni ya Italia, tarehe 14 Juni 1797 'Jamhuri ya Liguria' ilitangazwa kwa katiba ya mtindo wa Kifaransa; Dukedom ya Genoa ya karne nyingi iligeuka kwa vitendo kuwa mojawapo ya dola tegemezi za Ufaransa. Jamhuri ingeunganishwa moja kwa moja na Ufaransa mwaka 1805 na ingeachiwa Ufalme wa Sardinia-Piedmont kwa Kongamano la Viyana la 1815.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Mkataba wa Campo Formio — kugawanywa kwa Venice kati ya Austria na Ufaransa", "9f29678c"], "d": ["Mkataba wa Campo Formio uliotiwa saini tarehe 17 Oktoba 1797 kati ya Napoleon Bonaparte na mwakilishi wa Austria Count Cobenzl uliiondoa rasmi Jamhuri ya Venice ya miaka elfu moja na kugawanya ardhi zake: mashariki ya mto Adige, Istria na pwani ya Dalmatia (ikijumuisha Split, Zadar, Şibenik, Kotor) ziliachiwa Austria, na Visiwa vya İyon (Korfu, Kefalonya, Zakynthos, Lefkada, na vituo vya Venice kwenye pwani ya Albania-Mora ikiwemo Preveze na Parga) vilipita kwa Ufaransa. Austria pia iliiachia Ufaransa ardhi zake za Nchi za Chini (Ubelgiji ya leo).", "296ee82f"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["Kusalimishwa kwa Malta kwa Uingereza — mwisho wa mzingiro wa Kifaransa wa miaka miwili", "fedc2867"], "d": ["Malta, iliyochukuliwa na Napoleon njiani kuelekea kampeni ya Misri mwaka 1798, kwa muda mfupi baadaye kwa uasi wa wakazi wa kisiwa iliingia chini ya kizuizi cha majini cha meli za Uingereza; mwishoni mwa mzingiro wa miaka miwili na njaa, kamanda wa Kifaransa Jenerali Vaubois alisalimu amri kwa Jenerali wa Kiingereza Pigot tarehe 5 Septemba 1800. Malta hivyo ilipita kutoka Jamhuri ya Ufaransa hadi ulinzi wa Uingereza na ingefungwa rasmi na taji ya Uingereza kwa Mkataba wa Paris wa 1814 — ikawa kituo muhimu zaidi cha majini cha Uingereza Mediterania.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Mkataba wa Amiens — Menorka ilirudishwa kwa Uhispania", "f341e4b8"], "d": ["Mkataba wa Amiens uliotiwa saini kati ya Ufaransa, Uhispania, Uholanzi na Uingereza (25 Machi 1802) ulimaliza kwa muda Vita vya Muungano wa Pili; Uingereza ilirudisha karibu ardhi zote ilizozichukua wakati wa vita (isipokuwa Ceylon na Trinidad) — mojawapo ilikuwa Menorka iliyochukuliwa kutoka kwa Uhispania mwaka 1798. Amani ilidumu mwaka mmoja tu, vita vililipuka tena Mei 1803, lakini Menorka haikupita tena mikononi mwa Waingereza baada ya mkataba huu.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Mkataba wa Fredrikshamn (Hamina) — Uswidi kuiachia Finland kwa Urusi", "c0d407bc"], "d": ["Mkataba wa Fredrikshamn (Hamina ya leo) uliomaliza Vita vya Urusi-Uswidi vya 1808-1809 ulitiwa saini tarehe 17 Septemba 1809; Uswidi iliiachia Urusi Finland yote, ikijumuisha Visiwa vya Åland. Finland ilipata hadhi ya Grand Duchy yenye uhuru mpana wa ndani iliyofungwa na Dola ya Urusi, na ikahifadhi imani ya Kilutheri na sheria ya Uswidi. Hii ilimaanisha mwisho wa kivitendo wa hadhi ya Uswidi kama nguvu kubwa katika Baltic. Kwa mkataba huu majimbo sita ya Finland na Västerbotten hadi mto Torne (Kokkola, Joensuu, Savonlinna, Tornio, Rovaniemi, İnari n.k.) yalipita kwenye Grand Duchy ya Finland iliyofungwa na Urusi.", "fb46c9a1"]},
"OLAYLAR_EK16:1810-03-04:0":{"b": ["Kuunganishwa kwa Ufalme wa İmereti — Mfalme II. Solomon aliondolewa kwenye kiti", "5ad36bff"], "d": ["Mfalme wa mwisho wa Ufalme wa İmereti wa Kijojia wa Magharibi, II. Solomon, aliyelazimika kukubali utegemezi kwa Urusi mwaka 1804 kwa Makubaliano ya Elaznauri, alipoendelea kupinga shinikizo linaloongezeka la Urusi, vikosi vya Urusi tarehe 20 Februari 1810 vilichukua mji mkuu Kutaisi, vilimwondoa Solomon kwenye kiti na kuwalazimisha wakuu wa eneo kuapa utii kwa Tsar I. Aleksandr; Ufalme wa İmereti hivyo ulimalizika kwa vitendo na ulifungwa na utawala wa moja kwa moja wa Urusi. Solomon alikimbilia ardhi za Ottoman na alifariki uhamishoni (1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Mkataba wa Kiel — Denmark kuiachia Norwe kwa Uswidi", "59ab1601"], "d": ["Uswidi, iliyoishambulia Denmark kutoka kusini baada ya kushindwa kwa Napoleon Leipzig, kwa Mkataba wa Kiel uliotiwa saini tarehe 14 Januari 1814 ilichukua Norwe (isipokuwa Iceland, Visiwa vya Faroe na Greenland) — muungano wa Denmark-Norwe uliodumu tangu 1380 hivyo ulimalizika rasmi. Kwa malipo Uswidi iliiachia Denmark ardhi zake Pomerania; Denmark pia iliikabidhi Uingereza Helgoland. Norwe ilipinga mkataba kwa silaha na kutangaza katiba yake mwenyewe na Uswidi ililazimika kuitambua — matokeo yakawa muungano wa kibinafsi (real union) utakaodumu hadi 1905. Uswidi haikuweza kuichukua Norwe kwa vitendo: mkataba haukukubaliwa Norwe na utawala ulibaki kwa Christian Frederik; jeshi la Uswidi liliingia Norwe tarehe 26 Julai 1814 tu.", "223aed9a"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Waraka wa Mwisho wa Kongamano la Viyana — ramani ya Ulaya baada ya Napoleon ilichorwa upya", "fca1c676"], "d": ["Waraka wa Mwisho wa Kongamano la Viyana, uliotiwa saini kati ya dola kuu (Austria, Urusi, Prussia, Uingereza, Ufaransa) zilizomaliza Vita vya Napoleon, ulikubaliwa tarehe 9 Juni 1815 (siku 9 kabla ya Waterloo) na kuchora upya ramani ya bara kwa pamoja: Uholanzi ya zamani ya Kihispania/Kiaustria na Majimbo ya Muungano yaliungana chini ya 'Ufalme wa Muungano wa Uholanzi', Jamhuri ya Genoa iliunganishwa na Ufalme wa Sardinia-Piedmont, sehemu kubwa ya Dukedom ya Varşova ilifungwa na Urusi kwa jina 'Poland ya Kongamano' na Pomerania ya Uswidi (Stralsund) ilipita kwa Prussia. Siku hii moja inahesabiwa kuwa mwanzo rasmi wa mizani ya Ulaya baada ya vita (Concert of Europe). Kwa waraka huu Łódź, Częstochowa, Kielce, Radom, Lublin, Chełm na Zamość (Dukedom ya Varşova) zilipita kwa Ufalme wa Poland uliofungwa na Urusi, Poznań (Grand Duchy ya Posen) kwa Prussia, Maastricht na Roermond kwa Ufalme wa Uholanzi.", "b0c34466"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Mkataba Mkuu wa Baharini — Kavâsım na mashehe wengine wa Ghuba walifungwa na mkataba na Uingereza", "fc499e19"], "d": ["Uingereza, baada ya kupiga Ras el-Hayme kwa mizinga mwaka 1819 na kutawanya meli za Kasımî za 'maharamia', ilitoa kwa nguvu Mkataba Mkuu wa Baharini ulioanza tarehe 8 Januari 1820 na kukamilika hadi Machi kwa kutiwa saini na mashehe wa eneo moja moja; mkataba ulipiga marufuku uharamia na utumwa na kulazimisha meli kubeba bendera nyekundu-nyeupe inayofanana na bendera ya Uingereza. Kwa mkataba huu 'Pwani ya Maharamia' kwa muda ikageuka 'Pwani ya Mapatano' (Trucial Coast); ukuu wa Uingereza uliozidishwa na mapatano ya kudumu ya baharini ya 1853 na mikataba ya upekee ya 1892 ulikuwa mwanzo wa uhusiano utakaodumu hadi 1971.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Mwisho wa Mzingiro wa Gaeta — kuanguka kwa Ufalme wa Sicilia Mbili", "121ae580"], "d": ["Baada ya kuanguka kulikoanza kwa Garibaldi kutua Sicilia Mei 1860, mfalme wa Bourbon II. Francesco, aliyekimbia Napoli, alizingirwa katika ngome yake ya mwisho Gaeta tangu tarehe 3 Novemba 1860; kwa meli za Ufaransa kuondoka eneo hilo Januari 1861, kizuizi cha majini cha Italia kilibana na tarehe 13 Februari 1861 Gaeta ilisalimu amri. II. Francesco aliacha kiti chake na kwenda uhamishoni; kituo cha mwisho cha upinzani cha Ufalme wa Sicilia Mbili, Civitella del Tronto, kingeanguka tarehe 20 Machi 1861 tu. Kwa kuanguka kwa ufalme, ardhi za Sicilia (Palermo, Messina, Sirakuza, Trapani, Misilmeri) na za Campania (ikijumuisha Nola) hazikuwa tena chini ya utawala wa Bourbon.", "bb89dfd9"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Kutangazwa kwa Ufalme wa Italia — kuunganishwa kwa Sardinia, Toscana na Italia Kusini", "12e52f70"], "d": ["Katika kikao cha kwanza cha bunge la Italia huko Torino tarehe 17 Machi 1861, Ufalme wa Italia ulitangazwa rasmi na mfalme wa Sardinia-Piedmont II. Vittorio Emanuele alikuwa mfalme wa kwanza wa Italia iliyoungana. Ufalme mpya uliunganisha na Ufalme wa Sardinia ardhi za Toscana, Emilia-Romagna, Napoli na Sicilia (Sicilia Mbili) zilizojiunga mwaka uliopita kwa kura za maoni; Roma (Dola ya Papa) na Venice (Austria) bado zilibaki nje — zingejiunga mwaka 1870 na 1866 kwa mfuatano.", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["Kuanguka kwa Cizzah (Jizzakh) kwa Urusi — ngome ya mwisho ya Ufalme wa Emirate wa Bukhara kwenye mstari wa Syr Darya", "21205a6e"], "d": ["Wakati wa kusonga mbele kwa Urusi Asia ya Kati, baada ya jaribio lililoshindwa la Jenerali Çernyayev mnamo Februari 1866, vikosi vya Urusi chini ya amri ya Jenerali Dmitri Romanovski mwezi Oktoba 1866 kwa kuzingirwa kwa siku saba na shambulio kali viliteka Cizzah, ngome kubwa ya mwisho ya Uemiri wa Bukhara katika bonde la Syr Darya; kuanguka huku kulimaliza kwa vitendo upinzani wa Bukhara katika eneo na kufungua njia ya jeshi la Urusi kuelekea Samarkand.", "b95ba993"]},
"OLAYLAR_EK16:1868-05-14:0":{"b": ["Jeshi la Urusi lateka Samarkand — mji wapita kutoka Uemiri wa Bukhara hadi ugavana mkuu wa Turkestan", "321473be"], "d": ["Vikosi vya Urusi viliteka Samarkand iliyokuwa mikononi mwa Uemiri wa Bukhara na kuuunganisha mji na eneo la utawala mkuu wa Turkestan. Samarkand ilikuwa mji uliobaki kwenye kivuli cha Bukhara wakati wa khan wa Kiuzbeki; kwa utawala wa Urusi ikawa kituo kipya cha kusonga mbele kwa Urusi Asia ya Kati.", "3bc56bbe"]},
"OLAYLAR_EK16:1870-09-28:0":{"b": ["Kujisalimisha kwa Strasbourg: vikosi vya Ujerumani vyavamia mji", "ef3281f3"], "d": ["Baada ya kuzingirwa na kupigwa mabomu kwa wiki sita, Jenerali Uhrich alitia saini kujisalimisha usiku huko Koenigshoffen; asubuhi malango na Ngome zilikabidhiwa kwa vikosi vya Prussia na Baden. Mji ulibaki chini ya uvamizi wa kijeshi hadi Mkataba wa Frankfurt (10 Mei 1871).", "38c8361d"]},
"OLAYLAR_EK16:1870-10-29:0":{"b": ["Kujisalimisha kwa Metz: jeshi la Bazaine laweka silaha chini, vikosi vya Ujerumani vyachukua ngome", "8dd66f58"], "d": ["Itifaki ya kujisalimisha ya Jeshi la Rhine lililozingirwa ilitiwa saini jioni ya tarehe 27 Oktoba; asubuhi ya tarehe 29 Oktoba bendera za Prussia zilipandishwa kwenye ngome na vikosi vya Ufaransa viliiacha ngome. Metz ilibaki chini ya uvamizi wa kijeshi hadi Mkataba wa Frankfurt (10 Mei 1871).", "112e1a60"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["Assab yapita katika umiliki wa dola ya Italia — msingi wa koloni la kwanza la Italia", "15ab8732"], "d": ["Bandari ya Assab kwenye pwani ya Bahari Nyekundu ilikuwa imenunuliwa mwaka 1869 na kampuni ya kibinafsi ya meli ya Italia (Rubattino) kutoka kwa viongozi wa Afar wa mahali; kwa idhini ya Uingereza, serikali ya Italia tarehe 10 Machi 1882 ilichukua umiliki wa moja kwa moja wa dola wa bandari na kwa sheria iliyotolewa mwezi wa Julai ilitangaza rasmi Assab kuwa koloni la kwanza la Italia. Hii ilikuwa mwanzo wa upanuzi wa Italia kwenye pwani ya Bahari Nyekundu utakaogeuka baadaye kuwa Koloni la Eritrea (1890).", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["Kuangamizwa kwa kikosi cha Sinkat — Sinkat yapita kwa vikosi vya Mahdi", "e175a94e"], "d": ["Kikosi cha Sinkat, kilichozingirwa kwa miezi na vikosi vya Osman Digna na ambacho chakula chake kilikuwa kimeisha, pamoja na kamanda wake Tevfik Bey, kilijaribu kuvunja kuzingirwa na kufika Sevâkin; tarehe 8 Februari 1884 kiliangamizwa nje ya ngome na Sinkat ikapita mikononi mwa vikosi vya Mahdi. Habari zilifika Sevâkin tarehe 12 Februari.", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["Sheria ya kijeshi Sevâkin — mji wapita chini ya amri ya Uingereza", "801f6a81"], "d": ["Baada ya kikosi cha Baker cha kuikomboa Tokar kushindwa vibaya El-Teb tarehe 4 Februari, Admirali Hewett alishusha wanamaji Sevâkin tarehe 6 Februari. Tarehe 9 Februari 1884 sheria ya kijeshi ilitangazwa mjini na maafisa wa Uingereza walipewa mamlaka kamili ya kijeshi na ya kiraia juu ya mji; siku iliyofuata uwajibikaji wa mji ulikabidhiwa rasmi kutoka kwa Baker hadi kwa Hewett.", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["Kujisalimisha kwa Tokar kwa vikosi vya Mahdi", "0e21fd24"], "d": ["Kikosi cha Tokar kilichozingirwa kiliingia kwenye mazungumzo na vikosi vya Mahdi tarehe 19 Februari 1884 na siku iliyofuata, tarehe 20 Februari, kilikabidhi mji. Habari zilifika kwa kikosi cha Uingereza cha Trinkitat tarehe 24 Februari; operesheni ya uokoaji ya Graham ilikuwa imechelewa.", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["Uingereza kuanzisha ulinzi kwenye pwani ya Somalia Kaskazini — mwanzo wa Somaliland", "f301ea94"], "d": ["Kwa mujibu wa makala ya TDV ya Somali, Zeyla, Berberâ na Tâcûre zilifanywa koloni na Waingereza mwaka 1884 kwa jina Somaliland; kwa mujibu wa chanzo cha kawaida cha kitaaluma, mchakato huu ulianza kwa mkataba uliotiwa saini Berbera na kabila la Habar Avel tarehe 21 Ramazan 1301 (14 Julai 1884) na ulipanuka kati ya 1884-1886 kwa kutia saini mikataba kama hiyo na makabila ya Gadabursi, Habar Tolcaala, Habar Gerhacis, İse na Warsangeli; Uingereza iliahidi ulinzi wa kijeshi kwa malipo. Mnyororo huu wa mikataba uliandaa msingi wa tangazo rasmi la Ulinzi wa Uingereza wa Somaliland mwaka 1887.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Vita vya Müleydâ — mwisho wa Dola ya Pili ya Suud, Necid ilipita kwa Râşidî", "1cd3b213"], "d": ["Mahusiano yaliyoharibika kwa mgogoro wa zakat na kukamatwa kwa mjumbe wa Reşîdî hatimaye yalifikia mwisho ambapo jeshi la emîr wa Cebel Şammar Muhammed bin Reşîd, tarehe 21 Januari 1891 huko Müleydâ katika eneo la Kasîm, lilivishinda vibaya vikosi vya Suud na washirika wake chini ya uongozi wa Abdurrahman bin Faysal; huu ulikuwa mwisho wa kivitendo wa Dola ya Pili ya Suud, familia ya Al Suud ilienda uhamishoni Kuveyt na Necid yote iliingia chini ya utawala wa Râşidî; maeneo ya kusini ya Dilem (Harc), Havta (Havtat Benî Temîm) na Leylâ (Eflâc) pia yalikuwemo. Utawala ungedumu hadi Abdülaziz bin Suud kijana alipochukua Riyad tena mwaka 1902 (Shambulio la Riyad, 16 Januari 1902).", "b77d8161"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["Kurudishwa kwa Tokar na vikosi vya Uingereza-Misri — kujiondoa kwa Osman Digna", "80a2c26a"], "d": ["Tokar kwenye pwani ya Bahari Nyekundu, iliyokuwa mikononi mwa kamanda wa mahali wa harakati ya Mahdi Osman Digna tangu 1884, ilirudishwa mwezi Februari 1891 kwa operesheni ya vikosi vya Uingereza-Misri; Osman Digna alilazimika kujiondoa milimani. Hili lilikuwa pigo kubwa kwa uwepo wa Dola ya Mahdi kwenye pwani ya Bahari Nyekundu na eneo liliingia chini ya utawala wa pamoja wa Uingereza-Misri.", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["Kupita kwa safu ya Grenfell kupitia Sinkat — Sinkat yatoka kwenye utawala wa Mahdi na kurudi chini ya utawala wa Uingereza-Misri", "b7539a44"], "d": ["Baada ya Tokar kurudishwa mwezi Februari 1891, safu ya Uingereza-Misri chini ya amri ya Grenfell iliondoka Afafit kupitia Sinkat tarehe 3 Machi 1891 na ikafika Sevâkin tarehe 7 Machi; safu ilipata eneo ambalo halijawahi kuingiwa tangu 1884 likiwa limeachwa kabisa na adui. Msamaha wa jumla ulitangazwa kwa jina la Hidiv kwa mashehe waliokusanyika Sevâkin tarehe 8 Machi na Sinkat iliunganishwa tena na utawala wa Uingereza-Misri.", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Somalia ya Kiitalia kupita chini ya utawala wa moja kwa moja wa dola — kufutwa kwa Benadir Şirketi", "8c7d085b"], "d": ["Kwa mujibu wa makala ya TDV ya Somali, Italia ilikuwa imeanzisha utawala wake kwenye pwani ya Somalia Kusini (Benâdir) mwaka 1889-1891 kwa mikataba na Usultani wa Zengibar na Uingereza, na mwanzoni iliacha utawala wake kwa kampuni ya biashara yenye upendeleo (Benadir Company); kwa mujibu wa chanzo cha kawaida cha kitaaluma, upendeleo wa kampuni hii ulimalizika tarehe 24 Januari 1905 na dola ya Italia ilinunua ukuu wa moja kwa moja wa pwani ya Benâdir (ikijumuisha Mogadişu, Merka, Baraave) na kuanzisha utawala rasmi wa koloni. Kusambaa kwa vitendo kwa koloni kuelekea maeneo ya ndani (Bardera, Baydoa) kungekamilika na amri ya kuanzishwa ya 1908 na miaka iliyofuata.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Kuvunjwa kwa Muungano wa Norwe-Uswidi — tangazo la uhuru la upande mmoja la Storting", "aaba2935"], "d": ["Mfalme II. Oscar alipopiga kura ya turufu ombi la serikali ya Norwe la kuanzisha ukonsuli tofauti na kutangaza kwamba hawezi kuunda serikali mpya, Storting ya Norwe (bunge) tarehe 7 Juni 1905 iliamua kwa kauli moja kwamba mfalme hafanyi tena kazi kwa vitendo kama mfalme wa Norwe na kwamba muungano uliodumu tangu Mkataba wa Kiel wa 1814 umevunjwa. Katika kura ya maoni ya tarehe 13 Agosti 1905 karibu wapiga kura wote (kura 371.000 dhidi ya 184) waliidhinisha kuvunjwa; Uswidi, baada ya mazungumzo ya Karlstad, ilitambua rasmi uhuru tarehe 26 Oktoba 1905.", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["Libau (Liepāja) yachukuliwa na vikosi vya Ujerumani — uvamizi wa Kurland waanza", "fdb10548"], "d": ["Katika shambulio la kiangazi la Ujerumani la 1915 Kurland iliingiwa; Libau ilikuwa kituo cha majini cha Urusi kwenye pwani ya Baltic. Sehemu kubwa ya Kurland iliingia chini ya amri ya Ober Ost (hadi mwisho wa 1918).", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["Mitau (Jelgava) yachukuliwa na vikosi vya Ujerumani", "eb491281"], "d": ["Mitau, mji mkuu wa zamani wa dukedom ya Kurland, iliingia chini ya udhibiti wa Ujerumani; mbele ya Riga ilisimama ikiganda kwenye mstari wa Daugava hadi 1917.", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["Ngome ya Kovno (Kaunas) yachukuliwa na Wajerumani — Lithuania yaingia chini ya uvamizi", "9849405b"], "d": ["Jeshi la 10 la Ujerumani liliteka ngome kubwa zaidi ya Urusi kwenye Neman; Eneo la Lithuania liliingia chini ya utawala wa Ober Ost na mwaka 1918 Taryba ilitangaza uhuru chini ya uvamizi huu.", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["Vilna (Vilnius) yachukuliwa na vikosi vya Ujerumani", "2781858b"], "d": ["Wakati wa Kurudi Nyuma Kukubwa Vilna ilipita kwa vikosi vya Ujerumani na ikaunganishwa na Eneo la Lithuania la Ober Ost; mji ulibadilisha mikono kati ya vikosi vya Ujerumani, Kisovieti na Poland hadi 1919.", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["Mkataba wa Uingereza-Qatar — Qatar yaingia chini ya ulinzi wa Uingereza", "f61c4e49"], "d": ["Wakati Vita vya I. vya Dunia vikiendelea, kwa mkataba uliotiwa saini tarehe 3 Novemba 1916 kati ya mwakilishi wa kisiasa wa Uingereza katika Ghuba ya Basra Meja Percy Cox na şeyh wa Qatar Abdullah bin Cassim Âl Sânî, Qatar ilikubali kufunga mahusiano yake ya nje na idhini ya Uingereza, na kwa malipo ilipata dhamana ya ulinzi wa Uingereza dhidi ya mashambulizi ya baharini; mkataba huu uliunda msingi wa kisheria wa uhusiano wa ulinzi wa Uingereza wa Qatar utakaodumu hadi 1971 na uliidhinishwa rasmi mwaka 1918.", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["Riga yachukuliwa na Jeshi la 8 la Ujerumani", "df95df19"], "d": ["Vikosi vya Ujerumani vilivuka Daugava na kuchukua Riga; mji ulibaki chini ya udhibiti wa Ujerumani hadi Novemba 1918, na uhuru wa Latvia ulitangazwa chini ya uvamizi huu (18 Novemba 1918).", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["Baraza la Watu wa Latvia latangaza uhuru wake", "fc72a7f7"], "d": ["Baraza la Watu wa Latvia, lililokusanyika katika Ukumbi wa Taifa huko Riga, lilitangaza Jamhuri huru ya Latvia kutoka Dola ya Urusi; serikali ya muda iliundwa chini ya uenyekiti wa Kārlis Ulmanis. Wiki chache baadaye (Desemba 1918) Urusi ya Kisovieti ilishambulia na Vita vya Uhuru vilianza. Kwa tangazo hili Riga, Jelgava, Liepāja, Ventspils, Cēsis, Daugavpils na Rēzekne zilihesabiwa ardhi ya Jamhuri ya Latvia.", "615adeb0"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["Jeshi Nyekundu laingia Vilnius — serikali ya Lithuania yauacha mji", "889a97b3"], "d": ["Serikali ya Lithuania iliuacha Vilnius Jeshi Nyekundu liliposogea; vikosi vya Kisovieti viliingia mjini na Februari 1919 Jamhuri ya Kisovieti ya Lithuania-Belarus (Litbel) ilitangazwa kutoka hapa. Mji ungechukuliwa na vikosi vya Poland mwezi Aprili 1919.", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["Vikosi vya Poland vyachukua Vilnius (Wilno) kutoka kwa Wasovieti", "32d36c4a"], "d": ["Vikosi vya Józef Piłsudski vilichukua Wilno kutoka Jeshi Nyekundu mwezi Aprili 1919; Lithuania iliendelea kudai mji na suala la Vilnius lilitia sumu mahusiano ya Lithuania-Poland kati ya vita viwili.", "85e7c434"]},
"OLAYLAR_EK16:1920-10-12:0":{"b": ["Żeligowski atangaza Lithuania ya Kati — Vilnius yakuwa mji mkuu wa dola kibaraka inayoungwa mkono na Poland", "11400510"], "d": ["Jenerali Lucjan Żeligowski kwa 'uasi' wake alichukua Vilnius na akatangaza Jamhuri ya Lithuania ya Kati; dola ilidumu hadi tarehe 24 Machi 1922.", "d8050fe5"]},
"OLAYLAR_EK16:1922-02-28:0":{"b": ["Uingereza yaondoa ulinzi juu ya Misri na kutangaza Misri huru", "f8faab66"], "d": ["Uingereza, kwa tangazo la tarehe 28 Februari 1922, ilimaliza kwa upande mmoja ulinzi uliodumu tangu 1914 na ikaitangaza Misri dola huru; mambo kama ulinzi, njia za usafiri na Sudan yaliachwa kwa Uingereza. Wiki mbili baada ya tangazo (15 Machi 1922) Sultan Ahmed Fuâd alipata cheo cha mfalme. Kwenye ramani safu ya uvamizi wa Uingereza katika miji ya Misri inaisha siku hii.", "8cde4005"]},
"OLAYLAR_EK16:1922-03-24:0":{"b": ["Lithuania ya Kati yaunganishwa na Poland — Vilnius yakuwa ya Poland", "e929fa20"], "d": ["Sejm ya Wilno ilipiga kura ya kuunganishwa tarehe 20 Februari 1922; Sejm ya Poland iliidhinisha tarehe 24 Machi 1922. Mkutano wa Mabalozi ulitambua mpaka mwaka 1923, Lithuania haikutambua.", "4a067568"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["Lithuania yakubali ultimatum ya Ujerumani — Eneo la Memel lakabidhiwa kwa Ujerumani", "149fb0b2"], "d": ["Kwa ultimatum ya Ribbentrop, Lithuania iliiachia Ujerumani Eneo la Klaipėda (Memel); Hitler aliingia Memel tarehe 23 Machi. Eneo lilichukuliwa na Jeshi Nyekundu tarehe 28 Januari 1945.", "75afd979"]},
"OLAYLAR_EK16:1939-09-19:0":{"b": ["Jeshi Nyekundu lavamia Vilnius", "5b25d037"], "d": ["Jeshi Nyekundu, lililoingia mashariki mwa Poland tarehe 17 Septemba, liliingia Vilnius iliyokuwa mikononi mwa Poland usiku wa 18-19 Septemba. Kwa mkataba wa msaada wa pande zote wa Kisovieti-Lithuania wa tarehe 10 Oktoba mji ungeachiwa Lithuania na jeshi la Lithuania lingeingia tarehe 28 Oktoba.", "285aa71c"]},
"OLAYLAR_EK16:1939-10-28:0":{"b": ["Lithuania yapokea Vilnius — gharama ya mkataba wa msaada wa pande zote wa Kisovieti-Lithuania", "37ba5976"], "d": ["Vilnius, iliyochukuliwa na Jeshi Nyekundu tarehe 19 Septemba 1939, iliachiwa Lithuania kwa mkataba wa msaada wa pande zote wa tarehe 10 Oktoba 1939; jeshi la Lithuania liliingia mjini tarehe 28 Oktoba. Kwa malipo vikosi vya Kisovieti vilikaa Lithuania, na mwaka 1940 kuunganishwa kulifuata.", "60d2f2bf"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["Ujerumani yavamia Grodno", "b7ca9378"], "d": ["Mbele ya Mashariki: Barbarossa ya 1941 na Bagration ya 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["Ujerumani yavamia Brest-Litovsk", "25898c65"], "d": ["Mbele ya Mashariki: Barbarossa ya 1941 na Bagration ya 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["Pskov yachukuliwa na Jeshi la Ujerumani — uvamizi wa ardhi za Urusi waanza", "d9822e30"], "d": ["Katika wiki ya tatu ya Barbarossa Wehrmacht iliingia Pskov; mji ulibaki chini ya utawala wa kijeshi wa Ujerumani hadi tarehe 23 Julai 1944. Chanzo: kronolojia ya mji wa Pskov, memorialmuseums.org «Memorials in Pskov» — muhtasari wa utafutaji [muhtasari].", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["Vitebsk yachukuliwa na Jeshi la Ujerumani", "e1e4d7d0"], "d": ["Kundi la Majeshi la Kati liliteka Vitebsk katika wiki za kwanza za Barbarossa; mji ulibaki chini ya utawala wa kijeshi wa Ujerumani hadi Juni 1944, na sehemu kubwa ya wakazi wake iliangamia.", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["Smolensk yachukuliwa na Jeshi la Ujerumani", "5a7f4e2a"], "d": ["Kundi la Majeshi la Kati liliteka Smolensk; mji huu kwenye njia ya Moscow ulibaki chini ya uvamizi kwa miezi 26 hadi tarehe 25 Septemba 1943 na ukaona uharibifu mkubwa.", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["Mogilev yachukuliwa na Jeshi la Ujerumani", "4362b7a1"], "d": ["Mogilev ilipita mikononi mwa Wehrmacht baada ya ulinzi wa siku 23; mji ulibaki chini ya uvamizi hadi tarehe 28 Juni 1944.", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["Reichskommissariat Ostland yaanzishwa — nchi za Baltic na Belarus ziingia chini ya utawala wa kiraia wa Ujerumani", "052d4c08"], "d": ["Kwa uamuzi wa Hitler wa tarehe 17 Julai 1941 ardhi zilizovamiwa za Mashariki zilikabidhiwa kwa utawala wa kiraia; Ostland chini ya uenyekiti wa Hinrich Lohse ilijumuisha Estonia, Latvia, Lithuania na Belarus (kitovu Riga). Utawala wa kiraia wa Estonia ulianza tarehe 5 Desemba 1941, mashariki ya Belarus ilibaki chini ya utawala wa kijeshi.", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["Narva yachukuliwa na vikosi vya Ujerumani-Estonia", "60fc2b6a"], "d": ["Katika Vita vya Majira ya Kiangazi wajitolea wa Kiestonia na Wehrmacht waliteka Narva; mji uliunganishwa na Ostland na ulibaki chini ya utawala wa Ujerumani hadi tarehe 26 Julai 1944.", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["Novgorod yachukuliwa na Jeshi la Ujerumani", "4f599b62"], "d": ["Kundi la Majeshi la Kaskazini liliteka Novgorod; mojawapo ya miji ya zamani zaidi ya Urusi ilibaki chini ya uvamizi hadi Januari 1944 na iliharibiwa kwa kiasi kikubwa.", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["Gomel yachukuliwa na Jeshi la Ujerumani", "9d78eb92"], "d": ["Siku tatu baada ya shambulio la Wehrmacht dhidi ya Gomel, Jeshi Nyekundu lilijiondoa kabisa mjini; mji ulibaki chini ya uvamizi hadi tarehe 26 Novemba 1943.", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["Tallinn yachukuliwa na Jeshi la 18 la Ujerumani", "a855ad0d"], "d": ["Kwa kuondolewa kwa umwagaji damu kwa Jeshi la Majini la Kisovieti la Baltic hadi Kronstadt, Tallinn ilianguka; Estonia ikawa Generalbezirk Estland ndani ya Ostland (utawala wa kiraia tarehe 5 Desemba 1941).", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["Orel yachukuliwa na Jeshi la Ujerumani", "3127f454"], "d": ["Katika operesheni ya Bryansk-Vyazma, Jeshi la 2 la Panzer la Ujerumani liliteka Orel; mji ulibaki chini ya uvamizi hadi tarehe 5 Agosti 1943.", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["Bryansk yachukuliwa na Jeshi la Ujerumani", "20fa93f8"], "d": ["Mwishoni mwa Vita vya Bryansk vikosi vya Ujerumani viliingia mjini; mji ulibaki chini ya uvamizi hadi tarehe 17 Septemba 1943.", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["Kursk yachukuliwa na Jeshi la Ujerumani", "a723a00a"], "d": ["Kwa amri ya uongozi wa Kisovieti Kursk iliachwa, Jeshi la 2 la Ujerumani liliingia mjini; mji ulibaki chini ya uvamizi hadi tarehe 8 Februari 1943.", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["Kursk yakombolewa na Jeshi Nyekundu", "1ac03fba"], "d": ["Mwishoni mwa shambulio la majira ya baridi la Kisovieti (mwelekeo wa Kursk-Kharkov uliofuata operesheni ya Voronezh-Kastornoye) Kursk ilirudishwa; mwezi Julai wa mwaka huo huo jina la mji lilitolewa kwa Vita vya Kursk.", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["Orel yarudishwa na Jeshi Nyekundu — salamu ya kwanza ya Kisovieti baada ya Kursk", "80bfc68d"], "d": ["Kutekwa kwa mwinuko wa Orel na kupigwa kwa salamu ya kwanza ya mizinga huko Moscow pamoja na Belgorod.", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["Bryansk yarudishwa na Jeshi Nyekundu", "d0f2a35f"], "d": ["Kwa Operesheni ya Bryansk mji ulirudishwa tarehe 17 Septemba 1943.", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["Smolensk yakombolewa na Jeshi Nyekundu", "6516d85a"], "d": ["Katika kilele cha Operesheni ya Smolensk ya tarehe 7 Agosti-2 Oktoba 1943 mji ulirudishwa; Smolensk ilipata cheo cha 'mji shujaa' mwaka 1985.", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["Gomel yakombolewa na Jeshi Nyekundu", "280268c2"], "d": ["Mbele ya Belarus ilirudisha mji katika operesheni ya Gomel-Rechitsa; ni mojawapo ya ukombozi wa kwanza wa miji mikubwa ya Belarus.", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["Novgorod yakombolewa na Jeshi Nyekundu", "52962012"], "d": ["Wakati wa operesheni ya Leningrad-Novgorod, Veliki Novgorod ilirudishwa tarehe 20 Januari 1944.", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["Vitebsk yakombolewa na Jeshi Nyekundu — Operesheni Bagration", "b06be69c"], "d": ["Mbele ya 1 ya Baltic na ya 3 ya Belarus ziliizingira na kuchukua Vitebsk; ulikuwa ukombozi wa kwanza mkubwa wa mji wa Operesheni Bagration.", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["Mogilev yakombolewa na Jeshi Nyekundu — Operesheni Bagration", "52fa985d"], "d": ["Mbele ya 2 ya Belarus ilichukua Mogilev na kuvuka mstari wa Dnieper.", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["Jeshi Nyekundu lairudisha Minsk — Operesheni Bagration", "87dc1fb5"], "d": ["Katika Operesheni Bagration iliyoanza tarehe 22 Juni, mbele za Belarus zilivunja Kundi la Majeshi la Kati na kuizingira Minsk; mji ulirudishwa tarehe 3 Julai na takriban askari 50 elfu wa Ujerumani walibaki kwenye mzingiro mashariki. Utawala wa kiraia wa Ujerumani wa Belarus (Generalbezirk Weißruthenien) uliporomoka.", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["Jeshi Nyekundu lachukua Vilnius", "0172450e"], "d": ["Katika Operesheni ya Vilnius ya tarehe 5-13 Julai, Mbele ya 3 ya Belarus iliizingira kikosi cha Ujerumani na kuchukua mji (operesheni ya «Ostra Brama» ya Jeshi la Ndani la Poland ilikuwa ya wakati mmoja). Vilnius ikawa mji mkuu wa SSR ya Lithuania.", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["Jeshi Nyekundu lakomboa Grodno kutoka uvamizi wa Ujerumani", "1d134151"], "d": ["Mbele ya Mashariki: Barbarossa ya 1941 na Bagration ya 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["Pskov yarudishwa na Jeshi Nyekundu", "f18103aa"], "d": ["Baada ya uvamizi wa Ujerumani wa zaidi ya miaka mitatu, Pskov ilirudishwa na Jeshi Nyekundu.", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["Jeshi Nyekundu lachukua Narva", "64854ae3"], "d": ["Narva, iliyokaa magofu kwenye mstari wa mbele tangu Februari 1944, ilitekwa na vikosi vya Kisovieti katika Operesheni ya Narva ya Julai 1944; kaskazini-mashariki ya Estonia ilitoka mikononi mwa utawala wa kiraia wa Ujerumani (Generalbezirk Estland).", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["Rēzekne yachukuliwa na Jeshi Nyekundu — mashariki ya Latvia yakombolewa", "e9efd12d"], "d": ["Mbele ya 2 ya Baltic ilichukua Rēzekne; eneo la Latgale la Latvia lilitoka mikononi mwa utawala wa Ujerumani.", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["Daugavpils yakombolewa na Jeshi Nyekundu", "b4ee6622"], "d": ["Kitengo cha 360 cha Wanajeshi wa Miguu cha Mbele ya 2 ya Baltic kilichukua Daugavpils (Dünaburg); mji wa pili kwa ukubwa wa Latgale ulitoka mikononi mwa utawala wa Ujerumani.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["Šiauliai yachukuliwa na Jeshi Nyekundu — operesheni ya Šiauliai", "ccb20729"], "d": ["Mbele ya 1 ya Baltic ilichukua Šiauliai, njia panda ya reli kaskazini mwa Lithuania; operesheni ilidumu tarehe 5 Julai-29 Agosti 1944 na Ghuba ya Riga ilifikiwa.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["Jeshi Nyekundu lakomboa Brest-Litovsk kutoka uvamizi wa Ujerumani", "6d5a837a"], "d": ["Mbele ya Mashariki: Barbarossa ya 1941 na Bagration ya 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["Kaunas yachukuliwa na Jeshi Nyekundu — mji mkuu wa muda wa Lithuania watoka mikononi mwa utawala wa Ujerumani", "5c2b2c16"], "d": ["Mbele ya 3 ya Belarus ilichukua Kaunas; amri ya siku ya Stalin ya tarehe 1 Agosti ilitangaza kutekwa. Mji ulikuwa mji mkuu wa muda wa Lithuania katika 1919-1939.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["Tartu yachukuliwa na Jeshi Nyekundu — operesheni ya Tartu", "cc8069ab"], "d": ["Mbele ya 3 ya Baltic ilivunja ulinzi wa Jeshi la 18 la Ujerumani na kuchukua Tartu; mji ulibaki kwenye mstari wa mbele kwa wiki kadhaa na operesheni ya Tartu ilimalizika tarehe 6 Septemba 1944.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["Jeshi Nyekundu laingia Tallinn — vikosi vya Ujerumani viuacha mji", "41ae1ec5"], "d": ["Wakati wa Operesheni ya Tallinn Wajerumani waliuacha mji; serikali ya Kamati ya Taifa ya Estonia, iliyochukua majengo ya serikali tarehe 18 Septemba, haikuweza kuhifadhi utawala Jeshi Nyekundu lilipoingia. Estonia iliingia tena chini ya utawala wa Kisovieti.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["Jeshi Nyekundu lachukua Memel (Klaipėda)", "d01ad3dc"], "d": ["Katika operesheni ya Kisovieti iliyoelekea Prussia ya Mashariki na pwani ya Baltic, bandari ya Memel (Klaipėda) ilichukuliwa kutoka mikononi mwa Ujerumani na kuunganishwa na SSR ya Lithuania. Eneo lililokabidhiwa kwa Ujerumani mwaka 1939 hivyo lilitoka kwenye utawala wa Ujerumani.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["Mfuko wa Kurland wajisalimisha — Courland Army Group yatia saini kujisalimisha kwa Govorov", "3c88889b"], "d": ["Kundi la Majeshi la Kurland la Ujerumani, lililozingirwa karibu na Liepāja-Ventspils tangu Oktoba 1944, lilijisalimisha; magharibi ya Latvia ilipita chini ya udhibiti wa Kisovieti.", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["Vikosi vya Sultani wa Oman viingia vituo vikuu vya Oman ya ndani; uimamu wa Ibadhi wamalizika kwa vitendo", "9a9962a5"], "d": ["Mwezi Desemba 1955 Sultani wa Oman alitenda kuanzisha upya mamlaka yake na vikosi vyake viliingia vituo vikuu vya makazi vya Oman ya ndani (Bahlâ, İzkî, Nizvâ); utawala wa uimamu wa Ibadhi juu ya Oman ya ndani ulimalizika kwa vitendo. Chanzo kinatoa mwezi tu; kwenye ramani inaonyeshwa tarehe 1 Desemba 1955.", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Kuwait yatoka kwenye ulinzi wa Uingereza na kupata uhuru kamili", "e9a86d04"], "d": ["Kwa nota zilizobadilishwa kati ya Kuwait na Ufalme wa Muungano tarehe 19 Juni 1961, ulinzi wa Uingereza uliodumu tangu makubaliano ya 1899 ulimalizika na Kuwait ikawa huru kamili. Kwenye ramani safu ya Uingereza katika Kuwait inaisha siku hii.", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Qatar yatangaza uhuru wake kwa kumalizika kwa mikataba na Uingereza", "8f288cc6"], "d": ["Baada ya tarehe ambayo mikataba ya ulinzi iliyofanywa na Uingereza ilimalizika, Qatar ilitangaza uhuru wake tarehe 3 Septemba 1971. Kwenye ramani safu ya Uingereza katika Doha inaisha siku hii.", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["Kutekwa kwa ngome za Istıranca: Pınarhisar, Kırkkilise (Kırklareli) na Vize", "c6b1a9c1"], "d": ["I. Murad, aliyekaa majira ya baridi ya 1369 katika Ikulu ya Edirne, katika majira ya kuchipua alianza tena kuchukua hatua dhidi ya Bizanti na akachukua ngome za Pınarhisar, Kırkkilise na Vize kwenye miteremko ya milima ya Istıranca. Ushindi huu ulizua hofu İstanbul na Maliki V. Ioannes aliamua kwenda kwa papa kutafuta msaada.", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Taşkent ilipita chini ya utawala wa han wa Moğulistan Yûnus Han", "a37ee010"], "d": ["Wakati wa mapambano ya kiti kati ya şehzade wa Timurî, Taşkent na viunga vyake vilipita mikononi mwa han wa Çağatay Mashariki (Moğulistan) Yûnus Han. Miaka miwili baadaye Yûnus Han alipofariki, mwanawe Mahmud Han alichukua nafasi yake; mji ulibaki kwa mahan wa Moğul hadi Wauzbeki wa Şeybânî Han walipoichukua mwaka 1503.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Bâbür aliiachia Fergana kwa Wauzbeki na kwenda Kâbil", "69df593c"], "d": ["Bâbür wa Timurî, mwana wa Ömer Şeyh Mirza, baada ya vita na Muhammed Şeybânî Han, aliiachia Wauzbeki Fergana aliyoitawala tangu 1494, na akavuka Hindukuş na kukaa Kâbil.", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Pîrî Reis achora ramani ya dunia kongwe zaidi iliyoifikia siku zetu", "6ef941f5"], "d": ["Pîrî Reis alichora huko Gelibolu ramani ya dunia ya tarehe 919 (1513); kulingana na TDV İslâm Ansiklopedisi, miongoni mwa vyanzo vya ramani ni 'ramani za zamani zilizomfikia kutoka ulimwengu wa Mashariki na Magharibi na ramani ya Kristof Kolomb' — yaani inadhaniwa inabeba athari za ramani asili ya urambazaji ya Kolomb iliyohesabiwa imepotea wakati huo. Alimkabidhi Yavuz Sultan Selim ramani hiyo Cairo mwaka 923 (1517). Hadi siku zetu kimefika kipande kimoja tu kinachoonyesha pwani za magharibi/Atlantiki (Uhispania, Ureno, Afrika Magharibi, pwani ya mashariki ya Amerika Kusini); kipande hiki kilipatikana tena Ikulu ya Topkapı mwaka 1929 na kimo katika orodha ya Kumbukumbu ya Dunia ya UNESCO.", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Kuunganishwa kwa eneo la Kars: Şüregel, Arpaçay na Digor kuingia chini ya utawala wa Ottoman", "10f16b5c"], "d": ["Wakati wa Kampeni ya Irakeyn, ngome za Pasin, Şüregel na Oltu zilipita mikononi mwa Waottoman; kuna uwezekano mkubwa kwamba Ngome ya Kars nayo ilifungwa wakati huu. Eneo la Arpaçay na Digor kaskazini na mashariki mwa Kars liliingia chini ya udhibiti wa Ottoman kwa operesheni hiyo hiyo.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Mwisho wa Şirvanşah: Elkas Mirza alimteka Şâhruh, Şirvan ikawa vilâyet ya Wasafavî", "e6d64114"], "d": ["Elkas Mirza, aliyetumwa na Şah Tahmasb, aliiteka Şirvan, akachukua Ngome ya Baykurd na akamteka Şirvanşah Şâhruh mwenye umri wa miaka kumi na tano na kumpeleka Tebriz. Utawala wa Şirvanşah, uliodumu eneo hilo kwa muda mrefu, hivyo ulimalizika; Şirvan ikawa vilâyet ya Dola ya Wasafavî.", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Kupanuka kwa Ocaklık ya Cezayir kuelekea Sahara — kufungwa kwa Tuggurt-Ouargla kwa kodi, kutekwa kwa uhakika kwa Tilimsan", "705ec920"], "d": ["Kwa mujibu wa makala ya TDV ya Tilimsan, jeshi kubwa lililotumwa kutoka Cezayir mwaka 960 (1553), chini ya amri ya Salih Reis, lilichukua mji kwa uhakika na kumaliza nasaba ya Zeyyânî ya karne tatu. Katika kipindi hicho hicho (1552) Salih Reis alifanya kampeni dhidi ya Tuggurt na Vargla, zilizokuwa usultani huru; vikosi vya Ottoman vilichukua Tuggurt, vikasonga hadi Vargla, na usultani mbili zilifungwa kwa kodi; kikosi cha kudumu cha Ottoman kiliachwa Biskra iliyokuwa njiani. Hivyo mpaka wa Ocaklık ya Cezayir ulivuka kwa mara ya kwanza Tell Atlas na kufika ufuo wa Sahara. Vita kubwa mbele ya Mustagānim, kwa upande mwingine, havikutokea mwaka huu bali mwaka 1558: Hasan Paşa alimshinda hapo Kont wa Kihispania Alcaudete na kumaliza mashambulizi ya Kihispania Afrika Kaskazini.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Kuanzishwa kwa Mkoa wa Habeş — kuingia kwa pwani ya Bahari Nyekundu chini ya utawala wa Ottoman", "7dd470ec"], "d": ["Mkoa ulioanzishwa ili kuzuia Ureno kupenya Bahari Nyekundu kupitia Habeşistan, kwa mujibu wa makala ya TDV ya Mkoa wa Habeş, ulianzishwa rasmi tarehe 15 Şâban 962 (5 Julai 1555), na kitovu cha sancak kilikuwa Sevâkin. Özdemir Paşa alianza operesheni vuli ya 1555; alichukua visiwa vya Dehlek vinavyodhibiti Bandari ya Masavva' na tarehe 2 Aprili 1557 alichukua mji wa Masavva', kisha Arkîko. Ushindi uliendelea kwa mkoa wa Tigre kuingia chini ya utawala wa Ottoman mwaka 1558 na Debârvâ mwaka 1559.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Sedefkâr Mehmed Ağa ateuliwa mbunifu mkuu — mbunifu wa Msikiti wa Sultanahmet", "27b66fce"], "d": ["Mehmed Ağa, aliyechukuliwa ikulu kama devşirme kutoka mji wa İlbasan wa Albania katika miaka ya 1562-63, alilelewa kando ya Mimar Sinan na akateuliwa mbunifu mkuu wa Ottoman tarehe 11 Oktoba 1606. TDV İslâm Ansiklopedisi inanukuu kwamba chanzo cha wakati huo kilimwelezea 'mpole wa tabia, mnyenyekevu, mwenye kutimiza ahadi, mcha Mungu na mwerevu'. Mehmed Ağa, aliyeanza ujenzi wa Msikiti wa Sultanahmet miaka mitatu baadaye kwa amri ya I. Ahmed, alitia saini kazi pana kuanzia ukarabati wa Kaaba hadi chemchemi na misikiti mingi ya Istanbul na Edirne. Mjadala wa 'usawa' wa minara sita na Kaaba huko Makka ni hadithi ya kawaida ya watu; vyanzo vya ensaiklopedia haviithibitishi, vikiuelezea mpangilio huo tu kama 'usiojaribiwa hadi wakati huo'.", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["Sultani mpya I. Mustafa: mfungwa wa 'kafes' mwenye uso uliofifia na macho ya kutazama kwa kusahau kwenye kiti cha enzi", "c487b0d1"], "d": ["I. Mustafa, aliyepanda kiti cha enzi kwa kifo cha I. Ahmed, kama şehzade wa kwanza aliyeachwa hai na ndugu yake, alikuwa ameishi miaka mingi akiwa amefungwa ikulu chini ya uangalizi mkali; TDV İslâm Ansiklopedisi inamwelezea 'mwenye uso uliofifia, ndevu chache, macho makubwa meusi ya kutazama bila hisia' na inaandika kwamba kifungo hiki kirefu kilizidisha hali yake ya kisaikolojia. Katika utawala huu wa kwanza wa siku tisini na sita hakuweza kuendesha mambo ya dola; kwa upande mwingine inasimuliwa kwamba mara nyingi alikwenda kuwinda, alitembelea kiwanja cha meli na hata alitupa dhahabu majini na kutazama samaki. Ocak-yeniçeri na ulama, kwa kumwona hafai kwa utawala, walimwondoa kwenye kiti cha enzi tarehe 26 Februari 1618 na wakamweka mpwa wake wa miaka kumi na minne II. Osman mahali pake.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["Ndoto ya safari ya Evliya Çelebi — kusema 'Seyahat' badala ya 'Şefaat'", "2d863e22"], "d": ["Kulingana na TDV İslâm Ansiklopedisi, Evliya Çelebi anahusisha mwanzo wa maisha yake ya safari yatakayodumu miaka arobaini na ndoto aliyoiona usiku wa aşure wa mwezi wa Muharrem wa mwaka 1040 (19 Agosti 1630): katika ndoto yake, katika Msikiti wa Ahî Çelebi huko Istanbul, pamoja na jamaa kubwa, anamwona Mtume na kwa msisimko badala ya kusema 'şefaat yâ Resûlellah' anasema 'seyahat yâ Resûlellah'. Kulingana na riwaya, Mtume alitabasamu kwa kuteleza huku kwa ulimi na akampa bishara ya şefaat, seyahat na ziara zote. Hakuwahi kuoa na alitoa maisha yake kwa ahadi hii ya 'seyahat'.", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["Mikinzano ya IV. Murad: marufuku ya pombe ya sultani aliyependa pombe, kifundo cha mpiga mieleka, sikio la mtunzi", "3d2ea5e0"], "d": ["Katika miaka ya kwanza ya IV. Murad, aliyepanda kiti cha enzi akiwa na umri wa miaka kumi na moja, ushawishi wa mama yake Kösem Sultan ulikuwa wa kuamua; TDV İslâm Ansiklopedisi inanukuu kwamba Kösem, akiogopa mwelekeo wa madaraka kwa mwanawe, 'alimwelekeza kwenye burudani, akamfurahisha kwa zawadi na sherehe'. Alipochukua utawala kwa vitendo akiwa na takriban umri wa miaka ishirini, alikuwa mtawala mrefu, mwenye mabega mapana na wa kuheshimika — inasimuliwa kwamba alimwinua mtu mwenye nguvu kwa mkanda wake na kumzungusha mara kadhaa katika Has Oda. Mkinzano wa kushangaza unaoandikwa na TDV ni huu: sultani, aliyesemwa kuchukia tumbaku na afyuni, alikuwa mpenda pombe kupindukia, licha ya hayo kabla ya msafara alipiga marufuku kahawa, tumbaku na baadaye pombe yenyewe; wakati huo huo alikuwa na ujuzi wa muziki wa kutosha kutunga nyimbo kulingana na utamaduni wa makam.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["Safari ya Lâgarî Hasan Çelebi kwa roketi — riwaya ambayo Evliya Çelebi ndiye chanzo pekee", "1f02e3f2"], "d": ["Kulingana na Seyahatnâme ya Evliya Çelebi, Lâgarî Hasan Çelebi, mbele ya IV. Murad huko Sarayburnu, alitengeneza kifaa cha fataki chenye mikono saba kwa okka hamsini za baruti na akapanda juu ya fataki akisema 'Ee Sultani wangu, nakukabidhi kwa Mungu, naenda kuzungumza na Nabii İsâ'. Kulingana na riwaya, Hasan Çelebi, aliyepanda karibu mita 250, kwa vifaa vinavyofanana na bawa la mwewe aliteleza hadi baharini, akaogelea na kurudi kwa sultani na kwa malipo alipata sipahilik yenye mshahara wa akçe sabini kwa siku.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Kemankeş Kara Mustafa Paşa alikuwa sadrazam — kipindi cha mageuzi ya kifedha kilianza", "583846a4"], "d": ["Kemankeş Kara Mustafa Paşa, aliyekuwa vezîriâzam tarehe 17 Şâban 1048 (24 Desemba 1638) baada ya Tayyar Mehmed Paşa kufa shahidi katika Kampeni ya Bağdat, alitekeleza nidhamu kali ya kifedha katika enzi ya Sultani İbrahim: alipunguza idadi ya Yeniçeri na sipahi hadi theluthi moja, alirekebisha kiwango cha sarafu na akabana mfumo wa narh. Kwa idadi iliyotolewa na TDV, akiba hii ilifikia kese 6000 kwa mwaka — lakini udhibiti huu mkali ulimpa maadui katika mazingira ya ikulu.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["I. Mustafa afa baada ya miaka kumi na mitano ya kusahauliwa", "b4c872cd"], "d": ["I. Mustafa, aliyeondolewa kwenye kiti cha enzi kwa mara ya pili tarehe 10 Septemba 1623, alikaa katika chumba alichokuwa amefungiwa kwa miaka kumi na mitano hadi kifo chake; hakuna taarifa yoyote katika vyanzo kuhusu miaka hii. Alifariki tarehe 15 Ramazan 1048 (20 Januari 1639) — sehemu ya vyanzo huhesabu hii kuwa kifo cha kawaida huku sehemu nyingine ikidai kuwa na mkono wa IV. Murad.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["'İbrahim Mwendawazimu' au ugonjwa wa kupanda na kushuka?", "2abc230f"], "d": ["TDV İslâm Ansiklopedisi inakataa waziwazi lakabu 'Deli İbrahim' iliyoenea katika karne ya XX; inasimulia kwamba sultani alilalamika katika barua zake mwenyewe kuhusu maumivu, kukosa hamu ya kula, udhaifu wa miguu, hisia ya ukungu kichwani, kubana kwa kifua na mashambulizi ya kuzimia. Kwa upande mwingine, majibu yake thabiti na ya busara katika mchakato wa kuondolewa kwenye kiti yanapingana na madai ya kutokuwa na usawa wa kudumu; inahitimisha kwamba hali yake ilikuwa na mwenendo 'usio thabiti na ukali wake ukibadilika'. Katika kipindi hiki majukumu ya Kösem Sultan yaliongezeka polepole, na Cinci Hoca, aliyeitwa ikulu, kumpa sultani faraja ya kiroho kwa 'dua zenye athari', kuliongeza nguvu yake ya kuingilia siasa.", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["Tukio la Samur — kodi ya manyoya ya Sadrazam Ahmed Paşa iliandaa mwisho wa İbrahim", "a2a47d62"], "d": ["Wakati shauku ya Sultani İbrahim kwa manyoya ya samur na ambari ilipokua ikulu, Sadrazam Ahmed Paşa karibu 1647-1648 alianzisha utaratibu wa kukusanya kwa nguvu thamani ya manyoya ya samur kutoka kwa wakuu wa dola; TDV İslâm Ansiklopedisi inaandika kwamba watumishi waliuona wazi kama 'haraç'. Maafisa wa Yeniçeri walipokataa kulipa kwa pamoja, upinzani huu ukawa kichocheo cha moja kwa moja cha mchakato uliokwenda kuondolewa kwa sultani kwenye kiti — asubuhi ya tarehe 7 Agosti 1648 watumishi waliokusanyika kwanza walimuua Ahmed Paşa, na siku iliyofuata wakamuondoa İbrahim.", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["'Wanawake wanatawala dola' — uasi wa Varvar Ali Paşa kutoka Sivas", "5b027357"], "d": ["Beylerbeyi wa Sivas Varvar Ali Paşa alikataa kulipa kuruş 30.000 ambazo İstanbul ilizidai kwa jina 'bayramiye' akisema 'mapato ya kila mwaka ya Sivas hayatoshi kiasi hiki'; kwa mujibu wa TDV İslâm Ansiklopedisi, sababu ya uasi wake ilikuwa madai kwamba kwa sababu ya ugonjwa wa sultani mambo ya dola yalikuwa yamepita mikononi mwa wanawake na kwamba hili lilizaa kutokuwa na utulivu kwa kubadilisha magavana mara kwa mara. Ingawa Mei 1648 alipata kwanza mafanikio ya kijeshi, alishindwa mbele ya İpşir Mustafa Paşa, aliuawa tarehe 20 Mei 1648 na kichwa chake kikatumwa İstanbul.", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Kupotea kwa Anabolu (Nauplion) kwa Venice — mwamba wa mabadiliko wa Vita vya Mora", "9d400557"], "d": ["Kwa mujibu wa makala ya TDV ya Anabolu, wakati wa mzingiro, Waislamu wa mji waliobaki hai walikimbilia visiwa vya jirani na Anatolia (1686). Kwa mujibu wa chanzo cha kawaida cha kitaaluma (Setton, Venice, Austria, and the Turks in the Seventeenth Century), vikosi vya Königsmarck vilirudisha nyuma mashambulizi ya jeshi la msaada la Ottoman kwa wiki mbili; shambulio la İsmail Paşa la tarehe 29 Agosti liliposhindwa vibaya, ngome ilisalimu amri ndani ya siku chache. Anabolu ilikuwa ardhi ya Ottoman iliyopokelewa kwa mkataba mwaka 1540; kwa kupotea kwake kupita kwa peninsula ya Mora kwa Venice kuliharakishwa.", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["IV. Mehmed aliacha kuwinda — juhudi ya mwisho mkesha wa kuondolewa kwake", "7daa904b"], "d": ["Baada ya kushindwa kwa Mohaç (Agosti 1687), jeshi lisilolipwa mishahara yake liliasi na kuelekea İstanbul. IV. Mehmed alimuua Süleyman Paşa aliyekuwa ameiba muhuri wa usadrazam na akamwonyesha askari kichwa chake, na akatawanya vifaa vya kuwinda na mbwa wake na kutangaza kwamba ametubu — lakini ishara hii haikutosha kuokoa kiti chake, na miezi michache baadaye aliondolewa.", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Kusalimishwa kwa ngome ya Munkács (Mukacheve) kwa Austria baada ya mzingiro wa miaka mitatu", "ca2efc3d"], "d": ["Ngome ya Munkács, iliyozingirwa na vikosi vya maliki mwishoni mwa 1685, ilipinga kwa miaka mitatu chini ya utawala wa İlona Zrínyi, mke wa Thököly İmre; kwa mujibu wa vyanzo vingi vya marejeo vilivyochapishwa, ngome ilikabidhiwa kwa Jenerali Antonio Caraffa tarehe 17 Januari 1688. Hii ilikuwa kuanguka kwa mojawapo ya ngome kubwa za mwisho za upinzani unaounga Ottoman Hungaria kwenye mstari wa Ottoman-Habsburg.", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Baltacı Mehmed Paşa na hadithi ya Çariçe Katerina", "c1b739f1"], "d": ["Masimulizi maarufu yanayohusisha kuokolewa kwa jeshi la Urusi lililozingirwa Prut na zawadi/rushwa ambazo I. Katerina alimtumia Baltacı Mehmed Paşa yalirudiwa kwa karne nyingi.", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["Mjadala wa 'fursa iliyopotezwa' Prut — maoni mawili", "61ee699c"], "d": ["Kuridhika na amani wakati jeshi la Ottoman lilikuwa limelizingira kabisa jeshi la Urusi kulikuwa mada ya mjadala kati ya wanahistoria mara baada ya mkataba — kwa maneno ya TDV yenyewe 'imeeleweka kwamba fursa kubwa ilipotezwa na hoja hii imesisitizwa sana na wale walio na maoni yanayopinga.' Kulingana na wakosoaji, tsar angeweza kutekwa, silaha za jeshi la Urusi zingeweza kupokelewa; kulingana na watetezi, hata hivyo, ilikuwa 'sera ya busara zaidi' kuidhoofisha Urusi kwa kiasi kidogo ili kuzuia Uswidi kuimarika Ulaya ya Kaskazini. TDV inaripoti maoni yote mawili bila kuchukua upande.", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Baraza la watu thelathini na wawili la elimu/tafsiri lilianzishwa", "0e3a713c"], "d": ["Katika enzi ya usadrazam wa Damad İbrahim Paşa, İstanbul ilianzisha baraza la wanazuoni-makarani thelathini na wawili, 'linaloweza kuhesabiwa kuwa akademia ya enzi hiyo' kwa maneno ya TDV. Baraza lilitafsiri kwa Kituruki kazi za historia, falsafa na jiografia kutoka Kiarabu, Kiajemi, Kigiriki na Kilatini — kati ya hizo ni Yanyalı Esad Efendi kutafsiri Fizikia ya Aristotle kwa timu ya watu ishirini na watano na mshairi Nedim kuongoza baraza la tafsiri ya historia. Siku haijatajwa katika TDV, mwaka ni tangazo.", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["I. Mahmud alimnasa Patrona Halil kwa kumwalika ikulu", "6147059f"], "d": ["Wiki saba baada ya kupanda kiti, I. Mahmud, kupitia watu aliowaamini — Hacı Beşir Ağa ikulu, na Han wa Krimea I. Kaplan Giray nje — aliwavuta wakuu wa askari upande wake na akavunja ushawishi wa Patrona Halil. Tarehe 25 Novemba 1730, Patrona Halil, Muslu Beşe na Kel Mehmed Ağa walioitwa kwenye mkutano katika Chumba cha Sünnet cha Ikulu ya Topkapı waliingizwa ndani; kwa ishara ya Sadrazam Silâhdar Mehmed Paşa, watu thelathini na wawili wenye silaha waliokuwa wamefichwa mapema walitokea na kuwaua wote watatu. I. Mahmud hivyo alichukua kabisa udhibiti wa uasi.", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Humbaracı Ahmed Paşa (Bonneval) aliwekwa kichwani mwa Humbaracı Ocağı", "27b0b1d7"], "d": ["Afisa wa asili ya Kifaransa, jina lake halisi Claude-Alexandre Comte de Bonneval, baada ya kuhudumu kwanza katika majeshi ya Ufaransa na Austria, alisilimu Saraybosna na kuchukua jina Ahmed na mwaka 1729 alikimbilia Dola ya Ottoman. Ahmed Paşa, aliyewekwa kichwani mwa Humbaracı Ocağı mwaka 1731 katika enzi ya I. Mahmud, alifanya mazoezi kwa askari takriban 300 waliotolewa Bosnia katika kambi aliyoijenga Üsküdar Ayazma; idadi yao ilizidi 600 kwa muda mfupi na yeye mwenyewe pia alifundisha masomo ya hisabati. Jaribio lake la kuanzisha uasi na Rákóczi Hungaria kwa manufaa ya Ufaransa lilitikisa ushawishi wake na mwaka 1738 alihamishiwa Kastamonu. Alifariki İstanbul tarehe 23 Mei 1747, kaburi lake liko katika hazîra ya Galata Mevlevîhânesi.", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Kurudishwa kwa Semendire kutoka kwa Habsburg (taji ya Ufalme wa Hungaria) — Vita vya 1737-39", "63dcf604"], "d": ["Kwa mujibu wa makala ya TDV ya Semendire, ngome iliyoachiwa Austria kwa Pasarofça mwaka 1717 ilirudishwa kwa kusonga mbele kwa Ottoman kwenye mstari wa Danube-Sava katika Vita vya Ottoman-Austria vilivyoanza 1737; vikosi vya Habsburg (taji ya Ufalme wa Hungaria) viliweza kushikilia eneo hilo hadi Agosti 1738, na tangu tarehe hii Semendire iliingia tena chini ya utawala wa Ottoman. Mkataba wa Belgrad (1739-09-18), uliotiwa saini mwaka mmoja baadaye, ungethibitisha faida hii — pamoja na Belgrad na Serbia ya kaskazini.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Kurudi kwa bonde la Morava chini ya utawala wa Ottoman — Yagodina, Kragujevac na Çaçak", "b219d3c9"], "d": ["Kwa kurudishwa kwa Semendire Agosti 1738, bonde la Morava lililokuwa kati ya Semendire na mwili mkuu wa Ottoman nalo lilirudi chini ya utawala wa Ottoman: Yagodina, Kragujevac na Çaçak zinahesabiwa kuwa za Ottoman tangu tarehe hii. Vyanzo havitaji kando na kutoa tarehe ya kurudi kwa maeneo haya matatu; ramani inafanya kazi kwa siku ya Semendire. Mkataba wa Belgrad (1739-09-18) ulithibitisha hali hii.", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["I. Abdülhamid alipata kiharusi na akafa akisoma habari ya kuanguka kwa Özi", "6ac60365"], "d": ["Kwa mujibu wa makala ya abdulhamid-i ya TDV İslâm Ansiklopedisi, I. Abdülhamid, ambaye afya yake ilidorora kabisa kwa mwenendo mzito wa vita vya Urusi-Austria, alifariki kwa kiharusi cha ghafla alipokuwa akisoma kâime ya sadrazam iliyotangaza kwamba Ngome ya Özi imevamiwa na Warusi (11 Receb 1203 / 7 Aprili 1789). Maiti yake ilizikwa katika türbe aliyoijenga mwenyewe huko Bahçekapı, İstanbul. Siku hiyo hiyo mpwa wake III. Selim alipanda kiti.", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Muungano wa Ulinzi wa Ottoman-Urusi — ulinzi wa pamoja dhidi ya Ufaransa", "c87079d1"], "d": ["Kwa uvamizi wa Napoleon wa Misri, III. Selim na Tsar wa Urusi I. Pavel walianzisha muungano wa ulinzi wa miaka minane wa vifungu kumi na vinne. Pande zilichukua jukumu la kuwa na marafiki na maadui wa pamoja, kusaidiana, na kutofanya amani ya pekee.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Muungano wa Ulinzi wa Ottoman-Sicilia Mbili (Napoli) — lengo la pamoja dhidi ya Ufaransa", "1d2be816"], "d": ["Mbele ya uvamizi wa Ufaransa wa Italia, Malta na Misri, Dola ya Ottoman na Ufalme wa Sicilia Mbili walifanya muungano wa ulinzi wa vifungu tisa. Pande zilichukua jukumu la kuendesha vita kwa pamoja, kutofanya amani ya pekee na kusaidiana kwa nchi kavu na baharini.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Jamhuri ya Visiwa Saba ilianzishwa — Visiwa vya İyon chini ya ulinzi wa Urusi-Ottoman", "08839694"], "d": ["Mwaka 1799 meli za pamoja za Urusi-Ottoman ziliwatoa Wafaransa kwenye visiwa vya İyon (Ngome ya Korfu ilianguka tarehe 5 Machi 1799); kwa makubaliano ya vifungu kumi na viwili ya tarehe 21 Machi 1800, visiwa vilianzishwa kama Cezâyir-i Seb'a-i Müctemia Cumhuru (Jamhuri ya Visiwa Saba), yenye uhuru wa ndani na utegemezi kwa Ottoman katika mambo ya nje. Kipindi kati ya 1799-03-05 na siku hii ni kipindi cha uvamizi wa pamoja.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Tilsit — haki za Urusi juu ya Jamhuri ya Visiwa Saba zilikabidhiwa kwa Ufaransa", "98a78beb"], "d": ["Kwa makubaliano yaliyofikiwa Tilsit kati ya Urusi na Ufaransa, Urusi iliiachia Ufaransa haki zake juu ya Visiwa Saba; vikosi vya Ufaransa vilikaa visiwani majira ya joto ya 1807 na Jamhuri ya Visiwa Saba ilitoweka.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Ayamavra na Visiwa vya İyon kupita chini ya ulinzi wa Uingereza — utaratibu wa baada ya Napoleon", "0af821dc"], "d": ["Ayamavra na visiwa vingine vya İyon vilivyopita kwa Ufaransa mwaka 1797, baada ya kushindwa kwa uhakika kwa Napoleon, kwa mkataba maalum uliotiwa saini Paris tarehe 5 Novemba 1815 kati ya Uingereza, Urusi, Austria na Prussia viliachiwa chini ya ulinzi wa Uingereza kwa jina 'Majimbo ya Muungano ya Visiwa Saba' — hili ni waraka tofauti na Mkataba wa jumla wa Paris wa tarehe 20 Novemba 1815. Ulinzi ungedumu hadi 1864, kisha visiwa vingekabidhiwa kwa Ugiriki.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Kutekwa kwa Prizren — kitovu cha sancak ya Ottoman Kosova", "f84c220f"], "d": ["Tarehe 4 Receb 859 (20 Juni 1455), jeshi la Ottoman chini ya amri ya Fâtih Sultan Mehmed lilichukua Prizren baada ya vita na despot wa Kiserbia Curac Brankoviç — Vılkoğlu katika vyanzo vya Ottoman. Mji ulikuwa umepita kutoka Bizanti kwenda Ufalme wa Kiserbia katikati ya karne ya XIII na ulikuwa makazi ya kifalme katika enzi za Mfalme Milutin, Tsar Duşan na Mfalme Uroş; umuhimu wake ulikuwa umepungua baada ya kifo cha Duşan. Baada ya ushindi ulifanywa kitovu cha sancak na ulihifadhi hadhi hii kwa karne nne na nusu hadi 1912. Prizren ilikuwa mji pekee Balkan ambamo lugha tatu — Kialbania, Kituruki na Kiserbia — zilizungumzwa pamoja kabla ya kuvunjika kwa Yugoslavia.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["Kuanguka kwa Bastille — mwanzo wa Mapinduzi ya Ufaransa", "96e931f1"], "d": ["Katikati ya hasira iliyotokana na Mfalme XVI. Louis kumwondoa waziri wa fedha Necker (11 Julai 1789) na mgogoro wa kiuchumi, wananchi wa Paris walielekea ngome ya Bastille wakidai silaha na baruti. Katika mapigano yaliyoanza alasiri, ngome ambayo walinzi wapatao mia moja tu walikuwa dhidi ya waasi zaidi ya elfu tatu ilisalimu amri karibu saa 17:00; watumishi kadhaa, ikiwemo kamanda wa ngome Bernard-René de Launay, waliuawa na wafungwa saba waliachiliwa. Ngome iliyokuwa karibu tupu na iliyopangwa kubomolewa tayari ilikuwa ishara ya dhuluma ya kifalme — kuanguka kwake kunaripotiwa kwa XVI. Louis kwa maneno 'Hapana bwana, huu si uasi, ni mapinduzi'. Tarehe 14 Julai leo ni siku ya taifa ya Ufaransa na tukio linahesabiwa kuwa mwanzo wa ishara wa harakati ya wananchi iliyoenea haraka nchi nzima na wa Mapinduzi ya Ufaransa (1789-1799) — mapinduzi, katika muongo uliofuata, kwa kuangusha ufalme kamili, yangebadilisha kwa kudumu ramani ya kisiasa ya Ulaya na mizani ya kimataifa ambayo Ottoman nayo ilikuwa sehemu yake.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["Jeshi la Kimamluki liliingia Malatya — mji ulipita kutoka Ilhanlı kwenda utawala wa Kimamluki", "2540363d"], "d": ["Wamamluki walituma jeshi chini ya amri ya naib wa Dımaşk Seyfeddin Tengiz kuelekea Malatya; jeshi liliingia mjini tarehe 22 Muharrem 715 (28 Aprili 1315). Malatya hadi siku hiyo ilikuwa chini ya utawala wa Ilhanlı na ilikuwa kituo kikuu cha mstari ambapo maeneo ya ushawishi ya Ilhanlı na Mamluki yaligusana magharibi mwa Furat. Kubadilisha mikono kwa mji kunaonyesha kusonga kwa Wamamluki kuelekea Furat ya Juu katika mvutano mrefu kati ya dola mbili. Malatya baada ya tarehe hii ingeingia kwa muda chini ya utawala wa Eretnaoğulları, na kuanzia 1338 ingerudi tena chini ya utawala wa Kimamluki.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Mwisho wa Beylik ya Eşrefoğulları — Beyşehir na Seydişehir zilipita kwa Hamîdoğulları", "e4e70846"], "d": ["Demirtaş, mwana wa Emîr Çoban, gavana mkuu wa Anatolia wa Dola ya Ilhanlı, alichukua hatua dhidi ya beylik za Kiturkmen zilizotangaza uhuru wao na, akiingia Beyşehir, alimuua Eşrefoğlu Süleyman Şah aliyekuwa amemlalamikia hapo awali (9 Oktoba 1326). Beylik ya Eşrefoğulları, iliyoanzishwa mwishoni mwa karne ya XIII katika eneo la Beyşehir na Seydişehir, hivyo ilimalizika. Makala ya TDV ya Hamîdoğulları inatoa mwendelezo: Beyşehir, Seydişehir, Akşehir na Doğanhisar zilizokuwa za Eşrefoğulları walioondolewa na Demirtaş ziliunganishwa na mipaka ya beylik ya Hamîd. Mwaka huo huo Hamîdoğlu Dündar Bey pia alikabidhiwa kwa Demirtaş na kuuawa. Ardhi hizi zingeuzwa kwa I. Murad mwaka 1381 kwa dhahabu 80.000 na kupita chini ya utawala wa Ottoman.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Malatya iliingia tena chini ya utawala wa Kimamluki — mwisho wa utawala wa Eretnaoğulları", "08b80aa2"], "d": ["Malatya, iliyoingia chini ya utawala wa Kimamluki mwaka 1315, katika miaka ya kuvunjika kwa Dola ya Ilhanlı kwa muda ilikuwa imepita mikononi mwa Eretnaoğulları. Makala ya TDV ya Malatya inatoa kurudi kwa sentensi moja: kuanzia 1338 Wamamluki walitawala mji tena. Hii ni kipande cha miaka ambayo pengo la baada ya Ilhanlı kusini-mashariki mwa Anatolia lilishirikiwa kati ya Mamluki na Eretna.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Kupotea kwa Bandari ya İzmir kwa meli za Wapiganaji wa Msalaba — nguvu za majini za Aydınoğulları zilivunjika", "775c65fe"], "d": ["Meli za Wapiganaji wa Msalaba zilizoundwa na meli za Venice, Genoa, Ufalme wa Kupro, wapiganaji wa Rodos na duke wa Naksos kwa kuhimizwa na Papa VI. Clement ziliichukua Bandari ya İzmir kutoka kwa Aydınoğulları (28 Oktoba 1344). Bandari ilichukuliwa mwaka 1328-1329 na Mehmed Bey, baba wa Umur Bey, kutoka kwa Mgenoa Martino Zaccaria na ilikuwa kituo cha nguvu za majini za Aydınoğlu Aegean. Mwezi Septemba 1334 kundi la meli za Wapiganaji wa Msalaba lililokuja kwa madhumuni hayo hayo lilikuwa limelazimika kurudi nyuma; kampeni hii ya pili ilifanikiwa. Umur Bey aliendelea na upinzani na, kwa kuungana na beylik nyingine za Kituruki, alishinda meli za Wapiganaji wa Msalaba tarehe 17 Januari 1345, lakini bandari haikuweza kurudishwa.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Karamanoğlu Alâeddin Bey alijumuisha Konya, Aksaray na Niğde kwenye ardhi za Karaman", "2b8b0f70"], "d": ["Karamanoğlu Alâeddin Bey, aliyetaka kunufaika na Usultani wa Kimamluki kuuondoa Ufalme wa Armenia na kuunganisha Çukurova yote na ardhi zake, na machafuko yaliyotokea katika Dola ya Eretna ya Anatolia ya Kati, alijumuisha kwenye ardhi za Karaman, kuanzia na Konya (1366-1367), Niğde Karahisarı (Yeşilhisar), Aksaray, Akşehir, Ilgın, İshaklı na Kayseri. Konya, kwa uzito iliyokuwa nao kama mji mkuu wa Waseljuk, kwa Karamanoğulları haikuwa mji tu bali madai ya uhalali.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Uzun Hasan alimaliza Dola ya Karakoyunlu — bonde la ziwa la Van lilipita kwa Akkoyunlu", "d8d6c2e8"], "d": ["Mtawala wa Akkoyunlu Uzun Hasan, mwaka 1467, kwa kumshtukiza adui yake asiyesamehe, mtawala wa Karakoyunlu Cihan Şah aliyeelekea dhidi yake, alimaliza Dola ya Karakoyunlu. Kwa kuondolewa kwa Cihan Şah aliyetawala tangu 1438, bonde la ziwa la Van — Van, Bitlis, Bargiri (Muradiye), Hoşap na Kotur — lilipita kutoka Karakoyunlu hadi utawala wa Akkoyunlu. Ushindi huu uliifanya Dola ya Akkoyunlu kuwa nguvu kuu pekee Anatolia Mashariki na Iran na ukamweka Uzun Hasan kwenye njia ambayo ingemkutanisha na Ottoman kizazi kimoja baadaye.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Cem Sultan alipelekwa Roma — diplomasia ya mateka na dukati 40.000 kila mwaka", "1c6715a8"], "d": ["Papa VIII. Innocent, kwa makubaliano na Pierre d'Aubusson, mkuu wa wapiganaji wa Rodos, alimleta Cem Sultan Roma (4 Machi 1489). Cem alikuwa amekimbilia Rodos tarehe 29 Julai 1482, kutoka huko kwenda ardhi za Savoie, na hatimaye chini ya uangalizi wa papa. II. Bayezid alikuwa amekubali kuwalipa wapiganaji dukati 40.000 kila mwaka kwa kumshikilia kaka yake na kuwapa haki ya biashara huru katika ardhi za Ottoman. Malipo haya hayakuwa haraç, bali gharama ya kumfanya mpinzani halali wa kiti asisogee Ulaya: Cem angeachiliwa angeweza kukusanya jeshi Anatolia, na zaidi ya hayo angeweza kuwa chanzo cha uhalali kwa Vita vya Msalaba. Hivyo suala la nasaba likawa kikwazo kikuu cha siasa ya nje ya Ottoman kwa miaka thelathini — hii ndiyo sababu ya Bayezid kuwa mwangalifu Magharibi. Kwa kifo cha Cem mwaka 1495 kikwazo hiki kiliondoka.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Ufalme wa Georgia uligawanywa mara tatu — Kartli, Kaheti na İmereti yenye kitovu Kutaisi", "f9c5f798"], "d": ["Ufalme wa Georgia ulioungana uliotawaliwa na nasaba ya Bagratî, baada ya mapambano marefu ya ndani, uligawanywa rasmi kuwa falme tatu: Kartli yenye kitovu cha Tiflis mashariki, Kaheti kaskazini-mashariki na İmereti yenye kitovu Kutaisi magharibi. Makala ya TDV ya Gürcistan inathibitisha mgawanyo — 'Georgia iligawanywa kuwa falme tatu (Kartliya, Kahetya, İmeretiya) na beylik tano'. Mgawanyo ulikuwa wa maamuzi katika mvutano wa Ottoman-Wasafavî wa karne iliyofuata: kwa Mkataba wa Amasya wa 1555, İmeret, Dadyan, Güryel na Daveli ziliachiwa Ottoman; Kartli, Kahet na Mosuk ziliachiwa Wasafavî. Yaani atlasi kufunga Georgia ya magharibi na mashariki kwa mabwana tofauti kunatokana na mgawanyo huu. Yavuz Sultan Selim, akiwa bado gavana wa Trabzon, mwaka 1508 alikuwa ameufunga Ufalme wa İmeret (Açıkbaş) kwa utii na kodi.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Uvamizi wa Wahispania wa Trablusgarp — mwisho wa utawala wa Hafsî", "de319d23"], "d": ["Baada ya Ammâroğulları, utawala wa Hafsî Trablusgarp uliendelea hadi mwaka 1510. Mwaka huo mji ulivamiwa na Wahispania chini ya amri ya Kont wa Oliveto Don Pedro Navarro; Waislamu waliookoka mauaji waliuacha mji. Uvamizi huu ulikuwa ncha ya mashariki ya mnyororo wa ngome za Uhispania kwenye pwani ya Afrika Kaskazini unaoenea kutoka Melilla hadi Trablus. Wakazi wa Trablusgarp wangetuma ujumbe İstanbul mwaka 925 (1519) kuomba msaada wa Ottoman dhidi ya uvamizi wa Kihispania, na mji ungechukuliwa mwaka 1551 na Turgut Reis na Sinan Paşa na kuingia chini ya utawala wa Ottoman.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Malta na Trablus zilipewa Wapiganaji wa Saint Jean — kituo kipya cha agizo lililofukuzwa Rodos", "2595729e"], "d": ["Wapiganaji wa Saint Jean (Hospitalier), waliotolewa Rodos na Kanûnî Sultan Süleyman mwaka 928 (1522), baada ya kubaki miaka minane bila makazi, waliwekwa Malta na Mfalme wa Uhispania-Ujerumani V. Carlos; kwa zawadi hiyo hiyo ulinzi wa Trablusgarp pia ulipewa agizo. Malta ikawa kituo kinachofaa kwa wapiganaji wenye ushawishi baharini kwa bandari bora ilizokuwa nazo: kwanza walikaa Birgu, waliimarisha Ngome ya Saint Angelo na kujenga Ngome ya Saint Michel kwenye ncha ya Senglea. Makazi haya yalizaa kituo cha adui cha kudumu katikati ya Mediterania kinachokata njia za baharini za Ottoman; mapigano yaliyoanza kwa shambulio la Turgut Reis la Gozo mwaka 947 (1540) yangeendelea hadi Mzingiro wa Malta wa 1565.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Amani ya Vestfalya — Vita vya Miaka Thelathini vilimalizika, umoja wa Roma Takatifu ulivunjika", "d7719f05"], "d": ["Mikataba iliyomaliza Vita vya Miaka Thelathini (1618-1648) ilitiwa saini Münster na Osnabrück siku hiyo hiyo (24 Oktoba 1648). Ufalme mdogo karibu mia tatu wa Dola Takatifu ya Kirumi ulipata haki ya kuendesha siasa zao za nje; himaya ilikoma kuwa dola na ikageuka kuwa paa. Uswidi ilichukua Pomerania Magharibi na Stettin, Brandenburg ilipata Pomerania Mashariki na matarajio ya uaskofu mkuu wa Magdeburg — mkusanyiko wa ardhi wa Hohenzollern utakaoelekea ufalme mwaka 1701 unaanzia hapa. Uhuru wa Uholanzi na Uswisi ulitambuliwa rasmi. Kwa Ottoman umuhimu ni usio wa moja kwa moja lakini mkubwa: Wahabsburg walipojiondoa kwenye mstari wa magharibi, nguvu iliyoweza kugeukia tena mashariki Ulaya ya Kati ilizaliwa.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Ufalme wa Prussia ulitangazwa — I. Friedrich alitawazwa Königsberg", "337a9f74"], "d": ["Elector wa Brandenburg III. Friedrich, kwa idhini ya Maliki I. Leopold, alitawazwa Königsberg na kupokea cheo cha «Mfalme katika Prussia» (18 Januari 1701). Cheo kilichukuliwa kutoka Prussia Mashariki, kwa sababu huko palikuwa nje ya Dola Takatifu ya Kirumi na elector aliyefungwa na maliki angeweza kuwa mfalme nje ya mipaka ya himaya tu. Ardhi zilizotawanyika za nasaba ya Hohenzollern zilianza baada ya tarehe hii kutajwa kwa jina moja la dola.", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["Sardinia ilipita kutoka Uhispania kwa nasaba ya Savoy — Ufalme wa Sardinia ulizaliwa", "adf778b7"], "d": ["Katika kiungo cha mwisho cha mipangilio iliyofunga Vita vya Urithi wa Uhispania, kisiwa cha Sardinia kilichukuliwa kutoka Uhispania na kupewa nasaba ya Savoy; duke wa Savoy aliiachia Sicilia kwa malipo na akapokea cheo cha Mfalme wa Sardinia. Cagliari na Sassari hivyo zilitoka kwenye utawala wa Kihispania wa karne mbili. Ufalme wa Sardinia uliozaliwa ni kiini cha dola itakayoanzisha muungano wa Italia karne moja na nusu baadaye — yaani mzizi wa Ufalme wa Italia uliouingia Roma mwaka 1870 unaanzia hapa.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["Korsika iliuzwa na Genoa kwa Ufaransa — Mkataba wa Versailles", "770343df"], "d": ["Jamhuri ya Genoa iliikabidhi Ufaransa Korsika, iliyoishikilia kwa karne nyingi lakini ambayo kwa sababu ya uasi haikuweza kuidhibiti kwa vitendo. Makala ya TDV ya Korsika inatoa tukio kwa sentensi moja: Genoa iliuza kisiwa hiki, ambacho haikuweza kukimiliki sana, kwa Ufaransa mwaka 1768. Kukabidhi kunaashiria kujiondoa kwa Genoa kutoka mali yake kuu ya mwisho ya ardhi Mediterania; kisiwa kingepita kwa muda mikononi mwa Waingereza mwaka 1796, kisha kingerudishwa tena kwa Ufaransa. Kisiwa kuwa ardhi ya Ufaransa kulimfanya Napoleon Bonaparte, atakayezaliwa Ajaccio mwaka mmoja baadaye, kuwa raia wa Ufaransa. Mwaka huu (1768) Korsika, ikijumuisha Bastia, iliuzwa kutoka Genoa kwa Ufaransa (TDV Korsika; siku haijathibitishwa).", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Mkataba wa Tilsit — Prussia ilipoteza nusu ya ardhi zake, Dukedom ya Varşova ilianzishwa", "d30bb2cc"], "d": ["Baada ya kushindwa kwa Jena-Auerstedt, Prussia ililazimika kukubali amani nzito na Napoleon huko Tilsit (9 Julai 1807). Iliachia ardhi zake zote magharibi mwa Elbe na ardhi za Poland ilizozipata katika mgawanyo wa 1793 na 1795; kutoka za pili hizi Dukedom ya Varşova ilianzishwa na eneo la Białystok lilipewa Urusi. Prussia ilipoteza takriban nusu ya idadi yake ya watu na ardhi, na jeshi lake lilipunguzwa hadi 42.000. Katika atlasi Poznan na Toruń zinapita kuanzia siku hii kwa Dukedom ya Varşova, na Białystok kwa Urusi. Kwa mkataba huu Łódź na Częstochowa (majimbo ya Poland yaliyopita kwa Prussia baada ya 1772) zilipita kwa Dukedom ya Varşova; Gdańsk (Danzig) ikawa mji huru.", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Vikosi vya Italia viliingia Roma — mwisho wa Dola ya Papa na kukamilika kwa muungano wa Italia", "a3689f2e"], "d": ["Kwa kupinduliwa kwa III. Napoleon katika Vita vya Ufaransa-Prussia, kikosi cha Kifaransa kilichokuwa kikilinda Roma kilipoondolewa, vikosi vya Italia viliingia mjini na papa alirudi Vatikani. Hivyo Dola ya Papa iliyoendelea kuwepo kwa zaidi ya miaka elfu moja ilimalizika na Ufalme wa Italia, ulioiunganisha Roma pia, ulipanda jukwaani la Ulaya na dunia kama nguvu ya kisiasa. Hili ni tukio lenye matokeo ya moja kwa moja kwa nusu karne ya mwisho ya atlasi: Italia iliyoungana ni dola itakayochukua Trablusgarp na Visiwa Kumi na Viwili kutoka Ottoman mwaka 1911.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Vita vya Çelenko — mwisho wa Emirliği ya Harar na uvamizi wa Habeş", "5671a0d9"], "d": ["Dâvûd alipokuwa imamu wa Aussa, Harar, iliyokuwa katikati ya ardhi zinazotawaliwa na Waoromo, ilikuwa emirlik huru tena na ilidumisha hali hii hadi uvamizi wa Habeş wa 1887. Emîr Abdullah, aliyetangaza jihadi, aliwakabili Wahabeş Şeleneko (Çelenko) tarehe 7 Januari 1887 na watu 5000; alipoona atashindwa, alikimbilia eneo la Ogaden kusini mwa Harar. Vita vilionyesha tofauti ya usawa kati ya jeshi la Habeş lililokuwa na silaha za moto na vikosi vya emirlik na viliondoa mojawapo ya emirlik huru za mwisho za Kiislamu ng'ambo ya Bahari Nyekundu. Harar, Cîcîga na Dagahbûr hivyo ziliunganishwa na Habeşistan.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Şah İsmâil kuchukua Derbend — utawala wa Wasafavî ulifika mlango wa Caucasus", "305542c4"], "d": ["Şirvanşah Ferruh Yesâr aliposhindwa na kuuawa mwaka 1500, Bakü na Şemâhî zilipita mikononi mwa Wasafavî, na Derbend ilibaki tofauti kwa muda zaidi. Şah İsmâil mwaka 1509 alichukua mji na kuweka hapo moja ya makabila ya Rumlu; hivyo utawala wa Wasafavî ulifika mlango wa kaskazini wa Caucasus, njia hii nyembamba kati ya Hazar na milima. Kwa Şirvan kuingia chini ya utawala wa moja kwa moja wa Wasafavî mwaka 1538, uhusiano ulikuwa wa kudumu. Derbend ingepita mikononi mwa Ottoman katika kampeni ya 1578 na ingekuwa kitovu cha beylerbeylik ya sancak saba hadi 1607. Rekodi ya TDV ni hii: \\\"Kuundwa na kukua kwa Dola ya Wasafavî kulikuwa mwanzo wa kipindi kipya Derbend. Şah İsmâil mwaka 1509 alichukua mji na kuweka hapo moja ya makabila ya Rumlu. Mwaka 1538 Şirvan ilipoingia chini ya utawala wa moja kwa moja wa Wasafavî...\\\"", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Kuunganishwa kwa uhakika kwa Kars na ardhi za Ottoman — msumari wa mpaka wa mashariki", "6235c85a"], "d": ["Baada ya Dola ya Akkoyunlu kuangushwa na Wasafavî, Kars ilibaki kwa muda mikononi mwa Sevündük Han Kurçibaşı wa Waturkmen wa Avşar. Wakati wa Kampeni ya Irakeyn ya Kanûnî (940/1534), ngome za Pasin, Şüregel na Oltu zilipochukuliwa, kuna uwezekano mkubwa kwamba Ngome ya Kars nayo ilifungwa kwa Ottoman; hata hivyo kuunganishwa kwa uhakika kwa mji ni miaka mitatu baadaye. Rekodi ya TDV ni hii: \\\"Kars iliunganishwa kwa uhakika na ardhi za Ottoman mwaka 944 (1537) na Dulkadırlı Mehmed Han aliyeingia katika huduma ya Ottoman.\\\" Kwa kuwa mji na ngome vilikuwa vimeharibiwa kwa kiasi kikubwa na mapambano marefu, ukarabati wa haraka ulianzishwa; wakati ngome ilipokuwa ikirekebishwa mwaka 955 (1548), Wasafavî walishambulia mji na kuiharibu tena ngome. Kars baadaye kwa miaka mia tatu arobaini ingebaki kama kufuli ya mpaka wa kaskazini-mashariki wa Ottoman, na ingeachiwa Urusi baada ya vita vya 1877-78.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Kurudishwa kwa Niğbolu — uvamizi wa miezi sita wa Urusi ulimalizika", "7fb299d7"], "d": ["Katika vita vya Ottoman-Urusi vya 1806-1812, vikosi vya Urusi vilivyovuka hadi ufuo wa kusini wa Danube vilikuwa vimechukua Niğbolu Oktoba 1810 chini ya amri ya Jenerali Kutuzov. Miezi sita baadaye, kwa kuona hawawezi kushikilia mstari wa Danube, waliuacha mji; kabla ya kuondoka walilipua sehemu muhimu ya ngome. Rekodi ya TDV ni hii: \\\"Mwezi Oktoba mwaka 1810 (katika kipindi cha vita vya Kituruki-Kirusi vya 1808-1812) Niğbolu ilichukuliwa na vikosi vya Jenerali maarufu wa Kirusi Michail Kutuzov. Warusi, kabla ya kuuacha mji, mwezi Aprili 1811 walilipua sehemu muhimu ya ngome na kuuletea mji uharibifu mkubwa.\\\" Vikosi vya Urusi vilipoondoka, Waottoman walijenga upya ngome; kitabe cha 1813-1814 ni rekodi ya ukarabati huu.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Kuhamishwa kwa Silistre — ngome ya kati ya Danube iliachwa kuta zikiwa zimebomolewa", "561628bb"], "d": ["Silistre, mojawapo ya ngome zenye nguvu zaidi za Ottoman kwenye Danube, ilikuwa imepigwa na mizinga ya Urusi mwaka 1810, na kwa mlipuko wa ghala la silaha ngome na viunga vilipata uharibifu mkubwa. Warusi, baada ya kuchukua mji, badala ya kuushikilia walichagua kuharibu ngome zake: Jenerali Kutuzov aliamuru kuta zibomolewe na mwezi Mei 1811 alimjulisha tsar kwamba kuta za Silistre zimelipuliwa. Rekodi ya TDV: \\\"Mwaka 1810 mji ulipigwa na Warusi kwa mizinga… Baada ya Warusi kuuchukua mji na kabla ya kurudi, Jenerali Kutuzov aliamuru Silistre ibomolewe. Mwezi Mei 1811 alimjulisha tsar kwamba kuta za Silistre zimelipuliwa.\\\" Ngome hiyo hiyo ingechukuliwa tena na Warusi katika vita vya 1827-1828 na mzingiro huo ungesimuliwa kwa kina na Helmuth von Moltke.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Mwisho wa nasaba ya Zend — utawala wa Kaçar Iran", "5dda30a4"], "d": ["Kwa kushindwa kwa mtawala wa mwisho wa nasaba ya Zend Lutf Ali Han, nasaba iliyoanzishwa mwaka 1751 ilimalizika na Iran yote ilipita mikononi mwa Ağa Muhammed Han. Kuanzishwa rasmi kwa Dola ya Kaçar kunatarehe miaka miwili baadaye, Ağa Muhammed Han alipovaa taji ya şehinşah huko Tahran (1796); lakini mamlaka yalibadilishwa mwaka 1794.", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Tofauti za Lozan–Sevr: kutoka amani iliyolazimishwa hadi amani ya usawa", "4b578583"], "d": ["Sevr (10 Agosti 1920) ilikuwa waraka uliolazimishwa serikali ya İstanbul ambao haukuwahi kuanza kutumika; Lozan (24 Julai 1923) kwa upande mwingine ni amani ambayo Ankara ilitia saini kama upande wa usawa na TBMM iliiidhinisha tarehe 23 Agosti 1923 (Lozan k. 1, 143). Katika mipaka, Sevr inavuta mpaka wa Ulaya wa Uturuki hadi mstari wa Çatalca na kuipa Ugiriki Thrace Mashariki ikijumuisha Edirne na İmroz na Bozcaada (Sevr k. 27, 84); İzmir na viunga vyake kwa upande mwingine jina linabaki chini ya ukuu wa Kituruki lakini utawala unaachiwa Ugiriki, na baada ya miaka mitano bunge la eneo linaweza kuomba kujiunga (k. 65-83). Lozan inachora mstari wa Meriç-Arda, Edirne na Karaağaç zinabaki Uturuki, İmroz na Bozcaada zinakuwa za Kituruki (Lozan k. 2, 12, 14; Itifaki ya Karaağaç). Katika Mlangobahari, Sevr inaanzisha tume ya kimataifa inayoenea kwenye maji yote ambamo mwanachama wa Kituruki ana kura moja tu; ngome zinabomolewa na eneo linafunguliwa kwa matumizi ya Washirika (Sevr k. 36-61, 178-180). Lozan inahifadhi kanuni ya kupita kwa uhuru lakini inaacha tume yenye mwenyekiti wa Kituruki, maeneo yasiyo na silaha na kikosi cha watu 12.000 İstanbul (Lozan k. 23; Mkataba wa Mlangobahari). Kutambuliwa kwa Armenia na uamuzi wa mpaka wa rais wa Marekani, na mpango wa uhuru wa ndani wa Wakurdi (Sevr k. 62-64, 88-93) hautokei Lozan. Kuhusu ardhi za Kiarabu, Misri, Sudan na Kupro, Sevr inaweka masharti ya kina ya kukabidhi (Sevr k. 94-97 mandate, k. 98-100 Hicaz, k. 101-122 kuachana na Misri, Sudan, Kupro, Moroko, Tunis na Libya; vipindi vya makala vya TDV pia ni hivyo); Lozan inaandika kuachana kwa ufupi zaidi, Visiwa Kumi na Viwili vinabaki kwa Italia, Kupro kwa Uingereza, mpaka wa Musul unaahirishwa (Lozan k. 3, 15-21). Sevr inaanzisha upya na kupanua kapitulasyon, inadhibiti bajeti na ukopaji wa Kituruki kupitia Tume ya Fedha, nguvu za silaha (jandarma na vipengele vya nyongeza) haziwezi kuzidi watu 50.000, na anga ya kijeshi na ya majini imepigwa marufuku (Sevr k. 155, 164, 191-195, 231-264, 261-263). Lozan inakomesha kapitulasyon, inagawanya madeni na haiweki kikwazo tofauti cha jeshi (Lozan k. 28, 46-63; k. 113 pia inaondoa posta za kigeni). Masharti ya walio wachache ni mapana zaidi katika Sevr na yaliyo wazi kwa uingiliaji wa Washirika, wakati katika Lozan yana dhamana ya Ushirika wa Mataifa na ni ya kuheshimiana (Sevr k. 140-151; Lozan k. 37-45).\n\nMlinganisho kwa kila mhimili:\n• Thrace Mashariki, Edirne, Çatalca — Sevr: Mstari wa Çatalca ni mpaka; Thrace Mashariki na Edirne kwa Ugiriki (k. 27, 84-85) | Lozan: Mpaka kando ya Meriç na Arda; Edirne na Karaağaç Uturuki (k. 2; Itifaki ya Karaağaç)\n• Eneo la İzmir — Sevr: Ukuu ni wa Kituruki, utawala na jeshi la Kigiriki, ombi la kujiunga baada ya miaka mitano (k. 65-83) | Lozan: Hakuna kifungu maalum cha hadhi kwa İzmir; Anatolia iko ndani ya mipaka ya Uturuki (k. 2-3 mpaka wa jumla; hakuna ushahidi wa kifungu mahususi kwa İzmir)\n• Mlangobahari na İstanbul — Sevr: Tume ya Kimataifa ya Mlangobahari, Mturuki kura 1; kubomolewa kwa ngome, eneo chini ya matumizi ya Washirika; İstanbul iko mikononi mwa Waturuki lakini imefungwa na sharti la walio wachache (k. 36-61, 178-180) | Lozan: Kanuni ya kupita kwa uhuru; tume yenye mwenyekiti wa Kituruki, maeneo yasiyo na silaha, kikosi cha watu 12.000 İstanbul (k. 23; Mkataba wa Mlangobahari)\n• Armenia na Kurdistan — Sevr: Armenia inatambuliwa, mpaka wake unaamuliwa na rais wa Marekani; uhuru wa ndani wa Wakurdi, ombi la uhuru baada ya mwaka mmoja (k. 62-64, 88-93) | Lozan: Hakuna kifungu husika (hakitokei katika muhtasari wa k. 1-143)\n• Visiwa vya Aegean, Visiwa Kumi na Viwili — Sevr: İmroz, Bozcaada na visiwa vya Aegean kwa Ugiriki; Visiwa Kumi na Viwili na Meis kwa Italia (k. 84, 122) | Lozan: İmroz na Bozcaada Uturuki, visiwa vya Aegean Mashariki Ugiriki, Visiwa Kumi na Viwili na Meis Italia (k. 12-15)\n• Kupro, Misri, Sudan, ardhi za Kiarabu — Sevr: Mandate ya Syria/Mesopotamia na Palestina, Hicaz huru; ulinzi wa Misri, Sudan, kuunganishwa kwa Kupro kunatambuliwa (k. 94-98, 101-117) | Lozan: Mpaka wa Syria kwa makubaliano ya Kifaransa-Kituruki ya 1921, mpaka wa Iraq baadaye; kuachana na Misri, Sudan, Kupro (k. 3, 16-20)\n• Kapitulasyon — Sevr: Zinaanzishwa upya na kupanuliwa; mpango wa mageuzi ya mahakama katika tume ya Washirika (k. 136, 261-263, 308-309) | Lozan: Zinakomeshwa kabisa; posta za kigeni na Yüksek Sıhhiye Meclisi zinaondolewa (k. 28, 113-114)\n• Udhibiti wa fedha na madeni — Sevr: Tume ya Fedha ya Washirika inadhibiti bajeti na ukopaji, Düyun-ı Umumiye inapanuka, rasilimali ni dhamana (k. 231-264) | Lozan: Düyun-ı Umumiye inagawanywa kati ya hisa za dola; hasara za vita zinaachwa kwa pande zote (k. 46-63, 58)\n• Vikwazo vya kijeshi — Sevr: Jeshi watu 50.000, nguvu za anga na vifaru vimepigwa marufuku, Tume za Udhibiti za Washirika (k. 152-207) | Lozan: Hakuna kikwazo cha jumla; kuondoa silaha tu katika visiwa vya Kigiriki na maeneo ya Mlangobahari-Thrace (k. 13; mikataba ya Mlangobahari na Thrace)\n• Walio wachache — Sevr: Dhamana na haki ya kuingilia ya Washirika, kufutwa kwa Emval-i Metruke, kurudishwa (k. 140-151, 86, 142-144) | Lozan: Haki zenye dhamana ya Ushirika wa Mataifa kwa walio wachache wasio Waislamu, haki za Waislamu za kuheshimiana Ugiriki; ubadilishanaji wa Wagiriki-Waturuki (k. 37-45; Mkataba wa Ubadilishanaji)\n• Hadhi ya kisheria — Sevr: Ilitiwa saini na serikali ya İstanbul, Ankara iliikataa, haikuanza kutumika (TDV) | Lozan: Upande wa usawa; idhini ya TBMM tarehe 2 Agosti 1923, kura 213 za ndiyo 14 za hapana (TDV; k. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Kutengenezwa kwa akçe ya kwanza ya Ottoman", "38d2d638"], "d": ["Akçe ya kwanza ya fedha iliyotengenezwa kwa jina la Orhan Gazi ni tangazo la kifedha la mamlaka huru ya beylik; akçe ilibaki sarafu ya msingi kwa karne tano.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Beylerbeylik ya Rumeli yaanzishwa", "ffa16089"], "d": ["Ushindi wa upande wa Ulaya ulikusanywa chini ya mwavuli mmoja wa kijeshi na kiutawala; mfumo wa beylerbeylik ukawa uti wa mgongo wa mfumo wa mikoa wa himaya.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Ndoa ya Yıldırım Bayezid – Despina Hatun", "4b10dc6c"], "d": ["Utegemezi ulioundwa na ufalme wa Kiserbia baada ya Kosova ulitiwa muhuri kwa ndoa ya Olivera, binti Lazar, na Bayezid — mfano wa kawaida wa diplomasia ya ndoa ya kipindi cha awali.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Beylerbeylik ya Anatolia yaanzishwa", "5ef8d3a7"], "d": ["Beylerbeylik ya Anatolia ilipangwa kwa ajili ya kusimamia ardhi za beylik zilizounganishwa; mfumo wa utawala wa mabawa mawili ya Rumeli-Anatolia ulikamilika.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Msikiti Mkuu wa Bursa wakamilika", "27bcc4a5"], "d": ["Msikiti mkuu wa kuba ishirini uliojengwa kwa nyara za Niğbolu ni mfano wa kumbukumbu wa usanifu wa awali wa Ottoman na ni jumba la makumbusho la wazi la sanaa ya khati.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Kuondolewa na kunyongwa kwa Çandarlı Halil Paşa", "5e19438f"], "d": ["Baada ya ushindi, sadrazam wa familia ya zamani ya Çandarlı, aliyekuwa akikaa mbali na kuzingirwa, alinyongwa; kwa mara ya kwanza sadrazam aliuawa kwa amri ya sultani, na enzi ya mawaziri wenye asili ya devşirme ilianza.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Bogdan kuwekwa chini ya kodi", "25bd3693"], "d": ["Voivodeship ya Bogdan ilikubali kulipa kodi; pamoja na Eflak na Erdel, ukanda wa utegemezi mara tatu kaskazini mwa Danubi ukawa bafa ya kaskazini ya himaya. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Yaş.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Kodi ya Dubrovnik (Raguza)", "d127c78a"], "d": ["Jamhuri ya wafanyabiashara Raguza ilihakikisha uhuru wake wa ndani na marupurupu ya biashara kwa kodi; ilitajirika kama dirisha la Ottoman kwenye Adriatic. Kisiwa cha Mliyet (Mljet), ardhi ya jamhuri, nacho kilishiriki hadhi hii.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Msafara wa Eflak: Voivode wa Kuchomwa Miti", "fd4530bb"], "d": ["Kwa msafara uliopangwa dhidi ya Vlad Tepeş, aliyekataa kulipa kodi na kuwaua wajumbe, Eflak ilirudishwa kwenye utegemezi; shambulio la usiku na matukio ya kutisha ya kuchomwa miti yakawa hadithi Ulaya. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Bükreş.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Külliye ya Fatih yafunguliwa", "a150ea55"], "d": ["Külliye, pamoja na madrasa zake nane (Sahn-ı Semân), ilikuwa hatua kubwa ya kwanza ya mpango wa kuifanya Istanbul kituo cha elimu cha ulimwengu wa Kiislamu.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu Istanbul", "8508229d"], "d": ["Ali Kuşçu, mwakilishi mkubwa wa mwisho wa kituo cha uangalizi wa nyota cha Samarkand, kwa mwaliko wa Fatih alikuwa müderris katika Madrasa ya Ayasofya; alianzisha utamaduni wa hisabati-astronomia huko Istanbul.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunnâme ya Fâtih", "b08944c9"], "d": ["Kanunnâme ya kimila ya kwanza ya kina iliyokusanya mpangilio wa dola, itifaki na adhabu; hujadiliwa kwa kifungu chake maarufu kinachoruhusu mauaji ya ndugu 'kwa ajili ya utaratibu wa ulimwengu'.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Dhahabu ya kwanza ya Ottoman (sultanî) ilitengenezwa", "2fd5c0dd"], "d": ["Sarafu ya kwanza ya dhahabu ya Ottoman, sawa na dukati ya Venice, ilitengenezwa; hazina ya dola ilijiunga na mfumo wa fedha wa kimataifa.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Kuhamia Ikulu ya Topkapı", "b9cd6a5e"], "d": ["Kwa kukamilika kwa Ikulu Mpya (Topkapı), kitovu cha utawala wa dola kilihamia hapa; ikulu ilibaki ubongo wa himaya kwa karne nne.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Jamhuri ya Florence yabadilika kuwa dukedom — Alessandro de' Medici", "c08764e1"], "d": ["Kwa shinikizo la Papa VII. Clemens, tume ya uongozi ya Florence (Balìa) ilikubali katiba mpya; utawala wa jamhuri wa karne tano ulikomeshwa na Alessandro de' Medici akatangazwa duke wa kurithi, na tarehe 1 Mei alipanda kiti kwa vitendo. Hivyo Florence ilibadilika kutoka jamhuri huru ya mji hadi dukedom ya kurithi ya nasaba ya Medici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Ndoa ya Kanunî – Hürrem Sultan", "abc05f26"], "d": ["Kanunî kufunga ndoa rasmi na Hürrem kulibadilisha kwa mizizi desturi za ikulu; taasisi ya 'Haseki Sultan' ilizaliwa na mlango wa enzi ya wanawake katika siasa za nasaba ulifunguliwa.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Kapitulasyon za kwanza kamili kwa Ufaransa", "e2264e48"], "d": ["Kama sehemu ya muungano wa Ufaransa dhidi ya kubanwa na Habsburg, upendeleo wa kibiashara ulitiwa saini kati ya Jean de la Forest na Makbul İbrâhim Paşa; kapitulasyon, zilizokuwa zana ya kidiplomasia siku hiyo, zingegeuka kwa karne nyingi kuwa mlango wa utegemezi wa kifedha.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Msafara wa Bahari ya Hindi: kuzingirwa kwa Diu", "fcd1217a"], "d": ["Jeshi la majini lililoondoka Suez lilivuka Bahari Nyekundu na kuizingira Diu huko Gujarat; ingawa ngome haikutekwa, nguvu ya Ottoman ilifika Bahari ya Hindi kwa mara ya kwanza na ukiritimba wa Wareno ulitikiswa.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Safari ya Seydi Ali Reis ya India", "e5da3b2c"], "d": ["Seydi Ali Reis, aliyeagizwa kuleta Misri jeshi la majini lililokuwa Basra, alipeperushwa India na dhoruba; Mir'âtü'l-memâlik, ambamo alisimulia kisa cha kurudi kwake, ni mojawapo ya vitabu vya safari vya kwanza vya Ottoman.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Kunyongwa kwa Pîrî Reis", "63026444"], "d": ["Baharia na mchora ramani mkubwa, aliyerudi kutoka msafara wa Hormuz akiacha jeshi la majini Basra, alinyongwa akiwa na umri wa miaka 84 — mojawapo ya maamuzi yenye utata zaidi katika historia ya sayansi yetu.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Külliye ya Süleymaniye yafunguliwa", "1c6458b2"], "d": ["Külliye ambayo Mimar Sinan aliiita 'kazi ya ufundi wa msaidizi'; kwa madrasa zake, dârüşşifâ yake na maktaba yake ikawa jumba kubwa zaidi la elimu na hisani la enzi ya kawaida.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Kuzingirwa kwa Malta", "f57f6a85"], "d": ["Malta, ufunguo wa Mediterania, ilizingirwa kwa miezi minne; Turgut Reis alikufa shahidi na kuzingirwa kuliondolewa. Ilikuwa hatua kubwa ya kwanza ya kurudi nyuma ya uwezo wa majini wa enzi ya Kanunî.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Msikiti wa Selimiye wakamilika", "3b0484e1"], "d": ["Selimiye, ambayo Sinan aliiita 'kazi ya ustadi', ambapo kuba moja linatawala nafasi, huhesabiwa kuwa kilele cha usanifu wa kawaida wa Ottoman (Urithi wa Dunia wa UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Kituo cha Uangalizi cha Istanbul chaanzishwa", "169bdf5d"], "d": ["Kituo cha uangalizi cha Takiyyüddin, mojawapo ya vilivyokuwa na vifaa bora zaidi vya wakati huo, kilibomolewa mwaka 1580 kwa mijadala iliyoibuka baada ya nyota ya mkia ya 1577; unajimu wa kitaasisi ulichelewa karne tatu.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Ushindi wa Çıldır — vita vya mashariki vyaanza", "13125a54"], "d": ["Kwa kushindwa kwa jeshi la Safavi huko Çıldır, milango ya Caucasus ilifunguka; Tiflis ilitekwa na Georgia ikaingia chini ya utawala wa Ottoman.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Vita vya Mienge — Şirvan yabaki kwa uhakika Ottoman", "3bbc23bc"], "d": ["Katika vita vinavyoitwa kwa jina hili kwa sababu viliendelea usiku kwa mwanga wa mienge, Wasafavi walishindwa kabisa; utawala wa Ottoman Şirvan na Baku uliimarishwa.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Tağşiş Kuu — mgogoro wa akçe", "9205c3d4"], "d": ["Kwa shinikizo la vita virefu na fedha ya Amerika, kiwango cha fedha katika akçe kilishushwa hadi nusu; mapinduzi ya bei yalilisha kuvunjika kwa mfumo wa sipahi na machafuko ya Celâlî.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Ushindi wa Tebriz", "6506bdb9"], "d": ["Serdar Özdemiroğlu Osman Paşa aliingia Tebriz; mji mkuu wa zamani wa Wasafavi uliwekwa chini ya utawala wa Ottoman. Osman Paşa alifariki kambini wiki chache baadaye.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Mkataba wa Ferhad Paşa — mipaka mipana zaidi mashariki", "c429972f"], "d": ["Baada ya kuja Istanbul kwa Haydar Mirza, mjumbe wa Şah Abbas (18 Januari 1590), kwa mkataba uliofanywa kwa sharti la maeneo yaliyotekwa kubaki Ottoman na uliomaliza vita vya miaka 12, Tebriz, Karabağ, Şirvan, Georgia na Luristan zilibaki Ottoman; himaya ilifikia mipaka mipana zaidi ya historia yake upande wa mashariki.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Vita vya Ottoman-Safavi (1603-1612) vyaanza — mashambulizi ya kukabiliana ya Şah Abbas, kupotea kwa Tebriz", "abf27dd8"], "d": ["Şah Abbas, aliyeipanga upya jeshi lake, alianza shambulio kwa kutumia machafuko ya Celâlî; Tebriz ilianguka, na mafanikio ya Caucasus yalipotea ndani ya miaka michache. Makazi mengine yaliyopotea katika msafara huo huo na baadaye: Nahçıvan, Hoy, Merend, Selmâs; beyi wa Karacadağ (Ahar) na Mukrî nao waligeukia upande wa Safavi.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Evliya Çelebi azaliwa", "2b6051ff"], "d": ["Evliya Çelebi, aliyekusanya safari zake za zaidi ya miaka hamsini katika Seyahatnâme ya juzuu kumi, aliacha panorama isiyo na kifani ya ulimwengu wa Ottoman wa karne ya 17.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Mkataba wa Nasuh Paşa", "bb69e388"], "d": ["Kwa mkataba uliomaliza vita vilivyoendelea tangu 1603, mafanikio ya 1590 yaliachwa na mpaka wa Amasya wa 1555 ulirudishwa; mizani ilirejeshwa kwenye mbele ya mashariki.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Msikiti wa Sultan Ahmed wafunguliwa", "e39dfd43"], "d": ["'Msikiti wa Bluu', kwa minara yake sita na vigae vya buluu vya İznik, ni külliye kubwa ya mwisho ya masultani ya enzi ya kawaida.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Mauaji ya Sultan İbrahim", "bc4eb452"], "d": ["Kwa sababu ya ubadhirifu na mgogoro wa utawala, muungano wa ocak na ulama ulimwondoa İbrahim kwenye kiti cha enzi; siku kumi baadaye alinyongwa kwa fatwa. IV. Mehmed mwenye umri wa miaka saba alipanda kiti cha enzi; madaraka yalipita kwa vitendo mikononi mwa valide mkuu Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Kifo cha Kâtib Çelebi", "e167e89d"], "d": ["Kwa bibliografia yake ya Keşfü'z-zunûn na jiografia yake ya Cihannümâ, ni jina la kilele katika historia ya elimu ya Ottoman; anajulikana kwa mtazamo wake wa upainia wa kutumia vyanzo vya Ulaya.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Tukio la Edirne — kuondolewa kwa II. Mustafa", "0291c1cd"], "d": ["Sultani kukaa Edirne na hasira dhidi ya ushawishi wa Feyzullah Efendi viligeuka kuwa uasi mkubwa wa jeshi na wafanyabiashara; şeyhülislâm alipigwa hadi kufa na umati, sultani aliondolewa kwenye kiti cha enzi na ikulu ikarudi Istanbul.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Balozi mkuu Paris: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["Ubalozi mkuu uliotumwa Ufaransa ulikuwa uchunguzi wa kwanza wa kimfumo wa kuichunguza Magharibi papo hapo; Sefâretnâme yake ilihamasisha upya wa Enzi ya Tulip.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Mashine ya kwanza ya uchapishaji ya Ottoman yaanzishwa", "4943f7e5"], "d": ["Ruhusa ya kuchapisha vitabu vya Kituruki ilitolewa; kazi ya kwanza, Vankulu Lügati, ilichapishwa mwaka 1729. Mashine ya uchapishaji ni urithi wa kudumu zaidi wa upya wa Enzi ya Tulip.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Kapitülasyon zafanywa za kudumu", "d044a79e"], "d": ["Marupurupu yaliyopewa Ufaransa yaliacha kuwa ya sultani peke yake na yakafungwa kwa mkataba wa kudumu; mfumo wa kapitülasyon, uliokuwa hauwezi kufutwa kwa upande mmoja, uliweza kukomeshwa tu huko Lausanne.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Mühendishâne-i Bahrî-i Hümâyun yaanzishwa", "9bf3f439"], "d": ["Shule ya uhandisi iliyoanzishwa kuwafunza maafisa wa kisasa wa majini baada ya maafa ya Çeşme ndiyo taasisi ya kwanza ya kudumu ya elimu ya kiufundi ya mtindo wa Magharibi; shule ya uhandisi ya nchi kavu ilifuata mwaka 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Ubalozi wa kwanza wa kudumu London", "6b5630eb"], "d": ["Kama sehemu ya mpango wa Nizâm-ı Cedîd, balozi za kudumu zilifunguliwa katika miji mikuu ya Ulaya; diplomasia ya Ottoman ilipita kwenye kanuni ya kuheshimiana.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Kifo cha Alemdar Mustafa Paşa", "4426534e"], "d": ["Katika uasi wa yeniçeri ulioanza usiku wa 15 Novemba 1808, sadrazam mwanamageuzi aliyezingirwa Bâbıâli, msaada aliotarajia ulipokosa kuja, siku iliyofuata aliwasha ghala la silaha na akafa pamoja na mamia ya washambuliaji; mpangilio wa Sened-i İttifak na jaribio la kwanza la mageuzi vilizikwa pamoja naye.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Gazeti rasmi la kwanza: Takvîm-i Vekāyi", "c637f623"], "d": ["Gazeti rasmi la dola lilianza kuchapishwa; ni mwanzo wa utamaduni wa kisasa wa maoni ya umma na matangazo rasmi.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Mkataba wa Biashara wa Balta Limanı", "e790b383"], "d": ["Uingereza ilipewa nafasi ya upendeleo zaidi hata katika biashara ya ndani, mfumo wa yed-i vahit (ukiritimba) uliondolewa; huku uzalishaji wa ndani ukibaki bila kinga, mkataba ukawa hati ya kufunguliwa kikamilifu kwa soko la Ottoman kwa biashara huria.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Mwisho wa Uemiri wa Lebanon — kuondolewa kwa III. Beşîr Şihâb", "f85ae454"], "d": ["Emir II (III.) Beşîr, aliyeshindwa kudhibiti mvutano wa Wakristo-Wadruze na mizani ya ndani ya eneo la Şûf, aliondolewa Januari 1842; mfumo wa uemiri wa mahali uliodumu tangu 1516 (kupitia Ma'noğulları kisha Şihâboğulları) ulimalizika na eneo likapita kwenye utawala wa moja kwa moja wa Ottoman, kisha mfumo wa kaymakamlık mbili.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: mfumo wa Mecidiye", "c77be809"], "d": ["Kwa mageuzi ya sarafu, sarafu zilizoharibika kwa kiwango zilikusanywa; mfumo thabiti wa metali mbili uliojengwa juu ya lira ya dhahabu (Mecidiye) ulianzishwa.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Mwisho wa utawala wa mahali wa familia ya Harfûş Ba'lebek", "8438f4ae"], "d": ["Ushawishi wa familia ya Harfûş, iliyotawala Ba'lebek kama nasaba ndogo ya mahali tangu 1521 (baada ya uasi wa Canbirdi Gazâlî), ulimalizika kwa mpangilio mpya wa kiutawala wa Bâbıâli; mji ukafanywa kitovu cha kawaida cha kaza kinachotegemea vilâyet ya Dameski.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Şirket-i Hayriyye yaanzishwa", "462830e7"], "d": ["Kampuni iliyoanzishwa kuendesha meli za mvuke kwenye Bosphorus huhesabiwa kuwa ushirika wa kwanza wa hisa wa Ottoman; vituo vya meli za mvuke viliweka alama yake kwenye maisha ya mji.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Mkataba wa kwanza wa deni la nje", "9017c579"], "d": ["Mkopo wa kwanza wa nje ulichukuliwa kutoka soko la London kwa ajili ya kufadhili Vita vya Crimea; hatua iliyofikiwa kwa mikopo 15 katika miaka 21 ilikuwa kusimamishwa kulipa kwa 1875 na Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Laini ya telegrafu Istanbul", "d320f39f"], "d": ["Laini ya kwanza ya telegrafu iliyoanzishwa kwa mahitaji ya Vita vya Crimea ilifunguliwa kwa matumizi; ndani ya miongo michache himaya ilipata mojawapo ya mitandao mipana zaidi ya telegrafu duniani.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Kanunnâme ya Ardhi", "6bae243a"], "d": ["Kanunnâme iliyoisasa sheria ya ardhi iliunganisha matumizi halisi ya ardhi ya mîrî na tapu; ni mojawapo ya hati za msingi za mfumo wa umiliki wa Mashariki ya Kati ya leo.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Masomo ya kwanza katika Dârülfünun", "08f74066"], "d": ["Dârülfünun, itakayotoa elimu ya kiwango cha chuo kikuu, ilianza kazi kwa mihadhara ya wazi kwa umma; taasisi iliyoendelea kwa vipindi vya kukatika ilifunguliwa kwa kudumu mwaka 1900 na ikawa kiini cha Chuo Kikuu cha Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Nizamnâme ya Vilâyet", "ad20853b"], "d": ["Badala ya mfumo wa eyalet, shirika la vilâyet la mfano wa Kifaransa lilianzishwa; kwa kuchukua mfano wa utekelezaji wa Midhat Paşa katika Vilâyet ya Danubi, lilienezwa nchi nzima.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Safari ya Abdülaziz Ulaya", "9ff0fa1e"], "d": ["Safari ya kwanza ya sultani wa Ottoman Ulaya kwa madhumuni ya amani; maonyesho ya Paris na ziara za London zilitumika kama dirisha la diplomasia na usasa.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Galatasaray Mekteb-i Sultânîsi yafunguliwa", "f9688524"], "d": ["Shule ya sekondari iliyotoa elimu kwa Kifaransa, kwa muundo wake wa wanafunzi usiozingatia dini wala taifa, ikawa ishara ya bora ya usawa katika elimu ya Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Kitabu cha kwanza cha Mecelle chaanza kutumika", "6475461c"], "d": ["Mecelle, iliyokusanya sheria ya Kiislamu ya madeni na mali kwa mbinu ya kisasa ya kutunga sheria, huhesabiwa kuwa kanuni ya kwanza ya sheria ya kiraia ya Kiislamu; kamati iliyoongozwa na Cevdet Paşa ilikamilisha vitabu 16 mwaka 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Kuondolewa kwa Abdülaziz", "eb7397ea"], "d": ["Wanasiasa wa kimeşrutiyet na uongozi wa kijeshi walimwondoa Abdülaziz kwa mapinduzi ya kimya; kifo chake cha kutiliwa shaka siku tano baadaye na matukio ya Çırağan yaliyofuata vilizaa mahesabu yaliyodumu miaka mingi.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Shambulio la Çırağan (tukio la Ali Suâvi)", "d2a9ac87"], "d": ["Mwandishi wa habari Ali Suâvi alishambulia Çırağan ili kumrudisha V. Murad kwenye kiti cha enzi; shambulio lilikandamizwa kwa umwagaji damu, na utawala wa Abdülhamid ulibana kwa kudumu mzunguko wa usalama.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Utawala wa Reji wanzishwa (ukiritimba wa tumbaku)", "bad9b030"], "d": ["Mapato ya tumbaku yalikabidhiwa kwa kampuni ya Reji yenye mtaji wa kigeni ndani ya Düyûn-ı Umûmiyye; migogoro ya 'magendo ya Reji' kati ya wakulima na walinzi wa Reji ilidumu miongo mingi. Makazi mengine yaliyopotea tarehe hiyo hiyo: Zeyla.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Ziara ya Kaiser II. Wilhelm Istanbul na Yerusalemu", "2988cd06"], "d": ["Ziara ya pili ya mfalme wa Ujerumani iliimarisha ukaribu wa Ottoman-Ujerumani; njia ya ruhusa ya reli ya Baghdad ilifunguka, na Dameski hotuba ya 'rafiki wa Waislamu milioni mia tatu' ilitolewa.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Reli ya Hijaz yafika Madina", "95009b9c"], "d": ["Laini ya kilomita 1464, iliyojengwa kwa michango ya Waislamu tu na uhandisi wa ndani, ilifika Madina; safari ya hija ilipungua kutoka wiki hadi siku. Ni kazi kubwa zaidi ya miundombinu ya enzi ya II. Abdülhamid.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Tukio la 31 Mart", "1d7c2bb2"], "d": ["Uasi mkubwa dhidi ya Meşrutiyet ulichukua Istanbul; Jeshi la Harakati lililokuja kutoka Selanik lilikandamiza uasi na II. Abdülhamid akaondolewa kwenye kiti cha enzi.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Kuzingirwa kwa Edirne kwaanza", "234d9b28"], "d": ["Ulinzi wa miezi mitano wa Şükrü Paşa ukawa hadithi ya upinzani katika maafa ya Balkani; mji ulianguka kwa njaa na ukarudishwa Julai 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Shambulio la Bâb-ı Âli", "b304d02d"], "d": ["Serikali iliyokuwa ikijiandaa kukabidhi Edirne iliangushwa kwa shambulio la silaha la Ittihad; Waziri wa Vita Nâzım Paşa aliuawa. Kipindi cha mamlaka kamili ya Ittihad ve Terakki kilianza.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Kukomeshwa kwa Mutasarrıflık ya Cebel-i Lübnan", "b5639051"], "d": ["Mfumo wa mutasarrıflık unaojitawala, uliotegemea Reglement Organique ya 1861 na itifaki ya kimataifa iliyofanywa upya mwaka 1864, ulifutwa kwa upande mmoja na Dola ya Ottoman wakati wa Vita vya I. vya Dunia; Wizara ya Mambo ya Ndani ilianza kuteua moja kwa moja mutasarrıf Waislamu katika eneo hilo. Hivyo kipindi cha uhuru wa ndani ambapo mutasarrıf wanane walihudumu kati ya 1861-1915 kilifungwa.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Kugawanywa kwa nchi kati ya şehzade", "82f26bfb"], "d": ["Baada ya kushindwa kwa Ankara, Süleyman Çelebi alivuka hadi Rumeli na akatangaza usultani huko Edirne; İsa Çelebi alishikilia Bursa, na Çelebi Mehmed eneo la Amasya-Tokat-Sivas. Katika ramani sehemu hizi tatu zinaonyeshwa kwa rangi tofauti.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Mkataba wa Gelibolu: pwani ya Bahari Nyeusi hadi Misivri iliachwa kwa Bizanti", "a4164eca"], "d": ["Emîr Süleyman, aliyetaka kujishikiza Rumeli baada ya kushindwa kwa Ankara, alitia saini mkataba na Mfalme wa Bizanti Manuel huko Gelibolu. Aliiachia Bizanti Kartal, Pendik na Gebze pamoja na visiwa vingine, Selânik na Thessaly huko Rumeli, na ukanda wa pwani ya Bahari Nyeusi hadi Misivri; kodi ambayo Bizanti ilikuwa ikilipa kwa Ottoman pia iliondolewa. Ahtapolu, İğneada na Rezve kwenye pwani ya Istranca hivyo zilibaki chini ya utawala wa Bizanti kwa miaka ishirini na mmoja; II. Murad alirudisha nyingi ya sehemu hizi kwa amani ya 1424.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Kifo cha Yıldırım Bayezid utumwani", "7e968d83"], "d": ["Sultani aliyekuwa mateka mikononi mwa Timur alifariki Akşehir; mwili wake ulirudishwa Bursa na kuzikwa. Kifo chake kilifanya mapambano ya kiti cha enzi kati ya şehzade yasiweze kurudishwa nyuma.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Mkataba wa Gelibolu — makubaliano kwa Bizanti", "dfacbd00"], "d": ["Süleyman Çelebi, aliyetaka kuhakikisha nafasi yake Rumeli, alirudisha Selanik, pwani za Marmara na baadhi ya visiwa kwa makubaliano na Bizanti na dola za Kilatini; hata alikubali kulipa kodi.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Mapigano ya Ulubat — kushindwa kwa İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, aliyeshikilia Bursa, alishindwa Ulubat mbele ya ndugu yake Mehmed; majaribio kadhaa ya kujikusanya upya pia hayakuzaa matunda.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Kutoweka kwa İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, aliyerudi Anatolia mara kadhaa kwa msaada wa Süleyman Çelebi, alitoweka baada ya kushindwa kwake kwa mwisho; sehemu yake ilipita kwa Çelebi Mehmed na katika ramani eneo la Mehmed lilipanuka kuelekea magharibi.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi avuka hadi Eflak", "8441267a"], "d": ["Çelebi Mehmed, aliyepoteza Bursa na Ankara mbele ya Süleyman Çelebi na kujiondoa Tokat-Amasya, alimhimiza ndugu yake Musa aende Rumeli. Musa, kwa kukubali mwaliko wa Voivode wa Eflak Mircea, alifika Eflak kwa njia ya bahari; kutoka hapa angeingia katika mapambano yatakayomwacha Süleyman kati ya pande mbili.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed arudisha Bursa na Ankara — sehemu ya Anatolia yatoka mikononi mwa Süleyman Çelebi", "bfb69f12"], "d": ["Kwa mafanikio ya Mûsâ Çelebi Rumeli (Yanbolu, 13 Februari 1410), Emîr Süleyman Çelebi, aliyekuwa Anatolia, alivuka hadi Rumeli. Baada ya Süleyman kuondoka Anatolia, Mehmed Çelebi alirudisha eneo la Bursa pamoja na Ankara na akatengeneza sarafu yenye tarehe 813 kama ishara ya kupanda kiti cha enzi. Katika ramani upande wa Anatolia wa Marmara hupita kutoka sehemu ya Emîr Süleyman hadi rangi ya Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Vita vya Kosmidion", "0efc2caa"], "d": ["Katika vita vilivyofanyika mbele ya kuta za Istanbul kwa msaada wa Bizanti, Süleyman Çelebi alimshinda ndugu yake Musa; hata hivyo msaada wake Rumeli ulikuwa umeanza kupungua haraka.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Kuzingirwa kwa Istanbul na Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, aliyetaka kuiadhibu Bizanti iliyomuunga mkono Süleyman, alizingira Istanbul; kuzingirwa huku kuliisukuma Bizanti kwenye muungano na Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Kifo cha Emîr Süleyman — Musa atawala Rumeli", "325c1549"], "d": ["Süleyman Çelebi, aliyekamatwa akikimbia kutoka Edirne, aliuawa; Rumeli yote ilipita mikononi mwa Musa Çelebi. Katika ramani Rumeli hubadilika kutoka rangi ya buluu hadi zambarau.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Vita vya Çamurlu — kuanzishwa upya kwa umoja", "0b23173e"], "d": ["Çelebi Mehmed, aliyepata msaada wa Bizanti, ufalme wa kidespoti wa Kiserbia na beyi wa Rumeli, alimshinda kabisa ndugu yake Musa huko Çamurlu; Musa aliuawa akikimbia. Rumeli iliyokuwa mikononi mwa Musa ilipita kwa Mehmed pamoja na Edirne, na Mehmed Çelebi alijitangaza huko Edirne mtawala pekee wa Dola ya Ottoman. Enzi ya Fetret ya miaka kumi na moja iliisha, na sehemu za şehzade katika ramani ziliunganishwa katika mwili mmoja.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Uamuzi wa msafara wa Vienna — amani ya Vasvár haikufanywa upya, lengo lilibadilishwa kutoka Yanıkkale hadi Vienna", "1bf278f2"], "d": ["Mfalme I. Leopold alitaka Mkataba wa Vasvár, ambao muda wake ulikuwa haujaisha, ufanywe upya, na IV. Mehmed pia alionekana kupendelea amani. Sadrazam Merzifonlu Kara Mustafa Paşa, hata hivyo, kwa kutaja malalamiko ya İmre Tököli aliyemtangaza mfalme wa Hungaria ya Kati, hakuruhusu amani kufanywa upya; akiwahamasisha wahubiri, wakiongozwa na Vânî Mehmed Efendi, alimshawishi sultani aende vitani. Katika mashauriano yaliyofanyika iliamuliwa sultani abaki Belgrade na serdâr-ı ekrem asonge kuiteka Yanıkkale; lakini katika mashauriano ya Istolni Belgrade, licha ya pingamizi la khan wa Crimea Murad Giray na gavana wa Budin Uzun İbrâhim Paşa, lengo lilibadilishwa kuwa kuzingira Vienna.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Kuzingirwa kwa II. Vienna kwaanza — jeshi mbele ya Vienna", "bb542e49"], "d": ["Jeshi la Ottoman chini ya amri ya Vezîriâzam Kara Mustafa Paşa lilifika mbele ya Vienna tarehe 14 Julai 1683. Mfalme I. Leopold alirudi ndani ya Austria akimwachia Starhemberg ulinzi wa mji. Kuzingirwa huku kwa pili, kulikoandaliwa kwa kulenga Vienna moja kwa moja tofauti na kwa kwanza, kungedumu hadi 12 Septemba.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Kushindwa kwa Parkan na kupotea kwa Estergon", "a7366740"], "d": ["Jeshi lililojiondoa Vienna lilishindwa kwa mara ya pili huko Parkan; kisha Estergon, mojawapo ya ngome muhimu za Hungaria, ilianguka. Kurudi nyuma kulianza kugeuka kuwa kuporomoka.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Kunyongwa kwa Merzifonlu Kara Mustafa Paşa", "ce8b10ac"], "d": ["Sadrazam aliyehesabiwa kuwajibika kwa kushindwa kwa Vienna alinyongwa Belgrade; hata hivyo kunyongwa kwake hakukurekebisha mbele wala hakukurudisha heshima iliyotikiswa ya dola.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Muungano Mtakatifu wanzishwa", "060280d0"], "d": ["Chini ya uongozi wa upapa, Muungano Mtakatifu (Mukaddes İttifak) dhidi ya Ottoman ulianzishwa kati ya Austria, Poland na Venice; mwaka 1686 Urusi nayo ilijiunga. Hivyo himaya iliingia katika vita vya mbele nyingi vilivyodumu miaka kumi na sita.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Ulinzi wa kwanza wa Budin", "ccc43630"], "d": ["Kuzingirwa kwa kwanza kwa Budin na jeshi la Muungano Mtakatifu kulirudishwa nyuma kwa ulinzi wa ukaidi wa ngome uliodumu miezi minne; hata hivyo ngome za Hungaria ziliendelea kuanguka moja baada ya nyingine.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Kupotea kwa Uyvar", "689ab78c"], "d": ["Ngome ya Uyvar, iliyokaa mikononi mwa Ottoman kwa miaka ishirini na miwili na iliyokuwa methali Ulaya, ilianguka; uwepo wa Ottoman katika Hungaria ya Juu ulivunjika.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Kukamatwa kwa Tököli Varad — Ufalme wa Hungaria ya Kati wavunjika, ngome za Hungaria ya Juu zajisalimisha", "1741aaaf"], "d": ["Baada ya kushindwa kwa Vienna, Waottoman walianza kumhesabu Tököli pia miongoni mwa waliosababisha vita na kushindwa. Tarehe 15 Oktoba 1685, kwa amri ya Serdar Melek İbrâhim Paşa, beylerbeyi wa Varad Ahmed Paşa alimkamata Tököli aliyekuja kusaidia; kwa kumkabidhi kwa Habsburg ilitarajiwa kupata masharti bora ya amani. Habari za kukamatwa zilipoenea, ngome na miji yote ya Ufalme wa Hungaria ya Kati, isipokuwa Munkács iliyolindwa na mkewe Ilona Zrínyi, ilijisalimisha kwa Habsburg; wengi wa askari wa Kuruz walipita kwenye jeshi la Habsburg. Tököli alipoachiliwa Belgrade tarehe 2 Januari 1686, ufalme ulikuwa umeshatoweka.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Kupotea kwa Budin — mji mkuu wa Hungaria wa miaka 145", "70800e2b"], "d": ["Budin ilianguka mwishoni mwa kuzingirwa kwa siku sabini na nane; beylerbeyi wa mwisho Abdurrahman Abdi Paşa alikufa shahidi ukutani. Kupotea kwa mji uliokuwa chini ya utawala wa Ottoman tangu 1541 huhesabiwa kuwa ishara ya kupotea kwa Hungaria. Makazi mengine yaliyopotea tarehe hiyo hiyo: Peşte.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Kushindwa kwa II. Mohaç (Harşan) — kupotea kwa Erdel na Mohaç", "a7922681"], "d": ["Katika uwanda ambapo ushindi mkubwa ulipatikana mwaka 1526, safari hii kushindwa vibaya kulipatikana; jeshi lilitawanyika, askari waliasi na kumfanya sadrazam aondolewe. Kushindwa kulisababisha pia kupotea kwa Erdel.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Kupotea kwa Atina na mlipuko wa Parthenon", "b6691730"], "d": ["Bomu lililorushwa na wapiga mizinga wa Venice lililipua Parthenon, iliyotumiwa na Waottoman kama ghala la silaha; hekalu la miaka elfu mbili likawa magofu. Mji ulipita mikononi mwa Venice (utarudishwa mwaka 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Kuondolewa kwa IV. Mehmed na kupanda kwa II. Süleyman", "9f53037c"], "d": ["Kufuatia maafa mbele na uasi wa jeshi, IV. Mehmed aliondolewa baada ya utawala wake wa miaka 39; badala yake ndugu yake II. Süleyman, aliyewekwa kwenye kafes kwa miaka arobaini, alisimikwa.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Kupotea kwa Belgrade kwa mara ya kwanza — kuzingirwa kwa Muungano Mtakatifu", "c6b9b19a"], "d": ["Belgrade, iliyokuwa mikononi mwa Ottoman tangu 1521, ilijisalimisha kwa jeshi la Muungano Mtakatifu; milango ya Serbia ilifunguliwa kwa adui na hatari ilifika mstari wa Niş-Sofya. Makazi mengine yaliyopita kutoka Ottoman hadi Habsburg tarehe hiyo hiyo katika atlasi: Hisarcık (Grocka) — hufuata mnyororo wa abi-merkez wa Belgrade (TDV belgrad; makadirio yaliyotangazwa).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden avuka Morava mbele ya Pasarofça — Pasarofça yaanguka kwa Austria", "bcf3fc59"], "d": ["Margrave Ludwig von Baden alivuka Morava huko Pasarofça mnamo Agosti 1689 na akasonga kuelekea Niş; mji ulibaki mikononi mwa Austria hadi kiangazi cha 1690 (TDV suleyman-ii inasema Pasarofça ilirudishwa mwaka 1690). Siku na usomaji wa Röder havikuthibitishwa tena katika kikao hiki.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Kupotea kwa Niş — kusonga mbele kwa Habsburg (taji ya Ufalme wa Hungaria), mwaka muhimu zaidi", "c5e27b3f"], "d": ["Kusonga mbele kwa Habsburg (taji ya Ufalme wa Hungaria) kulichukua Niş pia kutoka utawala wa Ottoman; mashambulizi yalifika hadi Üsküp na Priştine. Vidin ilianguka baadaye, Oktoba 1689 (kipengee tofauti). Katika mwaka mweusi zaidi wa vita dola ilihisi mji mkuu wake pia uko chini ya tishio.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova na Fethülislâm zachukuliwa na kikosi cha Austria", "ee8dd875"], "d": ["Baada ya kutekwa kwa Vidin bila vita (Oktoba 1689, TDV vidin), Baden alikarabati Orsova na Fethülislâm tarehe 25 Oktoba 1689 na kuweka kikosi; Orsova ilibaki Austria hadi vuli ya 1690. Siku hutegemea Bánlaky/Röder, haikuthibitishwa tena katika kikao hiki.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niş yarudi Ottoman", "0c4f44eb"], "d": ["Fâzıl Mustafa Paşa alianza msafara Julai 1690; baada ya Şehirköy, Pasarofça na Güvercinlik kutekwa, Niş iliyozingirwa ilikuwa mikononi mwa Waottoman tarehe 27 Septemba 1690 (TDV semendire). Wakati huo huo Vidin nayo ilikuwa imerudishwa. Makazi mengine yaliyorudi kutoka Habsburg hadi Ottoman tarehe hiyo hiyo katika atlasi: Yagodina (Jagodina) na Ürküp (Prokuplje) — kwa kuwa siku ya kiwango cha mahali haikupatikana, siku ya Niş ilichukuliwa (TDV semendire; makadirio yaliyotangazwa; Röder 1842 anaandika kwamba vezir alipita Yagodina tarehe 8-24 Septemba, mgongano haukutatuliwa).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Wanajeshi wa Austria wajisalimisha Semendire", "90da20c4"], "d": ["Baada ya kutekwa kwa Niş tarehe 27 Septemba 1690, kwa kuzingirwa kwa siku nne wanajeshi wa Austria huko Semendire walijisalimisha (TDV semendire). Bánlaky/Röder wanasema 24 Septemba; vyanzo vinapingana, TDV ilichukuliwa kuwa msingi.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrade yarudishwa", "ab435838"], "d": ["Sadrazam Köprülüzâde Fâzıl Mustafa Paşa alirudisha Belgrade kutoka Austria tarehe 8 Oktoba 1690; mji uliopotezwa mwaka 1688 hivyo ulirudi Ottoman (TDV suleyman-ii). Makazi mengine yaliyorudi kutoka Habsburg hadi Ottoman tarehe hiyo hiyo katika atlasi: Hisarcık (Grocka) — hufuata mnyororo wa abi-merkez wa Belgrade (TDV suleyman-ii; makadirio yaliyotangazwa).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Kushindwa kwa Salankamen — Fâzıl Mustafa Paşa afa shahidi", "10d626f1"], "d": ["Katika mojawapo ya vita vya uwanjani vya umwagaji damu zaidi vya karne, sadrazam alipigwa paji la uso na akafa shahidi; jeshi lilitawanyika. Matumaini ya kujikusanya upya yalizimika kwa vita hivi.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Kupotea kwa kisiwa cha Sakız", "07c084f8"], "d": ["Jeshi la majini la Venice lilivamia Sakız; utawala wa Ottoman katika Aegean ulikuwa chini ya tishio. Kisiwa kitarudishwa mwaka unaofuata.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Uamuzi wa II. Mustafa wa kwenda vitani binafsi", "61c3ba9c"], "d": ["Sultani mpya alitangaza kwamba, akifuata njia ya mababu zake, ataenda vitani akiongoza jeshi; uamuzi huu ulileta ari jeshini na ulianzisha kipindi cha misafara ya binafsi kilichodumu miaka miwili.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Kurudishwa kwa Sakız", "6b496fca"], "d": ["Mezomorto Hüseyin Paşa, aliyelishinda jeshi la majini la Venice katika vita vya majini vya Visiwa vya Koyun, alirudisha Sakız; ilikuwa ishara ya kufufuka kwa muda mfupi kwa uwezo wa majini wa Ottoman.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Ushindi wa Lugoş — msafara wa kwanza wa II. Mustafa dhidi ya Austria", "d5ee9b34"], "d": ["Katika msafara wa kwanza ambao sultani alishiriki binafsi, Lipova ilirudishwa na majeshi ya Austria yakashindwa Lugoş; mpasuko wa kwanza ulitokea katika mnyororo wa kushindwa uliodumu miaka mingi. Atlasi inahesabu pia Karánşebeş (Caransebeş) kuwa ilirudi kutoka Habsburg hadi Ottoman katika msafara huu; chanzo kinataja Septemba 1695 tu (TDV mustafa-ii), siku ya atlasi ilichukuliwa kutoka kwenye kipengee cha Lugoş (makadirio yaliyotangazwa).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Kupotea kwa Ngome ya Azak", "2b78b5cd"], "d": ["I. Petro, aliyelenga kufikia Bahari Nyeusi, alichukua Azak katika kuzingirwa kwake kwa pili; Urusi kwa mara ya kwanza ilikaa kwa kudumu katika ngome ya Ottoman na ikapiga hatua ya kwanza kuelekea kuwa nguvu ya majini.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Ushindi wa Ulaş (Olaşin)", "02ac9ca8"], "d": ["Ushindi uliopatikana kando ya Danubi katika msafara wa pili wa sultani ulivuruga mpango wa Austria wa kuchukua Temeşvar; hata hivyo haukubadilisha mizani ya jumla ya vita.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Kushindwa kwa Zenta — hatima ya vita yaamuliwa", "475c4a7b"], "d": ["Jeshi lilishambuliwa ghafla na Prince Eugen lilipokuwa likivuka mto Tisa; vikosi vilivyogawanyika pande mbili za mto viliangamizwa ndani ya masaa machache, maelfu ya askari na wanaserikali, wakiwemo sadrazam Elmas Mehmed Paşa, walikufa. Zenta, mojawapo ya kushindwa vibaya zaidi katika historia ya Ottoman, ilifanya meza ya amani kuwa ya lazima.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Mazungumzo ya amani ya Karlofça yalianza", "1f395cf3"], "d": ["Katika mazungumzo yaliyoanza kwa usuluhishi wa Uingereza na Uholanzi, ujumbe wa Ottoman ulilazimika kwa mara ya kwanza kukubali kanuni ya 'uti possidetis' (kila upande ubaki na ulichonacho); mashauriano yaliyodumu vikao sabini na viwili yanahesabiwa kuwa kuzaliwa kwa diplomasia ya kisasa ya Ottoman.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali wa Kavala alitua Misri", "514c943f"], "d": ["Ndani ya jeshi la Ottoman lililotumwa kurudisha Misri iliyokuwa chini ya uvamizi wa Wafaransa kulikuwa na kikosi cha kujitolea kilichokusanywa kutoka Kavala. Mehmed Ali, aliyekuwa katika miaka yake ya thelathini, alikuwa kamanda wa pili wa kikosi hiki; aliweka mguu Misri si kama gavana, bali kama afisa wa kikosi.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Askari wa Kialbania walimpindua gavana wa Misri", "c76a0ec2"], "d": ["Vikosi vya Kialbania ambavyo mishahara yao haikulipwa viliasi na kumlazimisha gavana Hüsrev Paşa kukimbia ngome. Katika pengo lililotokea Wafaransa walipoondoka, mabeyi wa Kimamluki, ocak ya Kialbania na magavana walioteuliwa na Bâbıâli waliingia katika mapambano ya pembe tatu; Mehmed Ali alijitokeza kwa kuweka usawa katika pembetatu hii. Makazi mengine yaliyopotea tarehe hiyo hiyo: Tâif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Maulamaa wa Kahire walimtangaza Mehmed Ali gavana", "a16752f2"], "d": ["Wafanyabiashara na maulamaa wa Kahire, waliochoshwa na shinikizo la kodi, chini ya uongozi wa nakîbüleşraf Ömer Mekrem, waliasi na kutangaza kwamba hawamtambui gavana Hurşid Paşa, wakamweka Mehmed Ali kwenye wadhifa wa ugavana. Gavana kuchaguliwa na wananchi ni tukio adimu katika historia ya Ottoman.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Bâbıâli ilikubali jambo lililokwisha fanyika: amri ya ugavana wa Misri", "b86736a3"], "d": ["Bâbıâli, isiyokuwa na nguvu ya kumweka mgombea wake Misri, ilimtumia Mehmed Ali amri ya ugavana wa Misri pamoja na cheo cha vezir. Kwenye ramani, kuanzia tarehe hii Misri inahamia kwenye tabaka la kibaraka (rangi nyepesi): kisheria ni ardhi ya Ottoman, kwa vitendo ni nchi ya nasaba ya Kavalalı. Makazi mengine yaliyohamia tabaka la kibaraka tarehe hiyo hiyo: Kahire, İskenderiye, Dimyat, Asyut, Asvan, İbrim, Süveyş, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Kampeni ya Fraser ya Uingereza ilitua İskenderiye", "4d6c31be"], "d": ["Kwa kujibu Ottoman kukaribia Ufaransa, Uingereza ilituma kikosi cha kutua Misri. Wakati huo Mehmed Ali alikuwa Misri ya Juu akishughulika na Wamamluki; alirudi kwa haraka na kuandaa ulinzi.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Kushindwa kwa Reşid (Rosetta) — Waingereza walirudishwa nyuma", "3636004c"], "d": ["Safu ya Waingereza iliyoingia mji wa Reşid ilipata hasara kubwa katika mapigano ya barabarani; mwezi Septemba vikosi viliondoka Misri kabisa. Ushindi huu uliimarisha heshima ya Mehmed Ali Misri na İstanbul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Tukio la Kal'a: kuondolewa kwa mabeyi wa Kimamluki", "84030b97"], "d": ["Mabeyi wa Kimamluki waliokaribishwa kwenye msafara wa sherehe ulioandaliwa kwa ajili ya kampeni ya Hicaz walinaswa kwenye njia nyembamba ya Ngome ya Kahire na kuangamizwa. Ushawishi wa Wamamluki wa karne tano hivyo ulimalizika na Mehmed Ali hakuwa na mpinzani Misri.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Kampeni ya Hicaz ilianza — jeshi lilielekea Yenbu kwa bahari kutoka Süveyş na kwa nchi kavu kupitia njia ya hajj", "1c05c159"], "d": ["Kurudisha Haremeyn, iliyokuwa chini ya utawala wa Suûdî-Vehhâbî tangu 1803, ilikuwa suala kubwa zaidi la uhalali kwa II. Mahmud; Bâbıâli iliposhindwa, jukumu lilipewa gavana wa Misri. Mehmed Ali alimtuma mwanawe Tosun, mwenye umri wa miaka kumi na sita, kuongoza jeshi.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yenbu ilichukuliwa — kituo cha kwanza cha pwani cha kampeni ya Hicaz", "179bc78d"], "d": ["Askari wa miguu wa Kialbania wapatao elfu mbili, waliosafiri kwa meli mpya kutoka Süveyş, walitua karibu na Yenbu Oktoba 1811; mji ulisalimu amri baada ya upinzani dhaifu wa siku mbili. Wapanda farasi chini ya amri ya Tosun, waliofuata njia ya hajj kwa nchi kavu kupitia Akabe na Vech, walifika Yenbu wiki mbili baadaye tu. Yenbu ikawa kituo cha kwanza cha jeshi la Misri huko Hicaz, lililokuwa likielekea Medine na Mekke.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Kushindwa kwa kwanza kwenye njia ya Safra-Cedîde", "99ef804d"], "d": ["Kikosi cha mbele cha Misri kilichonaswa kwenye njia nyembamba za milimani kilitawanyika. Kushindwa huku kukawa funzo la kimbinu la kampeni: ikaeleweka kwamba haiwezekani kusonga Hicaz bila msaada wa makabila ya Kibedui.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Medine ilirudishwa", "6f6a5d55"], "d": ["Baada ya mzingiro mrefu Medine ilisalimu amri. Kurudishwa kwa mji wa Mtume kulisherehekewa İstanbul kwa sherehe za mizinga; Mehmed Ali alipewa pia ugavana wa Cidde kama zawadi.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Mekke ilirudishwa — njia ya hajj ilifunguka", "3d6d66a0"], "d": ["Vikosi vya Misri vilivyoingia Mekke vilisomesha tena khutba kwa jina la sultani wa Ottoman kwenye Kaaba. Misafara ya hajj iliyokatizwa kwa miaka kumi iliweza kuanza safari tena. Kwenye ramani Hicaz inarudi chini ya utawala wa Ottoman, lakini kwa kuwa inatawaliwa kutoka Kahire inaonyeshwa kwa rangi ya kibaraka. Mahali pengine palipopita chini ya utawala wa kibaraka tarehe hiyo hiyo: Cidde.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Kurudishwa kwa Tâif — kukamilika kwa kampeni ya Hicaz", "6315fb31"], "d": ["Baada ya Medine (Desemba 1812) na Mekke (Januari 1813), jeshi la Misri chini ya amri ya Tosun Paşa hatimaye lilirudisha Tâif kutoka kwa Wavehhâbî. Utawala wa Suûd wa miaka kumi ulimalizika, na vituo vitatu vitakatifu vya Hicaz vyote viliingia tena chini ya udhibiti wa Ottoman-Misri.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali mwenyewe alivuka kwenda Hicaz", "fda0ea2d"], "d": ["Gavana, akiona kampeni inaendelea polepole, alichukua utawala moja kwa moja mikononi mwake; kwa kujadiliana na wakuu wa makabila alijaribu kuuvunja mstari wa Suûdî kutoka ndani. Sehemu ya Misri katika biashara ya Bahari Nyekundu nayo ilikua kwa kampeni hii.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Vita vya Bisel: vikosi vya Suûdî vilishindwa", "9c9ab91f"], "d": ["Wasuûdî, waliopata kushindwa vibaya katika vita vya wazi, walirudi maeneo ya ndani. Mapatano yaliyofanywa hayakudumu; miaka miwili baadaye operesheni ingehamishiwa moyoni mwa Necid. Atlasi, kufuatia ushindi huu, inahesabu Türabe na Hurma mashariki ya Tâif kuwa yametoka mikononi mwa Wasuûdî (chanzo cha tukio ni Lorimer, Gazetteer; ushuhuda wa makazi mahususi haupo na siku ya 13 Januari ni makadirio yaliyotangazwa).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["İbrâhim Paşa alielekea kampeni ya Necid", "d5ed80d1"], "d": ["İbrâhim Paşa, aliyechukua uongozi baada ya kifo cha kaka yake Tosun, alianza safari ngumu ya jangwani iliyodumu miaka miwili. Jeshi lililosonga kisima kwa kisima, likiziondoa makabila moja moja, lilifika mji mkuu wa Suûdî.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Dir'iye ilianguka — Dola ya Kwanza ya Suûdî ilimalizika", "aa96206d"], "d": ["Baada ya mzingiro wa miezi sita Dir'iye ilisalimu amri na kuharibiwa. Emîr Abdullah b. Suûd alipelekwa İstanbul na kuuawa. Bendera ya Ottoman ilifika kwa mara ya kwanza kwa kina kama hicho ndani ya Uarabuni; kikosi cha Necid kilibaki hadi 1824. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Dir'iye (Necid).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Kampeni ya Sudan ilianza", "b1fc6905"], "d": ["Lengo la Mehmed Ali lilikuwa mara tatu: kukusanya askari kwa jeshi lake, kufikia dhahabu ya Sennâr, na kuangamiza masalio ya Wamamluki waliokimbia. Kikosi chini ya amri ya mwanawe İsmâil Paşa kilishuka kusini kikifuata Nile.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola ilichukuliwa — masalio ya Wamamluki yalitawanywa", "ba6bc24b"], "d": ["Jeshi lililoingia Dongola kwenye kona kuu ya Nile liliondoa kundi la mwisho la Wamamluki lililokuwa limekimbilia huko. Kwenye ramani Sudan inaonekana kwenye tabaka la kibaraka kuanzia tarehe hii: aliyeiteka ni Kahire, na atakayeitawala pia ni Kahire.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Usultani wa Sennâr (Fûnc) ulisalimu amri", "3cac7dd2"], "d": ["Nasaba ya Fûnc ya karne tatu ilisalimu amri bila mapigano. Mwaka huo huo kambi iliyoanzishwa mahali ambapo matawi mawili ya Nile yanakutana iligeuka upesi kuwa Hartum, kitovu cha utawala cha Sudan. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan ilitekwa", "06440602"], "d": ["Tawi la pili lililotumwa magharibi liliwashinda wanajeshi wa Dârfûr huko Bâre (Bâra) na kuchukua Kordofan pamoja na eneo la Nühûd. Utawala wa Misri juu ya Sudan hivyo ulienea kutoka bonde la Nile hadi nyika za magharibi.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Vikosi vya Misri vilitua Krete", "835aee90"], "d": ["Uasi wa Warumi ulipoenea hadi Krete, Bâbıâli iliomba kikosi cha Misri kitumwe kisiwani. Ushawishi wa Mehmed Ali kisiwani ulianza kwa uingiliaji huu na, miaka minane baadaye, ulizaa matunda kwa kupewa ugavana wa Krete.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Kuuawa kwa İsmâil Paşa huko Şendî", "223860c9"], "d": ["Emîr wa eneo hilo Nemir, aliyekasirishwa na madai ya kodi nzito na askari, alichoma nyumba aliyokuwa amefikia na kumteketeza İsmâil Paşa na msafara wake. Kampeni ya kulipiza kisasi iligeuza eneo kuwa bahari ya damu; utawala wa Sudan tangu hapo ulijengwa juu ya ukali.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["II. Mahmud aliomba msaada wa Mehmed Ali kwa Mora", "03594a42"], "d": ["Kwa uasi wa Mora uliokuwa umeshindwa kukandamizwa kwa miaka mitatu na jeshi la Yeniçeri, sultani aliligeukia jeshi la Misri lililofunzwa kwa mtindo wa Ulaya. Kwa kubadilishana aliahidiwa ugavana wa Mora na Krete. Ombi hili lilikuwa kukiri kwa mara ya kwanza kwa wazi kwamba dola imehitaji msaada kwa mkoa wake yenyewe.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["İbrâhim Paşa alitua Modon", "9c993dba"], "d": ["Kikosi cha kutua kilicholindwa na jeshi la majini la Misri kiliweka mguu kwenye ncha ya kusini-magharibi ya Mora. Jeshi hili, lililokuwa na askari wa miguu wa nizamî na mizinga ya uwanjani, lilipata ubora haraka dhidi ya magenge ya waasi.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripoliçe ilirudishwa — kitovu cha Mora kilianguka", "8a478c11"], "d": ["Kwa kuanguka kwa Tripoliçe, kitovu cha utawala cha uasi, sehemu kubwa ya Mora iliingia tena chini ya udhibiti. Kwenye ramani peninsula inaonekana kwa rangi ya kibaraka kwa kuwa iko mikononi mwa vikosi vya Misri.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonghi (Mesolongi) ilianguka", "07257f87"], "d": ["Baada ya mzingiro wa mwaka mmoja mji ulichukuliwa. Hata hivyo mwangwi wa ulinzi huo kwenye vyombo vya habari vya Ulaya ulifikisha kilele huruma kwa madai ya Wagiriki na kuandaa msingi wa uingiliaji wa madola makubwa.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Acropolis ya Athens ilichukuliwa", "3b19f946"], "d": ["Kwa kuanguka kwa Acropolis, uasi wa Wagiriki ulikuwa karibu kumalizika kijeshi. Hasa katika hatua hii suala lilitoka kuwa uasi wa ndani na kuwa mada ya diplomasia ya Ulaya.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Mkataba wa London: madola matatu yalilazimisha uhuru wa ndani wa Wagiriki", "7ce46fd8"], "d": ["Uingereza, Ufaransa na Urusi ziliamua kuchukua hatua ya pamoja ili kulazimisha Ottoman na Wagiriki kukubali kusitisha mapigano na sharti la uhuru wa ndani; zilitangaza kwamba meli zao zingeingilia kati ikiwa pendekezo lingekataliwa. Bâbıâli ilikataa pendekezo.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Makubaliano ya İskenderiye: uamuzi wa Misri kuondoka Mora", "cc978f37"], "d": ["Mehmed Ali, aliyepoteza jeshi lake la majini Navarin, alikubaliana moja kwa moja na admirali wa Uingereza bila kushauriana na İstanbul na kukubali kuondoa vikosi vyake Mora. Gavana kufanya mkataba wa pekee na madola makubwa ilikuwa ishara ya awali ya mgogoro ujao.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Vikosi vya Misri viliiacha Mora", "8fb742dd"], "d": ["Vikosi vya mwisho vilipandishwa kwenye meli; peninsula ilipotea kwa vitendo na kwa Itifaki ya London ya 1830 ikawa kiini cha Ugiriki huru. Mehmed Ali hakupata ugavana wa Mora aliyeahidiwa, na kwa malipo alipoteza jeshi kubwa la majini na jeshi la nchi kavu. Makazi mengine yaliyopotea tarehe hiyo hiyo: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Utawala wa Krete uliachiwa Mehmed Ali", "7f76396d"], "d": ["Ugavana wa Krete ulipewa Mehmed Ali kama fidia ya kupotea kwa Mora. Kisiwa kilitawaliwa kutoka Kahire kwa miaka kumi; kwenye ramani kinaonekana kwa rangi ya kibaraka kwa kipindi hicho. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Kandiye (Krete).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["İbrâhim Paşa aliingia Syria — mgogoro wa kwanza ulianza", "1a5cc386"], "d": ["Kisingizio kilikuwa gavana wa Akkâ aliyekataa kurudisha wakulima waliokimbia Misri; sababu halisi ilikuwa hitaji la Mehmed Ali la mbao, bandari na rasilimali watu za Syria. Jeshi lilivuka Sînâ na kuchukua haraka pwani ya Palestina.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Mzingiro wa Akkâ ulianza", "b211d96d"], "d": ["Ngome iliyomzuia Napoleon mwaka 1799 ilipinga kwa miezi sita. Mzingiro ulikuwa mtihani mkubwa wa kwanza wa mizinga ya kisasa ya jeshi la Misri.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Akkâ ilianguka", "0f47917b"], "d": ["Mizinga iliyopiga kuta ilipofungua pengo, ngome ilichukuliwa. Mlango wa Syria ulikuwa umefunguka; katika siku hizo hizo Bâbıâli ilimtangaza Mehmed Ali kuwa muasi na kuondoa ugavana wake.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Şam ilisalimu amri", "48da3b62"], "d": ["Mji ulisalimu amri bila mapigano. İbrâhim Paşa alijaribu kupata uungwaji mkono wa wenyeji kwa kutangaza mfumo wa kodi na usawa kwa wasio Waislamu; sera hizo hizo zingekuwa pia sababu ya uasi dhidi yake miaka michache baadaye. Maeneo mengine yaliyounganishwa katika siku hizo hizo: Beyrut, Trablusşam, Sayda.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Vita vya Humus", "867810ee"], "d": ["Jeshi la Ottoman lililotumwa kuokoa Syria lilishindwa kwenye ardhi wazi. Ilionekana kwamba jeshi jipya lililoundwa miaka sita baada ya kukomeshwa kwa Yeniçeri bado halikuwa tayari.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Halep ilichukuliwa", "9c0ead76"], "d": ["Kitovu cha biashara na utawala cha Syria Kaskazini nacho kilianguka. Hivyo jeshi la Misri lilifika miteremko ya Toroslar na likaelekea kwenye njia zilizo mlangoni mwa Anatolia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Kushindwa kwenye Njia ya Belen (Beylan) — Çukurova ilifunguka", "4bae872b"], "d": ["Mstari wa ulinzi ulivunjwa kwenye njia nyembamba ya milima ya Amanos. Antakya, Adana na Tarsus zilipita kwa vikosi vya Misri (kuvamiwa kwa Maraş, kwa mujibu wa TDV, ni 1833, kipengee tofauti); kwenye ramani Çukurova inarudi kwenye rangi ya kibaraka. Njia ya kuelekea ndani ya Anatolia sasa ilikuwa bila ulinzi.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Njia ya Gülek ilianguka — pwani ya İçil (Mersin, Silifke) iliingia chini ya udhibiti wa Misri", "d9049b5b"], "d": ["Njia ya Gülek, mlango wa Çukurova wa Toroslar, ilipita mikononi mwa jeshi la Misri. İbrâhim Paşa alimteua mütesellim wake mwenyewe kwenye Sancak ya İçil na bandari zote za pwani ziliingia chini ya udhibiti wa Misri. Kwenye ramani Mersin na Silifke zinaonyeshwa kuwa tegemezi kwa Misri kuanzia siku hii (kikomo cha chini; siku ya uteuzi haipo kwenye chanzo); kwa kuwa katika uamuzi wa Kütahya ni muhassıllık ya Adana pekee iliyopita, udhibiti huu unamalizika kwa kuondoka Anatolia.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğlisi chini ya uvamizi wa Misri — mdomo wa Toros wa njia ya Konya–Adana", "fb908900"], "d": ["Ereğli, iliyo njiani kuelekea Konya ya jeshi la Misri lililovuka Njia ya Gülek, iliingia chini ya uvamizi wa İbrâhim Paşa mwaka 1832 na, ilipoachwa kwa mpangilio wa Kütahya wa 1833, iliunganishwa tena na vilâyet ya Karaman. Kwenye ramani ni kituo cha kati chenye chanzo cha mstari wa uvamizi kati ya Adana na Konya; kwa Ulukışla na Karapınar ushuhuda wa ngazi ya mji haukupatikana.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Jeshi la Misri liliingia Konya", "13952a2d"], "d": ["Jeshi lililovuka Toroslar lilifika Anatolia ya Kati. Kwa mara ya kwanza vikosi vya gavana wa Ottoman vilikuwa vikisonga ndani ya ardhi kiini ya dola. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Vita vya Uwanjani vya Konya: sadrazam alitekwa", "ec82cc9a"], "d": ["Jeshi la Ottoman, lililotawanyika katika hali ya ukungu, lilishindwa vibaya na sadrazam Reşid Mehmed Paşa alitekwa. Jeshi kuu la dola halikuwepo tena; hakukuwa na nguvu ya kusimama kati ya İstanbul na vikosi vya Misri.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş ilivamiwa na Misri", "f558e383"], "d": ["Kwa mujibu wa TDV, Maraş ilivamiwa na Kavalalı İbrâhim Paşa mwaka 1833 na ilibaki chini ya utawala wake karibu miezi kumi na tisa. Kwa kuwa Maraş ilibaki nje ya mipaka ya majimbo katika mpangilio wa Kütahya, utawala huu si wa kisheria bali wa kivitendo.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) ilivamiwa na Misri — njia ya Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, iliyo njiani mwa jeshi la Misri lililosonga kuelekea Kütahya baada ya Vita vya Uwanjani vya Konya, ilibaki kwa muda mikononi mwa İbrâhim Paşa mwaka 1833. Kwenye ramani ni kituo cha kati chenye chanzo cha mstari wa uvamizi kati ya Konya na Kütahya; kwa Akşehir, Ilgın na İshaklı ushuhuda wa ngazi ya mji haukupatikana, zina rangi ya Ottoman.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Jeshi la Misri lilifika Kütahya", "214f8df6"], "d": ["İbrâhim Paşa alisimama Kütahya, umbali wa vituo vitatu kutoka İstanbul. Kutosonga mbele kwake hakukuwa kwa kijeshi bali kwa kisiasa: uingiliaji wa Urusi na mwitikio wa Ulaya vilihesabiwa.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Meli za Urusi mbele ya Büyükdere", "6f836d61"], "d": ["II. Mahmud, asiyepata msaada kutoka Uingereza na Ufaransa, aligeukia Urusi, adui wa jana. Uamuzi huu, unaokumbukwa kwa usemi wa sultani 'anayeanguka baharini hushika nyoka', ulileta askari wa Urusi kwenye mlangobahari na kulia kengele za tahadhari Ulaya.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Makubaliano ya Kütahya (ya mdomo) — Syria na Adana kwa Kavalalı", "25fe9985"], "d": ["Bâbıâli iliachia Mehmed Ali, kando na Misri, Krete na Hicaz, ugavana wa Şam, Halep, Trablusşam na Sayda; muhassıllık ya Adana ilipewa İbrâhim Paşa. Kwa malipo jeshi lilirudi kusini mwa Toroslar. Haya hayakuwa mkataba, bali amri za sultani kwa gavana — suala halikutatuliwa, liliahirishwa.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Kuondoka kwa jeshi la Misri Anatolia kulikamilika kupitia Gülek", "a53ac2a3"], "d": ["Baada ya mpangilio wa Kütahya, vikosi vya Misri viliiacha Anatolia; kuelekea katikati ya Juni jeshi lote lilivuka Njia ya Gülek hadi Çukurova. Pwani ya İçil (Mersin, Silifke) inarudi tena chini ya utawala wa Ottoman; muhassıllık ya Adana na Syria zinabaki kwa Misri.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Mkataba wa Hünkâr İskelesi", "da741d5c"], "d": ["Muungano wa ulinzi wa pande mbili wa miaka minane ulitiwa saini na Urusi. Kwa kifungu cha siri, Ottoman ingefunga mlangobahari kwa meli za kivita Urusi ikishambuliwa. Huu ukawa mojawapo ya maamuzi yenye utata zaidi ya diplomasia ya Ottoman na ukaifanya Uingereza ishiriki kikamilifu katika suala la Misri.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Uasi wa Palestina-Nablus dhidi ya utawala wa Misri", "4fe43e27"], "d": ["Uandikishaji wa lazima, ukusanyaji wa silaha na kodi mpya vilisababisha uasi mpana Palestina. Uasi ulikandamizwa kwa ukali; uungwaji mkono wa utawala wa Misri kwa wenyeji ulipungua haraka.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Mwisho wa utawala wa Misri Maraş (takriban)", "bb46ca42"], "d": ["Sentensi ya TDV ya 'karibu miezi kumi na tisa' ikihesabiwa tangu uvamizi wa 1833, utawala wa Misri unaisha karibu majira ya joto ya 1834. Kushindwa kwa Mustafa Bey wa Küçükalioğulları kuupinga jeshi la Misri mwaka 1834 na kurudi upande wa Maraş pia kunaonyesha kwamba Maraş wakati huo ilikuwa kimbilio nje ya udhibiti wa Misri.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Uasi wa Cebel-i Dürûz", "12e74626"], "d": ["Upinzani uliozuka katika eneo la Wadruzi ulidumu miaka miwili. Kutoridhika kulikorundikana Syria kungeacha nyuma ya jeshi la Misri wazi, meli za washirika zilipotua pwani mwaka 1840.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali alitangaza nia ya uhuru", "48633bbd"], "d": ["Gavana aliwaeleza makonsuli wa madola makubwa kwamba anafikiria kutangaza uhuru wa Misri na Syria. Uingereza ilipinga hili kwa uthabiti: kuzaliwa kwa dola yenye nguvu iliyo karibu na Ufaransa katika Mediterania kungetishia njia ya India.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Jeshi la Ottoman lilivuka Furat", "9af1ea69"], "d": ["II. Mahmud alipeleka jeshi lake kwenye mpaka wa Syria ili kurudisha alichopoteza Kütahya. Afisa wa Prussia Moltke, aliyekuwa jeshini kama mshauri, alipinga uchaguzi wa nafasi na mashambulizi ya mapema; pingamizi zake hazikusikilizwa.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Vita vya Nizip — jeshi la Ottoman lilitawanywa", "156b3cdf"], "d": ["Jeshi la Ottoman lililowekwa vibaya lilishindwa ndani ya saa chache. Sultani alikufa kabla habari za kushindwa hazijafika İstanbul; dola ingepoteza jeshi lake, mtawala wake na kisha meli zake ndani ya siku chache.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Kifo cha II. Mahmud", "07eccfff"], "d": ["Sultani, aliyekomesha Yeniçeri na kuanzisha upya utawala wa kati katika utawala wake wa miaka thelathini na moja, alifariki bila kumshinda adui yake mkuu. Ugonjwa wake haukuwa umetambuliwa kwa usahihi. Kifo chake kilifichwa hadi tarehe 30 Juni, hadi hatua za kijeshi zilipochukuliwa mjini kwa hofu kwamba mawazo ya Yeniçeri yangeamka.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Kutawazwa kwa Abdülmecid na mazishi ya II. Mahmud", "d0f3d2cc"], "d": ["Kwa kifo cha baba yake, Abdülmecid mwenye umri wa miaka kumi na sita alipanda kiti cha enzi. Siku hiyo hiyo jeneza la II. Mahmud lililetwa Ikulu ya Topkapı; machafuko yaliyohofiwa hayakutokea, na umati mpana wa Waislamu na wasio Waislamu ulishiriki katika msafara wa mazishi.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Kukabidhiwa kwa meli za jeshi la majini İskenderiye", "a53e6103"], "d": ["Kaptan-ı derya Ahmed Fevzi Paşa, kwa shaka kwamba sadrazam Koca Hüsrev Paşa angetoa meli kwa Urusi, alipeleka kundi la meli İskenderiye na kumkabidhi Mehmed Ali. Dola ya Ottoman ilibaki ndani ya mwezi huo huo bila jeshi, bila sultani na bila meli.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Waraka wa pamoja wa madola makubwa", "2a3b8316"], "d": ["Madola matano yalitoa waraka kwa Bâbıâli yakitaka isifanye makubaliano peke yake katika suala la Misri. Suala la ndani hivyo rasmi likawa 'suala la Ulaya'; dola ya Ottoman ilipoteza kwa vitendo mamlaka ya kuamua kuhusu mkoa wake yenyewe.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Mkataba wa London: madola manne upande wa Ottoman", "a517f775"], "d": ["Mkataba uliotiwa saini kwa kuiacha nje Ufaransa ulimpa Mehmed Ali uamuzi wa mwisho: akikubali ndani ya siku kumi, ugavana wa kurithi wa Misri na Akkâ kwa sharti la maisha; akikubali ndani ya siku ishirini, Misri pekee; akikataa, hakuna chochote. Gavana alikataa.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Mashambulizi ya mizinga Beyrut na kutua kwa washirika", "0905ce92"], "d": ["Meli za Uingereza na Austria zilipiga Beyrut kwa mizinga; silaha ziligawiwa kwa wananchi walioasi dhidi ya utawala wa Misri katika milima ya Lebanon. Udhibiti wa İbrâhim Paşa Syria ulianguka kati ya uasi wa ndani na uingiliaji wa nje.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beyrut na miji ya pwani ilipotea", "09bdaf23"], "d": ["Baada ya mapigano upande wa Ba'lebek, vikosi vya Misri viliondoka pwani. Kwenye ramani pwani ya Lebanon inatoka kwenye rangi ya kibaraka na kurudi chini ya utawala wa moja kwa moja wa Ottoman.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akkâ ilianguka ndani ya saa mbili", "5aec21f0"], "d": ["Katika mashambulizi ya mizinga ya meli za washirika, ghala la risasi la ngome lililipuka na Akkâ ilisalimu amri ndani ya saa chache. Ngome ambayo İbrâhim Paşa aliweza kuichukua kwa miezi sita miaka minane iliyopita ilionyesha ubora wa mizinga ya majini.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Mkataba wa İskenderiye", "85cb47b0"], "d": ["Mehmed Ali alikubali kuachana na Syria, Adana, Krete na Hicaz, kurudisha meli za Ottoman na kutambua mamlaka ya sultani; kwa malipo ugavana wa kurithi wa Misri ulihakikishwa.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Jeshi la Misri liliiacha Syria na Çukurova", "719a28dc"], "d": ["Uvamizi wa miaka tisa ulimalizika; jeshi la İbrâhim Paşa lilirudi Misri kupitia Sînâ. Kwenye ramani ukanda mpana unaoenea kutoka Halep hadi Gazze, kutoka Adana hadi Krete, unapita tena chini ya utawala wa moja kwa moja wa Ottoman. Makazi mengine yaliyopotea tarehe hiyo hiyo: Urfa, Maraş, Tarsus, Antakya, Kandiye (Krete), Hama, Şam, Kudüs, Yafa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Amri: ugavana wa Misri uliachiwa familia ya Kavalalı kwa kurithi", "87b89ff8"], "d": ["Amri ya sultani ilitambua ugavana kupita ndani ya nasaba kutoka baba hadi mwana; kwa malipo idadi ya jeshi ilishushwa hadi elfu kumi na nane, kodi ilifungwa na İstanbul, na mamlaka ya kutengeneza sarafu na kufanya mikataba yaliondolewa. Misri ilibaki mkoa, lakini sasa ilikuwa nchi ya nasaba tofauti. Utawala wa Hicaz na Haremeyn ulirudi kwa Bâbıâli. Makazi mengine yaliyorudi kutoka tabaka la kibaraka hadi tabaka la moja kwa moja tarehe hiyo hiyo: Mekke, Medine, Cidde, Yenbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Mkataba wa London wa Mlangobahari", "0e95a1ea"], "d": ["Mkataba uliochukua nafasi ya Hünkâr İskelesi ulihukumu kwamba wakati wa amani mlangobahari ufungwe kwa meli zote za kivita. Upendeleo ambao Urusi iliupata peke yake hivyo uligeuka kuwa dhamana ya pamoja ya Ulaya; suala la mlangobahari lilipata hadhi ya kimataifa.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrâhim Paşa kwa vitendo alikuwa gavana wa Misri", "9e14f5d9"], "d": ["Mwanawe İbrâhim Paşa aliwekwa kwenye ugavana mahali pa Mehmed Ali aliyezeeka na kupoteza uwezo wa akili. Hata hivyo miezi michache baadaye, Novemba 1848, alikufa kabla ya baba yake.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Kifo cha Kavalalı Mehmed Ali Paşa", "871310e0"], "d": ["Gavana, aliyezaliwa Kavala, aliyeanzisha nasaba Misri na kuileta dola kwenye ukingo wa shimo mara mbili, alikufa akiwa na umri wa miaka themanini. Nasaba aliyoianzisha ilitawala Misri hadi 1953; dola nayo, ikiona imeweza kuziba jeraha alilolifungua kwa uingiliaji wa Ulaya, iliendelea kwenye njia ya Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman b. Kutalmış ashindwa na kufa Aynüseylem; Antakya yatoka kwa Waseljuki wa Anatolia", "0412dfa1"], "d": ["Süleyman b. Kutalmış, aliyeichukua Antakya kutoka Bizanti mwaka 1084, alikufa katika vita vya Aynüseylem alivyopigana na mtawala wa Waseljuki wa Syria Tutuş; mji ulipita chini ya udhibiti wa Sultani Mkuu wa Seljuk Melikşah na Yağısıyan akateuliwa gavana.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Melikşah afa; Antakya pamoja na Yağısıyan yategemea Tutuş wa Seljuk ya Syria", "c61da1b4"], "d": ["Kufuatia kifo cha Sultani Mkuu wa Seljuk Melikşah, dola iligawanyika kati ya warithi; gavana wa Antakya Yağısıyan alitegemea Tutuş, mtawala wa Syria.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["İznik yajisalimisha kwa Wanamsalaba; kitovu cha Seljuk chajiondoa Konya, Bizanti yaanza kurudisha Anatolia ya magharibi", "8a4e90fa"], "d": ["Baada ya Wanamsalaba kuizingira İznik, mji ulijisalimisha kwa Bizanti tarehe 19 Juni 1097; sultani wa Seljuk I. Kılıcarslan alihamisha kitovu chake ndani ya nchi, hadi Konya, na Bizanti ikarudisha maeneo kama Efeso kwenye pwani za Anatolia ya magharibi.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["II. Kılıcarslan achukua Dorylaion (Eskişehir) na Kütahya kutoka Bizanti", "3ddee6c2"], "d": ["Baada ya Miryokefalon (1176), ngome za Dorylaion na Kütahya za Bizanti ndani ya Anatolia zilipita mikononi mwa II. Kılıcarslan mnamo 576/1180, katika miaka ya mwisho ya Manuel/baada ya kifo chake.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoğlu Mehmed Bey ateuliwa subaşı wa Ermenek, achukua utawala wa İç İl", "6d62be11"], "d": ["Karamanoğlu Mehmed Bey aliteuliwa subaşı wa Ermenek mwaka 675 (1276) na akaichukua İç İl chini ya utawala wake; Ermenek ikawa kitovu cha kwanza cha Karamanoğulları, ambao mwaka uliofuata wangeandamana kuelekea Konya.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Kifo cha Ertuğrul Gazi na Osman Bey kupokea beylik — urithi wa Söğüt na Domaniç", "395fb9fa"], "d": ["Kwa mujibu wa TDV, Ertuğrul Gazi alikufa mwaka 680 (1281-82); makala inabainisha kwamba tarehe za 1288 na 1289 pia hutolewa. Osman Bey hakurithi kutoka kwa baba yake mji uliotekwa, bali mgao miwili ambao sultani wa Waseljuk alimpa Ertuğrul aliyemweka kwenye mstari wa mbele kabisa wa eneo la mpakani: yurtluk (makazi ya majira ya baridi) Söğüt na yaylak (malisho ya majira ya joto) Domaniç. Yaani beylik ilianza si kwa urithi wa ushindi, bali kwa mgao wa malisho mawili; kwenye ramani sehemu hizi mbili zinaonyeshwa kama 'urithi' si 'ushindi'.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Jioni ya Sicilia — nasaba ya Anjou ipoteza kisiwa cha Sicilia", "547db635"], "d": ["Uasi uliolipuka Palermo wakati wa sala ya jioni ya Jumatatu ya Pasaka dhidi ya utawala wa Charles I wa Anjou ulikitenga kisiwa cha Sicilia na nasaba ya Anjou. Ufalme wa Sicilia uligawanyika mara mbili: kisiwa kilielekea Aragon, na nasaba ya Anjou ikajishikiza katika ufalme wa bara wenye kitovu Napoli. Mali za nje za nasaba kwenye Adriatic na Mediterania pia zilibaki zimeunganishwa na ufalme huu: Korfu waliyoishikilia tangu 1267 na Draç waliyoishikilia tangu miaka ya 1270 ziliendelea kama sehemu ya Ufalme wa Napoli; ngome za Avlonya, Kanina na Hımara kwenye pwani ya Albania pia zilibaki katika ufalme wenye kitovu Napoli (kamanda wa Avlonya John of Taxis alipinga dhidi ya Wabizanti katika mwaka mzima wa 1282; Draç, Avlonya na Kanina zinaelekea zilipita kwa Bizanti mwanzoni mwa 1285). Malta, hata hivyo, ilipita mikononi mwa Waaragon mwaka 1284 tu.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Uvamizi wa Kulacahisar — operesheni ya kwanza ya kijeshi ya Osman Bey", "79b00b14"], "d": ["Makala ya TDV ya Osman I: 'Aliiteka nyara na kuiteketeza kwa moto ngome ndogo ya Kulaca karibu na İnegöl (684/1285).' Hii ni hatua ya kwanza ya kijeshi ya Osman Bey inayoweza kupewa tarehe katika vyanzo. Hakuna makazi ya kudumu yaliyochukuliwa; ngome iliporwa na kuchomwa, kwa hiyo ni uvamizi wa kawaida wa mpakani zaidi kuliko ushindi. Inahesabiwa kuwa mahali pa kuanzia shughuli za kijeshi za beylik.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Kutekwa kwa Karacahisar — ongezeko la kwanza la mji na utawala juu ya Eskişehir", "178ae619"], "d": ["Makala ya TDV ya Osman I: Osman Bey mwaka 687 (1288) 'aliiteka Karacahisar na kuwa mmiliki wa Eskişehir'. Huu ni ongezeko la kwanza halisi la mji la beylik, na kwa mujibu wa riwaya, kwa mafanikio haya Osman Bey alipanda kuwa sancak beyi wa mpakani; inasimuliwa kwamba khutba ya kwanza ya Ijumaa kwa jina lake ilisomwa Karacahisar na kadhi wa kwanza aliteuliwa huko. Makala ya TDV ya Eskişehir inabainisha kuwa mapokeo ya Ottoman hutoa tarehe 1291, lakini usahihi wake una shaka.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Kuanguka kwa Akkâ kwa Mamluki — kufutwa kwa Wanamsalaba kwenye pwani ya Syria: Sayda na Beirut", "3ca7a464"], "d": ["Akkâ, iliyokuwa kwa muda mrefu kitovu cha Ufalme wa Wanamsalaba wa Yerusalemu, ilitekwa na Sultani wa Mamluki el-Melikü'l-Eşref Halîl, na utawala wa Wanamsalaba huko Palestina ulimalizika. Mashujaa wa Templier waliojiondoa Akkâ walikimbilia Sayda; jeshi la Mamluki lilipokaribia, waliiacha ngome ya baharini na kukimbilia Kupro, na mji ukapita kwa Mamluki majira hayo hayo ya kiangazi. Beirut, iliyokuwa mikononi mwa Wanamsalaba tangu 1197, nayo ilichukuliwa mwaka 1291 na gavana wa Dameski Sencer eş-Şücâî. Hivyo uwepo wa Wanamsalaba wa karne mbili ulifutwa kwenye pwani ya Syria-Palestina.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Kutekwa kwa Bilecik na Yarhisar kwa shambulio la usiku", "f461b0af"], "d": ["Makala ya TDV ya Bilecik: 'Ingawa tekfur wa Bilecik na tekfur wengine wa eneo hilo waliandaa shambulio la kumuua Osman Gazi, kwa kupata habari ya njama hiyo vikosi vya Ottoman vilizichukua Yarhisar na Bilecik kwa shambulio la ghafla (1299).' Ngome mbili zilichukuliwa katika operesheni moja, katika shambulio hilo hilo la usiku. Tarehe hii ni mwamba wa mabadiliko unaokubaliwa kuwa mwaka wa kuanzishwa kwa Dola ya Ottoman. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Vita vya Koyunhisar (Bapheus) — ushindi mkubwa wa kwanza dhidi ya jeshi la Bizanti", "584a9512"], "d": ["Makala ya TDV ya Osman I: Osman Bey alipigana na jeshi la Bizanti Bapheus (Koyunhisar) tarehe 27 Julai 1302 na kulishinda. Ushindi huu ni mwamba wa mabadiliko uliomtoa Osman Bey kuwa bey wa mpakani wa kikanda na kumpandisha hadi hadhi ya mwanzilishi wa nasaba. Baada ya vita tambarare ya Bursa iliingia chini ya udhibiti wa Ottoman na kizuizi cha İznik kilianza.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Ushindi wa Dimbos na kisha kuchukuliwa kwa Kite na Ulubat", "e168ab64"], "d": ["Makala ya TDV ya Osman I: mwaka 702 (1303) muungano ulioundwa na matekfur wa Bursa, Kestel, Kite na Adranos ulishindwa kwenye Njia ya Dimbos; adui alirudishwa nyuma kwa mapigano hadi kwenye njia nyembamba, na tekfur wa Kestel alikufa uwanjani. Mara baada ya ushindi ngome za Kite na Ulubat zilichukuliwa, uhusiano wa nchi kavu wa Bursa ulikatwa na kizuizi chake kikabanwa. Orhan kijana naye alishiriki katika vita hivi.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Kampeni ya Sakarya: kuchukuliwa kwa Leblebicihisar, Lefke, Mekece na Geyve", "a51ba4d3"], "d": ["Makala ya TDV ya Osman I inatoa mfuatano wa kampeni ya Sakarya ya 704 (1304): 'Alipofika Leblebüci Hisarı tekfur alitii... Alifika Lefke... Alifika Mekece... Alikwenda Geyve na kuchukua ngome aliyoikuta tupu.' Lefke ni mlango wa bonde la Sakarya unaofunguka kwa Bilecik. Kampeni hii moja, kwa kuweka mnyororo wa ngome unaoenea kando ya bonde chini ya udhibiti wa Ottoman, ilifunga ubavu wa mashariki wa bonde la İznik.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Sakız yapita chini ya udhibiti wa familia ya Zaccaria ya Genoa", "9eebe4de"], "d": ["Mbele ya tishio la Aydınoğulları, mfalme wa Bizanti aliomba msaada kutoka kwa Benedetto Zaccaria wa Genoa; kisiwa kilipita chini ya udhibiti wake (utegemezi wa jina wa Bizanti). Utawala wa Zaccaria ulidumu hadi 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Sisam yaingia katika umiliki wa Wagenoa (Zaccaria) wa Sakız", "0e6f51e3"], "d": ["Familia ya Zaccaria ya Genoa, iliyochukua udhibiti wa Sakız, iliongeza pia Sisam, iliyokuwa karibu tupu, katika umiliki wake (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Kutekwa kwa ngome za Njia ya Geyve: Karaçepüş, Karatigin na Absu", "76907c78"], "d": ["Makala ya TDV ya Orhan: katika kampeni ya Sakarya ya 705 (1305) Orhan 'aliteka ngome za Karaçepüş (Katoikia), Karatigin mbele ya İznik, Absu (Hypsu: kwenye Njia ya Geyve)'. Ngome hizi tatu, kwa kufunga njia kati ya bonde la Sakarya na bonde la İznik, zilikata kabisa msaada wa nchi kavu wa İznik. Gazi Abdurrahman aliwekwa Karaçepüş na Absu zilizo kwenye njia ya Geyve; mji sasa ungeweza kuangushwa kwa njaa tu.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Kampeni ya Adranos (Orhaneli) — kampeni ya mwisho ya Osman Bey", "4811546c"], "d": ["Makala ya TDV ya Orhan inaandika kampeni ya Ngome ya Adranos ya vuli ya 1323 kuwa kampeni ya mwisho ya Osman Bey. Tekfur wa Adranos alikuwa mwanachama wa muungano wa matekfur ulioundwa miaka ishirini iliyopita Dimbos dhidi ya Waottoman; kampeni hii ilimaanisha kufunga akaunti hiyo. Siku halisi ya kutekwa kwa ngome haijulikani; operesheni iliendelezwa na Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Kifo cha Osman Gazi na Orhan Bey kuchukua beylik", "021487cd"], "d": ["Osman Gazi, aliyeipa beylik jina lake, alifariki mwaka 724 (1324), kama ushahidi wa wakfu wa Asporça Hatun na Mekece unavyoonyesha. Mwanawe Orhan, aliyekuwa mkuu wa jeshi katika misafara tangu 1305, alikaa kwenye uongozi wa beylik baada ya kifo cha baba yake bila mapigano yoyote ya kiti cha enzi. Kupita kwa bendera kwa kizazi cha waanzilishi bila mtikisiko kunaonyesha kwamba nasaba ilipita mtihani wake mkubwa wa kwanza kwa utulivu katika njia kutoka beylik ya mpakani hadi dola.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Sakız yachukuliwa kutoka Zaccaria na kuunganishwa na Bizanti", "f6741b26"], "d": ["Mfalme III. Andronikos alimwondoa Zaccaria kisiwani na akaunganisha kisiwa na Bizanti chini ya ugavana wa III. Benedetto. Kisiwa kitavamiwa mwaka 1346 na Simone Vignosi wa Genoa.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Sisam yarudi kutoka Zaccaria hadi Bizanti (mnyororo wa Sakız)", "08034974"], "d": ["Kwa kuanguka kwa ubwana wa Zaccaria (kuunganishwa kwa Sakız na Bizanti mwaka 1329), umiliki wa Genoa Sisam pia ulimalizika.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Vita vya Pelekanon (Maltepe) na kuchukuliwa kwa Kocaeli yote", "389e7bd4"], "d": ["Makala ya TDV ya Orhan: siku ya kwanza ya vita Orhan Gazi alituma kikosi cha watu mia tatu kulivuta jeshi la Bizanti kwake; siku ya pili vita vilikua vikosi chini ya Pazarlu vilipoteremka kwenye tambarare, na maliki alipojeruhiwa kwa mshale hofu ilitokea katika jeshi la Bizanti. Matokeo ni ya uhakika: 'Orhan alichukua Kocaeli yote; baada ya ushindi Wana-İznik hawakuwa na matumaini yoyote.' Miji ya pwani kutoka Hereke hadi Üsküdar iliingia chini ya utawala wa Ottoman, Gebze ikafanywa kitovu cha eneo. Hili lilikuwa jeshi la mwisho la maliki wa Bizanti lililokuja kuokoa İstanbul.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Kuanzishwa kwa madrasa ya kwanza ya Ottoman huko İznik", "c85fb625"], "d": ["Orhan Bey, mara baada ya kuteka İznik, alimteua Çandarlı Kara Halil kuwa kadhi hapa, akabadilisha basilika kuwa msikiti na akajenga imaret na madrasa karibu nayo, akianza ujenzi wa mji. Kulingana na makala ya TDV kuhusu Dâvûd-i Kayserî, ujenzi wa madrasa ulikamilika mwaka 1336 na Orhan Gazi alimleta Dâvûd-i Kayserî kuwa müderris kwa akçe 30 kwa siku. Madrasa hii ni hatua ya kwanza ya kitaasisi ya maisha ya elimu ya Ottoman; beylik ilikuwa imeongeza utamaduni wa elimu pamoja na nguvu ya ushindi. Kubadilika kwa mji mkuu wa Bizanti uliotekwa kwa ushindi kuwa kituo cha elimu cha Kiislamu kulikuwa ishara ya kwanza dhahiri ya madai ya Ottoman ya kuwa dola thabiti.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Kufungwa kwa Bizanti kwenye kodi — mzingiro wa İzmit na mkataba", "0c1ec8d3"], "d": ["Makala ya TDV ya Orhan: Orhan alizingira İzmit majira ya joto ya 733 (1333) kwa jeshi kubwa na manati, na maliki alikubali mkataba. Kwa malipo ya kuacha mzingiro, Bizanti ilikubali kumlipa Orhan hyperper 12.000 za dhahabu kila mwaka; 'hivyo machoni mwa emîr wa Ottoman Bizanti ilikuwa imeshuka hadi hali ya nchi inayolipa kodi'. Kwa malipo Orhan angekuwa rafiki wa maliki na asingeshambulia miji iliyo tegemezi kwa Bizanti. Beylik ya mpakani kuiweka Roma ya Mashariki kwenye kodi ilikuwa tangazo la jinsi mizani ya nguvu ilivyogeuka.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Semadirek yapita kutoka Wavenice hadi familia ya Gattilusio ya Genoa", "c499ed5f"], "d": ["Familia ya Gattilusio ya Genoa iliwaondoa kisiwani Wavenice walioshikilia kisiwa tangu 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Kuunganishwa kwa Beylik ya Karesi: Balıkesir, Bergama, Biga, Edremit na Erdek", "c7cb0511"], "d": ["Makala ya TDV ya Orhan (İnalcık) inaweka kuunganishwa kwa tarehe 735 (1334-35): kwa kifo cha Demirhan Bey, mazi wa Karesi na Hacı İlbey walimwalika Dursun Bey kwenye kiti cha enzi na kuomba msaada wa Orhan. Orhan kwanza alielekea Balıkesir; Dursun Bey, aliyekwenda kwenye mazungumzo ya amani, alipokufa kwa mshale uliopigwa kutoka ngome ya Bergama, beylik iliunganishwa kabisa na ardhi ya Ottoman. Katika operesheni hiyo hiyo Kirmasti na Mihaliç zilitii, Gölyazı ilichukuliwa na Ulubat, iliyokuwa imeachwa hapo awali kwa aman, ilichukuliwa kwa uhakika. Orhan alimteua Süleyman Paşa kwenye sancak ya Karesi na kufanya Biga kuwa kitovu cha mpakani — hivyo kada ya majini ya kuvuka kwenda Rumeli ilipatikana. Kumbuka: makala ya TDV ya Karesioğulları inatoa tarehe 746 (1345) kwa tukio hilo hilo; ensaiklopidia inajipinga yenyewe. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Sisam yaingia katika umiliki wa Maona ya Sakız", "01628b2f"], "d": ["Kwa Simone Vignosi wa Genoa kuchukua Sakız na utawala kuachiwa kampuni ya Maona, Sisam pia iliingia katika umiliki wa Wagenoa wa Sakız (Maona) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Kapitülasyon ya kwanza ya Orhan Gazi na Wagenoa", "e64cb196"], "d": ["Orhan Gazi, aliyekubaliana na Wagenoa wakati wa vita vya Venice-Genoa, baada ya vita vya Mlango-bahari vya Februari 1352 alituma wapiga mishale 1000 kulinda Pera na akatoa dhahabu 60.000 kwa ajili ya kusafirisha askari; kwa malipo yake aliwapa Wagenoa kapitülasyon ya kwanza. Maandishi kamili ya mkataba hayajaifikia siku zetu. Hii ni makubaliano rasmi ya kwanza ya Ottoman na nguvu ya baharini ya Ulaya na ingefanywa upya miaka thelathini na tano baadaye mwaka 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Kutekwa kwa Gelibolu — kichwa cha daraja cha kudumu Rumeli", "ba51a160"], "d": ["Waottoman walichukua Gelibolu mwaka 1354, ambayo mazingira yake walikuwa wakiyajua kama washirika wa Kantakuzenos kati ya 1349-1352; tetemeko kubwa la ardhi lililoanguka kuta za mji lilikuwa limetoa fursa. Kichwa cha daraja chembamba cha Çimpe hivyo kiligeuka kuwa kituo halisi upande wa Rumeli wa Mlango-bahari, na mlango wa Trakya ulifunguliwa kabisa. Gelibolu ingepotea mwaka 1366 kwa msafara wa Wanamsalaba wa Savoy, lakini kwa ushindi wa pili mwaka 1376 ingeingia kwa uhakika chini ya utawala wa Ottoman. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Kifo cha Süleyman Paşa, mshindi wa Rumeli", "2dc98228"], "d": ["Süleyman Paşa, mwana mkubwa wa Orhan Bey na mbunifu wa ushindi wa Rumeli, alikufa kwa kuanguka kutoka farasini wakati wa uwindaji katika vuli ya 1357, tarehe inayokubalika zaidi kati ya zile zinazotolewa na vyanzo kama 758 (1357), 759 na 760 (1359). Kifo cha şehzade, aliyeanzisha uwepo wa kudumu wa Ottoman Rumeli kwa vivuko vyake vya kati ya 1352-1354, kiliacha nafasi ya urithi kwa ndugu yake Murad. Kaburi la Süleyman Paşa lililozikwa Bolayır lilibaki kuwa mnara wa kale zaidi wa nasaba ya Ottoman Ulaya.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Sheria ya Pençik — kuwekwa kwa msingi wa Jeshi la Yeniçeri", "e5877c2d"], "d": ["Baada ya ushindi wa Rumeli, kwa ushauri wa Karamanlı Kara Rüstem kutoka kwa ulama, mfumo wa pençik ulianza kutumika, ukitaka moja ya tano ya mateka wa vita au thamani yake kwa pesa kutengwa kwa dola. Kwa waliochaguliwa kati ya mateka hawa kulelewa kwa familia za Kituruki na kuandikishwa jeshini, kiini cha nguvu ya kudumu ya askari wa miguu iliyotegemea sultani moja kwa moja — Jeshi la Yeniçeri — kiliundwa. Kubadilika kwa beylik ya mpakani iliyotegemea wapanda farasi wa makabila kuwa dola yenye jeshi kuu kulianza kwa mpangilio huu.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Kushuka hadi Trakya ya Magharibi: ushindi wa Gümülcine", "9ef69221"], "d": ["Baada ya kutekwa kwa Edirne, vikosi vya mpakani vilivyoelekea magharibi mwa Meriç, chini ya amri ya Gazi Evrenos Bey, viliteka Gümülcine, kitovu cha Trakya ya Magharibi. Mji ukawa kambi ya mbele ambayo kutoka hapo Evrenos Bey angepeleka mashambulizi yake Makedonia. Hivyo sehemu ya Trakya iliyofika pwani ya Aegean iliingia chini ya udhibiti wa Ottoman na njia ya Selanik ikafunguka.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna yapita kwa Utawala wa Kifalme wa Dobruca na kuwa mji mkuu", "2bfe73f9"], "d": ["Wakati wa kuvunjika kwa Ufalme wa Kibulgaria, Varna kwenye pwani ya Bahari Nyeusi ilijiunga na Utawala wa Kifalme wa Dobruca ulioanzishwa na Dobrotiç na ikafanywa mji mkuu wa dola hii ndogo.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Magharibi mwa Filibe: kujiunga kwa Tatarpazarcığı na İhtiman", "1664d0e1"], "d": ["Baada ya kutekwa kwa Filibe mwaka 1372, Tatarpazarcığı kwenye ncha ya juu ya bonde la Meriç na İhtiman iliyoshikilia njia ya kuelekea Sofya ziliunganishwa na utawala wa Ottoman. Mstari huu, uliokuwa mikononi mwa beyi wa mahali waliokuwa tegemezi baada ya Vita vya Çirmen, ulipitishwa kwenye utawala wa moja kwa moja na njia ya Filibe-Sofya ikafanywa isiyokatika. Kusonga huku ni maandalizi ya njia inayoelekea ushindi wa Sofya miaka kumi na miwili baadaye.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Uasi wa Savcı Bey — uasi wa pamoja wa şehzade na mrithi wa Bizanti", "75198c33"], "d": ["Savcı Bey, mwana wa I. Murad, na Andronikos Palaiologos, mwana wa Mfalme wa Bizanti V. Ioannes, waliasi dhidi ya baba zao kwa wakati mmoja Bursa na Istanbul mwanzoni mwa Mei 1373. Muungano huu uliounganisha warithi wa nasaba mbili ulikandamizwa haraka; Savcı Bey alikamatwa, akatobolewa macho kwa chuma na akauawa. Tarehe 787 (1385) inayotolewa na masimulizi ya Ottoman kwa uasi ni ya makosa; tukio linaangukia mara baada ya miaka ambayo Bizanti iliingia katika utegemezi wa Ottoman na linaonyesha jinsi ikulu hizi mbili zilivyoingiliana.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Mabonde ya Struma na Mesta: kujiunga kwa Köstendil, Petriç, Nevrokop na Drama", "8c0980c4"], "d": ["Mabonde ya Struma na Mesta, yaliyokuwa mikononi mwa beyi wa mahali wa Kiserbia na Kibulgaria walioanza kulipa kodi kwa Ottoman baada ya ushindi wa Çirmen, yalichukuliwa chini ya utawala wa moja kwa moja wa Ottoman kwa kusonga mbele kwa beyi wa mpakani. Kwa kujiunga kwa Köstendil, Petriç, Nevrokop na Drama, nusu ya mashariki ya Makedonia ilifunguliwa na Selanik na Serez zikaingia kwenye mzunguko wa kuzingirwa. Kupanuka kwa Rumeli kuelekea kusini-magharibi katika ramani ni matokeo ya operesheni hii.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur alichukua Herat: mwisho wa nasaba ya Kert na kupita kwa Horasan kwa Timurî", "15f6019e"], "d": ["Horasan mwaka 1380 ilikuwa imegawanyika kutokana na mapambano kati ya Serbedârî, Kert na Muzafferî. Timur, baada ya kumtuma mwanawe Mîrân Şah eneo hilo, mwenyewe alielekea Herat na, baada ya kuizingira kwa muda, alipokea mji kutoka kwa Melik wa Kert Gıyâseddin Pîr Ali. Uasi uliotokea baada ya kuondoka kwake ulikandamizwa kwa damu na Mîrân Şah, na nasaba ya Kert iliyotawala Herat tangu 1255 ikamalizwa. Horasan yote, kutoka Meşhed hadi Nîşâbur, iliingia chini ya utawala wa Timurî tarehe hii.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Mwisho wa Beylik ya Eretna na kuanzishwa kwa Dola ya Kadı Burhâneddin", "60dcaf57"], "d": ["Eretnaoğulları, waliozaliwa kutoka ugavana wa Ilkhanid mwaka 1335 na waliotawala Anatolia ya Kati yenye vituo Sivas na Kayseri kwa miaka arobaini na sita, walivunjika kwa mivutano ya ndani ya ikulu. Kadı Burhâneddin, aliyekuwa vezir Mei 1378, baada ya kuwaondoa wapinzani wake Kılıcarslan na Hacı Şadgeldi, alitangaza usultani wake katika vuli ya 1381 na kuumaliza beylik, akianzisha dola iliyoitwa kwa jina lake. Hivyo jirani wa mashariki wa Ottoman alibadilika; mstari wa Sivas-Kayseri ungebaki mikononi mwa Kadı Burhâneddin kwa miaka kumi na saba iliyofuata.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Kusonga ndani ya Makedonia: ushindi wa Manastır na Ohri", "63bb7838"], "d": ["Manastır kwenye Via Egnatia na Ohri kando ya ziwa ziliingia chini ya utawala wa Ottoman wakati wa mashambulizi kuelekea Albania. Zote mbili zilikuwa sehemu muhimu za njia iliyofika Adriatic; Ohri pia ilikuwa kituo cha zamani zaidi cha askofu mkuu wa Kiorthodoksi wa Balkani. TDV inaandika kwamba hakuna taarifa ya uhakika kuhusu tarehe ya ushindi wa Ohri, na kwamba tarehe 787 (1385) na 797 (1395) baada ya kifo cha Kraliyeviç Marko zimependekezwa; hapa 1385 imechukuliwa kuwa msingi. Katika karne zilizofuata Manastır ingekuwa mojawapo ya vituo muhimu zaidi vya kijeshi vya Rumeli.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Vita vya Savra — kufunguliwa kwa milango ya Albania", "dda6671b"], "d": ["Kwa wito wa msaada wa beyi wa Kialbania Karlo Topya, aliyebanwa dhidi ya nasaba ya Balşa, vikosi vya Ottoman vililishinda jeshi la II. Balşa katika uwanda wa Savra; Balşa alikufa uwanja wa vita. Vita hivi, vilivyoingiwa kwa mwaliko wa beyi wa mahali, vilipatia Waottoman ushawishi wa kwanza wa kudumu katika ardhi za Albania zilizofika pwani za Adriatic. Sera hii, iliyogeuza ugomvi kati ya beyi wa eneo kuwa fursa, ingekuwa mbinu isiyobadilika ya ushindi wa Balkani kwa karne iliyofuata.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["'Kampeni ya miaka mitatu' ya Timur: kuchukuliwa kwa Azerbaijan na Iran Kaskazini", "2a98ec51"], "d": ["Timur, aliyeona hali ya mgawanyiko wa Iran kwa karibu wakati wa kampeni za Horasan, alielekea magharibi mwaka 788 (1386). Katika operesheni ya 1386-1388 inayoitwa 'kampeni ya miaka mitatu', alipitia Mâzenderan, Luristan na Georgia hadi Azerbaijan na kufika Karabağ; Tebriz, Erdebil, Urmiye na Nahçıvan ziliingia chini ya utawala wa Timurî. Kuchukua kwake Iran Kaskazini na Azerbaijan, kama ilivyokuwa zamani kati ya taifa la Cuci na Ilhanî, ilikuwa pia mwanzo wa mzozo mrefu na Altın Orda.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Vita vya Frenkyazısı na kuzingirwa kwa Konya — msafara wa kwanza wa Karaman", "af4e5d77"], "d": ["Dhidi ya Karamanoğlu Alâeddin Ali Bey, ambaye licha ya kuwa mkwe wa Ottoman alikasirishwa na upanuzi wa Ottoman Anatolia ya Magharibi, I. Murad alienda binafsi vitani; katika vita vilivyofanyika mahali panapoitwa Frenk Yazısı, jeshi la Ottoman lililofunzwa na lenye uzoefu liliwashinda vikosi vya Karaman. Kisha Ngome ya Konya ilizingirwa, lakini kwa kusamehewa kwa Alâeddin Bey beylik haikufutwa kabisa. Msafara huu ni pazia la ufunguzi wa mahesabu marefu kati ya Ottoman na Karaman yatakayodumu karne moja na kumalizika tu kwa kuunganishwa kwa uhakika mwaka 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Muş yapita kutoka utawala wa Karakoyunlu hadi utawala wa Timur (789/1387)", "ed2e7a11"], "d": ["Muş, iliyopita utawala wa Karakoyunlu baada ya enzi ya Wamongolia, katika 789 (1387) iliingia chini ya utawala wa Timur aliyekuwa mmiliki wa ardhi za Karakoyunlu. Katika atlasi Muş imeandikwa mwaka huu kama kutoka Karakoyunlu hadi Timurlu.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Kuanzishwa kwa Kiwanja cha Meli cha Gelibolu — kuzaliwa kwa jeshi la majini la Ottoman", "47546241"], "d": ["Kiwanja cha kwanza cha meli kilichopangwa vizuri cha Dola ya Ottoman kilianzishwa mwaka 1390 na Yıldırım Bayezid huko Gelibolu, mahali pa kiwanja kilichobaki kutoka Bizanti. Waottoman, wakirithi urithi wa baharini wa beylik za Anatolia ya Magharibi, hivyo kwa mara ya kwanza wakawa nguvu ya majini inayojenga meli zake yenyewe. Kiwanja, kilichokuwa mahali muhimu pa Mlango-bahari wa Çanakkale, kilitumika kama kituo kikuu cha jeshi la majini la Ottoman kwa karne moja na nusu, kuanzia kuzingirwa kwa Istanbul hadi misafara ya Aegean.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Hamîd-ili yajiunga na Ottoman: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Yıldırım Bayezid, aliyeanza msafara kufuatia shambulio la Karamanoğlu Alâeddin Bey dhidi ya Hamîd-ili na malalamiko ya watu, alichukua ardhi zote zilizobaki za Hamîdoğulları na akakabidhi utawala wake kwa mwanawe İsa Çelebi.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Mwisho wa nasaba ya Muzafferî: kushindwa kwa Şah Mansûr mbele ya Şîraz", "5fd14eb8"], "d": ["Şah Mansûr, mtawala wa mwisho mwenye nguvu wa Muzafferî waliotawala Yezd, Fars, Isfahan na Kirman tangu 1318, aliungana na jamaa zake na kuchukua hatua dhidi ya Timur. Katika vita karibu na Şîraz, mmoja wa emîr wake alipohamia upande wa pili, alipoteza sehemu kubwa ya vikosi vyake, akashindwa na kuuawa. Timur alipowauwa pia wanachama wote wa nasaba, utawala wa Muzafferî ulimalizika, na Fars na Kirman ziliunganishwa na utawala wa Timurî.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Kujiunga kwa Amasya na ardhi za Ottoman", "fe2860cf"], "d": ["Emir wa Amasya, aliyezingirwa wakati wa operesheni ya Anatolia ya Kati ya Yıldırım Bayezid, alikabidhi mji kwa Waottoman na Bayezid aliingia mjini mwaka 1393. Sultani aliiachia usimamizi wake kwa mwanawe Mehmed Çelebi; Amasya, kama sancak ya şehzade, tangu hapo ikawa mojawapo ya vituo muhimu zaidi vya malezi ya nasaba ya Ottoman. Chaguo hili lingekuwa la kuamua katika Enzi ya Fetret baadaye, na Çelebi Mehmed angeendesha mapambano ya kuiunganisha tena dola kutoka kwenye msingi huu wa Amasya.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur alichukua Bağdat — Wacelâyir walikimbilia Anatolia", "4d5602b3"], "d": ["Timur alichukua Bağdat baada ya mzingiro mrefu; mtawala wa mji, Sultani Ahmed wa Celâyir, alikimbia magharibi na kwanza alikimbilia kwa Wamamluki, kisha kwa ikulu ya Ottoman. Upanuzi wa Timur kuelekea magharibi hivyo kwa mara ya kwanza uligusana moja kwa moja na eneo la ushawishi la Ottoman. Mnyororo wa kwanza wa uhasama kati ya watawala hao wawili unaanzia hapa.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Kutekwa kwa Varna kwenye pwani ya Bahari Nyeusi", "a84b2abf"], "d": ["Wakati wa kubanwa kwa ardhi za Ufalme wa Kibulgaria kati ya Danubi na Bahari Nyeusi, Varna, bandari kubwa zaidi ya pwani, ilipita kwa utawala wa Ottoman. Kutekwa kwa bandari kulifungua njia ya kusonga kuelekea Dobruca na kuipa Ottoman gati kubwa ya kwanza kwenye pwani ya magharibi ya Bahari Nyeusi. Varna pia ingekuwa uwanja wa ushindi wa 1444 ambapo jeshi la Wanamsalaba lingeangamizwa miaka hamsini na moja baadaye.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Eneo la Nevşehir na Ürgüp lapita kutoka Karamanoğulları hadi Ottoman", "06ff59e8"], "d": ["Katika misafara ya Yıldırım Bayezid dhidi ya Karamanoğulları, eneo la Nevşehir (Muşkara) na Ürgüp lilipita chini ya utawala wa Ottoman mwaka 800/1398; mwaka 1402, baada ya Vita vya Ankara, Timur alirudisha eneo kwa Karamanoğulları.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Kuanguka kwa Dola ya Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, aliyetekwa na mtawala wa Akkoyunlu Karayülük Osman Bey, alipendekeza kuachiliwa kwa malipo ya kukabidhi Sivas, lakini wakazi wa mji walipinga na sultani aliuawa mbele ya kuta. Ingawa wakuu wa Sivas walimweka mwanawe Alâeddin Ali Çelebi mamlakani, mbele ya shinikizo la Akkoyunlu walimwomba msaada Yıldırım Bayezid; vikosi vya Ottoman chini ya amri ya Süleyman Çelebi vilimshinda Karayülük na kutawala mji. Hivyo Dola ya Kadı Burhâneddin ilitoweka katika historia na Sivas, Tokat, Niksar na Kayseri ziliongezwa kwenye ardhi za Ottoman. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Mzozo wa Timur: kurudishwa kwa wakimbizi kulikataliwa", "33790bc8"], "d": ["Kwa shinikizo la Timur, Sultani Ahmed wa Celâyir na kiongozi wa Karakoyunlu Kara Yûsuf walikimbilia ardhi za Ottoman; Timur alidai kurudishwa kwa wakimbizi hawa wawili, Yıldırım Bayezid alikataa. Kwa sababu hiyo barua zenye matusi mazito ya pande zote mbili zilianza kubadilishana kati ya watawala hao wawili. Msingi wa kiitikadi wa vita uliwekwa kwa mawasiliano haya kabla askari hata mmoja hajasonga.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Yıldırım Darüşşifası huko Bursa — hospitali ya kwanza ya Ottoman", "5f0dc59a"], "d": ["Katika miaka ambayo Yıldırım Bayezid alijenga Msikiti Mkuu wa kupendeza huko Bursa, alipatia mji pia dârüşşifa; ilikuwa sehemu iliyotengwa kwa tiba katika programu pana ya hisani iliyojumuisha imaret, madrasa, han na daraja. Jengo hili, hospitali ya kwanza iliyoanzishwa na dola, pia lilitumika kama shule ya tiba iliyofunza madaktari na likaweka mfano wa taasisi za afya za Ottoman. Kazi hii, iliyokamilika miaka miwili tu kabla ya maafa ya Ankara, ni mojawapo ya viungo vya mwisho vya maono ya Yıldırım ya kuufanya Bursa mji mkuu wa himaya.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur aliharibu Sivas kabisa", "f4d79de6"], "d": ["Timur, aliyeelekea Sivas kwa uongozi wa Karayülük Osman Bey wa Akkoyunlu na emîr wa Erzincan Mutahharten, alizingira mji kwa siku kumi na nane na, baada ya kuupokea kwa ahadi kwamba damu ya mtu yeyote haitamwagwa, alifanya mauaji makubwa; aliwajaza watetezi kwenye mitaro na kuwafunika wakiwa hai. Kuta kwanza, kazi muhimu za mji ziliharibiwa, Sivas ilianguka kidemografia. Hili ndilo pigo kubwa la kwanza ambalo Timur alilitoa kwa ardhi za Ottoman miaka miwili kabla ya Vita vya Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bayezid alirudisha Erzincan na Kemah", "7047ca08"], "d": ["Yıldırım Bayezid, akitumia fursa ya Timur kwenda kampeni ya Syria, alichukua Erzincan na Kemah kutoka kwa emîr wa Erzincan Mutahharten, aliyekuwa tegemezi kwa Timur. Ingawa hakuingilia uharibifu wa Sivas, hatua hii ilimaanisha kupinga moja kwa moja eneo la ushawishi la Timur Anatolia Mashariki. Uhusiano kati ya watawala hao wawili ulikuwa hauwezi kurekebishwa tangu hapo.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Uamuzi wa mwisho wa Timur kutoka Tebriz — masharti manne", "3e1ac50e"], "d": ["Timur, kwa mjumbe aliyemtuma kutoka Tebriz, alitangaza masharti manne: kurudishwa kwa Kemah kwa Mutahharten, kurudishwa kwa ardhi zilizochukuliwa kutoka kwa mabeyi wa Anatolia kwa wamiliki wake, kutumwa kwa şehzade wa Ottoman kama dhamana na kukubaliwa kwa külâh na mkanda kama alama ya utii, na kukabidhiwa kwa Kara Yûsuf. Bayezid hakukubali hata moja; licha ya msisitizo wa watu wa serikali na upatanishi wa Mutahharten, mazungumzo yalivunjika. Timur alikuwa ameazimia kufunga suala la Anatolia kwa uhakika kabla ya kwenda kampeni ya China.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Saruhanoğulları waliundwa upya — Manisa ilitoka kwa Ottoman", "ac747b05"], "d": ["Wiki tatu baada ya kushindwa kwa Ankara, kwa msaada wa Timur Orhan Bey alikalia kichwa cha beylik na mkoa wa Saruhan ukawa huru tena. Eneo lenye kitovu cha Manisa lilitoka kwenye ramani miaka kumi na miwili baada ya kuunganishwa kwa Ottoman mwaka 1390. Hii ni mojawapo ya utekelezaji wa kwanza wenye tarehe inayojulikana kwa uhakika wa sera ya Timur ya kufufua beylik.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emîr Süleyman alikimbilia Rumeli na hazina ya dola", "0a2b7363"], "d": ["Emîr Süleyman, akichukua pamoja naye hazina ya dola, kumbukumbu, familia yake na ndugu zake kutoka Bursa, alivuka kwa meli kutoka Gemlik hadi Güzelcehisar (Anadoluhisarı), kutoka huko alifika Gelibolu na kutangaza utawala wake Edirne. Kuhamishwa kwa kumbukumbu za dola na hazina hadi Rumeli ni mwanzo wa kuhama kwa kitovu cha mvuto cha Ottoman kuelekea Balkan kwa kizazi kimoja. Kwenye ramani Rumeli inachorwa kuanzia tarehe hii kwa rangi ya Emîr Süleyman mwenyewe.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur aliunda upya beylik za Anatolia — umoja wa Waturuki ulivunjika", "15187774"], "d": ["Timur, baada ya ushindi wa Ankara, aliwarudishia mabeyi waliokuwa pamoja naye ardhi zao za zamani. Mabeyi Karamanoğlu Mehmed na Ali walipewa mkoa wa Karaman pamoja na Kayseri, Kırşehir, Sivrihisar na Beyşehir; Germiyanoğlu II. Yâkub Bey alipewa Kütahya na mkoa wa Germiyan; Candaroğlu İsfendiyar Bey alipewa, pamoja na mstari wa Kastamonu-Sinop, Çankırı na Kalecik. Mikoa ya Aydın, Menteşe na Teke pia ilirudi kwa nasaba zao za zamani. Umoja wa Waturuki wa Anatolia ambao Yıldırım Bayezid aliujenga kwa miaka kumi ulivunjika ndani ya majira moja ya joto; kwenye ramani beylik hizi zinaonekana tena kwa rangi zao wenyewe.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur alichukua İzmir kutoka kwa Wapiganaji wa Saint Jean", "66dd1dd4"], "d": ["Timur, aliyeshuka magharibi kupitia Kütahya, Denizli, Aydın, Ayasuluk na Tire, alizingira na kuchukua İzmir ya pwani, iliyokuwa mikononi mwa Wakristo tangu 1344. Timur, aliyeiteka kwa haraka ngome ambayo Yıldırım Bayezid hakuweza kuichukua kwa miaka, baada ya kuchukua pia ngome za jirani, aliuacha mkoa wa Aydın kwa wamiliki wake wa zamani na kurudi mashariki. Mji tangu hapo uliingia chini ya utawala wa Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi alichukua Bursa — sehemu ya Anatolia ilizaliwa", "955128c1"], "d": ["Îsâ Çelebi, aliyerudi upande wa Karesi baada ya kushindwa kwa Ankara, alichukua Bursa wakati Timur akiwa İzmir. Katika mji mkuu wa zamani uliokuwa umeporwa na kuchomwa na askari wa Timur alitangaza utawala wake na kuamuru sarafu itengenezwe kwa jina lake; Januari 1403 alitambuliwa Anatolia kwa cheo cha 'mtawala wa Waturuki'. Kwenye ramani sehemu hii inayoenea kando ya pwani ya Asia ya Marmara inaonekana kwa rangi ya Îsâ Çelebi mwenyewe.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Kuondoka kwa Timur kutoka Anatolia", "93a98839"], "d": ["Timur, aliyepokea habari kwamba Yıldırım Bayezid amefia Akşehir, alihesabu kazi yake Anatolia kuwa imekwisha na akaelekea mashariki. Nyuma yake zilibaki beylik zilizotangaza utii kwake na şehzade wa Ottoman waliokuwa wamegombana; baadhi ya miji kama Sivas iliachwa mikononi mwa emîr kama Mezid Bey waliokuwa tegemezi kwa Timur. Timur hakurudi Anatolia tena, lakini mpangilio huu uliogawanyika alioanzisha ulidumu miaka kumi.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emîr Süleyman alivuka kwenda Anatolia: Bursa ilipita mikononi mwake", "9b27aa5f"], "d": ["Emîr Süleyman, aliyesikia kushindwa kwa Îsâ Çelebi, alivuka kwenda Anatolia pamoja na Çandarlı Ali Paşa kwa jeshi lenye nguvu na kuchukua Bursa; kumbukumbu za Machi 1404 zinaonyesha kwamba Karadeniz Ereğlisi pia ilikuwa chini ya utawala wake. Çelebi Mehmed hakuweza kupinga Süleyman, aliyetawala kwa muda mfupi Rumeli na sehemu kubwa ya Anatolia. Kwenye ramani kuanzia tarehe hii hadi Çelebi Mehmed aliporudisha Bursa (1410), pande zote mbili za mlangobahari zinaonekana kwa rangi moja, katika sehemu ya Emîr Süleyman.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Vita vya Tambarare ya Yenişehir — Çelebi Mehmed alirudi Amasya", "f1568288"], "d": ["Çelebi Mehmed, aliyepoteza Bursa na Ankara, alishindwa na Emîr Süleyman kwenye tambarare ya Yenişehir, akapoteza mafanikio yake yote Anatolia Magharibi na akarudi kwenye kituo cha Tokat-Amasya. Baada ya kushindwa huku aliepuka mapigano ya moja kwa moja na akaelekea kuimarisha mamlaka yake ndani ya Anatolia. Awamu tulivu ndefu zaidi ya Fetret ilianza hivyo.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emîr Süleyman amchukua Ankara kutoka kwa Çelebi Mehmed", "d6a2acd6"], "d": ["Emîr Süleyman aliizingira Ankara, iliyobaki mikononi mwa Çelebi Mehmed baada ya Timur kuondoka Anatolia, mwaka 1406. Mlinzi wa ngome Yâkub Bey alipinga kwa muda, lakini kwa hila ya Vezîriâzam Çandarlı Ali Paşa alikabidhi ngome kwa Süleyman. Kwa hiyo Çelebi Mehmed, kwa kukubaliana na Karamanoğlu Mehmed Bey, alianza kutenda dhidi ya Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed arudisha Sivas kutoka kwa Mezid Bey wa Timurlu", "90079b0c"], "d": ["Baada ya uvamizi wa Timur, utawala wa Sivas ulikuwa umeachwa kwa Mezid Bey aliyekuwa tegemezi wa Timur. Çelebi Mehmed, aliyekuwa Amasya, alimtuma kamanda wake Bayezid Paşa kuuchukua mji, na baada ya upinzani mkali Sivas ilipita kwa mara ya pili mikononi mwa nasaba ya Ottoman. Hivyo sehemu ya Mehmed ilifikia mpaka wake wa zamani mashariki miaka sita baada ya Vita vya Ankara.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Mwisho wa nasaba ya Artuklu: kukabidhiwa kwa Mardin kwa Karakoyunlu", "15b06f33"], "d": ["Waartuklu, waliotawala Mardin tangu 1106 na ambao ndio tawi lililodumu zaidi la nasaba, hawakuweza kustahimili shinikizo la Akkoyunlu. Melik Ahmed, aliyeona hawezi kuutetea mji, alikubaliana na mtawala wa Karakoyunlu Kara Yûsuf na kumkabidhi Mardin. Utawala wa Artuklu wa zaidi ya karne tatu hivyo uliisha; Mardin na mazingira yake yakawa uwanja wa mapambano ya Karakoyunlu-Akkoyunlu hadi ilipopita kwa Ottoman karne moja baadaye.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Vita vya Yanbolu — Mûsâ Çelebi aingia Edirne", "8f978408"], "d": ["Mûsâ Çelebi, aliyevuka hadi Rumeli kupitia Eflak, kwa msaada wa Eflak na Waserbia aliyashinda majeshi ya Emîr Süleyman huko Yanbolu na akaingia Edirne. Katika Enzi ya Fetret, Rumeli kwa mara ya kwanza ilitoka mikononi mwa Emîr Süleyman. Hata hivyo utawala wake haukuwa wa kudumu; miezi minne baadaye angeshindwa Kosmidion na kurudi ndani ya Balkani.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Vita vya İnceğiz — kushindwa kwa kwanza kwa Çelebi Mehmed Rumeli", "3c35cd43"], "d": ["Çelebi Mehmed, aliyevuka hadi Rumeli kwa meli za Bizanti, alipigana na Mûsâ Çelebi huko İnceğiz; Mûsâ, kwa yeniçeri elfu saba chini ya amri yake, alimshinda Mehmed na Mehmed alilazimika kurudi Anatolia. Kushindwa huku kulimwelekeza Mehmed kwenye mkakati wa kuwavuta beyi wa mpakani wa Rumeli na ufalme wa kidespoti wa Kiserbia upande wake badala ya vita vya moja kwa moja. Msingi wa ushindi wa Çamurlu miezi tisa baadaye uliwekwa kwa diplomasia hii.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Kuzingirwa kwa Konya na mkataba na Karamanoğulları — Hamîd-ili, Said-ili, Beyşehir, Seydişehir na Akşehir zarudishwa", "0996257e"], "d": ["Dhidi ya Karamanoğulları, waliovamia ardhi za Ottoman wakati wa Enzi ya Fetret na kuizingira na kuichoma Bursa, Çelebi Mehmed alipanga msafara mkubwa na akaizingira Konya mnamo Muharrem 818. Karamanoğlu II. Mehmed Bey alilazimika kuomba amani; kwa matokeo ya mkataba Hamîd-ili (eneo la Isparta) na Said-ili ziliongezwa tena kwenye ardhi za Ottoman, Beyşehir, Seydişehir na Akşehir pia zilirudishwa; Sivrihisar, ambayo Timur aliwapa Karamanoğulları mwaka 1402, nayo ilirudi kwa Waottoman. Msafara huu, ambapo umoja wa Anatolia uliovunjika katika Vita vya Ankara ulianza kushonwa upya, ni mojawapo ya sababu za kudhahiri za kumhesabu Çelebi Mehmed kuwa 'mwanzilishi wa pili'.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Kuchukuliwa kwa İzmir kutoka kwa Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["İzmir, kituo cha Aydınoğlu Cüneyd Bey aliyebadilisha upande kati ya şehzade mfululizo wakati wa Fetret, ilichukuliwa na Çelebi Mehmed baada ya kuzingirwa kwa siku kumi; Cüneyd alisamehewa na kupelekwa kwenye usimamizi wa sancak ya Niğbolu. Mji ambao Timur aliurudisha kwa Aydınoğulları mwaka 1402 hivyo ulirudi Ottoman baada ya miaka kumi na mitatu. Cüneyd angeuchukua tena mji mwaka 1422, na jambo hilo lingefungwa tu na II. Murad mnamo 1424-1426.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Kunyongwa kwa Torlak Kemal — Saruhan yabaki kwa uhakika Ottoman", "8a09dbf1"], "d": ["Torlak Kemal, aliyeongoza tawi la Anatolia ya Magharibi la harakati ya Sheikh Bedreddin, alishindwa katika eneo la Manisa na akanyongwa. Baada ya tarehe hii eneo la Saruhan liliingia kwa uhakika chini ya udhibiti wa Ottoman na beylik iliyofufuliwa na Timur mwaka 1402 ikatoweka katika historia. Masalio ya mwisho ya kisiasa ya Enzi ya Fetret katika Anatolia ya Magharibi yakaondolewa hivyo.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Ushindi wa Avlonya, Berat na Kanina", "1e1949b8"], "d": ["Waottoman mwaka 1417 walichukua chini ya utawala wao Avlonya kwenye pwani ya Adriatic, pamoja na mji wa Berat ndani ya nchi na Ngome ya Kanina. Mwaka mmoja baadaye jaribio la Venice la kurudisha mji lilishindwa na, kwa kuanzishwa kwa shirika la sancak hapa, mamlaka ya Ottoman yalifanywa ya kudumu. Kutekwa kwa Avlonya kuliifanya Ottoman kwa mara ya kwanza mmiliki wa moja kwa moja wa bandari kwenye Adriatic na kuipa mahali pa kurukia ng'ambo ya bahari mbele ya Italia.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Kurudishwa kwa Anatolia ya Kati: Kayseri na Kırşehir", "204eacb3"], "d": ["Miji ya Anatolia ya Kati iliyopita mikononi mwa Karamanoğulları wakati wa Enzi ya Fetret ilirudi chini ya utawala wa Ottoman wakati wa misafara ya Çelebi Mehmed ya kuiunganisha tena dola. Kwa kujiunga kwa Kayseri na Kırşehir, bonde la Kızılırmak lililopotezwa katika Vita vya Ankara lilirudishwa kwa kiasi kikubwa. Kusonga huku ni mwendelezo wa sera ya kuelekea mashariki iliyoanza na kuzingirwa kwa Konya miaka minne iliyopita.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Mamluki wampa Kayseri Dulkadırlı Nâsırüddin Muhammed", "aad4b00c"], "d": ["Jeshi la Mamluki lililoanza msafara dhidi ya Karamanoğlu Mehmed Bey liliivamia Kayseri; kamanda wa Mamluki aliuacha mji na mazingira yake kwa Dulkadırlı Nâsırüddin Muhammed na akarudi nchini kwake.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Kifo cha I. Mehmed na kupanda kwa II. Murad", "98acac77"], "d": ["I. Mehmed, aliyemaliza Enzi ya Fetret na kuziunganisha tena ardhi za Ottoman katika mkono mmoja, alifariki Edirne tarehe 25 Juni 1421 na mwanawe Murad alipanda kiti cha enzi Bursa. Kulingana na mpangilio uliofanywa na Bizanti kabla ya kifo chake, wana wake wadogo wangetumwa kwa mfalme kama mateka, na mfalme asingemwachilia mdai wa kiti cha enzi Mustafa Çelebi aliyekuwa mikononi mwake; II. Murad alikataa kuwatuma ndugu zake kwa mfalme.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Kufutwa kwa uhakika kwa Tekeoğulları: kutekwa kwa Antalya", "e65565b2"], "d": ["Beylik ya Tekeoğulları, iliyoanzishwa upya kwa kufufuliwa na Timur baada ya Vita vya Ankara, ilimalizika kwa vikosi vya Ottoman chini ya amri ya Hamza Bey kuizingira Antalya; mtu muhimu wa mwisho wa beylik Osman Çelebi aliondolewa. Hivyo Teke ili kwenye pwani ya Mediterania ilijiunga kwa uhakika na Ottoman baada ya kutengana kwa miaka ishirini na mmoja. Beylik hiyo, kama tawi lililojitenga na Hamîdoğulları, ilikuwa ikitawala Antalya tangu 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Msafara wa Mora wa Turahan Bey na kuvunjwa kwa Ukuta wa Hexamilion", "c6c2706d"], "d": ["Bizanti ilipomuunga mkono mdai mpinzani wa kiti cha enzi Mustafa Çelebi, II. Murad alimtuma Turahan Bey Mora. Turahan Bey alibomoa ukuta wa Hexamilion uliofunga Isthmus ya Korintho kutoka mwisho hadi mwisho, akaingia kwenye peninsula na akasababisha uharibifu mkubwa. Amani ilipatikana kwa sharti la ukuta kutojengwa tena na kodi ya kila mwaka kulipwa; utawala wa kidespoti wa Mora hivyo uliachwa bila ulinzi wa kijeshi na msingi wa ushindi wa mwisho wa 1460 uliandaliwa miaka thelathini na saba mapema.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Monasteri za Aynaroz (Athos) zaingia chini ya ulinzi wa Ottoman", "562de5ea"], "d": ["Katika miaka ambayo Selanik ilikuwa imezingirwa, jamhuri ya monasteri ya Aynaroz kwenye kidole cha mashariki cha Halkidiki ilimwomba II. Murad ulinzi na ikakubali utawala wa Ottoman. Haki za mali na ibada za watawa zilihakikishwa; monasteri ziliachwa huru katika mambo yao ya ndani kwa malipo ya kodi. Mpangilio huu ukawa mfano wa kudumu zaidi wa uhusiano wa ulinzi wa Ottoman na taasisi za Kiorthodoksi na ulidumu karne tano.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Kuunganishwa kwa Beylik ya Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Kwa shinikizo la beylerbeyi wa Amasya Yörgüç Paşa, Tâceddinoğlu Hüsâmeddin Hasan Bey alikabidhi funguo za nchi yake yenye kitovu Niksar katika mwaka 830 (1427); alipewa sancak huko Rumeli. Beylik iliyoanzishwa katika nusu ya pili ya karne ya XIV, ambayo mipaka yake wakati fulani ilifika Kelkit, Amasya, Samsun, Ordu na Giresun, hivyo ilimalizika. Mwaka huo huo ardhi zilizokuwa za Hacıemiroğulları pia zilifanyiwa tahrir na kuunganishwa na sancak ya Canik; enzi ya beylik za Bahari Nyeusi ya Kati ilifungwa.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Kuachiwa kwa Belgrad kwa Hungaria — Mkataba wa Tata", "62481183"], "d": ["Kwa kifo cha despot wa Kiserbia Stefan Lazareviç, kwa mujibu wa Mkataba wa Tata uliofanywa kati ya mfalme wa Hungaria Sigismund na mrithi Georg Brankoviç, ngome ya Belgrad ilikabidhiwa kwa Hungaria. Ngome iliyosimama mahali Danube na Sava zinakutana ilikuwa hadi siku hiyo mikononi mwa despotate ya Kiserbia na ilikuwa kufuli ya mlango uliofunguka kwa Ulaya ya Kati kwa Ottoman. Kukabidhiwa huku kuliifanya Belgrad kuwa kizuizi kikali zaidi mbele ya kusonga mbele kwa Ottoman kwa miaka mia moja: mizingiro ya 1440 na 1456 ingeshindwa, ngome ingeanguka mwaka 1521 tu.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin ipita kutoka kwa mlinzi wa Karakoyunlu hadi Akkoyunlu Karayülük Osman Bey", "d82bc97f"], "d": ["Mardin, iliyochukuliwa na Kara Yûsuf mwaka 1409, ilisimamiwa na Karakoyunlu kupitia magavana; Emîr Nâsır, aliyeachwa kama mlinzi, alikabidhi mji kwa Akkoyunlu Karayülük Osman Bey mwaka 835 (1432). Utawala wa Akkoyunlu ulidumu hadi mwanzo wa karne ya XVI.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Karamanoğulları wachukua Kayseri kutoka Dulkadırlılar", "2b09e8e8"], "d": ["Kwa ushindi alioupata dhidi ya Dulkadırlılar, beyi wa Karaman aliongeza Kayseri, Ürgüp, Develi Karahisârı na Uçhisar kwenye nchi yake.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Tukio la Buçuktepe — uasi wa kwanza wa yeniçeri na kurudi kwa II. Murad kwenye kiti cha enzi", "6388dda1"], "d": ["Tukio la Buçuktepe, uasi wa kwanza wa yeniçeri unaojulikana katika historia uliolipuka Edirne, ulianza kwa ombi la kuongezewa ulûfe zao nusu akçe na ukamalizika kwa kuondolewa kwa II. Mehmed mdogo kwenye kiti cha enzi. II. Murad alianza usultani wake wa pili kwa kuondoka haraka Manisa tarehe 8 Safer 850. Tukio hilo likawa ishara ya kwanza kwamba ocak ya kapıkulu sasa ilikuwa nguvu yenye neno juu ya kiti cha enzi na lilitengeneza tahadhari ya maisha yote ya Fatih dhidi ya yeniçeri.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Kujiunga kwa pwani ya Epir: Arta na Preveze", "796f7ecf"], "d": ["Miaka kumi na tisa baada ya Yanya kujisalimisha mwaka 1430, Arta na Preveze kwenye sehemu ya pwani ya utawala wa kidespoti wa Epir nazo ziliingia chini ya utawala wa Ottoman. Hivyo ghuba ya Ambrakia iliyofunguka kwenye Bahari ya Ionia ilichukuliwa chini ya udhibiti na uhusiano wa baharini wa Yanya ukakamilika. Preveze ni sehemu muhimu ya ghuba ambayo miaka tisini baadaye ingetoa jina lake kwa ushindi wa Barbaros utakaoingia katika historia.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Kifo cha II. Murad na kupanda kwa pili kwa II. Mehmed", "8f8256ad"], "d": ["II. Murad, aliyeugua baada ya harusi ya mwanawe, alifariki Edirne tarehe 1 Muharrem 855 (3 Februari 1451). II. Mehmed mwenye umri wa miaka kumi na tisa alipanda kiti cha enzi cha Ottoman kwa mara ya pili tarehe 16 Muharrem 855 (18 Februari 1451) — safari hii kwa kudumu. Kurudi kwa mtawala kijana aliyeondolewa kwenye kiti cha enzi Buçuktepe miaka mitano iliyopita ni mwanzo wa utawala ambao ungetawazwa kwa ushindi wa Istanbul miaka miwili baadaye na ungeigeuza Beylik ya Ottoman kuwa himaya ya dunia.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Kuzingirwa kwa kwanza kwa Kefe na vikosi vya pamoja vya Ottoman-Crimea", "e346d163"], "d": ["Khan wa Crimea Hacı Giray, aliyekubaliana na Fâtih Sultan Mehmed Juni 1454, aliizingira Kefe kwa nchi kavu kwa wapanda farasi 7000; jeshi la majini la Ottoman la galley hamsini hadi sitini pia lilichukua nafasi baharini. Kefe ya Genoa iliondoa kuzingirwa kwa kulipa kodi, na ushindi wa uhakika ukabaki hadi miaka ishirini na moja baadaye, 1475. Operesheni hii ya kwanza ya pamoja ilikuwa mfano wa kwanza wa ushirikiano wa kijeshi wa Ottoman-Crimea ambao ungerudiwa baadaye katika ushindi wa uhakika wa Kefe.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Kutekwa kwa visiwa vya Aegean ya Kaskazini: Bozcaada, İmroz na Taşoz", "76575895"], "d": ["Mara baada ya ushindi wa Istanbul, Fatih Sultan Mehmed alielekea visiwa kwenye mdomo wa Aegean wa Mlango-bahari wa Çanakkale ili kuhakikisha njia ya bahari ya mji mkuu mpya; Bozcaada na İmroz zilichukuliwa kutoka Bizanti, na Taşoz kutoka familia ya Gattilusio yenye asili ya Genoa. Visiwa hivi, vilivyofunga pande zote mbili za mlango-bahari, tangu hapo vikawa kiungo cha kwanza cha mstari wa chakula na ulinzi wa Istanbul. Utawala ulikwenda na kurudi kwa muda kutokana na uingiliaji wa majeshi ya majini ya upapa na Venice, na ulithibitishwa tu mwaka 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Ushindi wa Kosova: kutekwa kwa Priştine na Yenipazar", "d7ed2345"], "d": ["Jeshi la Ottoman lililosonga dhidi ya Utawala wa Kidespoti wa Kiserbia liliteka Priştine kwenye uwanda wa Kosova na Yenipazar, kitovu cha eneo la Raşka; katika operesheni hiyo hiyo Novoberda, maarufu kwa migodi yake ya fedha, pia ilitekwa. Hivyo nusu ya kusini ya Serbia iliunganishwa na utawala wa moja kwa moja wa Ottoman na kituo cha kidespoti cha Semendire kilitenganishwa na ardhi zake kuu. Ushindi huu ulikuwa hatua ya kuamua kwenye njia inayoelekea kuunganishwa kamili kwa Serbia miaka minne baadaye.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["İpek (Peç) yaingia chini ya utawala wa Ottoman — mojawapo ya vituo vya sancak ya Dukakin", "19511588"], "d": ["Mara baada ya msafara wa Serbia wa Fâtih Sultan Mehmed mwaka 1455, İpek, kitovu cha upatriaki wa Kiserbia, ilipita kwa utawala wa Ottoman; hakuna rekodi ya kupita huku katika vyanzo vya Ottoman. Kwa wakati mji ukawa mji mdogo wa Kiislamu na ukawa mojawapo ya makazi ya beyi wa sancak katika sancak ya Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Ushindi wa Enez na Semadirek — kukamilika kwa pwani ya Trakya ya Magharibi", "106e723b"], "d": ["Enez, mahali mto Meriç unapomwagika baharini, ilichukuliwa kutoka familia ya Gattilusio yenye asili ya Genoa iliyoishikilia kwa miaka themanini; kisiwa cha Semadirek kilichotegemea mji huo pia kilitekwa katika operesheni hiyo hiyo. Kwa kuanguka kwa Enez, ukanda wa pwani ya Trakya ya Magharibi ukawa ardhi ya Ottoman isiyokatika kuanzia Selanik hadi Gelibolu. Mikononi mwa familia ya Gattilusio kilibaki Midilli peke yake; nacho kingetekwa miaka sita baadaye.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Kushindwa kwa kuzingirwa kwa Belgrade", "3d53a604"], "d": ["Fatih Sultan Mehmed, baada ya ushindi wa Istanbul, aliizingira Belgrade iliyohesabiwa kufuli ya Ulaya ya Kati; hata hivyo nyongeza ya jeshi iliyoletwa na Jan Hunyadi kupitia Danubi na wajitolea waliokusanywa na mhubiri wa Wanamsalaba Kapistrano vilizuia kuanguka kwa ngome. Sultani, licha ya ushujaa wa binafsi alioonyesha mbele ya kuzingirwa, alijeruhiwa na akalazimika kujiondoa. Kushindwa huku kungefunga mpaka wa Hungaria kwa maendeleo ya Ottoman kwa miaka sitini na tano; Belgrade ingeweza kutekwa tu mwaka 1521 na Kanûnî.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Ushindi wa Mora ya Kaskazini: Balyabadra (Patras)", "c08a8509"], "d": ["Vikosi vya Fatih Sultan Mehmed, vilivyoelekea utawala wa kidespoti wa Mora katika miaka ile ile ya kuunganishwa kwa Serbia, viliteka Balyabadra kaskazini-magharibi mwa peninsula. Bandari hii inayoshikilia mdomo wa ghuba ya Korintho ni kufuli ya kuingia Mora kwa nchi kavu; kutekwa kwake kuliandaa msingi wa ushindi wa mwisho miaka miwili baadaye. Mji ulikuwa gati kubwa ya mwisho ambapo madespoti wa Bizanti walijenga uhusiano na ulimwengu wa Kilatini.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Kutekwa kwa pwani ya Bahari Nyeusi ya Magharibi: Amasra", "f43608fc"], "d": ["Amasra, koloni lenye ngome la Genoa kwenye Bahari Nyeusi ya Magharibi, ilijisalimisha bila kupinga kwa shinikizo la pamoja la jeshi la majini na jeshi la nchi kavu la Fatih Sultan Mehmed. Bandari hii kwenye pwani ya Bartın-Zonguldak ilisimama kama mfuko wa Kilatini kati ya Candaroğulları na ardhi za Ottoman; kwa kutekwa kwake pwani iliunganika. Kuanguka kwa Amasra ni hatua ya kwanza ya msafara mkubwa wa Bahari Nyeusi utakaoelekea Sinop na Trabzon miaka miwili baadaye (1461).", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Ushindi wa kisiwa cha Midilli", "fe17aeba"], "d": ["Jeshi la Ottoman chini ya amri ya Fâtih Sultan Mehmed, mnamo Zilhicce 866, baada ya kuzingirwa kwa muda mfupi lakini mkali, lilichukua Midilli kutoka mikononi mwa familia ya Gattilusio yenye asili ya Genoa na kuiunganisha. Kuanguka kwa kisiwa kikubwa zaidi cha Aegean ya Kaskazini kulimaliza pia kituo cha mwisho muhimu cha Wagenoa katika eneo hilo. Kisiwa, kwa ukaribu wake na pwani ya Anatolia, tangu hapo kingetumika kama kituo cha mbele cha jeshi la majini la Ottoman, na pia kingeingia katika historia ya baharini kama mahali walipolelewa ndugu Barbaros.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Kuanza kwa Vita vya Ottoman-Venice vya miaka kumi na sita", "563ddb68"], "d": ["Wavenice, ili kusimamisha kusonga mbele kwa Ottoman Mora na Aegean, walianza vita mwaka 1463 kwa kufanya muungano na watawala wa Karaman na Akkoyunlu. Mkakati huu wa kuzingira, ulioundwa na Uzun Hasan mashariki, Venice magharibi na Karaman katikati, ulimlazimisha Fatih kupigana kwenye mbele kadhaa kwa wakati mmoja. Mapambano yaliyodumu miaka kumi na sita yangejumuisha operesheni zote kubwa za wakati huo, kuanzia Otlukbeli hadi misafara ya Albania, na yangemalizika tu kwa Mkataba wa Istanbul wa 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Ushindi wa sehemu kubwa ya Herzegovina: Trebinye na Mostar", "f54c0100"], "d": ["Ardhi za Duke wa Herzegovina Stjepan Vukčić-Kosača, aliyeanzisha utawala tofauti na Bosnia, zilipita kwa kiasi kikubwa chini ya utawala wa Ottoman miaka mitatu baada ya kuanguka kwa Ufalme wa Bosnia: kusini Trebinye ilichukuliwa mwaka 1466 \"pamoja na karibu eneo lote la Herzegovina\". Mostar, iliyoanzishwa kuzunguka ngome mbili ndogo za daraja la Neretva, inaonekana ilitekwa muda mfupi kabla ya ushindi wa 1466-1468 wa Blagaj, kitovu cha Herzegovina; imeandikwa kwa jina la \"Köprülü Hisar\" katika tahrir ya icmal ya Bosnia ya 1468-1469. Ushindi wa Herzegovina pamoja na ngome zilizobaki za dukedom ulikamilika mwaka 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Msafara wa II. wa Albania — Fatih kwenda binafsi dhidi ya İskender Bey", "9cdd2bfa"], "d": ["Ili kuvunja upinzani wa İskender Bey uliodumu zaidi ya robo karne, Fatih Sultan Mehmed alipanga misafara mikubwa aliyoiamuru binafsi mnamo 1466-1467. Jeshi la Ottoman lilizingira Akçahisar na kujenga Ngome ya İlbasan (Elbasan) kudhibiti eneo. Msafara, ingawa ulivunja uti wa mgongo wa upinzani wa Kialbania, haukufanikiwa kuiangusha ngome; utii kamili wa eneo ungehitaji muongo mmoja baada ya kifo cha İskender Bey.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Vikosi vya mbele vya Akkoyunlu vyachukua ngome ya Bingöl kutoka Karakoyunlu", "51b94cbc"], "d": ["Katika wiki za mwisho za msafara ambao Cihan Şah alianzisha dhidi ya Uzun Hasan, vikosi vya mbele vya Akkoyunlu viliteka ngome ya Bingöl; kwa kuuawa kwa Cihan Şah tarehe 10 Novemba 1467 utawala wa Karakoyunlu katika eneo ulimalizika.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Kuporomoka kwa Dola ya Karakoyunlu: kuuawa kwa Cihan Şah", "30bc6358"], "d": ["Mtawala wa Karakoyunlu Cihan Şah, aliyeshambuliwa alipokuwa akirudi kutoka msafara dhidi ya Uzun Hasan kwa sababu ya majira ya baridi kuingia, aliuawa alipokuwa akikimbia kati ya Bingöl na Kiğı. Baada ya pigo hili dola haikuweza kujikusanya; mtawala wa mwisho Hasan Ali alikamatwa mwaka 1469 na Uğurlu Mehmed, mwana wa Uzun Hasan, na akauawa. Utawala wa Karakoyunlu uliodumu karibu karne moja katika Anatolia ya Mashariki, Azerbaijan na Iraki hivyo ulipita kwa Akkoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Kifo cha İskender Bey — kuzimika kwa upinzani wa Kialbania", "9158c35f"], "d": ["İskender Bey, aliyelelewa katika ikulu ya Ottoman lakini aliyeasi mwaka 1444 baada ya kushindwa kwa İzlâdi na kupinga Albania kwa zaidi ya robo karne, alikufa Leş alikokimbilia. Upinzani huu, uliowachelewesha mara kwa mara majeshi ya Ottoman katika enzi za II. Murad na Fatih, ulipoteza uongozi wake mkuu kwa kifo chake. Kwa kuporomoka kwa mbele ya Kialbania iliyolishwa na upapa na Venice, Waottoman ndani ya miaka kumi walichukua Akçahisar na İşkodra na wakaiunganisha kwa uhakika nchi hiyo.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Utawala wa Ottoman waanzishwa Kayseri: Gedik Ahmed Paşa amaliza Karamanoğulları", "33cf35fc"], "d": ["Kwa Gedik Ahmed Paşa kumaliza Karamanoğulları mwaka 1474, Kayseri iliingia chini ya utawala wa Ottoman; mji ulikuwa umebadilisha mikono kati ya Dulkadıroğulları, Ramazanoğulları na Karamanoğulları katika karne ya 15. Kwa utawala wa Ottoman Kayseri ikawa kitovu cha sancak cha beylerbeylik ya Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Sisam yaachwa: umiliki wa Genoa (Maona) wamalizika", "5bdc380c"], "d": ["Kulingana na TDV kisiwa kiliachwa baada ya 1475; mwaka 1479 Fatih Sultan Mehmed alikiteka kisiwa na akajenga ngome.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Kushindwa kwa Racova (Vaslui) huko Bogdan", "a1a74bf7"], "d": ["Voivode wa Bogdan Stefan cel Mare, kwa kuvuta vikosi vya Ottoman chini ya amri ya Beylerbeyi wa Rumeli Hadım Süleyman Paşa kwenye ardhi ya kinamasi, aliwashinda vibaya. Kushindwa huku, mojawapo ya kushindwa vibaya zaidi vya nchi kavu vya enzi ya Fatih, kulizua mwangwi mkubwa Ulaya na kulimpatia Stefan sifa katika ulimwengu wa Wanamsalaba. Sultani angeenda binafsi vitani mwaka uliofuata kulipiza kisasi.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Ushindi wa Akdere (Valea Albă) — msafara wa Bogdan", "45a66791"], "d": ["Fatih Sultan Mehmed, aliyeenda binafsi vitani kulipiza kisasi cha kushindwa kwa Racova mwaka mmoja kabla, kwa jeshi la Ottoman aliwashinda vibaya vikosi vya Bogdan mahali panapoitwa Akdere na akaingia Suceava, kitovu cha beylik. Hata hivyo ngome hazikuweza kutekwa; kwa sababu ya uhaba wa chakula, tauni iliyoibuka kati ya yeniçeri na maandalizi ya Wahungaria, jeshi lililazimika kurudi nyuma. Utii wa uhakika wa Bogdan ungepatikana tu katika miaka iliyofuata na kwa kutekwa kwa Kili na Akkirman mwaka 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Ushindi wa Akçahisar (Kruja) na kukamilika kwa Albania", "559a79b4"], "d": ["Miaka kumi baada ya kifo cha İskender Bey, kwa kutekwa kwa Akçahisar, Drivasto, Leş na Jabyak mwaka 1478, ushindi wa Albania ulikamilika kwa kiasi kikubwa. Kuanguka kwa Ngome ya Kruja, iliyopinga majeshi ya Ottoman kwa miaka na iliyokuwa ishara ya upinzani wa İskender Bey, kulimaanisha mwisho wa muungano wa Venice-Albania katika eneo hilo. İşkodra iliyobaki ingeachiwa Ottoman kwa Mkataba wa Istanbul utakaotiwa saini mwaka uliofuata.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Kujiunga kwa peninsula ya Taman", "4ef917b8"], "d": ["Baada ya kutekwa kwa Kefe na Kerç mwaka 1475, jeshi la majini lililotumwa na Fâtih Sultan Mehmed kwenye pwani za Caucasus, pamoja na Anapa na Kopa, liliteka Matrega ya Genoa (Tamatarhan) kwenye peninsula ya Taman. Hivyo pande zote mbili za mlango-bahari zilichukuliwa chini ya udhibiti na kuingia kwenye Bahari ya Azak kulifanywa kudhibitiwa kikamilifu. Taman, kama mlango wa Caucasus ya Kaskazini, iliunganishwa na sancak ya Kefe.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Kuingia kwa Sisam chini ya utawala wa Ottoman (Fatih)", "c877bc14"], "d": ["Fatih Sultan Mehmed aliiteka Sisam, akajenga ngome na akapanga upya sensa; ngome ilibomolewa na II. Bayezid mwaka 1483 kwa sababu za kisiasa.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Kushindwa kwa kuzingirwa kwa Rhodes", "35a85c28"], "d": ["Jeshi la majini la meli 160 chini ya amri ya Mesih Paşa kwa amri ya Fatih Sultan Mehmed lilizingira Rhodes katika majira ya kuchipua ya 885 (1480) na kisiwa kilibaki kwenye mzingiro kwa miezi mitatu. Mashujaa wa Saint-Jean wakiongozwa na bwana mkuu Pierre d'Aubusson walipinga kwa ukali licha ya hasara kubwa; shambulio kubwa la mwisho la tarehe 20 Cemâziyelevvel 885 liliporudishwa nyuma, jeshi la majini lilijiondoa tarehe 3 Agosti. Baada ya kushindwa huku kuta za mji zilifanywa upya kabisa na kuwa ngome yenye nguvu zaidi Ulaya, na kisiwa kingeweza kutekwa tu mwaka 1522 na Kanûnî.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Nikarya (İkarya) yaingia chini ya utawala wa Mashujaa wa Saint Jean wa Rhodes", "5cbc2669"], "d": ["Nikarya kati ya Sisam na Sakız ilikuwa chini ya utawala wa Mashujaa wa Saint Jean wa Rhodes kuanzia 1481 hadi 1521.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Vita vya Yenişehir — kushindwa kwa Cem Sultan", "c35abee2"], "d": ["Ndugu wawili waliotenda kwa kiti cha enzi baada ya kifo cha Fatih walikutana uso kwa uso katika uwanda wa Yenişehir na Cem Sultan alishindwa kabisa. Şehzade, aliyetawala Bursa kwa siku kumi na nane na kusomesha khutba kwa jina lake, baada ya kushindwa alilazimika kukimbilia kwanza Konya, kisha ardhi za Mamluki. Yenişehir ilianzisha mgogoro mrefu zaidi wa nasaba katika historia ya Ottoman: suala la Cem lingepooza sera ya nje ya Ottoman mbele ya Ulaya kwa miaka kumi na minne.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Kuunganishwa kwa Herzegovina", "bf247891"], "d": ["Ardhi za Dukedom ya Herzegovina iliyobaki baada ya ushindi wa Bosnia mwaka 1463 zilipita hatua kwa hatua chini ya utawala wa Ottoman: Trebinye na Mostar zilichukuliwa mwaka 1466, sancak ya Herzegovina iliundwa mwaka 1470, na ardhi za mwisho za dukedom kwenye pwani ya Adriatic, pamoja na Herseknovi (Herceg Novi), zilitekwa mwanzoni mwa 1482 na kuongezwa kwenye sancak. Hivyo eneo la milima nyuma ya Adriatic likawa la Ottoman kabisa na Bosnia na Herzegovina zikawa jiografia moja ya kiutawala. Mwana wa duke wa mwisho aliyeingia ikulu ya Ottoman ni Hersekzâde Ahmed Paşa, ambaye baadaye angepanda hadi sadrazam.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Kuachiwa kwa Zaklise (Zakynthos) kwa Venice kwa kodi ya kila mwaka", "268a691a"], "d": ["Zaklise, mojawapo ya visiwa vya İyon vilivyochukuliwa kutoka kwa familia ya Tocco mwishoni mwa enzi ya Fatih, iliachiwa Venice na sultani mpya aliyekuwa akishughulika na suala la Cem Sultan, katika kutafuta utulivu Magharibi. Kisiwa kilikabidhiwa kwa utawala wa Venice unaotambua mamlaka ya Ottoman na kulipa kodi ya kila mwaka ya dukati mia tano. Hivyo utawala wa moja kwa moja wa Ottoman katika Bahari ya İyon ulibaki Ayamavra pekee.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Cem Sultan akimbilia Rhodes", "2228d6da"], "d": ["Cem Sultan, ambaye jaribio la kuizingira Konya pia halikuzaa matunda, alikimbia Anatolia na watu wake kama thelathini na kufika Rhodes, na akapokelewa kwa sherehe na mashujaa wa Saint-Jean. Hata hivyo ukarimu uligeuka haraka kuwa utumwa; şehzade alikabidhiwa kwanza kwa Ufaransa, kisha kwa Upapa, na akawa kadi mikononi mwa siasa za Ulaya. II. Bayezid alilazimika kulipa malipo ya kila mwaka kwa kuzuiliwa kwa ndugu yake na hatua za kijeshi za Ottoman kuelekea Magharibi zilisimamishwa hadi kifo cha Cem.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Kuanza kwa Vita vya Ottoman-Mamluki (mbele ya Çukurova)", "3fe3f0c7"], "d": ["Mapambano ya ushawishi juu ya Dulkadıroğulları na uadui ulioachwa na Cem Sultan kukimbilia ardhi za Mamluki vilianzisha mwaka 1485 vita vya miaka sita kati ya nguvu mbili kubwa za Kisuni. Katika mapigano yaliyotokea karibu na Adana na Tarsus katika Çukurova, pande hazikuweza kupata ubora juu ya nyingine; majeshi ya Ottoman yalipokea mapigo kadhaa mazito. Vita hivi ni awamu ya kwanza ya mgawanyiko katika uhusiano wa Ottoman-Mamluki na ufunguzi wa mchakato ambao ungehitimishwa miaka thelathini baadaye na misafara ya Yavuz ya Mercidâbık na Ridâniye.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Amani ya Ottoman-Mamluki — upatanishi wa Tunisia", "60dd6719"], "d": ["Katika vita vya Ottoman-Mamluki vilivyoanza mwaka 1485, pande hazikuweza kupata ushindi wa uhakika; kwa upatanishi wa Mtawala wa Tunisia Osman Hafsî, makubaliano yalifikiwa mwaka 1491. Mkataba ulirudisha mipaka kwa kiasi kikubwa hali ya kabla ya vita na mahesabu kati ya dola mbili za Kiislamu yaliahirishwa kwa kizazi kimoja. Mapambano ya kuchosha ya miaka sita ni mojawapo ya sababu kuu za sera ya nje ya tahadhari ya II. Bayezid na ya yeye kuweka uzito kwenye mipangilio ya ndani badala ya kuelekea mashariki.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Kupokelewa kwa Wayahudi wa Sefarad waliofukuzwa kutoka Uhispania na Ottoman", "5c2b5c24"], "d": ["Baada ya kuanguka kwa Granada, sehemu ya Wayahudi waliokimbia dhulma ya uchunguzi wa kidini huko Uhispania walikimbilia ardhi za Ottoman na wakapewa makazi katika miji mbalimbali. Chini ya utawala wa Ottoman jumuiya hizi za Sefarad zilipata uhuru ambao hawakuwahi kuuona hadi wakati huo, kama kukaa wanapotaka, kuishi imani zao, kufungua taasisi za elimu na kujenga masinagogi mapya. Uhamiaji huu, uliobadilisha maisha ya kiuchumi ya Selanik na Istanbul kwa elimu ya uchapishaji, tiba na fedha waliyoleta, ukawa mfano unaozungumzwa zaidi Ulaya wa mfumo wa uvumilivu wa Ottoman.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Kifo cha Cem Sultan — mwisho wa mateka wa miaka kumi na minne", "f6588b70"], "d": ["Cem Sultan, aliyekabidhiwa kutoka Upapa kwa Mfalme wa Ufaransa VIII. Charles, alikufa mahali panapoitwa Castel Capuana baada ya kuondoka Roma tarehe 27 Januari 1495; vyanzo vinaandika kwamba huenda alitiwa sumu na duru za upapa. Kifo cha şehzade, aliyeshikiliwa kwa miaka kumi na minne mikononi mwa dola za Ulaya kama kadi ya tishio dhidi ya Ottoman, hatimaye kilimwachia II. Bayezid mikono huru. Kwa hakika sultani baada ya hapo angetangaza vita dhidi ya Venice na kupeleka jeshi lake la majini kwenye ushindi wake mkubwa wa kwanza.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Ushindi wa Majini wa Sapienza (Zonchio) — mafanikio ya kwanza makubwa ya jeshi la majini Mediterania", "9754aaef"], "d": ["II. Bayezid, aliyejikuta mikono huru kwa kuisha kwa suala la Cem, alitangaza vita dhidi ya Venice mwaka 1499; jeshi la majini la Ottoman, kwa kulishinda jeshi la Venice nje ya Sapienza (Zonchio), lilipata ushindi wake mkubwa wa kwanza wa baharini Mediterania. Kwa ushindi huu jeshi la majini lilitangaza kwamba sasa linaweza kuikabili Venice baharini.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Kupotea kwa Kefalonya na İthaki", "60f0f687"], "d": ["Venice, iliyotikiswa na kuchukuliwa kwa Modon na Koron, iliungana na Uhispania na kuanzisha shambulio la kukabiliana na kuizingira Kefalonya iliyokuwa mikononi mwa Ottoman tangu 1479. Baada ya upinzani wa siku arobaini na saba ngome ilianguka, kisiwa kilipita kwa Venice pamoja na İthaki na hakikurudi chini ya utawala wa Ottoman kwa miaka mia tatu. Kupotea huku kuliunda mizani ambapo kilichopatikana Mora kilirudishwa İyon.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Kuanguka kwa Ukhanana wa Golden Horde na kupanda kwa Crimea", "0d1dc515"], "d": ["Mtawala wake wa mwisho Şeyh Ahmed Han (1481-1502) hakuweza kukiokoa kiti chake kutoka kwenye mgogoro alioingia, na Ukhanana wa Golden Horde ulitoweka katika historia mwaka 1502 kwa mapinduzi ya Khan wa Crimea Mengli Giray. Kwa matokeo ya mapigano ya kiti cha enzi na kuvunjika, ukhanana wa Crimea, Kazan, Nogay, Astrakhan na Sibir ulijitokeza katika ardhi za zamani za Golden Horde. Ushindi huu wa Crimea iliyokuwa chini ya ulinzi wa Ottoman, huku ukifanya ushawishi wa Ottoman kaskazini mwa Bahari Nyeusi usiopingika, pengo lililotokea katika eneo hilo lingejazwa na Moscow katika karne iliyofuata.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Kuisha kwa Vita vya Ottoman-Venice na amani", "125b1526"], "d": ["Vita vilivyoanza mwaka 1499 na kuitikisa Venice kwa kupotea kwa Sapienza, İnebahtı, Modon na Koron vilimalizika kwa amani mwaka 1502. Venice, kwa kupoteza vituo vyake muhimu zaidi Mora, ililazimika kutambua ukuu wa Ottoman kwa malipo ya kuhifadhi marupurupu yake ya kibiashara katika Mediterania ya Mashariki. Utawala wa II. Bayezid uliohesabiwa wa tahadhari, kwa vita hivi, ulikuwa umeinua Ottoman kwa mara ya kwanza hadi hadhi ya nguvu kubwa ya majini Mediterania.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Uasi wa Şahkulu — uasi wa Kızılbaş kutoka eneo la Teke hadi Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, aliyeonyesha uasi wake wazi mwaka 1510 kwa athari ya propaganda ya Safavi Anatolia, alivamia soko la Antalya Machi 1511 na Aprili alikuwa amewashinda vikosi vya Ottoman katika Kütahya na mazingira yake. Katika mapigano ya mwisho aliyoyafanya karibu na Sivas na sadrazam Hadım Ali Paşa, pande zote mbili zilipata hasara kubwa; sadrazam na kiongozi wa uasi wote walikufa. Uasi huu, uliotikisa mamlaka ya dola Anatolia, ulionyesha pengo la madaraka katika miaka ya mwisho ya II. Bayezid na ukawa sababu yenye nguvu zaidi ya kuandamana kwa Şehzade Selim kwenye kiti cha enzi.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Kujiondoa kwa II. Bayezid kwenye kiti cha enzi na kupanda kwa Yavuz Sultan Selim", "c4cfab69"], "d": ["Kwa shinikizo la Şehzade Selim, aliyepata msaada wa yeniçeri katika mapambano ya kiti cha enzi na ndugu zake, II. Bayezid alijiondoa kwenye kiti cha enzi tarehe 24 Aprili 1512 na I. Selim alipanda kiti siku hiyo hiyo kama mtawala wa tisa wa Ottoman. Sultani mzee, akielekea Dimetoka alikozaliwa, alifariki njiani katika kijiji cha Abalar karibu na Çorlu tarehe 25 Rebîülevvel 918 (10 Juni 1512). Mahali pa utawala wa tahadhari na wa kujielekeza ndani wa miaka thelathini na mmoja palichukuliwa na enzi ya Yavuz itakayoongeza mipaka ya himaya mara mbili katika miaka minane.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Kutekwa kwa Ngome ya Sin (Sinj)", "83271ea5"], "d": ["Vikosi vya wavamizi vya Ottoman vilivyo kwenye mpaka wa Bosnia vilichukua kutoka Ufalme wa Hungaria Ngome ya Sin (Sinj) inayoenea ndani ya Dalmatia. Hii ilikuwa kiungo cha mapema cha mstari wa mpaka wa Dalmatia ambao ungepanuliwa miaka tisa baadaye kwa ushindi wa Gazi Hüsrev Bey wa Knin na viunga vyake; ngome ingepotezwa kwa Venice mwaka 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Vita vya Yenişehir na kuondolewa kwa Şehzade Ahmed", "e2ed15dd"], "d": ["Yavuz Sultan Selim alimshinda kaka yake Şehzade Ahmed, mpinzani mwenye nguvu zaidi wa kiti cha enzi, kwenye tambarare ya Yenişehir karibu na Bursa, akamkamata na kumwondoa. Hivyo mzozo wa ndugu uliodumu tangu 1511 ulifungwa, mgawanyiko wa ndani Anatolia ulimalizika. Selim, akiwa ameimarisha nyuma yake, alipata uhuru wa kuelekea suala la Wasafavî.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Kuingia kwa Yavuz Sultan Selim Tebriz", "dad2e227"], "d": ["Baada ya ushindi wa Çaldıran, jeshi la Ottoman liliingia Tebriz, mji mkuu wa Wasafavî, na khutba ilisomwa mjini kwa jina la sultani. Selim alikaa huko wiki moja na kuhamisha İstanbul sehemu ya mafundi na maulamaa wa Tebriz; uhamisho huu ungeathiri sana sanaa ya ikulu ya Ottoman. Ingawa mji uliachwa kwa sababu ya kukaribia kwa majira ya baridi na kutoridhika kwa Yeniçeri, ubora wa Wasafavî Mashariki ulikuwa umevunjika. Kwenye ramani maeneo yaliyopita kwa Ottoman siku hii hayakaribiani, na hilo ni sahihi: Tebriz ni uvamizi wa jeshi wa siku tisa; tambarare ya Erzincan ilisalimu amri bila vita wakati wa kampeni, lakini ngome ya Kemah iliyo katikati yake ilipinga ikiwa ya Wasafavî hadi 19 Mei 1515; Siirt ilirudishwa kutoka kwa Wasafavî na Halil Bey, melik wa Hasankeyf aliyeokolewa kutoka kifungo cha Şah İsmail Tebriz na kutii Ottoman — Diyarbakır iliyo karibu nayo ilibaki ya Wasafavî hadi 1515, na Hasankeyf hadi 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş na Bingöl (Çapakçur) zapita kutoka Wasafavi hadi utawala wa Ottoman", "b0a53b5a"], "d": ["Kwa kuchukuliwa kwa Anatolia ya Mashariki kutoka kwa Wasafavi baada ya Çaldıran, Muş iliingia chini ya utawala wa Ottoman mwaka 921/1515; Çapakçur (Bingöl) jirani ilijiunga na Ottoman katika mchakato huo huo.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Ushindi wa Ngome ya Kemah kutoka kwa Wasafavi", "73fd8671"], "d": ["Yavuz Sultan Selim, aliyekaa majira ya baridi Amasya akirudi kutoka Çaldıran, alimwagiza Bıyıklı Mehmed Paşa kuteka Ngome ya Kemah yenye ngome imara iliyoshikilia kivuko cha Frati. Mwishoni mwa kuzingirwa ambako sultani alishiriki binafsi, ngome ilichukuliwa kutoka mikononi mwa Wasafavi na mlango wa Anatolia ya Mashariki ukafunguliwa. Ushindi huu ni hatua ya kwanza dhahiri ya kugeuza ushindi wa Çaldıran kuwa faida ya kudumu ya ardhi.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Ushindi wa Turnadağ — Beylik ya Dulkadir ikawa tegemezi kwa Ottoman", "fd879145"], "d": ["Vikosi vya Ottoman vilimshinda Bey wa Dulkadir Alâüddevle Bozkurt, aliyeshika msimamo wa kusitasita wakati wa kampeni ya Çaldıran, kwenye eneo la Ördekli kati ya Göksun na Andırın; Alâüddevle aliuawa katika vita hivi. Beylik haikuunganishwa tarehe hii: baada ya Alâüddevle, Şehsuvaroğlu Ali Bey aliwekwa na Yavuz Sultan Selim kichwani mwa Beylik ya Dulkadıroğulları, na nchi yenye kitovu cha Maraş-Elbistan iliendelea kama beylik tegemezi kwa Ottoman. Kizuizi kilichoko mpakani mwa Wamamluki hivyo kiliingia chini ya udhibiti wa Ottoman na njia ya kampeni ya Misri ya miaka miwili baadaye ilifunguka; kuunganishwa kungetokea baada ya kuuawa kwa Ali Bey.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Ushindi wa Âmid (Diyarbekir) na kuanzishwa kwa beylerbeylik ya Diyarbekir", "a6867d5b"], "d": ["Baada ya İdrîs-i Bitlisî kuwavutia beyi wa Kikurdi wa Kisuni wa eneo hilo upande wa Ottoman, vikosi vya Safavi havikuweza kustahimili kuzingirwa kwa muda mrefu na funguo za Âmid zilikabidhiwa kwa Bıyıklı Mehmed Paşa. Mji ulifanywa kitovu cha beylerbeylik ya Diyarbekir iliyoanzishwa mpya. Hivyo kiini cha kiutawala cha Mesopotamia ya Juu kilipita mikononi mwa Ottoman.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Ushindi wa Harput — kufunguliwa kwa njia ya Diyarbekir", "564eb269"], "d": ["Beylerbeyi wa Karaman Hüsrev Paşa, aliyeanza safari kuikomboa Diyarbekir iliyochukuliwa baada ya Çaldıran kutoka kuzingirwa kwa Safavi, alichukua Ngome ya Harput, ambayo mazingira yake Çerkez Hüseyin Bey alikuwa ameyateka kabla, mwishoni mwa kuzingirwa kwa siku tatu. Njia ya kuelekea Diyarbekir mashariki mwa Frati hivyo ilihakikishwa.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Vita vya Koçhisar (Kızıltepe) — kushindwa kwa Kara Han", "9ea9e843"], "d": ["Jeshi la Ottoman chini ya amri ya Bıyıklı Mehmed Paşa lilimshinda gavana wa Safavi Kara Han katika vita vya uwanjani vilivyodumu siku nzima mahali panapoitwa Koruk kwenye uwanda wa Dede Garkın karibu na Koçhisar; kichwa kilichokatwa cha Kara Han kilitumwa kambini mwa sultani. Kisha ingawa vikosi vya Ottoman viliingia mji wa Mardin, vilikaa siku chache na kuondoka; Ngome ya Mardin iliyoshikiliwa na walinzi wa Safavi ingeweza kuchukuliwa mwaka mmoja baadaye tu. Ushindi huu ulihakikisha mpaka wa kusini wa Yavuz na kumwezesha kuelekea msafara wa Misri. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Kuondoka kwa Yavuz Sultan Selim kutoka Istanbul kwa msafara wa Misri", "ac258b4b"], "d": ["Yavuz Sultan Selim aliondoka Istanbul kwa kujionyesha kujiandaa kwa msafara mpya wa mashariki dhidi ya Wasafavi na akaelekea kusini kupitia Akşehir. Sultani wa Mamluki Kansu Gavri kuwasiliana na Şah İsmâil na kutishia ubawa wa mashariki wa Ottoman kungesababisha kubadilika kwa lengo hivi karibuni. Msafara ni mwanzo wa operesheni kubwa itakayodumu miaka miwili na itakayoigeuza Ottoman kuwa himaya ya Mashariki ya Kati.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Kutekwa kwa Zebîd: kuingia kwa kwanza kwa mabaharia wa Ottoman Bahari Nyekundu", "38740e0c"], "d": ["Mbele ya shinikizo la Ureno katika Bahari ya Hindi, mabaharia wenye asili ya Ottoman Hüseyin Bey na Selman Reis, waliotumwa Bahari Nyekundu kwa ombi la Sultani wa Mamluki Kansu Gavri, waliteka Zebîd kwa jeshi lao la majini. Operesheni hii, iliyoendeshwa bado katika huduma ya Mamluki, ni uwepo wa kwanza wa kweli wa jeshi la majini la Ottoman kwenye mstari wa Bahari Nyekundu-Hindi. Mwaka mmoja baadaye Misri ilipopita kwa Ottoman, jeshi hilo hilo lingeunganishwa moja kwa moja na Istanbul.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Kutangazwa rasmi kwa lengo la msafara kuwa Mamluki na Aleppo", "689e310d"], "d": ["Yavuz Sultan Selim, Kansu Gavri alipokubaliana na Wasafavi na kuendesha jeshi lake kuelekea Aleppo, alitangaza wazi lengo la msafara kuwa sultani wa Mamluki na Aleppo. Hivyo ushindani uliofichika wa miaka mingi kati ya dola mbili za Kisuni uligeuka vita vya wazi. Tangazo hili lilianzisha hesabu ya nyuma ya wiki nne kuelekea Mercidâbık.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Kushindwa kwa kuzingirwa kwa Aden: jaribio la kwanza la Bahari Nyekundu dhidi ya Ureno", "8ffd46f2"], "d": ["Selman Reis na Hüseyin Bey walifanya kuzingirwa kwa siku nane ili kuteka Aden, mlango wa Bahari Nyekundu kuelekea Bahari ya Hindi, lakini walilazimika kujiondoa mbele ya ngome imara za mji. Kutoweza kuteka Aden kungechelewesha mkakati wa kusini dhidi ya Ureno kwa miaka mingi. Jaribio hili ni mtihani wa kwanza wa Ottoman katika siasa za bahari.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Beylik ya Ramazanoğulları yaunganishwa na Ottoman", "cfaa3754"], "d": ["Wakati wa uteuzi uliofanywa baada ya ushindi wa Mercidâbık, Beylik ya Ramazanoğulları yenye kitovu Adana ilipewa Mahmud Bey na kuchukuliwa chini ya utawala wa Ottoman. Beylik iliyotoka kwenye utegemezi wa Mamluki iliachwa kwa familia kwa hadhi ya 'ocaklık' badala ya kuondolewa; Ramazanoğulları waliendelea kusimamia Çukurova kama beyi wa sancak wa Ottoman. Mpangilio huu wa upendeleo ulidumu hadi mwaka 1608 ambapo Pîr Mansûr aliiacha beylik. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Malatya, Tarsus, Musul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Rakka na Deyrizor zaingia chini ya utawala wa Ottoman", "2088eb6a"], "d": ["Siku nne baada ya Mercidâbık, Yavuz Sultan Selim aliingia Aleppo bila kukutana na upinzani na khutba ilisomwa kwa jina lake katika misikiti ya mji. Kuanguka kwa haraka hivyo kwa Aleppo, iliyohesabiwa mji mkuu wa kibiashara na kiutawala wa Syria, kunaonyesha kwamba mamlaka ya Mamluki katika eneo yalikuwa yameporomoka. Kutekwa kwa mji kulifungua mara moja njia ya Dameski na kutoka huko hadi Misri. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Antakya, Rakka, Deyrizor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Mazungumzo huko Aleppo Gökmeydan na Khalifa wa Kiabbasi III. Mütevekkil", "22979f42"], "d": ["Khalifa wa Kiabbasi wa Cairo III. Mütevekkil, aliyetekwa pamoja na jeshi la Mamluki huko Mercidâbık, alipelekwa mbele ya sultani Gökmeydan huko Aleppo na Yavuz Sultan Selim alimwonyesha heshima kubwa. Ukhalifa wa Cairo, nafasi ya ishara chini ya kivuli cha masultani wa Mamluki tangu 1261, kwa mazungumzo haya ulipita kwa vitendo chini ya ulinzi wa Ottoman. Khalifa baadaye angepelekwa Istanbul pamoja na sultani.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Trablusşam na Hama zaingia chini ya utawala wa Ottoman", "a1e19a79"], "d": ["Baada ya Aleppo na Hama, Trablusşam kwenye pwani ya Syria nayo ilipita kwa utawala wa Ottoman bila kupinga. Mji huo, mojawapo ya bandari zenye shughuli nyingi zaidi za Mediterania ya Mashariki, ulikuwa mlango wa Dameski kuelekea baharini na kituo cha biashara ya hariri na sukari. Kwa kutekwa kwake ukanda wa pwani wa Bilâdüşşam ulibadilisha mikono kabisa.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Dameski (Dımaşk) yaingia chini ya utawala wa Ottoman", "2b844d91"], "d": ["Yavuz Sultan Selim, ambaye njia yake ilifunguka kwa kujisalimisha kwa Hama na Humus baada ya Aleppo, alifika mbele ya Dameski tarehe 27 Septemba; hakuingia mjini mara moja bali alisimika hema lake nje mahali panapoitwa Mastaba na akaingia ndani kwa sherehe kubwa siku ya kumi na mbili ya kuwasili kwake. Akikaa Dameski kwa muda mrefu, alianzisha mpangilio wa kiutawala wa Syria na akajenga kaburi la Muhyiddin İbnü'l-Arabî. Hivyo Bilâdüşşam yote ilitoka chini ya utawala wa Mamluki. Maeneo mengine yaliyoongezwa tarehe hiyo hiyo: Beirut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tomanbay atangazwa sultani wa Mamluki huko Cairo", "6020d90d"], "d": ["Baada ya Kansu Gavri aliyekufa Mercidâbık, emiri wa Mamluki walimpandisha kiti cha enzi Tomanbay, atakayekuwa sultani wa mwisho wa dola. Sultani mpya mwenye asili ya Kicherkesi alirithi dola iliyopoteza Syria, yenye hazina iliyoisha na isiyo na silaha za moto. Hata hivyo angeunda mstari wa ulinzi mbele ya Cairo na kuandaa upinzani wa mwisho dhidi ya kusonga mbele kwa Ottoman.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Vita vya Gaza (Han Yûnus): kushindwa kwa Canbirdi Gazâlî", "9f1eb8cb"], "d": ["Yavuz Sultan Selim alimtuma Sadrazam Hadım Sinan Paşa Gaza kwa kikosi cha mbele cha watu elfu nne. Canbirdi Gazâlî, aliyeteuliwa na Tomanbay kuwa naibu wa Dameski, ingawa alijaribu kusimamisha kikosi cha mbele cha Ottoman kwenye mstari wa Gaza-Han Yûnus, alishindwa vibaya na akakimbilia Misri. Kwa kutawanyika kwa kikosi cha mwisho cha bafa cha Mamluki huko Palestina, njia ya jangwa la Sinai ilifunguka kabisa.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Mashariki ya Yordani: Amman yaingia chini ya utawala wa Ottoman", "9db62667"], "d": ["Vikosi vya Ottoman vilivyokuwa vikijiandaa kwa msafara wa Misri baada ya vita vya Gaza vilipokuwa vikishuka kusini, Amman mashariki mwa Yordani nayo iliingia chini ya utawala wa Ottoman. Miji ya pwani na ya ndani ya Palestina (Yafa, Nablus, Sayda, Akkâ, Yerusalemu) ilikuwa tayari imebadilisha mikono katika vuli ya 1516 baada ya Mercidâbık. Miji hii ilisimamiwa kwa karne nne kama sancak za eyalet ya Dameski.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Kuwasili kwa Yavuz Sultan Selim Yerusalemu", "66d7bfad"], "d": ["Yerusalemu, iliyopita chini ya utawala wa Ottoman bila kupinga baada ya Mercidâbık, ilitembelewa na Yavuz Sultan Selim pamoja na wakuu wa dola na jeshi baada ya vita vya Gaza. Sultani alitembelea Kubbetü's-sahre na Msikiti wa Aksâ na akathibitisha hadhi takatifu ya mji. Yerusalemu, kuanzia tarehe hii hadi Desemba 1917, ingebaki chini ya utawala wa Ottoman kwa karne nne kamili.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Kuingia kwa Yavuz Sultan Selim Gaza na kuelekea jangwa la Sinai", "2106bfc7"], "d": ["Baada ya kushindwa kwa Canbirdi Gazâlî huko Hanyûnus (21 Desemba 1516), Gaza ilikuwa mikononi mwa kikosi cha mbele. Sultani aliingia Gaza tarehe 2 Januari 1517 na akakutana hapa na Sinan Paşa aliyekuwa mkuu wa kikosi cha mbele, na jeshi likafanya maandalizi ya mwisho ya kuvuka kuingia Misri. Katika jangwa lisilo na maji la Katya (Sinai) kutoka Gaza hadi Sâlihiye, vituo nane vingetembewa na maji yangebebwa kwa ngamia. Kuvuka huku ni awamu hatari zaidi na ngumu zaidi kiusafirishaji ya msafara.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Kutekwa kwa Suez — mlango wa Bahari Nyekundu", "05f3324e"], "d": ["Kwa jeshi la Ottoman kuingia Cairo baada ya ushindi wa Ridâniye, Suez kwenye ncha ya kaskazini ya Bahari Nyekundu nayo ilipita kwa utawala wa Ottoman. Bandari hii ya viwanja vya meli, ambapo Mamluki walituma jeshi la majini kwenda Bahari ya Hindi, ilikuwa kituo cha sera ya kusini dhidi ya Ureno. Suez ni mdomo wa kaskazini wa mstari ambao mfereji ungefunguliwa karne tatu baadaye.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Kuingia kwa kwanza kwa vikosi vya Ottoman Cairo", "0a3f4f4d"], "d": ["Siku iliyofuata ushindi wa Ridâniye, majeshi ya Ottoman yaliruhusiwa kuingia Cairo na tarehe 24 Januari vikosi vilikaa mjini. Hata hivyo kuingia huku hakumaanisha udhibiti kamili wa mji; Tomanbay alikuwa amejiondoa Misri ya Juu, upinzani wa Mamluki ulikuwa bado haujavunjika. Ushindi wa Cairo ungekamilika si kwa siku moja bali katika mchakato wa umwagaji damu uliodumu wiki.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Shambulio la Tomanbay Cairo na mapigano ya mitaani ya siku tatu", "b83b6ce6"], "d": ["Tomanbay, aliyejiondoa Misri ya Juu, usiku wa 27-28 Januari aliingia Cairo ghafla na watu wake takriban elfu saba na akaanzisha upinzani ndani ya mji, akiwaacha vikosi vya Ottoman katika hali ngumu sana. Katika mapigano makali ya mitaani yaliyodumu siku tatu, Mamluki walishikilia sehemu kubwa ya mji kwa muda. Upinzani ulivunjwa tu kwa kuingia kwa wapiga mizinga wa Ottoman na vikosi vya nyongeza.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Canbirdi Gazâlî aingia katika huduma ya Ottoman", "a94ea459"], "d": ["Canbirdi Gazâlî, emiri wa zamani wa Mamluki aliyejiondoa Sâlihiye baada ya Ridâniye, alimwomba sultani msamaha. Yavuz Sultan Selim, akifikiri atakuwa na manufaa katika kuweka utulivu Misri na Syria, alimkubali katika huduma yake. Chaguo hili ni mfano wa kwanza mkubwa wa sera ya Ottoman ya kujumuisha makada wa Mamluki katika mfumo badala ya kuwafuta.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Kuingia kwa Yavuz Sultan Selim Cairo kwa sherehe na kusomwa kwa khutba", "6d98080c"], "d": ["Baada ya mapigano ya mitaani kukandamizwa, sultani aliingia Cairo tarehe 15 Februari 1517 kwa sherehe ya kupendeza sana na khutba ilisomwa kwa jina lake katika misikiti. Kusomwa kwa khutba Cairo kwa jina la sultani wa Ottoman ni tangazo la kuisha kisheria kwa utawala wa Mamluki uliodumu tangu 1250. Tarehe hii huhesabiwa kuwa wakati wa ishara wa kukamilika kwa ushindi wa kweli wa Misri.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Kukamatwa kwa sultani wa mwisho wa Mamluki Tomanbay huko Terrûce", "7058e6ad"], "d": ["Tomanbay, aliyejificha katika delta ya Nile baada ya kuuacha Cairo, aliripotiwa na wabedui waliompa makazi na akakamatwa katika eneo la Terrûce. Kukamatwa kwake kuliondoa kitovu kilichopangwa cha upinzani wa Mamluki. Sultani wa mwisho angeshikiliwa mikononi mwa Ottoman kwa siku kumi na nne zaidi.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Kunyongwa kwa Tomanbay Bâbüzüveyle na mwisho wa Dola ya Mamluki", "ad9820be"], "d": ["Siku kumi na nne baada ya kukamatwa kwake, Tomanbay alinyongwa kwenye lango maarufu la Cairo Bâbüzüveyle; mwili wake baadaye ulizikwa katika madrasa iliyojengwa na mjomba wake. Hivyo Dola ya Mamluki iliyotawala Misri na Syria tangu 1250 ilitoweka rasmi katika historia. Kwa kuvunjwa kwa upinzani, miji kama Asyut na Aswan katika Misri ya Juu (Said) pia iliunganishwa na utawala wa Ottoman.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Shambulio la jeshi la majini la Ureno Cidde na ulinzi wa Selman Reis", "52322cf5"], "d": ["Jeshi la majini la Ureno la takriban galley na kalyon thelathini lilishambulia Cidde; Selman Reis, kwa kuongoza ulinzi wa mji, alizuia adui kutua nchi kavu na akazamisha meli kadhaa za Ureno. Ulinzi huu ulizuia bandari ya Makka, na hivyo njia ya hija, kuangukia mikononi mwa dola ya Kikristo. Cidde ingejumuishwa rasmi chini ya utawala wa Ottoman miezi michache baadaye kwa bîat ya Hijaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["İskenderiye ilichukuliwa na jeshi la majini — kukamilika kwa ushindi wa Misri", "386878fe"], "d": ["Miezi minne kamili baada ya Ridâniye, siku thelathini na sita baada ya kuuawa kwa Tomanbay, kwa meli za Ottoman chini ya Câfer Bey kufika bandarini, İskenderiye ilipita chini ya utawala wa Ottoman; bandari za delta kama Reşîd na Dimyat nazo ziliunganishwa katika mchakato huo huo. Kwamba bandari hii kubwa ya Misri inayofunguka kwa Mediterania ilichukuliwa miezi kadhaa baada ya kuanguka kwa Kahire, na kwa bahari si kwa nchi kavu, inaonyesha wazi kwamba ushindi ulikamilika eneo kwa eneo si kwa vita moja. İskenderiye tangu hapo ingekuwa bandari muhimu inayounganisha İstanbul na Kahire. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Kuunganishwa kwa Hicaz bila vita: bîat ya Ebû Nümeyy, mwana wa Şerif wa Mekke", "c13b98c7"], "d": ["Yavuz Sultan Selim alikuwa amefikiria kwanza kupeleka askari kuchukua Mekke na viunga vyake, lakini aliachana na hilo Emîr wa Mekke Şerîf Berekât alipotangaza utii wake. Ebû Nümeyy, mwana wa Berekât mwenye umri wa miaka kumi na miwili, alikuja Kahire na zawadi za baba yake na funguo za Mekke, na akapokelewa mbele ya sultani. Hivyo Hicaz iliunganishwa na Ottoman si kama matokeo ya moja kwa moja ya Ridâniye, bali miezi mitano na nusu baadaye na bila risasi hata moja, kwa amani na kwa bîat. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Tâif.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Kukubaliwa kwa cheo cha Hâdimü'l-Haremeyn na khutba Medine", "63b32b59"], "d": ["Baada ya mapokezi ya pili ya ujumbe wa Mekke, Yavuz Sultan Selim alichukua rasmi ulinzi wa Haremeyn na kuanza kutumia cheo cha 'hâdimü'l-Haremeyni'ş-şerîfeyn'. Şerîf Berekât alivaa hil'at aliyotumiwa na kusomesha khutba kwa jina la sultani; ujumbe wa Medine ulipokwenda İstanbul pia, emîrlik ya Berekât ilithibitishwa kwa berat. Sultani alituma kwa watu wa Haremeyn dhahabu elfu mia mbili na akiba nyingi ya chakula, na akaanza mila ya surre itakayorudiwa kila mwaka. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Yenbu, Tebük.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis kuingia katika huduma ya Ottoman na kuhamishwa kwa sera ya Bahari Nyekundu", "771da99a"], "d": ["Selman Reis, aliyekuwa akiilinda Cidde dhidi ya Wareno, alikuja Kahire na kuonekana mbele ya Yavuz Sultan Selim; ingawa alizuiliwa kwa muda, aliitwa İstanbul mwaka 1519 na akaahidi kuandaa kadırga thelathini na kalyata chache dhidi ya tishio la Ureno. Mkutano huu ni mwanzo wa kuchukuliwa kwa sera ya Bahari Nyekundu na Bahari ya Hindi kutoka urithi wa Wamamluki na kuunganishwa moja kwa moja na İstanbul. Ottoman sasa, kando na kuwa dola ya Mediterania, ilikuwa nguvu iliyoendesha sera ya bahari kuu.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Yavuz Sultan Selim kuondoka Kahire na beylerbeylik ya Hayır Bey", "8cd4fb23"], "d": ["Yavuz Sultan Selim, aliyekaa Misri karibu miezi minane na kuweka utaratibu wa kiutawala, kifedha na kijeshi, aliondoka Kahire; Hayır Bey, naib wa zamani wa Halep ambaye huko Mercidâbık alivuta ubavu wa kushoto na kuharakisha kuangamia kwa Wamamluki, alianza utawala kutoka Kal'atülcebel kama beylerbeyi wa kwanza wa Ottoman wa Misri. Kuchaguliwa kwa gavana mwenye asili ya Kimamluki ilikuwa sera ya mpito iliyokusudiwa ili utawala mpya usionekane wa kigeni kwa wenyeji. Sultani, njiani kurudi, alichukua pamoja naye İstanbul khalifa wa mwisho wa Kiabbasi III. Mütevekkil na mafundi na maulamaa wateule wa Misri.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Mwisho wa ukhalifa wa Kiabbasi wa Kahire — hadithi ya 'sherehe ya kukabidhi'", "1d357640"], "d": ["Yavuz Sultan Selim alipochukua Misri, alimleta İstanbul khalifa wa mwisho III. Mütevekkil-Alellah, aliyetekwa Mercidâbık; ukhalifa wa Kiabbasi wa Kahire, uliodumu bila mamlaka chini ya kivuli cha masultani wa Kimamluki tangu 1261, hivyo ulimalizika. Kwa upande mwingine, hadithi maarufu kwamba ukhalifa ulikabidhiwa kwa Yavuz katika sherehe rasmi Ayasofya inatajwa kwa mara ya kwanza mwishoni mwa karne ya XVIII katika kazi ya d'Ohsson, na haipatikani katika chanzo chochote cha enzi ya Yavuz. TDV İslâm Ansiklopedisi inaihesabu hadithi hiyo kuwa uzushi kwa kuwa hakuna chanzo asili kinachothibitisha sherehe; hata hivyo inabainisha pia kwamba kwa mujibu wa sheria hapakuwa na haja ya sherehe kama hiyo ya kukabidhi ili ukhalifa upite.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum iliunganishwa na utawala wa Ottoman — ushawishi wa Wasafavî Anatolia Mashariki ulivunjika", "78d1be02"], "d": ["Ingawa ushawishi wa Ottoman eneo hilo uliongezeka baada ya ushindi wa Çaldıran (1514), kuchukuliwa kikamilifu kwa Erzurum kulichelewa hadi kuvunjika kwa ushawishi wa Iran; mji uliunganishwa na utawala wa Ottoman mwaka 1518-19 tu, baada ya kampeni ya Misri. Erzurum ilikuwa imeingia chini ya utawala wa Wasafavî mwaka 1502 Şah İsmâil alipomaliza Beylik ya Akkoyunlu; kipindi hiki cha miaka kumi na sita hivyo kilifungwa. Beylerbeylik ya Erzurum ingeanzishwa mwaka 1534 wakati wa Kampeni ya Irakeyn. Kati ya 1518-1519 Aşkale iliunganishwa na utawala wa Ottoman pamoja na eneo la Erzurum (siku haijathibitishwa).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Mwanzo wa uasi wa Celâlî: uasi wa Şeyh Celâl wa Bozok", "99bd8a99"], "d": ["Mtu aliyeitwa Şeyh Celâl katika eneo la Bozok alitangaza umahdi wake na kuasi karibu na Tokat; ingawa uasi ulikandamizwa, jina lake likawa jina la harakati zote za majambazi na uasi Anatolia kwa karne nzima. Celâlîlik, ikichanganyika na kuvunjika kwa mfumo wa tımar na shinikizo la idadi ya watu mwishoni mwa karne ya XVI, iligeuka kuwa tatizo refu zaidi la usalama wa ndani wa dola. Uasi huo ulisababisha uhamaji mkubwa wa umati Anatolia unaoitwa 'kaçgunluk kuu'.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Kuunganishwa kwa Cezayir na Dola ya Ottoman", "b8eba4c1"], "d": ["Hayreddin Reis, aliyekuwa akipinga shinikizo la Wahispania Afrika Kaskazini, aliomba İstanbul ili aweze kuendelea kuwepo, akamkabidhi sultani Cezayir, na khutba ilisomwa kwa jina la Yavuz Sultan Selim. Hivyo Cezayir iliunganishwa rasmi na ardhi za Ottoman, na Hayreddin alitumiwa askari na mizinga pamoja na cheo cha beylerbeyi. Kuunganishwa huku kuliweka msingi wa ubabe wa majini wa Ottoman Mediterania ya Magharibi uliodumu karne nyingi. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Konstantin, Şerşel (Cherchell), Medea (Titteri), Setif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Kifo cha Yavuz Sultan Selim huko Çorlu", "9fe83744"], "d": ["I. Selim, aliyekuza ardhi ya dola zaidi ya mara mbili ndani ya miaka minane, aliondoka İstanbul tarehe 18 Julai 1520 kwa kampeni mpya; kwa sababu ya uvimbe mkubwa uliotokea mgongoni hakuweza kusonga mbele zaidi ya Çorlu. Licha ya uingiliaji wa madaktari ugonjwa wake uliongezeka, na baada ya matibabu yasiyo na matumaini ya miezi miwili alifariki hapa tarehe 8-9 Şevval 926 (21-22 Septemba 1520). Kwa Çaldıran, Mercidabık na Ridâniye alikuwa amezuia Iran na kuiondoa Dola ya Kimamluki, na alikuwa ameleta ukhalifa na ulezi wa Haremeyn kwa Ottoman. Alimwacha mwana mmoja wa kiume tu: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Kisiwa cha Nikarya (İkarya) kuingia chini ya utawala wa Ottoman", "6afa972b"], "d": ["Nikarya, kati ya Sisam na Sakız, ilikuwa chini ya utawala wa Wapiganaji wa Saint Jean wa Rodos kuanzia 1481 hadi 1521; kipindi cha kwanza cha Ottoman kisiwani kilianza 1522 na kilidumu hadi 1822. Katika kipindi hiki, kaymakam alikuwa na jukumu la kukusanya na kulipa kodi; kama katika visiwa vingine vya Aegean, baraza la wazee wa eneo (demogerontia) liliendelea kuwepo na wakati mwingine liligongana na utawala wa Ottoman.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Kuunganishwa kwa nchi ya Dulkadir — mkoa wa Dulkadır wenye kitovu cha Maraş", "595c3c30"], "d": ["Nchi ya Dulkadır, iliyoendelea kama beylik tegemezi kwa Ottoman baada ya kushindwa kwa Turnadağ ya 1515, iliunganishwa moja kwa moja na ardhi za Ottoman baada ya Şehsuvaroğlu Ali Bey kuuawa pamoja na watoto wake huko Artukova, na ikafanywa mkoa wenye kitovu cha Maraş. Eneo la Bozok la beylik liliunganishwa na utawala wa Ottoman kama sancak tofauti. Hivyo kipindi cha takriban karne mbili cha Dulkadır cha Maraş, Elbistan, Göksun, Gürün, Zamantı na Darende kilifungwa; beylik ya kizuizi kwenye mpaka wa Wamamluki iliondoka kabisa.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Kutekwa kwa Knin", "a46d3117"], "d": ["Kwa mashambulizi ya sancakbeyi wa Bosnia Gazi Hüsrev Bey katika miaka 927-928 (1521-1522), mfululizo wa ngome za Venice, kuanzia Knin, Skradin na Ostrovica, zilipita chini ya utawala wa Ottoman; mpaka ulisukumwa zaidi ya safu ya pili ya milima. Mfululizo huu wa ushindi uliweka msingi wa sancak ya Dalmatia itakayokamilishwa kwa kuchukuliwa kwa Klis miaka kumi na mitano baadaye.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Kuondoka kwa Wapiganaji: kukabidhiwa kwa Bodrum, İstanköy na Visiwa Kumi na Viwili", "ea01666e"], "d": ["Kwa mujibu wa masharti ya kusalimishwa kwa Rodos, Wapiganaji wa Saint Jean waliacha si kitovu cha kisiwa pekee bali nafasi zote walizoshikilia kwa miaka mia mbili. Ngome ya Bodrum (Saint Pierre) kwenye pwani ya Anatolia na visiwa vya İstanköy, Kelemez na İleryoz hivyo vilipita bila mapigano chini ya utawala wa Ottoman. Kwa kukabidhiwa huku kulikokamilika wiki mbili baada ya kuanguka kwa Rodos, uwepo wa Kilatini kwenye kona ya kusini-mashariki ya Aegean ulimalizika kabisa.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Uasi wa Hain Ahmed Paşa Misri", "b18bb805"], "d": ["Ahmed Paşa, aliyetumwa kwenye ugavana wa Misri akisubiri ukuu wa sadrazam, alitangaza uhuru wake Kahire kwa kujitangaza 'el-Melikü'l-Mansûr Sultan Ahmed'. Uasi ulikandamizwa kwa muda mfupi na paşa kuuawa, lakini tukio lilionyesha udhaifu wa udhibiti wa kati katika mkoa tajiri zaidi wa dola. Kwa hiyo İbrahim Paşa alikwenda Misri na kuandaa Mısır Kanunnâmesi maarufu iliyopanga upya utawala wa mkoa.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Kuunganishwa kwa Bosnia Kaskazini: Yayça na Banaluka", "8ec86cfa"], "d": ["Mstari wa ulinzi wa Hungaria ulipoanguka baada ya Mohaç, sancakbeyi wa Bosnia Gazi Hüsrev Bey alisonga kwenye bonde la Vrbas na kuchukua ngome za mwisho za Bosnia zilizobaki mikononi mwa ufalme wa Hungaria. Kwa kuanguka kwa Yayça na Banaluka, mkoa wa Bosnia ulifikia mto Sava kaskazini na mstari wa Kroatia ulizaliwa. Banaluka upesi ikawa kitovu cha pili cha mkoa.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Kuchukuliwa kwa Budin na kukabidhiwa kwa Zapolya", "fba4f89b"], "d": ["Njiani kuelekea kampeni ya Viyana, jeshi la Ottoman lilizingira na kurudisha Budin iliyokuwa imepita mikononi mwa Ferdinand, na likamkabidhi mji mfalme wa Hungaria aliye chini ya ulinzi wa Ottoman János Szapolyai. Hivyo mfano wa ufalme kibaraka wa kizuizi uliundwa katika ushindani wa Habsburg–Ottoman juu ya Hungaria. Utaratibu huu ungedumu hadi 1541, na baada ya kifo cha Zapolya Budin ingefanywa mkoa wa moja kwa moja wa Ottoman.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Kanunî alielekea kampeni ya Ujerumani — changamoto kwa Şarlken", "7c3d7055"], "d": ["Baada ya mzingiro wa Viyana kutozaa matunda na Ferdinand kuizingira Budin tena, sultani aliondoka İstanbul wakati huu kumvuta maliki Şarlken moja kwa moja kwenye vita vya wazi. Jeshi lingecheleweshwa Agosti na upinzani wa ngome ndogo ya Güns, na maliki asipotoka kwenda vitani kampeni ingebaki kuwa mashambulizi ya wavamizi. Kampeni iliandaa msingi wa amani ya kwanza na Wahabsburg mwaka uliofuata.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Kampeni ya Ujerumani na mzingiro wa Güns (Kőszeg)", "8aec937a"], "d": ["Kanunî alielekea Austria na jeshi lake ili kumlazimisha Şarlken kwenye vita vya wazi; ngome ndogo ya Güns ilipinga siku ishirini na tano na kuchelewesha kusonga mbele kwa jeshi. Maliki asipotoka vitani, wavamizi walipiga eneo la Viyana na kwa kusonga kwa msimu walirudi. Kampeni haikuleta ongezeko la ardhi, lakini iliwakalisha Wahabsburg mezani na kuandaa msingi wa amani ya mwaka uliofuata.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Mkataba wa İstanbul — amani ya kwanza na Wahabsburg", "b085767a"], "d": ["Sultani, akimpokea Cornelius, mjumbe wa Ferdinand, alikubali kusitisha mapigano na maandishi ya kwanza rasmi ya amani kati ya Ottoman na Austria yalizaliwa. Kwa mkataba Ferdinand alikubali kulipa kodi ya kila mwaka kwa ardhi za Hungaria alizozishikilia, na archduke wa Austria alihesabiwa kwenye itifaki sawa na sadrazam. Hadhi hii isiyo sawa ilikuwa usemi wa wazi wa madai ya ubora wa diplomasia ya Ottoman katika karne ya XVI.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Kuchukuliwa kwa Kars na kufunguka kwa mpaka wa kaskazini-mashariki", "742e3101"], "d": ["Wakati tawi la mbele la Kampeni ya Irakeyn lilipoelekea mashariki kutoka Erzurum, ngome ya Kars, iliyokuwa mikononi mwa atabeg wa Kijojia na iliyokuwa magofu tangu Timur, ilipokelewa bila upinzani. Kwa kuwa mji ulishikilia njia kati ya kitanzi cha Aras na Çıldır, ulihesabiwa kuwa ufunguo wa mlango wa kaskazini unaofunguka kwa Iran. Ongezeko hili likawa kiungo cha kwanza cha beylerbeylik ya Kars itakayoanzishwa miaka thelathini baadaye na ya mstari wa Caucasus.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Kuingia kwa mara ya kwanza Tebriz — kufunguliwa kwa Kampeni ya Irakeyn", "cf7ed4e3"], "d": ["İbrahim Paşa, aliyeondoka mbele kwa cheo cha serdar-ı ekrem, Şah Tahmasb alipoepuka vita vya wazi na kurudi ndani ya nchi, aliingia Tebriz, mji mkuu wa Wasafavî, bila upinzani. Kanunî pia alifika mjini Septemba; lakini kwa sababu ya kuingia kwa majira ya baridi na urefu mkubwa wa njia ya usambazaji, jeshi lilielekea upande wa Bağdat na Tebriz haikuweza kushikiliwa kwa muda mrefu. Mji uliochukuliwa kwa mara ya pili baada ya Çaldıran ukawa mahali ambapo Ottoman ilijifunza kwamba kuuchukua mashariki ni rahisi, kuushikilia ni vigumu.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Ushindi wa Tunis wa Barbaros", "d8754216"], "d": ["Kaptan-ı deryâ Barbaros Hayreddin Paşa, baada ya kupiga pwani za Italia kwa meli zake, alielekea Tunis na kuingia mjini akimkimbiza mtawala wa Hafsî Mevlây Hasan. Kuchukuliwa kwa Tunis, kwa nafasi yake inayodhibiti Mlangobahari wa Sicilia, kuligeuza ghafla mizani ya nguvu Mediterania ya Magharibi kwa manufaa ya Ottoman. Hata hivyo ubabe huu haungedumu, Şarlken angejibu mwaka uliofuata kwa jeshi kubwa la majini.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Kupotea kwa Tunis kwa Şarlken", "a691f0f8"], "d": ["Şarlken, kwa kampeni kubwa iliyoungwa mkono na meli za Genoa na Upapa, baada ya kuangusha Halkulvâd alichukua Tunis na kumrudisha Mevlây Hasan kwenye kiti chini ya ulinzi wa Wahispania. Kikosi cha Kihispania kiliwekwa mjini, na kusonga mbele kwa Ottoman Mediterania ya Kati kulisimamishwa kwa muda. Ushindi wa uhakika wa Tunis ungewezekana tu miaka arobaini baadaye, mwaka 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Operesheni ya Gazi Hüsrev Bey kando ya Sava: Bosna Brodu na Jasenovaç", "3740ec83"], "d": ["Baada ya kuchukuliwa kwa Yayça na Banaluka mwaka 1528, ngome kando ya mto Sava ziliendelea kwa muda zaidi kwenye mpaka wa Kikroeshia-Kislavonia uliounganishwa na taji ya Habsburg. Gazi Hüsrev Bey, aliyekuwa sancakbeyi wa Bosnia kwa mara ya tatu mwaka 1536, mwaka huo huo alipochukua Pojega na viunga vyake, pia aliunganisha na utawala wa Ottoman ngome za Brod na Jasenovaç kwenye ufuo wa Sava. Hivyo mpaka wa kaskazini wa Bosnia ulifikia Sava; eneo lilikamilishwa miaka miwili baadaye kwa kuchukuliwa kwa Dubiça.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Kuuawa kwa Makbul İbrahim Paşa", "348aa7b8"], "d": ["İbrahim Paşa, aliyekuwa sadrazam kwa miaka kumi na mitatu, rafiki wa karibu zaidi wa Kanunî na mtu wa pili wa dola kwa vitendo, alinyongwa na kuuawa katika ikulu alikoitwa kwa iftar bila sababu yoyote kuonyeshwa. Msimamo wake katika kampeni ya Irakeyn, matumizi yake ya cheo cha 'serasker sultan' na mizani ya ndani ya ikulu vinahesabiwa kuwa vilichangia kifo chake. Kuuawa huko ni mwamba wa mabadiliko unaoonyesha kwamba vezir-i âzam katika utawala wa kati wa Ottoman hawakuwa na usalama kamili.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Kutekwa kwa Ngome ya Klis na kuanzishwa kwa sancak ya Dalmatia", "6ffd4ebf"], "d": ["Murad Bey, kethüdâ wa Gazi Hüsrev Bey, mwenye asili ya Kikroeshia aliyesilimu, alichukua kutoka Venice Ngome ya kimkakati ya Klis iliyo kaskazini mwa Split. Mara baada ya ushindi, Klis ilifanywa kitovu cha sancak na kaza mpya iliyojumuisha viunga vyake; mipaka ya sancak hii kwa kiasi kikubwa ilichora mfumo wa Kroatia ya Ottoman. Ushindi huu, uliokuja miaka kumi na tano baada ya Knin, ulikamilisha mfupa wa kiutawala wa ndani ya Dalmatia.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Mzingiro wa Korfu na vita na Venice", "11af95bd"], "d": ["Baada ya kampeni ya Pulya (Apulia), jeshi la Ottoman lilituma askari Korfu na kuizingira ngome yenye nguvu ya Venice ya kisiwa. Kwa sababu ya hali ya mwamba wa ngome, hasara kubwa na hali ya msimu, kizuizi kiliondolewa na jeshi likarudi tarehe 6 Septemba. Ingawa mzingiro haukuzaa matunda, vita vilivyofunguliwa na Venice vilimalizika kwa visiwa vingi vya Aegean na Adriatic kuunganishwa na Ottoman na kwa ushindi wa Preveze mwaka uliofuata.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Kampeni ya Aegean ya Barbaros: kuchukuliwa kwa visiwa vinavyotawaliwa moja kwa moja na Venice", "1b32ed96"], "d": ["Meli zilizorudi kutoka mzingiro wa Korfu, zikitumia fursa ya vita vilivyotangazwa dhidi ya Venice, zilipokea moja moja katika Aegean visiwa vilivyokuwa tegemezi moja kwa moja kwa Venice, si kwa dukedom. Egina ilichukuliwa baada ya upinzani mkali, Astipalya, iliyokuwa mikononi mwa familia ya Querini, na Karpatos na Kaşot zilisalimu amri, na Batnoz, iliyokuwa chini ya utawala wa monasteri, nayo ilikubali ulinzi wa Ottoman. Dukedom ya Nakşa, kwa upande mwingine, ilifungwa kwa kodi na kuachwa mahali pake; kuunganishwa kwake kungesubiri 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Kampeni ya Aegean Kaskazini ya Barbaros: kuchukuliwa kwa İskiros na Sporadi za Kaskazini", "20ab688e"], "d": ["Njiani kuelekea Preveze, meli zilipokea moja moja visiwa vya Aegean Kaskazini vilivyokuwa vimekimbilia Venice baada ya ushindi wa İstanbul. İskiros kaskazini mwa Eğriboz na İskiathos, İskopelos na Alonisos zinazoshikilia mdomo wa ghuba ya Selanik hivyo ziliingia chini ya utawala wa Ottoman. Visiwa hivi vilifunga pengo la mwisho la Aegean Kaskazini ambalo lilibaki mikononi mwa Venice kwa miaka sitini na minane zaidi ingawa Eğriboz ilikuwa imechukuliwa mwaka 1470.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Kuchukuliwa kwa Aden na kuunganishwa kwa pwani ya Yemen", "e7d46d8f"], "d": ["Meli zilizoondoka Süveyş kwa kampeni ya India, kwa kuwa haingewezekana kwenda bahari kuu bila kuifanya Bahari Nyekundu salama, kwanza ziliekekea pwani ya Yemen. Hadım Süleyman Paşa aliingia bandari ya Aden tarehe 3 Agosti 1538; mtawala wa Tâhirî Âmir b. Dâvud, aliyeelekea Wareno, aliletwa kwenye mlango wa nahodha na kuuawa, na kikosi cha walinzi 500 kiliachwa mjini. Katika kampeni hiyo hiyo Moha na visiwa vya Kemeran na Ferasan vinavyodhibiti mlangobahari pia vilipokelewa, na msingi wa beylerbeylik ya Yemen uliwekwa. Hivyo Dola ya Ottoman ilimiliki kwa mara ya kwanza pwani yote ya kaskazini ya Bâbülmendep; Sana na maeneo ya ndani yangelazimika kusubiri miaka tisa zaidi.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Kampeni ya Boğdan na kuunganishwa kwa eneo la Bucak (Bender)", "90a88a56"], "d": ["Katika kampeni dhidi ya voivode wa Boğdan Petru Rareş, aliyeshindwa kutimiza wajibu wake kwa Ottoman, Suçava ilichukuliwa na mji wa Yaş uliporwa na Han wa Kırım Sâhib Giray. Sultani alimweka Çekirge Stefan kwenye uvoivode na akaunganisha moja kwa moja na ardhi za Ottoman eneo la Bucak (Besarabia ya Kusini) pamoja na Bender. Kuunganishwa huku kulikuwa mojawapo ya viungo vilivyogeuza pwani za kaskazini-magharibi za Bahari Nyeusi kuwa bahari ya ndani ya Ottoman. Boğdan ilikuwa tayari uvoivode tegemezi kwa Ottoman; kampeni hii haikuchukua ardhi kutoka dola ya kigeni, ilichukua tu utawala wa ndani wa Bender na Bucak kutoka kwa voivode na kuufunga moja kwa moja na sultani; sehemu iliyobaki ya uvoivode iliendelea na hadhi ya utegemezi. Muundo huo huo ungerudiwa Kili na Akkirman mwaka 1484 na Hotin mwaka 1713: ngome za mpakani moja kwa moja, ardhi za ndani tegemezi.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Kupokelewa kwa Anabolu (Nauplion) kwa mkataba", "104d0937"], "d": ["Vita vya Venice vya miaka mitatu baada ya Preveze vilimalizika kwa jamhuri kukubali kuacha ngome zake mbili za mwisho Mora. Anabolu na Benefşe, zilizoshindwa kuchukuliwa kwa mzingiro, zilikabidhiwa kwa Ottoman mezani pamoja na fidia ya vita ya dukati laki tatu. Peninsula ya Mora hivyo iliunganishwa kwa namna ambayo hakubaki hata alama moja ya Venice.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Segedin kuingia chini ya utawala wa Ottoman na kuundwa kwa livâ ya Segedin", "019aa000"], "d": ["Baada ya utawala wa Ottoman kuanzishwa kikamilifu Budin mwaka 1541, wakuu wa Segedin walikubali mamlaka ya I. Ferdinand na wakajiandaa kwa ulinzi wa silaha. Beylerbeyi wa Budin Küçük Bâlî Paşa, mwanzoni mwa 1543, aliwaita watawala wa mji kwake na kuwanyonga kwa sababu ya usaliti, kisha akatuma kikosi kuuchukua mji. Wakati huo livâ ya Segedin iliundwa na Derviş Bey, mwana wa Bâlî Paşa, aliteuliwa kuwa sancak beyi wa kwanza; livâ mwanzoni ilienea kati ya Danube na Tisa.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Kutekwa kwa Valpo, Şikloş na Peçuy", "2ca030a3"], "d": ["Lengo la kwanza la kampeni ya Hungaria iliyofanyika miaka miwili baada ya kuunganishwa kwa Budin lilikuwa kuufanya salama ubavu wa kusini wa mkoa mpya kati ya Drava na Danube. Baada ya ngome za Valpo na Şikloş kuchukuliwa, Peçuy, kitovu cha Baranya, ilisalimu amri. Mji ungekuwa kitovu chenye watu wengi na kilichoendelezwa zaidi cha Hungaria ya Ottoman, na mwanahistoria İbrahim Peçuylu alichukua jina lake kutoka hapa.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Kutekwa kwa Estergon na İstolni Belgrad", "efca9e05"], "d": ["Katika kampeni ya Hungaria aliyoiongoza Kanunî mwenyewe, baada ya mzingiro wa wiki mbili na nusu, Estergon, kitovu cha kidini cha Ufalme wa Hungaria na mji wa askofu mkuu, iliingia chini ya utawala wa Ottoman. Kisha İstolni Belgrad, mji wa kutawazwa wafalme wa Hungaria, pia ilichukuliwa na mkanda wa ulinzi wa mkoa wa Budin ukakamilika. Estergon ingebaki mikononi mwa Ottoman hadi 1595 kama ngome kuu ya mstari wa Danube.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Mkanda wa ulinzi wa kaskazini na magharibi wa Budin: Vaç, Hatvan na Şimontorna", "733ee5ce"], "d": ["Estergon na İstolni Belgrad zilipochukuliwa, beylerbeyi wa Budin alichukua hatua bila kampeni ya sultani ili kukamilisha pete ya ngome inayozunguka mji mkuu. Vaç kwenye kona ya Danube, Hatvan, mlango wa Alföld, na Şimontorna kwenye mstari wa Sió zilipokelewa moja moja. Mafanikio ya mwaka huu tulivu yaliigeuza Budin kutoka mji wa mpakani kuwa kitovu cha mkoa kitakachodumu miaka mia moja arobaini.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Kuunganishwa kwa Basra na kutoka hadi Ghuba ya Basra", "02f87c11"], "d": ["Wakati wa kutekwa kwa Bağdat (1534), mtawala wa Basra Râşid b. Megāmis alikuwa ametangaza utii kwa Kanunî, na mwaka 1538 alituma funguo za mji. Şeyh Yahyâ aliyemrithi alipochukua msimamo dhidi ya Waottoman, Beylerbeyi wa Bağdat Ayas Paşa alisonga kwa nchi kavu na sancak beyi wa Musul na meli 120 kupitia Furat; Ayas Paşa aliingia Basra tarehe 26 Desemba 1545 na mji ukawa kitovu cha beylerbeylik. Bandari hii kwenye mdomo wa Şattülarab ilikuwa mlango ambao Ottoman ilifunguka kwenye ghuba iliyodhibitiwa na Ureno kutoka Hürmüz; kwa Mkataba wa Amasya wa 1555 Iran pia ilitambua hali hii.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Kutekwa kwa Sana na maeneo ya ndani ya Yemen", "d31ded85"], "d": ["Baada ya Taiz, Sana nayo ilichukuliwa na nchi nzima ilifungwa kwenye beylerbeylik. Hata hivyo kwa sababu ya jiografia ngumu na tofauti ya madhehebu utawala huu haukuwahi kuwa wa utulivu; Yemen ikawa mstari wa vita ulioendelea kumeza askari kwa Ottoman.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Kutekwa kwa Taiz", "d4509df9"], "d": ["Yemen, iliyokuwa imeridhika na ukanda wa pwani miaka tisa iliyopita, imamu wa Kizaydî walipoendelea kuwa na nguvu katika maeneo ya ndani ya milima, vikosi vya Özdemir Paşa vilipanda nyanda za juu na kuchukua Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Mkataba wa İstanbul — amani ya miaka mitano na Wahabsburg", "41f81773"], "d": ["Amani ya miaka mitano ilitiwa saini kati ya Ottoman na Wahabsburg; Ferdinand alikubali kulipa dukati 30.000 kila mwaka kwa ardhi za Hungaria alizozishikilia. Mkataba ulithibitisha kisheria hali halisi ya Hungaria kugawanywa katika sehemu tatu. Kuhakikishwa kwa usalama wa mstari wa magharibi kulimpa Kanunî nafasi ya kuandaa kampeni mpya dhidi ya Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Kampeni ya Pili ya Iran na kuchukuliwa tena kwa Tebriz", "e82365df"], "d": ["Katika kampeni iliyofanywa kwa uchochezi wa Elkas Mirza, kaka wa Şah Tahmasb aliyemwasi na kukimbilia İstanbul, jeshi liliingia Tebriz kwa mara ya pili. Kwa kuwa Wasafavî tena hawakuingia vitani vya wazi na walirudi nyuma wakichoma ardhi, mjini iliwezekana kukaa wiki chache tu. Kampeni ilithibitisha kwamba Tebriz haiwezi kushikiliwa na kuelekeza mkakati wa Ottoman kuanzisha mstari wa mpaka wa kudumu, yaani kuiimarisha Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Kutekwa kwa Van na kuthibitishwa kwa mpaka wa mashariki", "fc8f930b"], "d": ["Ngome ya Van, iliyozingirwa wakati wa kurudi kutoka Tebriz, kwa nafasi yake juu ya mwamba kwenye ufuo wa mashariki wa ziwa, ilikuwa kufuli isiyopingika ya eneo na ilisalimu amri baada ya mzingiro mfupi. Mji ulifanywa mara moja kitovu cha beylerbeylik; sancak za Erciş, Adilcevaz na Hakkâri ziliunganishwa nayo. Tofauti na Tebriz, Van ilishikiliwa na kwa karne nne ilibaki kama nafasi ya kudumu ya mbele zaidi ya Ottoman mashariki.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Kuunganishwa kwa Lahsa na Katîf — pwani ya Kiarabu ya Ghuba", "f6701e60"], "d": ["Baada ya kuchukuliwa kwa Basra, Katîf, iliyokuwa imekuwa kituo cha mbele cha Ureno kwenye pwani ya magharibi ya ghuba, ilichukuliwa na beylerbeylik mpya iliundwa pamoja na oasisi za Lahsa za ndani. Hapa palikuwa mahali pa kuanzia operesheni za kuelekea Bahrain na Hürmüz. Dola ya Ottoman hivyo ikawa na usemi kwa wakati mmoja kwenye pwani za Bahari Nyekundu na Ghuba ya Basra za peninsula ya Uarabuni.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Kupotea kwa Şehrizor — bey wa Erdelân Sührâb alielekea Wasafavî", "5600efc9"], "d": ["Eneo la Şehrizor, lililokuwa limetambua utawala wa Ottoman wakati wa Kampeni ya Irakeyn (1535), lilikuwa chini ya utawala wa emîr wa Erdelân Bige Bey aliyekaa Ngome ya Zalm. Kaka yake Sührâb, aliyechukua Ngome ya Zalm na kutawala beylik kwa kifo cha Bige Bey mwaka 1550, alielekea Wasafavî na akaacha kutii Ottoman; eneo la Şehrizor hivyo lilitoka kwenye ushawishi wa Ottoman. Eneo lilipatikana tena tu mwaka 1554 wakati wa kampeni ya Nahçıvan kwa Ngome ya Zalm kuzingirwa na kuchukuliwa.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Kuchukuliwa kwa Ardahan na bonde la Çıldır", "14c9eb76"], "d": ["Beylerbeyi wa Erzurum, wakati wa vita vinavyoendelea na Wasafavî, aliyaelekea maeneo ya atabeg wa Kijojia kwenye kitanzi cha Kür na kuunganisha Ardahan na eneo la Çıldır na utawala wa Ottoman. Mstari wa Kars-Ardahan hivyo uliunganishwa na nyanda za juu zinazofunguka kwa Georgia kaskazini-mashariki zilichukuliwa chini ya udhibiti. Mpangilio wa kiutawala wa uhakika wa eneo ungekamilishwa na mkoa wa Çıldır utakaoundwa miaka ishirini na saba baadaye.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokullu Mehmed Paşa alivuka Danube — kuanza kwa vita vya Transylvania", "38fde931"], "d": ["Kufuatia machafuko yaliyosababishwa na mtawa Martinuzzi, mlezi wa mfalme mdogo wa Transylvania János Zsigmond, na Transylvania kuziachia Ferdinand ngome za Banat, kampeni mpya ilionekana kuwa ya lazima; amri ilipewa Beylerbeyi wa Rumeli Sokullu Mehmed Paşa. Jeshi, licha ya juhudi za Martinuzzi za kuchelewesha, lilivuka Danube na kuchukua Beçe, Beçkerek, Çanad na Lippa; hata hivyo mzingiro wa Temeşvar uliondolewa tarehe 16 Novemba kwa sababu ya baridi. Hivyo vita vipya vya Ottoman-Habsburg vilifunguliwa Hungaria.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Mji wa Lipova (Lippa) wapita mikononi mwa jeshi la Austria la Castaldo — ngome ilijisalimisha tarehe 5 Desemba", "a0e1ff0d"], "d": ["Lipova, iliyochukuliwa na Sokullu Mehmed Paşa Oktoba 1551, ilizingirwa na jeshi la Jenerali Castaldo tarehe 4 Novemba; siku mbili baadaye mji ulipita mikononi mwa Waaustria. Ulama Paşa, kwa walinzi 5.000, aliitetea ngome kwa siku tisa zaidi na akatoka kwa makubaliano tarehe 5 Desemba 1551. Lipova ilibaki mikononi mwa Habsburg hadi kuanguka kwa Temeşvar mwaka 1552.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Vikosi vilivyotumwa kutoka Temeşvar vyashikilia palanka za Banat ya Kusini — Versec, Haram, Keve", "edca0921"], "d": ["Baada ya Temeşvar kujisalimisha kwa jeshi la Ottoman, vikosi vilivyojitenga na jeshi la kuzingira vilielekea palanka ndogo za Banat; kulingana na maelezo ya Bánlaky, palanka za Versec, Facset, Mehádia, Csákóvár, Haramvár na Keve zilishikiliwa na vikosi hivi. Hivyo Haram kando ya Danubi nayo ilipita mikononi mwa Ottoman.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Kutekwa kwa Solnok na kushindwa kwa mzingiro wa Eğri", "a7156e8f"], "d": ["Majeshi mawili ya Ottoman yaliyoungana baada ya kuchukuliwa kwa Temeşvar yalichukua Solnok kwenye Tisa karibu bila mapigano walinzi wa kukodiwa walipoiacha ngome. Ngome ya Eğri iliyozingirwa baadaye, kwa upande mwingine, haikuweza kuchukuliwa mbele ya upinzani wa siku thelathini na nane wa kikosi cha watu elfu mbili chini ya amri ya İstvan Dobo na jeshi lilirudi majira ya baridi yalipoingia. Ngome moja kuanguka kwa urahisi na nyingine kuhimili katika kampeni hiyo hiyo ilikuwa ishara ya kwanza ya wazi kwamba mpaka Hungaria haukuwa ukisonga mbele tena kwa manufaa ya Ottoman yenyewe.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Muungano wa Ottoman na Ufaransa — meli za Ufaransa kuingia chini ya amri ya Ottoman", "a8e01b22"], "d": ["Kwa mkataba wa tarehe 1 Februari 1553, meli za Ufaransa ziliwekwa chini ya amri ya jeshi la majini la Ottoman; operesheni ya pamoja dhidi ya Uhispania ilipangwa Mediterania ya Magharibi. Baada ya mkataba Turgut Reis aliondoka tarehe 15 Juni 1553 kwa kadırga arobaini na tano kuiunga mkono Ufaransa. Huu ulikuwa mkataba wa kwanza rasmi wa muungano uliohamisha msingi wa kibiashara wa kapitulasyon za 1536 hadi ushirikiano wa kijeshi.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Kuuawa kwa Şehzade Mustafa huko Konya Ereğlisi", "dec36858"], "d": ["Şehzade Mustafa, aliyeingia hemani mwa baba yake ili kujiunga na jeshi lililokusanyika kwa kampeni ya Nahçıvan, alikutana na wauaji alipokuwa karibu kufika mbele ya sultani, na alinyongwa na kuuawa. Kuuawa kwa mgombea wa urithi aliyependwa sana jeshini kulizua hasira kubwa kati ya Yeniçeri, na Rüstem Paşa aliondolewa kwenye usadrazam. Tukio liliingia katika fasihi na kumbukumbu ya wananchi kama mojawapo ya mivunjiko yenye utata zaidi ya siasa za şehzade za Ottoman.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Kuhamishwa kwa mpaka wa İbrim na Nübye kusini", "c57d5d77"], "d": ["Mpaka wa kusini wa beylerbeylik ya Misri ulihamishwa hadi zaidi ya maporomoko ya pili kwa ngome ya İbrim, inayoinuka juu ya kilele cha mwamba kwenye Nile, kuimarishwa na Özdemir Bey na Nûbe ya Chini kuunganishwa kikamilifu na Misri ya Ottoman. (Mpangilio wa kiutawala wa Ottoman huko İbrim ulikuwa umeanzishwa baada ya ushindi wa Misri; kwenye ramani İbrim inaonyeshwa kuwa ya Ottoman kuanzia 1517. Mwaka huu ni wa takriban, chanzo hakitoi mwaka.) Ngome ilikuwa kizuizi dhidi ya mashambulizi kutoka Nübye na pia kituo cha ukaguzi cha njia ya dhahabu na watumwa kwenda Sennar. Kikosi cha walinzi wa Kibosnia kilichowekwa hapa kilikuwa cha kudumu kiasi kwamba wajukuu wao bado walikuwa ngomeni miaka mia tatu baadaye. Vyanzo vinatoa masimulizi mawili tofauti kuhusu wakati İbrim iliingia chini ya utawala wa Ottoman: makala ya TDV ya Sudan inahusisha kuunganishwa kwa Nûbe ya Chini na Misri ya Ottoman na operesheni ya Özdemir Paşa katikati ya karne ya XVI, wakati makala ya Nûbe inaandika kwamba eneo hadi bonde la Halfa na mpangilio wa kiutawala huko İbrim viliundwa mara baada ya ushindi wa 1517. Sancak ya İbrim iliunganishwa na mkoa wa Habeş tarehe 26 Julai 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Kuchukuliwa kwa Bicâye (Bougie) kutoka kwa Wahispania", "49691cda"], "d": ["Bicâye, iliyokuwa mikononi mwa Uhispania kwa miaka arobaini na mitatu na iliyogawanya pwani kati ya Cezayir na Konstantin mara mbili, ilisalimu amri baada ya kuzingirwa kwa nchi kavu na bahari. Kwa kuanguka kwa ngome, pwani ya ocak ya Cezayir ilikuwa isiyokatika hadi Vehran. Kupotea huku kuliamsha hasira kubwa Uhispania kiasi kwamba kamanda Alonso de Peralta, aliyeikabidhi ngome, aliuawa nchini mwake.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Kuunganishwa kwa Zeyla na Mkoa wa Habeş", "7bbf369a"], "d": ["Bandari ya Zeyla, kwenye ncha ya kusini ya mkoa wa Habeş kwenye pwani ya Afrika ya Ghuba ya Aden, iliunganishwa na utawala wa Ottoman. Mji huu, mlango wa Usultani wa Adal unaofunguka baharini, ulikuwa kituo cha mwisho cha usambazaji kwa meli zinazotoka nje ya Bâbülmendep. Kwa kuunganishwa kwa Zeyla mpaka wa Dola ya Ottoman Afrika ulifika sehemu yake ya kusini zaidi.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Vita vya Mashehzade vya Konya", "1c8de387"], "d": ["Şehzade Bayezid, aliyeingia katika mapambano ya kiti cha enzi, alifika mbele ya Konya na kikosi chake cha takriban watu 30.000 na, katika mapigano ya siku mbili, alishindwa na kaka yake Şehzade Selim. Bayezid, aliyeshindwa vibaya, alikimbilia Iran kwa Şah Tahmasb kupitia Amasya. Vita viligeuza mgogoro wa urithi wa usultani katika miaka ya mwisho ya Kanunî kuwa tatizo la sera ya nje.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Ushindi wa Majini wa Cerbe", "c7b905c1"], "d": ["Meli za Ottoman chini ya amri ya Piyâle Paşa, kwa ujanja wa kugawanyika mara mbili mbele ya Cerbe, zilitawanya meli za washirika wa Kihispania-Kigenoa-Kimalta zilizokusanyika kurudisha Trablus. Washirika walipoteza sehemu kubwa ya meli zao, na ngome ya kisiwani ilianguka muda mfupi baadaye. Cerbe inahesabiwa kuwa ushindi wa pili mkubwa wa majini ulioimarisha ubora wa Ottoman Mediterania baada ya Preveze.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Kuuawa kwa Şehzade Bayezid huko Kazvin", "a759de14"], "d": ["Şehzade Bayezid, aliyekimbilia Iran, baada ya majadiliano marefu alikabidhiwa na Şah Tahmasb kwa ujumbe wa Ottoman na alinyongwa na kuuawa pamoja na wanawe wanne. Kwa malipo ya kukabidhi, Wasafavî walipata makubaliano muhimu ya kifedha na dhamana ya mpaka. Kwa utekelezaji huu kizuizi cha mwisho mbele ya kupanda kiti cha enzi kwa II. Selim kiliondolewa na utaratibu wa amani wa Mkataba wa Amasya ulihifadhiwa.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Kuchukuliwa kwa Sakız kutoka kwa Wagenoa", "a4559b96"], "d": ["Sakız, iliyotawaliwa kwa miaka mia mbili kama koloni la biashara la familia ya Giustiniani ya Genoa na iliyolipa kodi kwa Ottoman, ilipokelewa na Piyâle Paşa bila risasi hata moja kwa sababu ya kuchelewesha kodi yake na kuzipa meli za adui bandari. Pamoja na Sakız na İpsara, uwepo wa mwisho wa Genoa kwenye pwani ya mashariki ya Aegean pia ulisafishwa. Uzalishaji wa mastiki wa Wana-Sakız na upendeleo wao vilihifadhiwa na kisiwa kiliunganishwa na mkoa wa Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Kuunganishwa kwa Dukedom ya Nakşa — Visiwa vyote vya Kiklad", "68f0ec0b"], "d": ["Dukedom ya Kilatini ya Nakşa, iliyodumu tangu 1207 na iliyolipa kodi kwa Ottoman tangu 1537, ilifutwa kwa kuonyesha kama sababu malalamiko yaliyofika duke wa mwisho Giacomo Crispo alipowakandamiza wananchi wake. Nakşa, Paros, Değirmenlik, Andros, Sire, Mikonos, Nio, Yamurgi na visiwa vyote vya Kiklad vinavyozunguka vilichukuliwa chini ya utawala wa moja kwa moja wa Ottoman kwa uamuzi mmoja. Kanunî alimkabidhi Yasef Nasi utawala wa visiwa kwa muda; utawala wa Kilatini wa karne tatu na nusu hivyo ulimalizika katikati ya Aegean.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Uasi wa Yemen na kampeni ya Yemen ya Koca Sinan Paşa", "c8218d8e"], "d": ["Imam wa Kizaydî Mutahhar, kwa kisingizio cha kodi kukusanywa kwa nguvu, aliasi na kuuondoa utawala wa Ottoman kutoka sehemu kubwa ya Yemen. Koca Sinan Paşa, aliyetumwa kutoka İstanbul, kwa operesheni aliyoiongoza kati ya 1568-1570, baada ya kuchukua Kevkebân kufuatia mzingiro mrefu, alianzisha tena utawala wa Ottoman eneo hilo. Kampeni ilikuwa ya umuhimu muhimu katika kulinda udhibiti wa mlango wa kusini wa Bahari Nyekundu na njia ya biashara ya Bahari ya Hindi.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Muungano wa ulinzi na Usultani wa Açe na msaada wa Bahari ya Hindi", "8e835f24"], "d": ["Wajumbe wa Açe, waliomwomba Kanunî msaada mbele ya mashambulizi ya Wareno, kwa kifo cha sultani huko Zigetvar waliwasilisha utii wao kwa II. Selim na mkataba wa ulinzi ulitiwa saini naye. Sultani aliamuru mizinga, bunduki, risasi na mafundi watumwe kutoka İskenderiye; meli kumi na saba za kivita ziliandaliwa kupelekwa maji ya Hindi. Kukua kwa uasi wa Yemen kulizuia meli kuondoka, lakini wapiga mizinga na mafundi wa Ottoman waliofika Açe waliacha alama ya kudumu eneo hilo.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Kutua Kupro: kuchukuliwa kwa Limasol", "9074ccc9"], "d": ["Jeshi la Ottoman lililotua kisiwani lilichukua Limasol bila kukutana na upinzani mkubwa na siku iliyofuata likaelekea Larnaka. Kwa wenyeji kutoridhika na utawala wa Venice na kuvisaidia vikosi vya Ottoman, hakuna upinzani mkubwa uliopatikana Larnaka pia; Bandari ya Tuzla ilifanywa kituo cha kutua askari na vifaa. Venice ilikuwa imekusanya ulinzi wake Lefkoşa na Magosa; gavana wa Baf alitangaza utii kwa serdar baada ya Lefkoşa kuanguka tu.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Kutekwa kwa Lefkoşa", "413d866b"], "d": ["Baada ya mzingiro wa siku arobaini na tano ulioanza tarehe 25 Julai 1570, Lefkoşa, mji mkuu wa Kupro chini ya utawala wa Venice, ulisalimu amri kwa jeshi la Ottoman. Kuanguka kwa kitovu cha kisiwa kulibana upinzani wa Venice ndani ya ngome ya Magosa. Ushindi uliamsha mwangwi mkubwa Magharibi na kuharakisha mchakato uliokwenda kwenye kuundwa kwa meli za Muungano Mtakatifu chini ya uongozi wa Papa.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Kusalimishwa kwa Girne — pwani ya kaskazini ya Kupro", "39fdeea5"], "d": ["Kuanguka kwa Lefkoşa kwa upanga tarehe 9 Septemba kulivunja upinzani kaskazini mwa Kupro. Ngome ya Girne iliyo nyuma ya milima ya Beşparmak, ilipojua hatima ya mji mkuu, ilisalimu amri kwa masharti siku nane baadaye na kikosi chake kiliruhusiwa kuondoka kisiwani. Bendera ya Venice ilibaki kisiwani Magosa pekee; hiyo nayo ingedumu miezi kumi na moja zaidi.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Kujengwa upya kwa meli baada ya İnebahtı", "db51fe44"], "d": ["Kazi ya kwanza ya Kılıç Ali Paşa, aliyeteuliwa kuwa kaptan-ı deryâ baada ya kushindwa kwa İnebahtı, ilikuwa kujenga upya meli zilizopata hasara kubwa; viwanja vya meli vilifanya kazi bila kusimama majira yote ya baridi ya 1571-1572. Mwezi Juni 1572 kundi jipya la meli, lililoundwa na takriban kadırga 250 na kadırga 300 za reis wa kujitolea, lilitoka kwenda Mediterania. Kupona huku kwa haraka kulionyesha kwamba İnebahtı haikuvunja nguvu ya majini ya Ottoman kwa kudumu.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Mkataba wa İstanbul na Venice — kutambuliwa kwa Kupro", "4d08ef50"], "d": ["Venice, iliyobaki peke yake kwa kuvunjika kwa Muungano Mtakatifu, ilifanya amani ya pekee na Ottoman na kukubali rasmi kwamba Kupro ni ya Ottoman na kukubali kulipa fidia ya vita. Mkataba ulifichua wazi kwamba ushindi wa İnebahtı haukuleta faida ya kisiasa kwa ulimwengu wa Kikristo. Venice, tangu hapo, kwa miaka sabini ingeepuka kuingia vitani moja kwa moja na Ottoman.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Kifo cha II. Selim", "c289f5ee"], "d": ["II. Selim, baada ya kuanguka, hakuweza kutoka kwenda divan kwa takriban miezi miwili na akafa. Kifo chake kilifichwa ikulu kwa siku kumi na mbili hadi mwana wake mkubwa Murad kutoka Manisa alipofika İstanbul. Vyanzo vinatofautiana kuhusu siku ya kifo: Selânikî anasema 15 Desemba; Gerlach, Mehmed b. Mehmed na Cenâbî wanasema 13 Desemba.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Kutangazwa kwa kifo cha II. Selim na kutawazwa kwa III. Murad", "84334d70"], "d": ["Kifo cha II. Selim na kutawazwa kwa III. Murad aliyeletwa kutoka Manisa vilitangazwa rasmi tarehe 22 Desemba 1574. Sultani mpya angebaki kwenye kiti cha enzi kwa miaka ishirini na moja, utawala wake ukikumbukwa kwa vita virefu vya Iran Mashariki, mkesha wa Vita Virefu Magharibi na kupunguzwa kwa kiwango cha akçe ndani. Hadi kifo cha Sokullu Mehmed Paşa mwaka 1579, utaratibu wa zamani uliendelea katika uongozi wa dola.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Vita vya Vâdisseyl (Kasrılkebir) — Abdülmelik, aliyeungwa mkono na Ottoman, aliangamiza jeshi la Ureno", "21280dac"], "d": ["Abdülmelik, aliyekalia kiti cha Moroko kwa msaada wa Ottoman, aliangamiza jeshi kubwa la Mfalme Sebastian wa Ureno huko Vâdisseyl; kwa kuwa watawala watatu walikufa vitani kwa pamoja, vinaitwa katika vyanzo vya Magharibi 'Vita vya Wafalme Watatu'. Nguvu ya kijeshi ya Ureno ilianguka na nchi ilipita muda mfupi baadaye mikononi mwa Uhispania. Abdülmelik naye alikufa vitani; kaka yake Ahmed el-Mansûr aliyechukua nafasi yake alitangaza ushindi İstanbul kwa ujumbe. Uhusiano kati ya dola mbili ulibaki si wa kodi wala utegemezi bali wa kubadilishana wajumbe na zawadi, na muda mfupi baadaye ulipata mvutano kwa sababu ya suala la zawadi.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Wakazi wa Derbend kuwasilisha utii kwa Lala Mustafa Paşa — Demirkapı chini ya utawala wa Ottoman", "9c55aeff"], "d": ["Wakati wa kampeni ya Şirvan, ujumbe wa watu saba kutoka wakazi wa Derbend ulikwenda kwa Serdar Lala Mustafa Paşa aliyekuwa Ereş na kuwasilisha utii. Derbend (Demirkapı), inayofunga njia nyembamba kati ya ukuta wa Caucasus na Bahari ya Hazar, kama njia ya lazima ya barabara za nchi kavu zinazotoka kaskazini, ilicheza nafasi kuu katika kushikilia Şirvan. Utawala wa Ottoman hapa uliendelea hadi 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Kutekwa kwa Şirvan: kuchukuliwa kwa Şamahı", "9afae4c1"], "d": ["Jeshi lililofunguka kwa Caucasus baada ya Ushindi wa Çıldır liliingia Şirvan, mkoa tajiri zaidi wa Wasafavî kwenye pwani ya Hazar, na kuchukua mji kitovu Şamahı. Özdemiroğlu Osman Paşa aliteuliwa beylerbeyi huko na tawi la kaskazini la Njia ya Hariri liliingizwa chini ya udhibiti wa Ottoman. Şirvan ingekuwa mstari uliobadilisha mikono zaidi na uliogharimu zaidi wa vita vya mashariki vya miaka kumi na miwili.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Kuchukuliwa kwa Bakü — kutoka hadi pwani ya Hazar", "eb5adab8"], "d": ["Kama kiungo cha mwisho cha operesheni ya Şirvan, bandari ya Bakü kwenye ufuo wa magharibi wa Bahari ya Hazar ilichukuliwa. Visima vya mafuta vinavyozunguka mji vilikuwa chanzo cha mapato kinachojulikana hata wakati huo, na bandari ilikuwa mahali pa kutokea kwa hariri ya Iran iliyokuja kupitia Hazar. Dola ya Ottoman hivyo ikawa kwa mara ya kwanza na ya pekee katika historia yake mmiliki wa pwani kwenye Bahari ya Hazar.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Kutekwa kwa Revan (Erivan) na ujenzi wa ngome", "7f623b7b"], "d": ["Ferhad Paşa, aliyepokea amri Kars ya kwenda Revan na kujenga ngome huko, alielekea Revan na mji ulichukuliwa chini ya udhibiti wa Ottoman mwanzoni mwa Ramadhani ya 991 (katikati ya Septemba 1583). Ngome mpya na kubwa ilijengwa Revan, inayoshikilia mlango wa kaskazini wa bonde la Aras; mji ulifanywa kitovu cha beylerbeylik. Revan, iliyosimama katikati ya njia ya jeshi kati ya Kars na Tebriz, ilikuwa uti wa mgongo wa usambazaji wa mstari wa mashariki. Ngome ilijengwa imara kiasi kwamba kwa miaka mia mbili iliyofuata ikawa lengo lisilobadilika la vita vya Ottoman-Iran.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Kuunganishwa kwa Karabağ na Gence", "29abaead"], "d": ["Kama ongezeko la mwisho la vita vya mashariki vya miaka kumi, Ferhad Paşa alielekea Gence mwaka 1588 na kuingia mjini tarehe 1 Septemba; eneo la Karabağ kati ya Kür na Aras na kitovu chake Gence viliingizwa chini ya utawala wa Ottoman. Hivyo Şirvan, Revan na Karabağ ziliungana na kuunda mstari wa Ottoman usiokatika Caucasus. Mkataba wa Ferhad Paşa uliotiwa saini 1590 ungethibitisha mpaka huu, lakini faida ingeweza kushikiliwa miaka ishirini tu.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Kutekwa kwa Bihaç", "651a7275"], "d": ["Beylerbeyi wa Bosnia Telli Hasan Paşa, baada ya kuchukua Ripaç, ngome ya mbele ya Bihaç, Novemba 1591, mwaka 1592 alichukua pia mji na ngome yenyewe; baada ya mzingiro wa siku kumi, kamanda Lamberg alisalimu amri. Ushindi huu uliusukuma mbele mpaka wa Bosnia kando ya mto Una na ukawa ongezeko kubwa la mwisho la Ottoman kabla ya Vita Virefu, vilivyolipuka mwaka mmoja baadaye Telli Hasan Paşa alipokufa shahidi mbele ya Kulpa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Kuanza kwa 'Vita Virefu' vya Ottoman-Austria", "bd22c392"], "d": ["Beylerbeyi wa Bosnia Telli Hasan Paşa aliposhindwa na kufa shahidi mbele ya Kulpa (Siszek), Dola ya Ottoman ilitangaza vita dhidi ya Austria na Vita Virefu vitakavyodumu miaka kumi na mitatu vilianza. Vita hivi, ambavyo askari wa miguu wenye silaha za moto walikuwa wa maamuzi, vilichochea ajira ya sekban na askari wenye bunduki katika mfumo wa jeshi la Ottoman na kuzidisha kudorora kwa sipahi wa tımar. Vita vingemalizika kwa Mkataba wa Zitvatorok mwaka 1606.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Paşa alielekea kampeni ya Austria — kampeni ya kwanza ya Vita Virefu", "d4a2f46d"], "d": ["Baada ya beylerbeyi wa Bosnia Hasan Paşa kushindwa na kufa shahidi mbele ya Siska (Sisak), sadrazam Koca Sinan Paşa, kwa maneno ya kung'aa na ahadi, alimshawishi sultani kwenda vitani na akaondoka na Yeniçeri 12.000 na vikosi vingine. Hivyo kampeni ya kwanza ya vita vya Ottoman-Austria vya miaka kumi na mitatu ilifunguliwa.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Kutekwa kwa Yanıkkale (Győr)", "14b75207"], "d": ["Sadrazam Koca Sinan Paşa, baada ya mzingiro uliodumu zaidi ya mwezi mmoja, alipokea Yanıkkale, iliyohesabiwa kuwa kufuli ya njia ya Viyana. Kuanguka kwa ngome kulizua hofu kubwa Ulaya na kukawa ongezeko la kung'aa zaidi la Ottoman katika Vita Virefu. Hata hivyo ngome ingeshikiliwa miaka minne tu.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Kifo cha III. Murad", "1b62e886"], "d": ["Baada ya utawala wa miaka ishirini na moja, III. Murad alifariki katika siku ambazo jeshi la Eflak lilichoma İbrâil na kufika Silistre, na akazikwa katika hazîra ya Ayasofya. Mwanawe III. Mehmed, aliyeitwa kutoka Manisa, alifika İstanbul siku kumi baadaye na kupanda kiti cha enzi (27 Januari 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Kupotea kwa Estergon kwa Austria", "f420d333"], "d": ["Walinzi wa Estergon, wasiopata msaada wa kutosha katika mzingiro ulioongozwa na Karl von Mansfeld, waliikabidhi ngome kwa Archduke Matthias. Kwa mwisho wa utawala wa Ottoman wa miaka hamsini na miwili, mnyororo wa ulinzi wa mstari wa Danube ulivunjika na Budin iliingia chini ya tishio la moja kwa moja. Ngome ingerudishwa miaka kumi baadaye tu, mwaka 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Kutekwa kwa Ngome ya Eğri", "3e511629"], "d": ["Baada ya mapambano ya wiki tatu, Ngome ya Eğri yenye nguvu, ambayo Waottoman walikuwa hawajaweza kuichukua hapo awali, ilianguka kwa walinzi kusalimu amri. Ushindi huu, uliofanyika sultani akiwepo mwenyewe, ulirekebisha kwa kiasi fulani ari iliyoharibiwa na kupotea kwa Estergon na mkoa wa Eğri uliundwa. Pamoja na ushindi wa Haçova uliopatikana wiki mbili baadaye, mwaka 1596 ukawa mwaka wenye mafanikio zaidi wa Ottoman katika Vita Virefu.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Kupotea kwa Yanıkkale (Győr)", "b4ccc679"], "d": ["Vikosi vilivyoongozwa na Miklós Pálffy na Adolf von Schwarzenberg vilirudisha Yanıkkale kwa shambulio, wakilipua milango ya ngome. Kupotea kwa ngome ambayo Koca Sinan Paşa alikuwa ameipata kwa juhudi kubwa miaka minne iliyopita kulibomoa mstari wa mbele wa Ottoman Hungaria. Ingawa vikosi vya adui vilivyozingira Budin mwaka huo huo vilirudishwa nyuma, mizani ya vita ilizidi kugeuka kuwa vita vya kuchosha.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Uasi wa Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, aliyekusanya sekban na levend waliokimbia jeshi katika Vita Virefu, alidhibiti eneo pana Anatolia ya Kati, akaichukua Ngome ya Urfa (Novemba 1599) na, akitangaza usultani wake kwa cheo cha 'Halim Şah', alituma amri zenye tuğra yake mwenyewe. Karayazıcı, anayehesabiwa kuwa kiongozi wa kwanza wa wimbi kubwa la Celâlî, alikufa mwaka 1602 na harakati yake iliendelezwa na kaka yake Deli Hasan. Uasi ni mwanzo wa kipindi cha 'kaçgunluk kuu' ambapo wakulima wa Anatolia waliiacha ardhi yao kwa umati.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Ulinzi wa Kanije wa Tiryaki Hasan Paşa", "d56a5e6a"], "d": ["Archduke Ferdinand na washirika wake, wakitaka kurudisha Kanije iliyochukuliwa mwaka mmoja kabla, walizingira ngome kwa zaidi ya miezi miwili; Tiryaki Hasan Paşa alipinga kwa kikosi chake cha watu 9000. Ingawa hakupata msaada kutoka nje, alirudisha nyuma mashambulizi ya jumla na, kwa operesheni za kutoka ngomeni, alimlazimisha adui kurudi akiwa amepata hasara kubwa. Ulinzi umekuwa hadithi ya kishujaa katika uandishi wa historia ya Ottoman na 'Kanije Muhasarası' imekuwa aina ya kifasihi kwa yenyewe.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Kifo cha III. Mehmed na kutawazwa kwa I. Ahmed", "da735fde"], "d": ["Kwa kifo cha III. Mehmed tarehe 20 Desemba, mwanawe I. Ahmed mwenye umri wa miaka kumi na minne alipanda kiti cha enzi. Kuwa sultani wa kwanza kukalia kiti akiwa mtoto na bila kutumwa sancak kunaonyesha kwamba mila ya kulelewa şehzade mikoani ilikuwa imekoma kwa vitendo. Katika utawala wa I. Ahmed, kuuawa kwa ndugu kuliachwa na kanuni ya 'ekberiyet' (mwanachama mkubwa zaidi wa kiume kupanda kiti) ingeanzishwa.", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Kurudishwa kwa Estergon", "7330f273"], "d": ["Sadrazam Lala Mehmed Paşa alizingira Estergon, iliyopotea miaka kumi iliyopita, na kuirudisha tena chini ya utawala wa Ottoman. Katika kampeni hiyo hiyo Peşte na Vaç pia ziliokolewa, na Ottoman ilirekebisha mstari wake Hungaria. Mafanikio haya yalifanya iwezekane kuketi mezani kwa nguvu kiasi huko Zitvatorok mwaka uliofuata; Estergon ingebaki mikononi mwa Ottoman hadi 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Ushindi wa Tambarare ya Oruç na kukandamizwa kwa uasi wa Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Paşa, aliyeanzisha beylik huru Halep na kutafuta muungano na Toskana, alishindwa vibaya na Sadrazam Kuyucu Murad Paşa kwenye Tambarare ya Oruç. Kwa kuanzishwa tena kwa mamlaka ya kati Syria, tawi hatari zaidi la wimbi la Celâlî lilivunjika. Usafishaji usio na huruma wa Kuyucu Murad Paşa wa miaka miwili, hata kwa muda, ulileta utulivu Anatolia.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Ushindi wa Alaçayır na kukandamizwa kwa uasi wa Kalenderoğlu", "55db0485"], "d": ["Kalenderoğlu, kiongozi wa Celâlî aliyetoza kodi maeneo ya Manisa na Bursa, alishindwa na Kuyucu Murad Paşa huko Alaçayır na alilazimika kukimbilia Iran. Kwa ushindi huu, jeshi la mwisho kati ya majeshi makubwa ya Celâlî Anatolia lilitawanywa. Usafishaji mkali wa Kuyucu Murad Paşa, anayesimuliwa kuwajaza waasi aliowauwa kwenye visima alivyovichimbisha, ingawa ulileta utulivu kwa muda mfupi, haukuweza kufidia upotevu wa idadi ya watu na uzalishaji wa Anatolia.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Kutolewa kwa ahidnâme ya kwanza kwa Uholanzi", "5d9d117e"], "d": ["Cornelis Haga, mjumbe wa Jamhuri ya Muungano ya Uholanzi, aliweza kupata kutoka kwa I. Ahmed ahidnâme yenye wigo sawa na zile zilizotolewa kwa Ufaransa na Uingereza. Uholanzi hivyo ilipata haki ya kufungua ubalozi İstanbul, ukonsuli katika bandari za Ottoman na kufanya biashara kwa bendera yake mwenyewe. Ahidnâme hii inaashiria kuingia kwa madola ya kaskazini ya baharini, yaliyochukua nafasi ya Venice katika biashara ya Mediterania, kwenye soko la Ottoman.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Kifo cha I. Ahmed na kutawazwa kwa I. Mustafa — utaratibu wa ekberiyet", "9901c09e"], "d": ["Baada ya ugonjwa wa tumbo wa siku hamsini na moja, I. Ahmed mwenye umri wa miaka ishirini na minane alifariki na kaka yake I. Mustafa alipandishwa kwenye kiti badala ya mwanawe. Hivyo utaratibu wa urithi wa baba kwenda mwana uliachwa na mfumo wa 'ekberiyet' ambapo mwanachama mkubwa zaidi wa kiume wa nasaba hupanda kiti ulianzishwa kwa vitendo. Utawala huu wa kwanza wa siku tisini na sita pia ni mwanzo wa enzi ya kulelewa şehzade 'kafesini'.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Kuondolewa kwa I. Mustafa na kutawazwa kwa Genç Osman (II. Osman)", "e0f552f2"], "d": ["Kwa kisingizio kwamba afya yake ya akili haikuwa sawa, I. Mustafa aliondolewa kwenye kiti baada ya siku tisini na sita na II. Osman, mwana wa I. Ahmed mwenye umri wa miaka kumi na minne, alikuwa sultani. Kwa mujibu wa simulizi inayomtegemea Hasanbeyzâde, Kızlar Ağası Mustafa Ağa alikuwa na ushawishi katika uamuzi huu wa kumwondoa. Genç Osman, kwa mpango wake wa kukomesha ocak ya Yeniçeri na kuunda jeshi jipya, anahesabiwa kuwa jina la kwanza lenye msimamo mkali katika mijadala ya mageuzi ya Ottoman. Mpango huu ungegharimu maisha yake mwenyewe miaka minne baadaye.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Mkataba wa Serav — kufanywa upya kwa amani na Iran", "e778aca8"], "d": ["Mkataba wa Serav uliofikiwa na Iran baada ya kushindwa kwa Pül-i Şikeste kwa kiasi kikubwa ulithibitisha masharti ya Mkataba wa Nasuh Paşa wa 1612; kiasi cha hariri ambacho Wasafavî wangetuma kila mwaka kilipunguzwa kutoka mizigo mia mbili hadi mia moja. Hivyo awamu ya pili ya vita vya mashariki vilivyodumu tangu 1603 ilifungwa. Amani haingekuwa ya muda mrefu; kwa kupotea kwa Bağdat mwaka 1623 vita vingewaka tena.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Kampeni ya Hotin na Mkataba wa Hotin", "bc4c823c"], "d": ["Dhidi ya jeshi kubwa lililoongozwa na II. Osman mwenyewe, kambi yenye ngome ambayo Chodkiewicz aliiweka mbele ya Hotin haikuweza kuvukwa na hakuna matokeo yaliyopatikana baada ya mashambulizi ya miezi kadhaa. Kwa mkataba uliotiwa saini tarehe 9 Oktoba, mto Dinyester ulikubaliwa kuwa mpaka, na Wapolandi waliahidi kuzuia mashambulizi ya Wakazak. Ingawa ilitangazwa kama ushindi, kampeni isiyozaa matokeo iliimarisha kutoamini kwa sultani kijana kwa Yeniçeri na nia yake ya kusafisha ocak.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Kuchukuliwa kwa Hormuz kutoka kwa Wareno", "93e5f6cf"], "d": ["Vikosi vya Safavi vilizingira Hormuz, iliyokuwa mikononi mwa Ureno tangu 1515, na kuirudisha; Kişm na Gamrûn (Bender Abbas) kwenye pwani pia zilipita chini ya utawala wa Safavi na biashara ya Ghuba ikahamia bandari mpya.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Kuondolewa kwa mara ya pili kwa I. Mustafa na kutawazwa kwa IV. Murad", "1b3a9e74"], "d": ["I. Mustafa, aliyepandishwa kwenye kiti kwa mara ya pili baada ya kuuawa kwa II. Osman, aliondolewa tena baada ya mwaka mmoja na miezi mitatu, na IV. Murad mwenye umri wa miaka kumi na mmoja alitangazwa sultani. Kwa miaka tisa ya kwanza dola ilitawaliwa kwa vitendo na mama yake Kösem Sultan na wakuu wa ikulu. IV. Murad, kuanzia 1632, angechukua utawala mwenyewe na kuanzisha kipindi cha ukali wa uwekaji kati.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Kupotea kwa Bağdat kwa Wasafavî", "db81be0c"], "d": ["Kufuatia mazungumzo ya Bekir Subaşı, aliyeasi Bağdat, na Wasafavî, mwanawe Derviş Mehmed, aliyekuwa akilinda ngome ya ndani, aliukabidhi mji kwa vikosi vya Şah Abbas. Kupotea kwa mojawapo ya miji ya ishara ya urithi wa ukhalifa na sehemu kubwa ya Iraq kuliamsha hasira kubwa İstanbul. Kurudisha Bağdat kungekuwa lengo pekee la sera ya mashariki ya Ottoman kwa miaka kumi na tano.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Kukandamizwa kwa uasi wa Abaza Mehmed Paşa wenye kitovu cha Erzurum", "e6da2729"], "d": ["Abaza Mehmed Paşa, Beylerbeyi wa Erzurum aliyeasi dhidi ya Yeniçeri kwa madai ya kulipiza kisasi kuuawa kwa II. Osman, alishikilia Anatolia Mashariki chini ya udhibiti wake kwa miaka na alipinga serikali kuu. Kwa mzingiro wa Erzurum wa Sadrazam Hüsrev Paşa alilazimika kusalimu amri, alisamehewa na kuteuliwa Bosnia. Kumalizika kwa uasi kulikuwa sharti la awali ili IV. Murad aweze kwenda kampeni dhidi ya Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Kuuawa kwa şeyhülislâm wa kwanza: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Şeyhülislâm Ahîzâde Hüseyin Efendi aliuawa karibu na Büyükçekmece kwa sababu zilizotajwa za kufanya usuluhishi katika machafuko ya kijeshi na kumtumia sultani onyo la maandishi kuhusu utaratibu wa kimahakama. Kuwa şeyhülislâm wa kwanza wa Ottoman kuuawa kulivunja mapokeo ya zamani kwamba adhabu kali zaidi kwa wanachama wa ilmiye ilikuwa uhamisho. Tukio linahesabiwa kuwa ishara ya ugumu wa mamlaka ya IV. Murad na kuvurugika kwa mizani kati ya dola na maulamaa.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Ushindi wa Revan wa IV. Murad", "b65a9b73"], "d": ["IV. Murad, aliyeondoka İstanbul tarehe 28 Machi 1635, alizingira Revan tarehe 28-29 Julai na akapokea ngome tarehe 8 Agosti; kisha aliingia Tebriz iliyoachwa na kuamuru mji uharibiwe. Sultani alijenga Revan Köşkü katika Ikulu ya Topkapı kwa kumbukumbu ya ushindi. Kampeni hii ilikuwa operesheni ya kwanza kubwa ya mashariki baada ya pengo la miaka thelathini ambapo sultani aliliongoza jeshi mwenyewe.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Kupotea kwa Revan kwa Wasafavî", "fbb8dd25"], "d": ["Baada ya jeshi la Ottoman kuondoka, vikosi vya Şah Safî vilizingira Revan na kuirudisha ndani ya miezi minane. Kupotea kwa ngome kwa haraka hivyo kulionyesha jinsi ilivyokuwa vigumu kiusafirishaji kuwa na utawala wa kudumu Caucasus. Revan, kwa Mkataba wa Kasr-ı Şirin wa 1639, pia ingeachwa Iran na Ottoman ingeachana na madai yake ya Azerbaijan.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Kutekwa tena kwa Bağdat", "4d2f27f3"], "d": ["IV. Murad, aliyeondoka İstanbul tarehe 8 Mei 1638, alirudisha Bağdat iliyokuwa mikononi mwa Wasafavî kwa miaka kumi na mitano baada ya mzingiro mkali wa siku arobaini; katika mzingiro Vezir Tayyar Mehmed Paşa alikufa shahidi. Kwa ushindi wa mji, utawala wa Ottoman Iraq ulianzishwa tena na sultani alipokea cheo cha 'Mshindi wa Bağdat'. Ushindi, kwa Mkataba wa Kasr-ı Şirin wa mwaka uliofuata, ulifanywa wa kudumu na kuweka msingi wa mpaka wa leo kati ya Uturuki na Iran.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Kifo cha IV. Murad na kutawazwa kwa Sultan İbrahim", "e2ca1ca0"], "d": ["Baada ya IV. Murad, aliyefariki akiwa na umri wa miaka ishirini na saba (ishirini na minane kwa hesabu ya hijria), kaka yake İbrahim, mwanachama pekee wa kiume aliyebaki hai wa nasaba, alipanda kiti. Katika utawala wa sultani mpya, aliyeishi miaka mingi kafesini, matumizi ya ikulu na mapambano ya ushawishi ndani ya ikulu yalitikisa utaratibu wa dola. Kwa kuondolewa kwake na kuuawa miaka minane baadaye, kuuawa kwa pili kwa sultani katika historia ya Ottoman kulitokea.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Kurudishwa kwa Ngome ya Azak kutoka kwa Wakazak", "e5fcf160"], "d": ["Ngome ya Azak, iliyochukuliwa na Wakazak wa Don mwaka 1637, iliachwa mbele ya operesheni ya pamoja ya Sultanzâde Mehmed Paşa na Han wa Kırım IV. Mehmed Giray; Wakazak walichoma ngome na kuondoka. Kurudishwa kwa mlango wa kaskazini wa Bahari Nyeusi kulifunga kipindi hatari ambapo mashambulizi ya Wakazak yalifika hadi Boğaz ya İstanbul. Ngome ingepotezwa mwaka 1696 kwa Tsar wa Urusi I. Petro.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Kuanza kwa kampeni ya Krete na kutekwa kwa Hanya", "a1b0c77f"], "d": ["Kwa kisingizio cha maharamia wa Malta kupiga meli ya hajj ya Ottoman na kukimbilia Krete, vita vilitangazwa dhidi ya Venice na meli chini ya amri ya Yûsuf Paşa zilituma askari kisiwani. Baada ya mzingiro wa siku hamsini na nne ngome ya Hanya ilichukuliwa na kituo cha kwanza cha kudumu cha Ottoman Krete kilianzishwa. Hivyo vita virefu zaidi katika historia ya Ottoman vilianza; kisiwa kingeweza kutekwa kikamilifu miaka ishirini na nne baadaye tu, mwaka 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Kutekwa kwa Resmo — kugawanywa kwa Krete mara mbili", "8f2c4353"], "d": ["Mwaka mmoja baada ya kuchukuliwa kwa Hanya, ngome ya Resmo katikati ya kisiwa nayo ilianguka na nusu ya magharibi ya Krete iliingia kabisa chini ya utawala wa Ottoman. Venice ilibaki na mji mkuu Kandiye pekee na ncha ya mashariki; kisiwa kiliishi kikiwa kimegawanywa mara mbili kwa miaka ishirini na mitatu. Kuchukuliwa kwa Resmo kulikuwa hatua iliyoanzisha mzingiro wa Kandiye — mzingiro mrefu zaidi katika historia ulianza hapa.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Kupotea kwa Klis kwa Venice", "5473c22c"], "d": ["Katika mstari wa Dalmatia wa Vita vya Krete (Kandiye), shambulio la kukabiliana la kamanda wa Venice Leonardo Foscolo lilijumuisha pia Klis, kitovu cha sancak tangu 1537; ngome ilipita kwa Venice. Ottoman kuelekeza nguvu zake zote Krete kulifanya kurudishwa kwa upotevu huu kwenye mpaka wa Dalmatia kutowezekana — Klis haingerudi tena chini ya utawala wa Ottoman; kitovu cha sancak kilihamishiwa Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Kuanza kwa mzingiro wa Kandiye", "13016b10"], "d": ["Baada ya kuchukuliwa kwa Hanya na Resmo, jeshi la Ottoman liliweka chini ya mzingiro Kandiye, kituo kikuu cha mwisho cha Venice kisiwani. Kizuizi hiki kitakachodumu miaka ishirini na mmoja kiliandikwa kama mojawapo ya mizingiro mirefu zaidi katika historia ya kijeshi ya dunia. Wakati wa mzingiro, majaribio ya meli za Venice kuufunga Mlangobahari wa Çanakkale yangeleta vita hadi kiini cha Aegean.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Kuuawa kwa Büyük Vâlide Kösem Sultan", "9d763f79"], "d": ["Kösem Sultan, mwenye umri wa takriban miaka sitini na miwili, alipatikana katika chumba cha Harem na kuuawa na Başlala Uzun Süleyman Ağa na watu wake waliokuwa wakitenda kwa amri ya Turhan Sultan, mama wa IV. Mehmed. Kifo cha mwanamke huyu mwenye nguvu wa nasaba, aliyeongoza siasa za dola katika enzi za masultani watatu, kinahesabiwa kuwa mwisho wa kivitendo wa kipindi kiitwacho 'Usultani wa Wanawake'. Mamlaka iliyobaki wazi ilifungua njia ya Köprülü Mehmed Paşa kuwa sadrazam kwa mamlaka ya kipekee miaka mitano baadaye.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Kushindwa kwa Çanakkale na kupotea kwa Bozcaada na Limni", "e01a1f7e"], "d": ["Ushindi mkubwa wa majini ulioupata admirali wa Venice Mocenigo mbele ya Mlangobahari wa Çanakkale Juni 1656 uliangamiza karibu kabisa meli za Ottoman; kisha Bozcaada, Limni na Semadirek zilivamiwa. Kwa mlangobahari kuingia chini ya kizuizi cha Venice, bei za chakula İstanbul zilipanda na hofu ya shambulio kwenye mji mkuu ilienea. Janga hili lilikuwa sababu ya moja kwa moja ya Köprülü Mehmed Paşa kufanywa sadrazam kwa masharti na mamlaka ya kipekee Septemba 1656.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Ushindi wa Çanakkale na kurudishwa kwa Bozcaada", "603da863"], "d": ["Meli zilizokusanywa na Köprülü Mehmed Paşa zilishinda kundi la meli za Venice mbele ya Boğaz tarehe 19 Julai 1657; kisha vikosi chini ya amri ya Kurd Paşa vilirudisha Bozcaada tarehe 25 Agosti na tarehe 30 Agosti Wavenice waliondoka kisiwani kabisa. Mwezi Novemba Limni nayo iliokolewa, kizuizi cha Çanakkale kilivunjwa na njia ya chakula ya İstanbul ilifunguka tena. Köprülü alivuka mwenyewe kisiwani na kuamuru ngome zirekebishwe; mafanikio haya ni ongezeko la kwanza kubwa la kijeshi la enzi ya Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["Kurudishwa kwa Limni kutoka Venice", "a4c3c69b"], "d": ["Limni, iliyochukuliwa na Venice Julai 1656, ilirudi Ottoman Novemba 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Kutekwa kwa Yanova (Ineu) na kampeni ya Transylvania", "d1089616"], "d": ["Köprülü Mehmed Paşa, aliyeenda kampeni kumwadhibu Mfalme wa Transylvania II. György Rákóczi, aliyevunja ulinzi wa Ottoman kwa kwenda kampeni ya Poland bila ruhusa, alipitia Belgrad na kuchukua ngome ya kimkakati ya Yanova. Mfalme mpya aliteuliwa Transylvania na uhusiano wa ubaraka ulikumbushwa kwa ukali. Kampeni hii ilikuwa kiungo cha kwanza cha jaribio la Ottoman kuanzisha tena mamlaka yake Ulaya ya Kati. Transylvania ilikuwa tayari utawala wa kifalme tegemezi kwa Ottoman; kuchukuliwa kwa Yanova hakukuwa ushindi kutoka dola ya kigeni, bali ni kuondoa ngome hii ya Transylvania tegemezi kutoka utawala wa kifalme na kuiunganisha moja kwa moja na sancak ya Ottoman; sehemu iliyobaki ya utawala wa kifalme ilibaki katika hadhi ya utegemezi.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Kukandamizwa kwa uasi wa Abaza Hasan Paşa", "4ba74321"], "d": ["Abaza Hasan Paşa, aliyewaunga nyuma beylerbeyi wa Anatolia na maağa wa sekban dhidi ya usafishaji mkali wa Köprülü Mehmed Paşa, alianzisha uasi mkubwa akidai kuondolewa kwa sadrazam. Uasi ulikandamizwa Halep na viongozi wake kuondolewa; huu ukawa upinzani wa mwisho wa pamoja wa mapaşa wa mikoani dhidi ya serikali kuu. Mamlaka ya Köprülü hivyo yakawa hayana mjadala na wadhifa wa usadrazam ulipanda tena kuwa kitovu halisi cha utendaji wa dola.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Kutekwa kwa Varad (Oradea)", "0e6ad300"], "d": ["Ngome na mji wa Varad ulichukuliwa katika mfumo wa kampeni iliyoandaliwa dhidi ya Mfalme wa Transylvania II. György Rákóczi, aliyetangaza vita dhidi ya Ottoman. Kwa kuanguka kwa mojawapo ya ngome kuu za Transylvania, mkoa mpya wa Ottoman (Mkoa wa Varad) uliundwa eneo hilo. Ushindi ulizitia tahadhari Wahabsburg na ukawa mojawapo ya sababu za moja kwa moja za vita vya Ottoman-Austria vitakavyoanza miaka mitatu baadaye. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Varat. Hapa pia ardhi haikuchukuliwa kutoka dola ya kigeni: Transylvania ilikuwa tayari utawala wa kifalme tegemezi wa Ottoman; kufanywa mkoa kwa Varad kulichukua tu utawala wa mji huu kutoka utawala wa kifalme tegemezi na kuufunga moja kwa moja na sultani, kama ilivyokuwa Yanova miaka miwili iliyopita.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Vita vya Sen Gotar (St. Gotthard)", "61ebc1f2"], "d": ["Vikosi vya Ottoman vilivyovuka mto Raab vilisimamishwa na jeshi la pamoja la Ulaya chini ya amri ya Montecuccoli na vilipata hasara kubwa. Vita vinahesabiwa kuwa mwamba wa mabadiliko katika historia ya kijeshi kwa kuonyesha wazi kwa mara ya kwanza ubora wa risasi za bunduki za askari wa miguu wenye nidhamu juu ya shambulio la wapanda farasi wa Ottoman. Licha ya kushindwa, Ottoman iliweza kupata masharti yenye faida katika Mkataba wa Vasvar uliotiwa saini siku tisa baadaye.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Mkataba wa Vasvar", "089c978c"], "d": ["Mkataba uliotiwa saini licha ya kushindwa kwa Sen Gotar ulihukumu kwamba Uyvar na Varad zibaki kwa Ottoman, Transylvania iachwe isiyoegemea upande chini ya ulinzi wa Ottoman na Austria ilipe 'zawadi' ya kuruş 200.000. Amani hii ya miaka ishirini ni mojawapo ya mifano adimu ambapo upande uliopoteza vita ulishinda mezani. Kutoridhika kulikoanzishwa na mkataba katika maoni ya umma ya Habsburg kungelisha harakati ya Hungaria ya Kati na, isivyo moja kwa moja, kampeni ya Viyana ya 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Kuanza kwa utawala wa dayı Cezayir", "e99faa51"], "d": ["Ocak ya Cezayir na taife-i reîs (manahodha wa maharamia) walimwondoa ağa wa mwisho na kumchagua Hacı Mehmed kuwa dayı kwa sharti la maisha. Baada ya tarehe hii Cezayir haikutawaliwa na beylerbeyi aliyeteuliwa na İstanbul, bali na dayı aliyechaguliwa na ocak ya wenyeji kutoka ndani yake; uhusiano wa Ottoman ulibaki ukiwa umepunguzwa kwa kusomwa kwa jina la sultani kwenye khutba, bendera na wajibu wa kampeni. Cezayir hivyo iligeuka kutoka mkoa kuwa ocaklık — mabadiliko hayo hayo yalipitiwa na Tunis mwaka 1705 kwa Wahüseynî, na Trablusgarp mwaka 1711 kwa Wakaramanlı.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Kampeni ya Poland ilianza — IV. Mehmed na Fâzıl Ahmed Paşa kichwani mwa jeshi", "75e15a39"], "d": ["Mashambulizi ya Poland dhidi ya hetman wa Ukraine Petro Doroşenko, aliyeingia chini ya ulinzi wa Ottoman, yalipoendelea, İstanbul ilimtaka mfalme wa Poland aache mashambulizi; jibu chanya lisipofika, uamuzi wa kampeni dhidi ya Poland ulichukuliwa. Vezîriâzam Fâzıl Ahmed Paşa, pamoja na jeshi ambalo sultani pia alikuwa nalo, aliondoka kuelekea Poland tarehe 4 Juni 1672. Kampeni ingemalizika kwa kutekwa kwa Kamaniçe na Mkataba wa Bucaş.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Kutekwa kwa Kamaniçe na kuundwa kwa Mkoa wa Podolya", "c3f4f6d0"], "d": ["Baada ya mzingiro wa siku tisa, Kamaniçe, iliyohesabiwa kuwa ngome yenye nguvu zaidi ya Poland mashariki, ilipokelewa; IV. Mehmed alisali Swala ya kwanza ya Ijumaa tarehe 2 Septemba kwenye msikiti uliogeuzwa kutoka kanisa kuu. Ngome ilifanywa kitovu na Mkoa wa Podolya uliundwa, na bendera ya Ottoman ilifika kaskazini zaidi katika ardhi za Ukraine ya leo. Kamaniçe ingebaki kama ncha ya kaskazini-magharibi ya dola hadi Mkataba wa Karlofça wa 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Paşa alipokea Uman kutoka Poland", "0d3543a0"], "d": ["Kara Mustafa Paşa, aliyetumwa dhidi ya Poland, alipokea Uman, mojawapo ya ngome zilizokuwa mikononi mwa Poland; mji ulibaki chini ya utawala wa Ottoman hadi Karlofça.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Kutekwa kwa Ngome ya Çehrin", "a17cedd0"], "d": ["Baada ya operesheni ya mwaka uliopita ambayo Melek İbrahim Paşa hakuweza kupata matokeo, Sadrazam Merzifonlu Kara Mustafa Paşa, akiamuru mwenyewe, aliizingira Ngome ya Çehrin yenye ngome (19/21 Julai) na akaichukua tarehe 21 Agosti. Kuanguka kwa ngome, ishara ya ushindani wa Ottoman-Urusi juu ya hetmanlık ya Wakazak Ukraine, kuliilazimisha Urusi kwenye amani. Mafanikio haya pia yalikuwa mojawapo ya vyanzo vya kujiamini kwa Merzifonlu kulikokuwa kunaelekea Viyana.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Mkataba wa Bahçesaray — amani ya kwanza rasmi na Urusi", "df82bc0b"], "d": ["Mwishoni mwa mazungumzo yaliyofanywa kwa upatanishi wa Han wa Kırım baada ya kampeni za Çehrin, amani ya miaka ishirini ilitiwa saini kati ya Dola ya Ottoman na Urusi kwa mto Özü (Dinyeper) kukubaliwa kuwa mpaka. Hii inahesabiwa kuwa waraka wa mwanzo wa mahusiano ya Ottoman-Urusi kwa kuwa mkataba wa kwanza kamili kati ya dola hizo mbili. Kwa amani, mstari wa mashariki ulifanywa salama na jeshi liliweza kuelekezwa Ulaya ya Kati.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Kupewa kwa Tököli İmre berat ya ufalme wa Hungaria ya Kati", "3cd8d51d"], "d": ["Tököli İmre, mkuu wa Kiprotestanti wa Hungaria aliyeasi dhidi ya shinikizo la Habsburg, alianza kuhesabiwa 'mfalme mteule wa Hungaria ya Kati' tangu Aprili 1682, na tarehe 16 Septemba Beylerbeyi wa Budin İbrahim Paşa alimkabidhi alama za utawala wa kifalme. Hivyo dola mpya ya Kihungaria kibaraka chini ya ulinzi wa Ottoman iliundwa. Uingiliaji huu, kwa kufanya vita na Austria visiweze kuepukika, ulianzisha mnyororo uliokwenda kwenye Mzingiro wa Pili wa Viyana wa mwaka uliofuata.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Kupotea kwa Ayamavra (Lefkada) kwa Venice", "e6905fee"], "d": ["Meli za Venice, iliyojiunga na Muungano Mtakatifu, baada ya kuupiga mji kwa mizinga, zilivamia Kisiwa cha Ayamavra katika Bahari ya İyon. Mwaka huo huo, kwa kuanguka kwa Preveze pia, udhibiti wa Ottoman kwenye mdomo wa Adriatic ulivunjika. Hasara hizi zilikuwa hatua za mwanzo za operesheni ambayo Morosini angechukua Mora yote ndani ya miaka mitatu.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Kupotea kwa Koron kwa Venice", "2ed762bc"], "d": ["Vikosi vya Venice chini ya amri ya Morosini vilichukua ngome ya Koron kwenye ncha ya kusini-magharibi ya peninsula ya Mora; mji ungebaki chini ya utawala wa Venice kwa miaka thelathini baadaye. Kuanguka kwa Koron kulikuwa ongezeko la kwanza kubwa la operesheni ya Venice kuelekea ushindi wa Mora. Ngome ingeweza kurudishwa mwaka 1715 tu na jeshi la Ottoman chini ya amri ya Silâhdar Ali Paşa.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Kurudishwa kwa Athens — Venice kujiondoa", "03393b46"], "d": ["Morosini, aliyeipiga Acropolis kwa mizinga mwezi Septemba 1687 na kulipua Parthenon, baada ya kukaa majira ya baridi Athens aligundua kwamba hawezi kushikilia mjini. Kwa mlipuko wa tauni, ugumu wa usambazaji na kupona kwa vikosi vya Ottoman, kikosi cha Venice kiliuacha mji na kurudi Mora. Athens hivyo ilirudi chini ya utawala wa Ottoman bila kupigana, lakini uharibifu uliopata Parthenon haukuweza kurudishwa.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) yajisalimisha kwa Caraffa — yapita mikononi mwa Austria", "7f0a8d38"], "d": ["Baada ya kuzingirwa kwa siku tatu na Antonio Caraffa, Lipova ilijisalimisha kati ya tarehe 12-22 Juni 1688 na ikapita mikononi mwa Austria. Waottoman baadaye walirudisha mji, Austria iliuchukua tena mwaka 1691; katika msafara wa 1695 Ottoman ilipata tena udhibiti. Makazi mengine yaliyopita kutoka Ottoman hadi Habsburg tarehe hiyo hiyo katika atlasi: Arad na Világos (Şiria). Kwa Arad chanzo kinatoa mwaka tu (MKL, Arad: mikononi mwa Ottoman kati ya 1551-1688); siku imechukuliwa kutoka Lipova, Világos hufuata mnyororo wa Arad (makadirio yaliyotangazwa).", "0dfcf5af"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Kurudishwa nyuma kwa mzingiro wa Venice wa Eğriboz", "aae7e6a0"], "d": ["Morosini, aliyeelekea Aegean baada ya kuchukua Mora, alijaribu kuchukua Eğriboz kwa mzingiro wa zaidi ya miezi mitatu; hata hivyo, mbele ya ngome iliyoimarishwa katika majira ya baridi ya 1687-1688 na upinzani wa kikosi, alilazimika kurudi akiwa amepata hasara kubwa. Kushindwa huku kulisimamisha kusonga mbele kwa Venice Aegean na kutikisa heshima ya kijeshi ya Morosini. Eğriboz ingebaki mikononi mwa Ottoman pia huko Karlofça.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Kupotea kwa Ngome ya Kanije kwa Austria", "553b45f3"], "d": ["Kanije, iliyowekwa chini ya kizuizi kikali cha jeshi la Habsburg la watu 60.000 tangu Januari 1690, baada ya kupinga kwa miezi bila kupata msaada, ilipotea kwa makubaliano ya kusalimu amri yaliyotiwa saini na mlinzi wake wa mwisho Mustafa Paşa. Hivyo utawala wa Ottoman wa miaka tisini kwenye ngome inayokumbukwa kwa ulinzi wa kishujaa wa Tiryaki Hasan Paşa ulimalizika. Kupotea kwa Kanije kulikuwa kuanguka kwa kituo kikuu cha mwisho cha Ottoman magharibi mwa Hungaria.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Kifo cha II. Süleyman", "d2478080"], "d": ["II. Süleyman, aliyewekwa kiti cha enzi mwaka 1687 baada ya takriban miaka arobaini kafesini, alifariki Edirne mnamo Ijumaa tarehe 22 Juni 1691 karibu na adhuhuri alipokuwa mgonjwa akifuatilia maandalizi ya jeshi; utawala wake ulidumu miaka mitatu, miezi minane na siku mbili. Sadrazam alikuwa ametoa mapema maagizo yaliyohitajika ili ndugu yake Ahmed asimikwe kiti cha enzi endapo sultani atakufa. Swala ya mazishi ilisaliwa siku hiyo hiyo katika Alay Köşkü; mwili wake ulileta Istanbul na kuzikwa katika kaburi la Kanûnî Sultan Süleyman, upande wa kulia wake.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Kupanda kiti cha enzi kwa II. Ahmed", "52947b14"], "d": ["Kwa kifo cha II. Süleyman, kaka yake II. Ahmed mwenye umri wa miaka arobaini na tisa alipanda kiti Edirne. Utawala wake ulilingana na miaka mizito zaidi ya vita vya Muungano Mtakatifu; miezi miwili baada ya kutawazwa kwake, Sadrazam Fâzıl Mustafa Paşa alikufa shahidi Salankamen. Kwa upande mwingine, mfumo wa mâlikâne uliowekwa katika enzi yake ukawa mojawapo ya mipangilio muhimu zaidi iliyobadilisha muundo wa muda mrefu wa fedha za Ottoman.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Kifo cha IV. Mehmed Edirne", "17388b7e"], "d": ["Avcı Mehmed, aliyeondolewa kwenye kiti cha enzi mwaka 1687, alipelekwa Edirne wakati wa msafara wa Hungaria wa II. Süleyman wa 1689 na pia alishuhudia utawala wa ndugu mwingine II. Ahmed. Alifariki katika mji huu aliokuwa akiupenda sana. Mwili wake ulileta Istanbul na kuzikwa katika kaburi la mama yake Turhan Sultan karibu na Yenicami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Kifo cha II. Ahmed Edirne", "c6306c08"], "d": ["II. Ahmed, ambaye utawala wake wa miaka minne ulipita vitani, alifariki Edirne akiwa na umri wa miaka hamsini na miwili kwa istiskā (uvimbe wa maji). Mwili wake ulileta Istanbul na kuzikwa katika kaburi la Kanûnî Sultan Süleyman. Mpwa wake II. Mustafa alimrithi.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Kuchukuliwa kwa Basra na Wairani", "a9cdf3a3"], "d": ["Dola ya Ottoman ilipokuwa ikishughulika na vita vya Muungano Mtakatifu magharibi, Basra, baada ya mlipuko wa tauni wa 1690, ilikuwa imeporwa kwanza na şeyh wa Müntefik Mâni, kisha na Han wa Huveyze Ferecullah. Wairani, wakitumia machafuko haya, walichukua mji mwaka 1696 na wakaacha kikosi cha walinzi Basra.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Mkataba wa İstanbul — kuachiwa kwa Azak kwa Urusi", "79db4724"], "d": ["Huko Karlofça ilikuwa imewezekana kufanya mapatano ya miaka miwili tu na Urusi; amani ya kudumu ilitiwa saini İstanbul baada ya mazungumzo magumu ya mwaka mmoja na nusu. Dola ya Ottoman iliiacha rasmi kwa Urusi Ngome ya Azak iliyoipoteza mwaka 1696 na ardhi zinazoizunguka, na ikaacha kodi ya kila mwaka ambayo han wa Kırım alipokea kutoka Moscow. Kwa upande mwingine, Urusi ilipata haki ya kuwa na mjumbe wa kudumu İstanbul; hivyo uwepo wa Urusi kwenye pwani ya kaskazini ya Bahari Nyeusi ulithibitishwa kisheria.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Paşa kurudisha Kürne na Basra", "7adb777d"], "d": ["Daltaban Mustafa Paşa, aliyeteuliwa ugavana wa Bağdat na seraskerlik ya Basra baada ya Mkataba wa Karlofça, alisonga kusini na vikosi vya Halep, Rakka, Sivas na Karaman na meli za mtoni zilizoshuka kutoka Birecik. Mashehe wa makabila ya jirani walitii moja moja, mlinzi wa Kiirani wa Basra Dâvud Han aliuacha mji, na Kürne na Basra ziliingia tena chini ya utawala wa Ottoman.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Kifo cha II. Mustafa", "626c394d"], "d": ["II. Mustafa, aliyeachia kiti cha enzi kwa ndugu yake III. Ahmed kwa Tukio la Edirne, alifariki katika Edirne aliyokuwa akiipenda sana karibu miezi mitano baada ya kuondolewa kwenye kiti cha enzi. Huzuni ya matukio ya hivi karibuni ilikuwa imeongezwa kwenye ugonjwa wake. Baadhi ya vyanzo vya Magharibi vinaandika kwamba imani ya kwamba alitiwa sumu ilikuwa imeenea miongoni mwa watu.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Kuanza kwa utawala wa Kölemen (Memlûk) Bağdat", "abe52618"], "d": ["Kwa Hasan Paşa wa asili ya Kijojia kuteuliwa kwenye ugavana wa Bağdat, kipindi kilianza ambapo Iraq ilitawaliwa na tabaka la watawala lililokulia kutoka kwa watumwa wao wenyewe badala ya magavana walioteuliwa kutoka kituo. Kwa ugavana wa Süleyman Paşa mwaka 1749 mfumo ulizidi kuimarika na Bâbıâli ililazimika kuteua mmoja wa kölemen waliokuwa wamechukua ushawishi, si mtu iliyemtaka. Ingawa muundo huu wa nusu uhuru wa ndani ulifaa katika kulinda mpaka wa Iran, ulidhoofisha udhibiti wa mamlaka kuu juu ya Iraq kwa karne moja na nusu.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Kuanzishwa kwa nasaba ya Hüseynî Tunis", "cb1a98f9"], "d": ["Katika pengo la mamlaka lililotokea kwa uvamizi wa vikosi vya Cezayir Tunis, Hüseyin b. Ali, sipahi ağası wa asili ya Kituruki, alichukua beylik na kupata uhalali kwa kutangaza utii kwa sultani wa Ottoman. Nasaba aliyoianzisha ilitawala Tunis kati ya 1705-1735 na 1756-1957; utaratibu wa beylik wa baba kwenda mwana ulichukua nafasi ya utawala wa ocak. Hivyo mfano wa kwanza wa miundo ya nasaba iliyo tegemezi kwa kituo lakini yenye uhuru wa ndani kwa vitendo katika ocak za Magharibi ulizaliwa.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Kuchukuliwa kwa Vahran (Oran) na Mersalkebîr kutoka kwa Wahispania", "b67ce06a"], "d": ["Vikosi vya beylerbeyi wa Ocak ya Cezayir, baada ya mzingiro mrefu, vilichukua Vahran, iliyokuwa mikononi mwa kikosi cha Kihispania kwa karne mbili, na bandari ya Mersalkebîr. Ulikuwa mafanikio makubwa zaidi ya ocak za Magharibi chini ya ulinzi wa Ottoman dhidi ya Uhispania Mediterania ya Magharibi na ulihakikisha ubavu wa magharibi wa Cezayir. Mji ungevamiwa tena na Wahispania mwaka 1732, lakini ungerudishwa kwa uhakika mwaka 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Mkataba wa Prut — kurudishwa kwa Azak na Taygan", "bac5d2a1"], "d": ["Mkataba wa vifungu saba uliotiwa saini jeshi la Urusi lililozingirwa kando ya Prut liliposalimu amri uliamua kurudishwa kwa Ngome ya Azak kwa Ottoman pamoja na ardhi yake na silaha. Ngome za Taygan, Kamenka na Yenikale zingebomolewa na pande hazingejenga ngome mpya katika maeneo haya. Utaratibu wa meli na kituo ambao I. Petro alijenga kwa miaka kumi na sita Voronej na Azak ulianguka; kushuka kwa Urusi kwenye Bahari Nyeusi kulichelewa takriban miaka hamsini.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Kuanzishwa kwa nasaba ya Karamanlı Trablusgarp", "e1105d4a"], "d": ["Katika Trablusgarp, iliyochoshwa na mivutano ya maağa wa ocak, afisa wa wapanda farasi Ahmed Karamanlı alichukua utawala na kurasimisha hali yake kwa berat ya beylerbeylik aliyoipata kutoka İstanbul. Nasaba iliyodumu kati ya 1711-1835 kupitia Ahmed Paşa, mwanawe Mehmed Paşa na mjukuu wake Yûsuf Paşa ilizaliwa; muundo wa nusu huru uliojenga meli zake mwenyewe na kutia saini mikataba moja kwa moja na dola za Ulaya ulijitokeza. Kipindi hiki kingemalizika tu mwaka 1835 kwa mkoa kufungwa moja kwa moja na kituo.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Mkataba wa Edirne na Urusi", "14901a70"], "d": ["Kwa ahadi zilizotolewa Prut kutotimizwa, vita vilitangazwa mara mbili zaidi, na hatimaye Warusi walipokubali ahadi, amani ya kudumu ilitiwa saini Edirne. Mkataba ulithibitisha masharti ya Prut; Urusi isingeingilia mambo ya Poland, ingejitoa kutoka ardhi za Wakazak na isingezuia kurudi kwa mfalme wa Uswidi Demirbaş Şarl nchini mwake. Kufungwa kwa mstari wa kaskazini hivyo kuliiwezesha Dola ya Ottoman kugeuza uso wake kwenye mstari wa Mora na Venice. Maeneo mengine yaliyounganishwa tarehe hiyo hiyo: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Tangazo la vita dhidi ya Venice — maandalizi ya kampeni ya Mora", "d970b122"], "d": ["Kwa kuonyesha kama sababu Venice kuwaunga mkono waasi wa Karadağ, kuchukua meli za biashara za Ottoman na kuiponda Mora iliyoipata Karlofça kwa kodi nzito, uamuzi wa vita ulichukuliwa Divan. Kampeni iliyoandaliwa na Sadrazam Silâhdar Damad Ali Paşa ingemalizika mwaka uliofuata kwa kurudishwa kwa peninsula yote ya Mora ndani ya chini ya siku mia moja. Hata hivyo mafanikio haya yangeichochea Austria na kufungua mlango wa vita vizito zaidi mwaka 1716.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["İstendil (Tinos): kusalimishwa kwa kisiwa cha mwisho cha Venice Aegean", "4abec891"], "d": ["Meli zilizoelekea kampeni ya Mora ziliweka nanga mbele ya İstendil, kisiwa pekee kilichobaki mikononi mwa Venice Aegean, njiani. Kisiwa, ambacho kwa idadi yake ya Kilatini kilibeba bendera ya Venice kwa miaka mia moja hamsini zaidi ingawa Dukedom ya Nakşa ilianguka mwaka 1566, kilisalimu amri bila kumwaga damu baada ya mzingiro mfupi. Hivyo alama ya mwisho ya Venice Bahari ya Aegean ilifutwa na bahari ikawa kabisa bahari ya ndani ya Ottoman.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Kutekwa kwa Anabolu — ngome kuu ya Mora", "62a5808a"], "d": ["Anabolu, mji mkuu wa Venice Mora na ngome yake yenye nguvu zaidi, ilianguka tabya ya Palamidi ilipochukuliwa baada ya mashambulizi ya mizinga ya siku tisa. Kuchukuliwa kwa ngome kwa haraka kiasi hicho kulivunja upinzani katika sehemu iliyobaki ya peninsula. Kurudishwa kwa Mora iliyopotezwa Karlofça kulikamilika kwa vitendo hapa. Tarehe hiyo hiyo, makazi mengine yaliyopita kutoka Venice kwenda Ottoman katika atlasi: Argos — inafuata mnyororo wa abi-merkez wa Anabolu (TDV anabolu; makadirio yaliyotangazwa).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Kusalimishwa kwa Modon", "43faa909"], "d": ["Baada ya kuanguka kwa Anabolu, ngome ya Modon kwenye ncha ya kusini-magharibi ya Mora ilizingirwa na jeshi kwa nchi kavu na meli kwa bahari na ilisalimu amri kwa muda mfupi. Bandari hii, iliyotumiwa na Venice kwa miaka mia mbili katika kampeni zake za Mediterania ya Mashariki, ilikuwa kituo cha lazima ambapo meli zilipata maji na chakula. Kupotea kwake kulimaliza uwezo wa kusonga wa meli za Venice Aegean.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Kujisalimisha kwa Koron — kukamilika kwa msafara wa Mora", "e4b9c8a4"], "d": ["Kwa kujisalimisha kwa ngome ya Koron inayoshikilia mdomo wa ghuba ya Mesenya, utawala wa Venice kwenye peninsula ya Mora ulimalizika kabisa. Peninsula iliyopotezwa Karlofça ilirudishwa kabisa miezi mitatu tu baada ya kuanza kwa msafara. Katika mwendelezo wa msafara huo huo, mnamo Septemba 1715 kisiwa cha Ayamavra (Lefkada) katika Bahari ya Ionia pia kilichukuliwa kutoka Venice. Kasi hii ililazimisha Venice kuiingiza Austria vitani na miaka mitatu baadaye njia ya Pasarofça ilifunguka.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Kutekwa kwa Kisiwa cha Çuha (Kythira)", "494de6c6"], "d": ["Kisiwa cha Çuha kwenye ncha ya kusini ya Mora kilikabidhiwa kwa jeshi la majini baada ya kukamilika kwa peninsula. Kisiwa kinachochunga njia kati ya Bahari ya Ionia na Aegean kilikuwa kituo cha mbele ambacho Venice ilikitumia kudhibiti maji haya. Hata hivyo hakikubaki kuwa kisiwa pekee kilichoshikiliwa na Ottoman: miaka mitatu baadaye kilirudishwa Venice huko Pasarofça.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austria na Venice ziliunda muungano — mlango wa Vita vya Ottoman-Austria vya 1716-1718", "99511ca2"], "d": ["Baada ya Ottoman kuirudisha Mora kutoka Venice, Austria, ikidai kwamba Mkataba wa Karlofça ulikuwa umevunjwa, ilitia saini mkataba wa muungano na Venice; Prince Eugène katika barua aliyomwandikia sadrazam aliomba kurudishwa kwa maeneo yaliyochukuliwa kutoka Venice. Katika mashauriano ya kambi ya Davutpaşa, kwa shinikizo la sadrazam Ali Paşa, vita vilitangazwa dhidi ya Austria na fatwa ilipatikana kutoka kwa şeyhülislâm kwa ajili hiyo.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Sadrazam Ali Paşa alielekea kampeni ya Austria", "2fbdce42"], "d": ["Baada ya kutangazwa kwa vita dhidi ya Austria, serdâr-ı ekrem Ali Paşa alielekea kampeni ya Austria na jeshi la zaidi ya 100.000; meli nazo zilielekea Korfu majira hayo hayo. Jeshi lingesonga kutoka Belgrad kuelekea Varadin na katika kushindwa kwa mwanzoni mwa Agosti sadrazam angekufa shahidi.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Kushindwa kwa Varadin (Petrovaradin) — kifo cha shahidi cha Damad Ali Paşa", "265c1d81"], "d": ["Jeshi la Ottoman lililovuka Danube kupitia Belgrad lilikutana na vikosi vya Austria chini ya amri ya Prince Eugène mbele ya Varadin; ingawa katika shambulio la kwanza shambulio la Yeniçeri lililazimisha mitaro ya adui, safu zilitawanyika ubavu wa wapanda farasi ulipoanguka. Sadrazam Silâhdar Damad Ali Paşa alipigwa kwenye paji la uso na kufa shahidi, kambi na kikosi cha mizinga vilipita kabisa mikononi mwa adui. Kushindwa huku, kunakokumbukwa na vekāyi'nâme za Ottoman kama 'mwaka wa Varadin', kilikuwa kiungo cha kwanza cha mnyororo uliokwenda kwenye kupotea kwa Temeşvar na, mwaka uliofuata, Belgrad.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Kushindwa kwa Kuzingirwa kwa Korfu", "b2aa7011"], "d": ["Seraskeri wa Mora Kara Mustafa Paşa kwa nchi kavu na Kaptanıderyâ Canım Hoca Mehmed Paşa kwa jeshi la majini baharini walishambulia Korfu; kisiwa kilikuwa kituo muhimu cha Venice kwenye Adriatic. Hata hivyo ngome zenye nguvu kubwa za ngome, nyongeza zilizoletwa na jeshi la majini la Venice na habari za kushindwa kutoka mbele ya Danubi zilisababisha kuondolewa kwa kuzingirwa. Kutoweza kuteka Korfu kulizima hali ya furaha iliyoinuliwa na ushindi upya wa Mora na kuhamisha kitovu cha vita hadi Hungaria.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Kupotea kwa Temeşvar (Timişvar) kwa Austria", "27fe1365"], "d": ["Baada ya kushindwa kwa Varadin, Prince Eugène alielekea moja kwa moja Temeşvar na ngome ilikabidhiwa kwa makubaliano baada ya kuzingirwa kwa zaidi ya siku arobaini. Mji huu, uliotekwa mwaka 1552 wakati wa Kanûnî na kuhesabiwa nguzo ya mashariki ya ulinzi wa Hungaria kama kitovu cha beylerbeylik kwa miaka 164, hivyo ulipotea. Kwa kuanguka kwa Temeşvar eneo lote la Banat lilipita kwa Austria na mpaka wa Ottoman ukasukumwa kusini mwa Danubi. Makazi mengine yaliyopita kutoka Ottoman hadi Habsburg tarehe hiyo hiyo katika atlasi: Csákóvár, Facset na Karánşebeş (Caransebeş) — pamoja na kipindi cha eyalet ya Temeşvar (TDV timisvar; siku ya kiwango cha mahali haipo katika chanzo, mnyororo wa abi-merkez, makadirio yaliyotangazwa).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Kukabidhiwa kwa ngome ya Haram (Yeni Palanka) kwa Austria — pwani ya Danubi ya Banat yapotea", "38ee4c6d"], "d": ["Baada ya kuanguka kwa Temeşvar, jenerali wa wapanda farasi wa Austria Mercy, aliyeagizwa kuchukua sehemu iliyobaki ya Banat, tarehe 14 Novemba alisonga kuelekea Haram (Yeni Palanka) kando ya Danubi; alipofika ngomeni tarehe 16 Novemba, kikosi cha Ottoman cha watu 200 kilikabidhi kwa sharti la kuinua bendera nyeupe na kujiondoa kwa uhuru. Hivyo mstari wa Danubi wa Banat ya Kusini iliyokuwa mikononi mwa Ottoman tangu 1552 nao ulipita kwa Austria. Makazi mengine yaliyopita kutoka Ottoman hadi Habsburg tarehe hiyo hiyo katika atlasi: Versec — hufuata mnyororo wa abi-merkez wa Haram (Bánlaky 0019/1703; makadirio yaliyotangazwa).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Mkataba wa Pasarofça — Mora ilipatikana, Belgrade na Banat zilipotea", "d46aa216"], "d": ["Mora ilikuwa imerudishwa kutoka Venice, lakini Austria, iliyoingia vitani, ilipata ubora mezani kwa ushindi wake huko Petrovaradin na Belgrade. Mkataba uliotiwa saini kwa upatanishi wa Uingereza na Uholanzi uliiachia Ottoman Mora, na kwa malipo yake Serbia ya Kaskazini pamoja na Belgrade, Banat na Eflak Ndogo ziliachiwa Austria; kwa maneno ya TDV 'Bosnia ya Kaskazini imeachwa kabisa kwa Austria' — ngome kama Bosna Dubiça na Bosna Brod kando ya Sava hupita kwa Austria kwenye ramani kuanzia siku hii (mpaka wa uhakika ulichorwa na makomisaa mmoja baada ya mwingine, TDV haizitaji ngome hizi kwa jina); Venice ilihifadhi vituo vyake kwenye pwani ya Ionia kama Preveze na Çuha. Kwa ahidnâme ya biashara iliyotiwa saini siku hiyo hiyo, ushuru wa forodha uliotozwa kwa bidhaa za Austria ulipunguzwa kutoka asilimia tano hadi tatu. Mkataba, ukirekodi kurudi nyuma kwa Dola ya Ottoman katika Ulaya ya Kati, ulijenga msingi wa Enzi ya Tulip (1718-1730) kupitia amani ya miaka ishirini na saba iliyoifungua: chini ya utawala wa Nevşehirli Damad İbrahim Paşa, mashine ya kwanza ya uchapishaji ya Ottoman (1727, İbrahim Müteferrika), kamati za tafsiri, uchunguzi wa chanjo ya ndui na maisha mapya ya ikulu na utamaduni ni matunda ya miaka hii ya amani. Makazi mengine yaliyobadilisha mikono katika atlasi siku hiyo hiyo: Krayova (Craiova), Rimnik (Râmnicu Vâlcea) na Turnu Severin (Eflak Ndogo/Oltenia, kutoka Ottoman hadi Austria) pamoja na Ayamavra (Lefkada) (kutoka Ottoman hadi Venice; TDV ayamavra: mwaka 1718 kwa Mkataba wa Pasarofça kisiwa kiliachiwa Venice). Katika Eflak Ndogo pia Tırgu Jiu hupita kwa Austria; Vonitsa (Voniçe, TDV pasarofca-antlasmasi) na Kisiwa cha Çuha (Kythira, TDV cuka-adasi: kifungu cha 3 cha Pasarofça) hupita kwa Venice.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Msafara wa mashariki: kutekwa kwa Tiflis na kuanza kwa vita vya Iran", "78343dc2"], "d": ["Kufuatia kuporomoka kwa Dola ya Safavi kwa uvamizi wa Waafghani na Urusi kushuka kwenye pwani za Caspian, Dola ya Ottoman ilituma jeshi mashariki ili pengo lisiachwe kabisa kwa ushawishi wa Urusi. Tiflis ilitekwa na Georgia ikaunganishwa na utawala wa Ottoman; kisha kusonga mbele kuliendelea kuelekea Gence, Revan na Nahcıvan. Msafara huu, uliofanywa nyuma ya sura ya amani ya Enzi ya Tulip, ukawa mwanzo wa safari ndefu ya mashariki iliyodumu miaka kumi na mitatu na hatimaye kumalizika kwa kurudishwa kwa kila mahali palipopatikana.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Msafara wa Iran wa 1723: kuingia Şirvan na Georgia", "c81189fc"], "d": ["Kufuatia kuporomoka kwa Dola ya Safavi kwa uvamizi wa Waafghani, msafara wa mashariki ulianzishwa kwa sababu ya kuzuia Urusi kushuka kwenye pwani za Caspian. Jeshi la Erzurum liliingia Tiflis kupitia Georgia na tawi la Şirvan liliingia Şamahı, likirudisha ardhi zilizopotezwa miaka mia moja na thelathini kabla. Msafara huu ukawa kusonga mbele kubwa ya mwisho ya Ottoman Caucasus.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Kutekwa kwa Kirmanşah — mlango wa Zagros", "ad14799f"], "d": ["Jeshi la Baghdad lilivuka njia za Zagros na kuteka Kirmanşah, iliyohesabiwa mlango wa magharibi wa Iran. Mji ulikuwa kwenye njia ya misafara na majeshi kutoka Baghdad hadi İsfahan na kutekwa kwake kulihakikisha usalama wa mashariki wa eyalet ya Iraki. Kusonga huku kulianzisha mbio za mgawanyo kati ya Ottoman na Urusi juu ya ardhi ya Safavi iliyovunjika.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Mukāsemenâme ya Istanbul — kugawanywa kwa Iran na Urusi", "fce8eec2"], "d": ["Ili kuzuia Ottoman na Urusi kukabiliana juu ya ardhi ya Safavi iliyoporomoka, mkataba wa mgawanyo ulitiwa saini kwa upatanishi wa balozi wa Ufaransa. Pwani za magharibi na kusini za Bahari ya Caspian ziliachwa kwa Urusi; Georgia, Şirvan, Azerbaijan na miji ya Iran ya Magharibi kwa Dola ya Ottoman. Mgawanyo huu, uliooneka kuwa faida kubwa kwenye karatasi, hivi karibuni ungekuwa batili kwa vitendo kwa kupanda kwa Nâdir Şah. Kulingana na mkataba, ardhi zenye rutuba za Şirvan kama Şabran na Müşkür ziliachwa upande wa Urusi (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Kutekwa kwa Nahçıvan", "bdf14d0a"], "d": ["Vikosi vya Ottoman vilivyosonga kando ya Aras viliteka Nahçıvan na Ordubad; Culfa pia iliunganishwa na liva ya Nahçıvan. Mji uliunganishwa na eyalet ya Revan iliyoanzishwa mpya kama mlango wa kaskazini-magharibi wa Iran. Hivyo mpaka wa Ottoman ulifikia tena mstari wake wa mashariki zaidi wa enzi ya Kanûnî.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Ushindi wa Hemedan", "e1339a97"], "d": ["Jeshi lililoandamana mashariki kutoka Kirmanşah lilichukua Hemedan kwenye kizingiti cha magharibi cha uwanda wa Iran baada ya kuzingirwa kwa muda mrefu. Mji ulikuwa kituo kikubwa cha mwisho kwenye njia ya İsfahan, mahali pa mashariki zaidi ambapo majeshi ya Ottoman yalikuwa yamefika tangu Msafara wa Irakeyn. Mukavelenâme ya Istanbul iliyotiwa saini na Urusi mwaka huo huo iliandika kwenye karatasi mgawanyo wa Iran iliyovunjika kati ya Ottoman na Urusi.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Ushindi upya wa Revan", "88acabef"], "d": ["Baada ya kuzingirwa kwa siku tisini kwa ukaidi, Revan, ngome muhimu ya bonde la Aras, iliingia tena chini ya utawala wa Ottoman. Ngome iliyojengwa mwaka 1583 na kupotezwa mwaka 1604 safari hii iliimarishwa kwa kikosi chenye nguvu zaidi. Urefu wa kuzingirwa ulikuwa ishara kwamba jeshi la Ottoman halikusonga tena kwa urahisi. Nahiye za Karpi (Üçkilise), Şerür, Makû na Şüregel pia ziliunganishwa na eyalet ya Revan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Kutekwa kwa Tebriz — kuchukuliwa kwa Azerbaijan", "e502a4f7"], "d": ["Tebriz, iliyozingirwa tena baada ya jaribio lililoshindwa mwaka mmoja kabla, ilijisalimisha kwa jeshi la Ottoman baada ya vita vikali vilivyopiganwa barabara kwa barabara. Merend, Merâga na Sovukbulak (Mahabad), zilizotegemea eyalet ya Tebriz, nazo ziliingia chini ya utawala wa Ottoman. Mwaka huo huo Lori, Gence, Erdebil na Hürremâbâd pia zilitekwa, na maeneo yaliyoangukia sehemu ya Ottoman kwa Mukāsemenâme ya Istanbul yalivamiwa kwa vitendo. Upana huu uliofikiwa mashariki ulikuwa mpaka wa mbali zaidi tangu enzi ya Mkataba wa Ferhad Paşa; hata hivyo kuyashikilia kuliweka mzigo mzito kwa jeshi na hazina.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Ushindi wa Gence — mwisho wa msafara wa Caucasus", "875bca7a"], "d": ["Gence, lengo la mwisho la operesheni ya Caucasus, ilikabidhiwa kama kitovu cha Karabağ kati ya Kür na Aras. Kwa kukamilika kwa mstari wa Şirvan, Revan, Nahçıvan na Gence, Dola ya Ottoman ilifikia upana wake wa 1590 Caucasus. Hata hivyo faida hii ilikuwa ya muda mfupi: kupanda kwa Nâdir Şah kungechukua tena eneo lote ndani ya miaka kumi.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Mkataba wa Hemedan — kujiunga kwa Iran ya Magharibi na Ottoman", "94a29dc3"], "d": ["Kwa mkataba uliotiwa saini na mtawala wa Kiafghani Eşref Şah, vita vya miaka minne vilimalizika na ardhi za Iran ya Magharibi zilizovamiwa na Dola ya Ottoman zilitambuliwa kisheria. Eşref Şah kwa malipo alikubali ukhalifa wa sultani wa Ottoman na akachukua jukumu la khutba kusomwa kwa jina la sultani huko Iran. Ushindi huu wa kidiplomasia ulikuwa wa muda mfupi; shambulio la kukabiliana la Nâdir Şah lililoanzishwa mwaka 1730 lingefuta mafanikio ya mkataba ndani ya miaka michache.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Paşa ateka Rûmiye", "eac7f64d"], "d": ["Katika msafara wa Iran Hekimoğlu Ali Paşa alichukua kwanza Urmiye (Rûmiye), kisha Tebriz iliyoachwa kwa Ottoman tarehe 15 Novemba 1731. TDV haitoi siku ya kutekwa kwa Urmiye; inajulikana tu mwaka na kwamba ilitangulia Tebriz.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Mkataba wa Ahmed Paşa — kurudishwa kwa sehemu kubwa ya Iran ya Magharibi", "590d839f"], "d": ["Kufuatia ushindi wa Nâdir Şah huko Melâyir na mashambulizi ya Iran mfululizo, gavana wa Baghdad Ahmed Paşa alitia saini maandishi ya amani bila kushauriana na kitovu. Kulingana na mkataba, mto Aras ulikubaliwa kuwa mpaka; miji ya Iran ya Magharibi kama Hemedan, Kirmanşah, Erdelan, Erdebil na Tebriz ilirudishwa Iran, Gence na Tiflis zikabaki Ottoman. Maandishi haya, yaliyopokelewa kwa hasira Istanbul, yalionekana pia kutotosha na Nâdir Şah, na vita viliwaka tena kabla ya mwaka 1732 kuisha. Atlasi inahesabu pia Kotur, inayofuata mnyororo wa Hoy, kuwa ilipita kutoka Ottoman hadi Safavi siku hii (TDV hoy; siku mahsusi kwa Kotur haipo katika chanzo — makadirio yaliyotangazwa).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Kupotea tena kwa Vahran (Oran) kwa Uhispania", "20485027"], "d": ["Jeshi kubwa la majini la kutua lililotumwa na mfalme wa Uhispania V. Felipe lilifika mbele ya Vahran chini ya amri ya Count Montemar na, kwa kulishinda vibaya vikosi vya Ocak ya Algeria, lilirudisha mji. Bandari iliyotekwa miaka ishirini na minne kabla ingebaki tena mikononi mwa kikosi cha Uhispania kwa miaka sitini. Hasara hii, iliyoonyesha mipaka ya nguvu za ocak za Magharibi katika Mediterania ya Magharibi, ingeweza kufidiwa tu kwa ushindi wa uhakika wa Vahran mwaka 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Marekebisho ya Ocak ya Humbaracı kwa mtindo wa Ulaya na kuanzishwa kwa Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Paşa wa asili ya Kifaransa aliyeingia katika huduma ya Ottoman, kwa msaada wa sadrazam Hekimoğlu Ali Paşa, alikifanya ocak ya humbaracı kuwa kikosi chenye mishahara kilichopangwa kwa mtindo wa Ulaya. Mafunzo ya kawaida yaliyotegemea hesabu na jiometri yalitolewa kwa askari mia tatu walioandikishwa kutoka Bosnia; nizamnâme mpya zilitayarishwa kwa shirika, vifaa na kustaafu, na kwa mbinu ya kisasa mizinga ya humbara mia moja na humbara elfu hamsini zilitengenezwa. Humbarahâne, ambapo jiometri ilifundishwa, huhesabiwa kiini cha kwanza cha elimu ya kisasa ya uhandisi wa kijeshi huko Ottoman.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Kifo cha III. Ahmed", "455f7fba"], "d": ["III. Ahmed, aliyeondolewa kwenye kiti cha enzi mwaka 1730 kwa uasi wa Patrona Halil, alipitisha miaka sita ya mwisho ya maisha yake katika makazi ya Ikulu ya Topkapı yaliyotengwa kwa masultani walioondolewa na alifariki akiwa na umri wa miaka sitini na mitatu. Alizikwa Bahçekapı katika kaburi la nyanya yake Turhan Sultan karibu na Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Mkataba wa Istanbul — kuiachia Iran Caucasus ya Kusini", "8c205aab"], "d": ["Vita vya pili vya Iran vilivyodumu miaka minne vilimalizika kwa mkataba uliotiwa saini baada ya kushindwa kwa Arpaçay na kupotea kwa Gence na Tiflis. Dola ya Ottoman ilijiondoa kutoka ardhi zote za Caucasus ya Kusini na Iran ya Magharibi ilizozitwaa tangu 1723, na mpaka ulirudi kwenye mstari wa Kasr-ı Şîrin wa 1639. Kutoka misafara ya mashariki ya miaka kumi na mitatu kilibaki mzigo mzito wa kifedha na hazina tupu; hata hivyo, kwa vita vipya vilivyoanza na Urusi, kufungwa kwa mbele ya mashariki ilikuwa faida muhimu.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Kuanguka kwa Ngome ya Özi (Ochakov) kwa Warusi", "f93e61f3"], "d": ["Jeshi la Urusi chini ya amri ya Marshal Münnich lilizingira Ngome ya Özi kwenye mdomo wa Dnieper; kwa kulipuka kwa ghala la silaha ulinzi uliporomoka na ngome ilianguka kwa hasara kubwa ya maisha. Kupotea kwa Özi, iliyohesabiwa kufuli ya pwani ya kaskazini-magharibi ya Bahari Nyeusi, kulifungua kwa Warusi njia ya kuelekea Crimea na kulileta hofu kubwa Istanbul. Ngome ingeachwa na Warusi mwaka uliofuata kwa sababu ya mlipuko wa ugonjwa na ugumu wa usambazaji na kurudi kwa Ottoman.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Ushindi wa Banaluka — ukombozi wa Bosnia", "f603865a"], "d": ["Vikosi vya Austria vilipoingia Bosnia na kuizingira Banaluka, gavana wa Bosnia Hekimoğlu Ali Paşa alifika kusaidia kwa vikosi alivyokusanya kutoka kwa wakazi wa mahali na akamshinda vibaya adui aliyekuwa na wingi. Ushindi huu ulivunja mpango wa Austria wa kuivamia Bosnia tangu hatua ya kwanza na sehemu ya kaskazini ya eyalet ilirudishwa kabisa. Banaluka ilikuwa mojawapo ya mageuzi yaliyoinua ari ya jeshi la Ottoman lililokuwa likirudi nyuma mara kwa mara mbele ya Austria baada ya 1683.", "81c1850e"]}
});
